/* AMaC Bleep Cards: 65 on-call cards for F1 doctors. Sources last checked October 2026. */
window.BLEEP_CARDS = [{"id": "BLEEP-01", "title": "Falling oxygen saturations", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mrs Okafor's sats have dropped to 89 per cent on air over the last hour, she's a bit breathless.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations (respiratory rate, saturations, heart rate, BP, temperature, consciousness) and the NEWS2 score"}, {"lead": "New or a trend? Target range?", "text": "Ask whether this is a new finding or a gradual trend, and whether the patient has a documented individual oxygen target range already, or any condition that puts them at risk of hypercapnic respiratory failure (not just COPD — also, for example, neuromuscular disease, morbid obesity, chest wall deformity, cystic fibrosis, or bronchiectasis with fixed airflow obstruction)"}, {"lead": "Sit up + start O₂", "text": "Ask the nurse to sit the patient upright and start oxygen now. Use their documented target range if one exists. Otherwise:\n- If they look critically ill (even if at risk of hypercapnic respiratory failure, until blood gases are back), or saturations are below 85%: reservoir mask at 15 L/min.\n- If they are at risk of hypercapnic respiratory failure but not critically ill: 24% Venturi mask at 2–3 L/min, or nasal cannulae at 1–2 L/min, aiming for 88–92%.\n- Otherwise: nasal cannulae aiming for 94–98%.\n\nConfirm and prescribe the target range yourself on arrival."}, {"lead": "Recheck sats; repeat obs", "text": "Ask for the saturations to be rechecked 5 minutes after starting oxygen, and for observations at least every 15 minutes until you arrive (continuous monitoring if the NEWS2 is now 7 or more), with a cannula tray and an ABG kit ready"}, {"lead": "Location; stay with patient", "text": "Confirm the patient's location and ask the nurse to stay with the patient until you arrive"}], "first_five_minutes": [{"lead": "Check probe and O₂ delivery", "text": "Confirm the saturation reading is accurate: check probe placement, the signal and perfusion, whether the patient is peripherally cold or has nail varnish or false nails, and, once oxygen is running, that the delivery device and tubing are working"}, {"lead": "ABCDE", "text": "Do a structured airway, breathing, circulation, disability, exposure assessment rather than jumping straight to a chest X-ray request"}, {"lead": "Focused chest exam", "text": "Look specifically at respiratory rate, chest expansion, trachea position, breath sounds, and work of breathing"}, {"lead": "Hypercapnia risk?", "text": "Determine whether the patient has a documented oxygen target range, or is at risk of hypercapnic respiratory failure for any reason (not limited to COPD); if uncertain, get a blood gas and seek senior advice rather than guessing"}, {"lead": "ABG", "text": "Take an ABG: BTS recommends a blood gas for an unexpected fall in saturation below 94% or any patient who needs oxygen to reach their target range, for anyone at risk of hypercapnia who becomes breathless or desaturates, and if the saturation fails to rise after 5–10 minutes of increased oxygen"}, {"lead": "CXR + ECG", "text": "Request a portable chest X-ray and a 12-lead ECG (PE, ischaemia and arrhythmia are all on the differential)"}, {"lead": "Recalculate NEWS2", "text": "Recalculate the NEWS2 score with the new observations and decide on the escalation threshold it triggers; at 7 or more, vital signs need continuous monitoring"}], "can_i_do_alone": {"alone": "Starting or titrating supplemental oxygen to the appropriate target range and prescribing it, repeating observations, requesting a portable chest X-ray and an ABG, and giving a first dose of a bronchodilator if wheeze is present and it is already prescribed or covered by a ward protocol (if at risk of hypercapnic respiratory failure, use a nebuliser driven by air, not oxygen, with nasal cannula oxygen to keep 88–92%)", "senior_opinion": "Saturations that do not reach the target range on nasal cannulae or a simple face mask (BTS advises changing to a reservoir mask and seeking senior advice), a new oxygen requirement in a patient who was previously well, or uncertainty about the target range in a patient with possible carbon dioxide retention; and a NEWS2 of 5–6 or a single parameter scoring 3 (both need urgent review)", "senior_in_person": "Saturations still below the target range on a reservoir mask, signs of exhaustion or a falling consciousness level, suspicion of a tension pneumothorax or airway obstruction, or a NEWS2 score of 7 or more. These need a senior at the bedside now, not a phone call; follow your trust's escalation policy for who attends."}, "escalate_now_if": ["Saturations stay below the target range despite oxygen via a reservoir mask", "The patient is using accessory muscles, cannot complete sentences, or looks exhausted", "There is stridor, absent breath sounds on one side, tracheal deviation, or suspected tension pneumothorax", "The NEWS2 score is 7 or more — and escalate at any score if you are clinically concerned", "Falling consciousness level or new confusion alongside the hypoxia"], "document": "Record the time the bleep was received, the observations and NEWS2 score at review, examination findings, oxygen given and the target saturation chosen, investigations ordered, and the plan agreed with the senior including the time they were contacted.", "fail": "An unsafe response gives uncontrolled high-concentration oxygen to a patient at risk of carbon dioxide retention who is not critically ill, without a target range or a blood gas; does not repeat observations after starting treatment; or sits on a NEWS2 score of 7 or more without escalating.", "pass": "A safe response does a structured assessment, starts oxygen at an appropriate target, requests the right first-line investigations, and escalates promptly when the red flags are met.", "high_performance": "An excellent response also considers the differential diagnosis proactively (infection, PE, heart failure, atelectasis), pre-empts what the senior will ask for, and documents and hands over clearly so the next team knows what has already been done.", "one_thing": "If you only remember one thing: treat the patient in front of you first, and only decide the oxygen target once you know whether they are at risk of carbon dioxide retention.", "img_note": "In the UK, oxygen is prescribed on the drug chart with a target saturation range, not just a flow rate; check this before adjusting it, and remember that your hospital's emergency or outreach escalation pathway (not just the 2222 crash call) is usually the right first step for serious deterioration that isn't yet arrest or peri-arrest — the crash team itself is for arrest or peri-arrest.", "source": "British Thoracic Society, BTS Guideline for oxygen use in adults in healthcare and emergency settings, May 2017 (O'Driscoll BR et al, Thorax 2017;72(Suppl 1):i1–i90) — still the current BTS oxygen guideline; it sets the prescribed target range of 94–98% for most acutely ill patients and 88–92% for those at risk of hypercapnic respiratory failure pending blood gases, and when to check blood gases. A new BTS guideline on target oxygen saturations in adults receiving emergency oxygen therapy is in development; this card follows the 2017 guideline until it is replaced. NEWS2 scoring and response thresholds: Royal College of Physicians, National Early Warning Score (NEWS) 2, December 2017.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Okafor on ward 12, her saturations dropped to 89% on air, her NEWS2 was 6 on air and is now 7 on oxygen.", "B": "she's day two post a hip replacement, previously well, no known lung disease.", "A": "her respiratory rate is 26, heart rate 88, BP 132/78, temperature 37.6 and she's alert; she has reduced air entry at the right base, she's on 4 litres of oxygen via nasal cannula and only at 93%, below her 94 to 98% target, so I'm increasing it and will change to a reservoir mask at 15 litres if she stays below target on nasal cannulae, and I'm worried about a chest infection or a PE given her recent surgery.", "R": "I'd like you to come and review her now, and with a NEWS2 of 7 I think we should involve critical care outreach per our escalation policy; I'm arranging a chest X-ray and an ABG now, can we also work out her Wells score together to decide between an immediate CTPA and a D-dimer."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-02", "title": "New chest pain on the ward", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Davies has just come over with chest pain, he says it's a 7 out of 10 and started about ten minutes ago.\"", "nurse_call": [{"lead": "Full obs", "text": "Ask for a full set of observations and whether the patient looks unwell, sweaty, or short of breath"}, {"lead": "12-lead ECG now", "text": "Ask the nurse to get a 12-lead ECG done immediately and to keep the patient resting in bed"}, {"lead": "Pain history", "text": "Ask about the character, site, and radiation of the pain, and whether there is any associated breathlessness, sweating, or nausea"}, {"lead": "Monitor, IV kit, resus trolley", "text": "Ask the nurse to put the patient on a cardiac monitor, to have IV access equipment and the resuscitation trolley nearby, and to repeat observations every few minutes"}, {"lead": "Past history", "text": "Confirm whether the patient has a history of similar pain, known heart disease, or recent surgery or immobility"}], "first_five_minutes": [{"lead": "ECG — read it yourself", "text": "Get a 12-lead ECG urgently and review it yourself, while assessing and treating any immediate airway, breathing or circulation threat first if present — the ECG is urgent, not a reason to bypass ABCDE in a patient who is already unstable"}, {"lead": "Focused history", "text": "Take a focused history: onset, character, site, radiation, associated symptoms, and risk factors for ACS and for PE"}, {"lead": "Examine, incl. dissection signs", "text": "Examine the chest, heart sounds, calves, and check for a pleural rub or asymmetrical air entry. Check haemodynamic status and look for signs of complications, such as pulmonary oedema or cardiogenic shock, and of non-coronary causes of acute chest pain, such as aortic dissection. Suspect dissection if there is sudden tearing or ripping pain going through to the back, a pulse or BP difference between the arms, a new aortic regurgitation murmur or a neurological deficit. Consider a chest X-ray to help exclude complications such as pulmonary oedema, or other diagnoses such as pneumothorax or pneumonia, and do not give antiplatelets or anticoagulants if dissection is suspected until a senior has reviewed"}, {"lead": "Targeted O₂; analgesia, aspirin", "text": "Give oxygen only if saturations are below 94%, aiming for 94–98%; if the patient is at risk of hypercapnic respiratory failure (for example COPD), give it only if saturations are below 88%, aiming for 88–92% until blood gases are available. Offer pain relief as soon as possible (GTN — not if systolic BP is below 90 mmHg, or if they take sildenafil, tadalafil, vardenafil or riociguat (ask specifically, including as-needed use) — or an IV opioid such as morphine particularly if an MI is suspected, per local protocol). If ACS is suspected, offer a single 300 mg aspirin loading dose unless there is clear evidence of aspirin allergy (see below for when to check with a senior first) — do not give a second antiplatelet before a diagnosis of unstable angina or NSTEMI has been made; in suspected STEMI, the reperfusion team decides"}, {"lead": "Troponin now + repeat", "text": "Send urgent bloods including a high-sensitivity troponin now, and arrange a repeat at the interval your trust's assay protocol specifies. Do not treat one normal troponin as ruling out MI — a single-sample rule-out applies only to low-risk patients on your trust's pathway and is a senior's call. With pain that started only minutes ago, plan a repeat rather than relying on one sample"}, {"lead": "PE probability + chest X-ray", "text": "If PE is suspected, offer a chest X-ray to exclude other causes, and use the two-level PE Wells score to estimate clinical probability and guide further testing (D-dimer or CTPA)"}, {"lead": "NEWS2: registrar or crash call?", "text": "Reassess the NEWS2 score and decide whether this needs a registrar review now or a crash call"}], "can_i_do_alone": {"alone": "Arranging an immediate ECG, taking a focused history and examination, sending troponin and routine bloods, giving pain relief, and giving oxygen only if saturations are below target (below 94%, or below 88% if at risk of hypercapnic respiratory failure), following your trust's chest pain protocol. Give a single 300 mg aspirin loading dose if ACS is suspected — NICE says offer it unless there is clear evidence of aspirin allergy — but on the ward treat recent major surgery, active bleeding, or anticoagulation as reasons to get a senior opinion first rather than giving it alone (follow your trust's protocol)", "senior_opinion": "Any ECG changes you are unsure about, including ST depression or deep T-wave inversion that may mean NSTEMI or unstable angina in a patient who is now pain-free and stable, a rising or significantly elevated troponin, or any case where the diagnosis between cardiac and non-cardiac causes is unclear", "senior_in_person": "An ECG showing regional ST elevation (at least 1 mm in two contiguous leads; higher thresholds in V2–V3), presumed new left bundle branch block, or a STEMI equivalent: ST depression in V1–V3 suggesting posterior MI, or any bundle branch block or paced rhythm with ongoing ischaemic symptoms, especially with persistent pain or haemodynamic instability, needs urgent reperfusion-pathway activation per your local protocol; call the medical or cardiology registrar now. The same applies to ST depression or deep T-wave inversion with ongoing pain or haemodynamic instability. Reserve an actual crash call (2222) for a patient who is peri-arrest or has arrested — an abnormal ECG in a stable patient is an urgent registrar call, not a crash call"}, "escalate_now_if": ["The ECG shows regional ST elevation (at least 1 mm in two contiguous leads; higher thresholds in V2–V3), presumed new left bundle branch block, or a STEMI equivalent: ST depression in V1–V3 suggesting posterior MI, or any bundle branch block or paced rhythm with ongoing ischaemic symptoms — call the cardiology or medical registrar urgently for reperfusion-pathway activation per your local protocol", "The patient is hypotensive, has new breathlessness, or looks grey or sweaty", "There is a new cardiac arrhythmia or heart block on the ECG", "You suspect a PE with haemodynamic compromise, or an aortic dissection", "The pain is not settling with initial treatment or is recurring"], "document": "Record the time of onset and review, the ECG findings with a printed copy filed in the notes, examination findings, bloods sent, treatment given, and the escalation discussion including who was called and what was agreed.", "fail": "An unsafe response delays getting an ECG, misses clear ischaemic changes, or fails to escalate a patient who looks unwell while waiting for troponin results.", "pass": "A safe response gets an immediate ECG, does a focused assessment, sends appropriate bloods, and escalates promptly if there are concerning features or an abnormal ECG.", "high_performance": "An excellent response keeps both ACS and PE actively on the differential given the surgical context, repeats the ECG if pain persists, and proactively updates the nursing staff and the patient on the plan while waiting for senior review.", "one_thing": "If you only remember one thing: get the ECG urgently and review it yourself, but don't let that stop you treating an immediate ABCDE threat first if one is present.", "img_note": "Post-operative patients are a common source of confusion for new doctors, because pain, anxiety, and blood loss can all mimic or mask cardiac symptoms; have a low threshold to involve the surgical team as well as the medical registrar, and remember that in UK hospitals you can usually request an urgent ECG and troponin yourself without senior co-signature.", "source": "NICE CG95, Recent-onset chest pain of suspected cardiac origin: assessment and diagnosis (published March 2010, last updated 30 November 2016) — initial assessment, immediate 12-lead ECG, oxygen only below 94% (88–92% target in COPD at risk of hypercapnic respiratory failure), 300 mg aspirin and high-sensitivity troponin testing (single-test rule-out only for low-risk people with a first result below the limit of detection); NICE HTG552 (formerly DG40), High-sensitivity troponin tests for the early rule out of NSTEMI (August 2020, migrated December 2025, recommendations unchanged) — early rule-out strategies, interpreted against time since symptom onset; NICE NG185, Acute coronary syndromes (published 18 November 2020; minor updates December 2021, December 2024 and July 2026, none to the early-management recommendations used here) — immediate reperfusion assessment for STEMI, immediate angiography for unstable angina or NSTEMI if clinically unstable, and no dual antiplatelet therapy before a diagnosis of unstable angina or NSTEMI; NICE NG158, Venous thromboembolic diseases: diagnosis, management and thrombophilia testing (March 2020, last updated August 2023) — two-level PE Wells score and the D-dimer/CTPA pathway; Glyceryl trinitrate 400 micrograms sublingual spray SmPC (emc) — contraindicated in severe hypotension (systolic BP below 90 mmHg) and with PDE-5 inhibitors or riociguat; ESC 2023 Guidelines for the management of acute coronary syndromes (published 25 August 2023) and the Fourth Universal Definition of MI (2018; since replaced by the Fifth Universal Definition of MI, ESC/ACC/AHA/WHF, 28 August 2026), for ST-elevation thresholds and STEMI equivalents; ESC 2023 also for the more-than-3-hours condition on single-sample troponin rule-out; BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Davies on ward 8, he's developed central chest pain ten minutes ago, 7 out of 10, saturations are 92% on air.", "B": "he's day one post a knee replacement, no known cardiac history, but he's had limited mobility.", "A": "his ECG shows no acute ischaemic changes, I've started oxygen, observations are otherwise stable, but given his immobility I'm concerned about a PE as well as a cardiac cause, and his recent surgery means I haven't given aspirin without your input.", "R": "I've sent a troponin with a repeat planned. I'd like your advice on bleeding risk before any antiplatelet or anticoagulant, and I'd like us to work out his two-level PE Wells score to decide between an immediate CTPA and a D-dimer. Can you come and see him?"}, "checked": "3 Oct 2026"}, {"id": "BLEEP-03", "title": "Hypotension and possible sepsis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Singh's blood pressure has dropped to 88 over 50, he's also spiked a temperature of 38.9.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the current NEWS2 score"}, {"lead": "Source?", "text": "Ask about an obvious source: a new cough, urinary symptoms, a wound, or a line in place"}, {"lead": "O₂, cannula, cultures", "text": "Shocked or critically ill, or saturations below 85% and not at risk of hypercapnic respiratory failure: reservoir mask at 15 L/min. Otherwise, saturations below 94%: nasal cannulae to 94–98% (88–92% via a 24% Venturi mask or 1–2 L/min nasal cannulae if at risk of hypercapnic respiratory failure). Cannula and blood cultures if the nurse is trained, otherwise have the equipment ready"}, {"lead": "Prepare a fluid bolus", "text": "Ask for an IV fluid bolus to be prepared and for the patient to be moved where observations can be done frequently"}, {"lead": "Allergies + meds", "text": "Confirm allergies and current medications, especially anything that could be lowering the BP"}], "first_five_minutes": [{"lead": "High risk: antibiotics in 1 hour, registrar now", "text": "NEWS2 7 or more = high risk of severe illness or death from sepsis: blood cultures, broad-spectrum IV antibiotics within 1 hour of the NEWS2, 250 ml bolus, registrar now. NEWS2 5–6 with lactate over 2 mmol/L or AKI = treat as high risk. NEWS2 5–6 with a single parameter scoring 3 (for example systolic BP 90 mmHg or below): get a high-priority FY2-or-above review now — if the infection is causing it, it is managed as high risk. NEWS2 5–6 without any of these = FY2-or-above review within 1 hour"}, {"lead": "ABCDE: rate higher than the score?", "text": "Assess ABCDE and look for a source. A single NEWS2 parameter scoring 3 (such as new confusion) needs a high-priority FY2-or-above review for a definite risk decision. Rate the risk higher than NEWS2 suggests if mottled or ashen, a non-blanching petechial or purpuric rash, cyanosis of the skin, lips or tongue, or deteriorating or not improving since the last NEWS2 or intervention"}, {"lead": "Cultures first, never past 1 hour", "text": "Take blood cultures and other relevant samples before antibiotics, but never let them push a high-risk patient beyond the 1-hour limit. Send a venous gas (glucose and lactate), FBC, CRP, U&E and creatinine, LFTs and clotting; consider procalcitonin"}, {"lead": "250 ml boluses, up to 1,000 ml", "text": "High risk and fluids not contraindicated: 250 ml crystalloid (Hartmann’s, or 0.9% sodium chloride if not available) over 10–15 minutes, within 1 hour. Reassess after each bolus; repeat up to 1,000 ml in total including fluid already given. Not improved enough after 1,000 ml: senior clinical decision maker now"}, {"lead": "Medium or low risk: FY2+ review first", "text": "Medium and low risk: FY2-or-above review within 1 hour; antibiotics may wait up to 3 h (medium) / 6 h (low) only on that review. Medium: the reviewer also checks the lactate and decides with a senior clinical decision maker, including on IV fluids. Low: also a registered health practitioner review within 1 hour. Very low (NEWS2 0, no concern): registered health practitioner review and recalculate NEWS2 per local protocol. These are maximums, not targets — once antibiotics are decided, give them without delay"}, {"lead": "Bowel resection: tell the surgeons", "text": "Day 3 after a bowel resection: think anastomotic leak or collection and tell the operating surgical team early — source control (imaging, drainage or theatre) may be needed"}, {"lead": "Recheck NEWS2, urine, document", "text": "Recalculate NEWS2 and document the risk category and plan: every 30 minutes if high risk, hourly if medium, every 4–6 hours if low, and whenever the patient deteriorates or changes unexpectedly. NEWS2 7 or more needs continuous monitoring. Ask when urine was last passed and monitor output; catheterise for close monitoring per local protocol"}], "can_i_do_alone": {"alone": "Assessing, taking blood cultures, sending bloods with a venous lactate, recalculating NEWS2 and — for a high-risk patient, while you escalate — giving 250 ml crystalloid boluses, reassessing after each, up to 1,000 ml in total (senior advice if not improved) and the first dose of broad-spectrum IV antibiotics within 1 hour per your trust's sepsis pathway", "senior_opinion": "Phone if you are unsure of the risk category, and for every medium- or low-risk patient: deferring antibiotics (up to 3 hours medium, 6 hours low) is decided by a clinician at FY2 or above who reviews the patient — for medium risk with a senior clinical decision maker — not by you alone", "senior_in_person": "Any high-risk patient (NEWS2 7 or more, or 5–6 with lactate over 2 mmol/L or AKI, or 5–6 with a single parameter scoring 3 because of the infection): urgent bedside review by FY2 or above and referral now to the senior clinical decision maker (ST3 or above), with the consultant involved by clinical judgement. A single parameter of 3: high-priority FY2-or-above review. High risk and no response within 1 hour of any intervention: the senior clinical decision maker attends in person, critical care is involved and the responsible consultant is informed"}, "escalate_now_if": ["NEWS2 is 7 or more, or 5–6 with lactate over 2 mmol/L or AKI — this is high risk.", "A single NEWS2 parameter scores 3, such as new confusion — get a high-priority FY2-or-above review now; if the infection is causing it, it is managed as high risk.", "There is mottled or ashen skin, a non-blanching petechial or purpuric rash, or cyanosis of the skin, lips or tongue — rate the risk higher than the NEWS2.", "BP or consciousness has not improved enough after 1,000 ml of fluid, or a high-risk patient has not responded within 1 hour of any intervention.", "There is a new reduction in consciousness level or new confusion.", "Urine output stays very low despite fluid resuscitation.", "You are not sure which risk category applies — ask rather than default to either extreme."], "document": "Record the time of the bleep, the observations and the time NEWS2 was calculated (antibiotic timings run from this), the risk category and why, the times of blood cultures, antibiotics and fluids and the fluid volume, the likely source, and the escalation with the time and name of the senior contacted.", "fail": "An unsafe response delays antibiotics in a high-risk patient while waiting for a senior, treats every suspected infection as a 1-hour-antibiotic emergency regardless of risk, gives large volumes of fluid without reassessing, or fails to escalate a patient who is not responding.", "pass": "A safe response risk-stratifies with NEWS2 and clinical judgement, gives antibiotics within 1 hour if high-risk, otherwise gets an FY2-or-above review (within 1 hour for medium risk) so any deferral stays within 3 hours (medium) or 6 hours (low), and escalates non-response or high-risk criteria.", "high_performance": "An excellent response actively looks for and documents a likely source of infection to guide antibiotic choice, reassesses after each intervention rather than working through a checklist mechanically, explicitly states the risk category and reasoning when handing over or escalating, and proactively alerts the outreach or critical care team early rather than waiting for deterioration to become undeniable.", "one_thing": "If you only remember one thing: decide whether this patient is high-risk — if so, antibiotics within 1 hour and a registrar now; if not, an FY2 or above reviews and decides whether antibiotics can wait up to 3 hours (medium) or 6 hours (low).", "img_note": "Most UK trusts have a sepsis pathway with a paper or electronic prompt sheet and a time target for antibiotics from recognition; find out where this is kept on your ward on your first day, and know that the critical care outreach team can usually be contacted directly for advice on a deteriorating patient even before the registrar arrives.", "source": "NICE guideline NG253, Suspected sepsis in people aged 16 or over: recognition, assessment and early management (published 19 November 2025, last updated 23 September 2026; replaced the adult content of NG51) — sets NEWS2-based risk bands in hospital (high 7 or more, medium 5–6, low 1–4, very low 0), antibiotics within 1 hour for high risk and FY2-or-above decisions on deferral up to 3 hours (medium) or 6 hours (low), 250 ml crystalloid boluses up to 1,000 ml for high risk, and escalation to the senior clinical decision maker, critical care and consultant; used with the Royal College of Physicians National Early Warning Score 2 (NEWS2), December 2017 (Chart 4: continuous monitoring of vital signs at NEWS2 7 or more), and the British Thoracic Society Guideline for oxygen use in adults in healthcare and emergency settings, 2017 (E2: in critical illness including sepsis and shock, start with a reservoir mask at 15 L/min)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Singh on ward 5, his BP has dropped to 88 over 50, heart rate 118, respiratory rate 22, sats 96% on air, temperature 38.9, and he's alert, I'm concerned about sepsis.", "B": "he's three days post a bowel resection, previously well.", "A": "His NEWS2 was 8 when the nurse called, which on its own puts him in the high-risk group, and his lactate is 3.2. I've started oxygen via a reservoir mask and will titrate it down to 94–98% once he's stable, taken cultures, given the first 250 ml bolus and the first dose of antibiotics within the hour as per our sepsis pathway, and his BP has come up slightly to 95 over 55.", "R": "I'd like you to come and review him now. His NEWS2 was 8 on air and is now higher on oxygen, so he needs continuous monitoring, which I've asked for. I'm giving further 250 ml boluses and reassessing after each, up to 1,000 ml; I'd like your view if he's not improved by then, on vasopressor support and on involving outreach or critical care. Given his bowel resection, I've also told the surgical team, because he may need a CT to look for a leak."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-04", "title": "Low urine output and suspected acute kidney injury", "fpc_tags": ["Clinical assessment", "Holistic planning"], "scenario": "Nurse bleeps: \"Mrs Patel has only passed 60 millilitres of urine in the last 6 hours, her blood results have just come back and her creatinine has gone up.\"", "nurse_call": [{"lead": "Exact urine output", "text": "Ask for the exact urine output over the last 6, 12, and 24 hours, and the patient's weight if known"}, {"lead": "Obs + fluid status", "text": "Ask for the current observations and whether the patient looks dehydrated or fluid overloaded"}, {"lead": "Current fluids + meds", "text": "Ask what fluids and medications the patient is currently receiving, particularly anything that could affect the kidneys"}, {"lead": "Catheter blocked?", "text": "Ask the nurse to check whether there is a catheter in place and, if so, whether it might be blocked"}, {"lead": "Renal trend", "text": "Ask for the most recent and any previous renal function results to be available when you arrive"}], "first_five_minutes": [{"lead": "Urine dipstick", "text": "Perform a urine dipstick for blood, protein, leucocytes, nitrites and glucose as soon as AKI is suspected or detected"}, {"lead": "Stage the AKI", "text": "Review the trend in creatinine and urine output to confirm and stage the AKI"}, {"lead": "Fluid status", "text": "Assess fluid status clinically: pulse, BP, jugular venous pressure, chest for crackles, and peripheral oedema"}, {"lead": "Retention? Bladder scan", "text": "Check for a blocked catheter or urinary retention with a bladder scan if there is no catheter; if the catheter is blocked, flush or change it (or ask the nurse to), and if the scan shows retention, insert a urinary catheter — obstruction above the bladder, or no improvement, still needs a senior"}, {"lead": "Review nephrotoxins", "text": "Review the drug chart for medicines that can cause or worsen AKI (such as NSAIDs, aminoglycosides, ACE inhibitors, ARBs and diuretics) and stop or withhold them where appropriate; ask the ward pharmacist for advice on optimising medicines and doses"}, {"lead": "Bloods + K⁺", "text": "Send urgent bloods including renal function, potassium, and a VBG if hyperkalaemia is a concern"}, {"lead": "500 ml bolus if hypovolaemic", "text": "If the patient is hypovolaemic and not fluid overloaded, give a 500 ml bolus of crystalloid containing sodium 130–154 mmol/litre over less than 15 minutes, then reassess before giving more; do not give a loop diuretic to treat AKI or to increase urine output — discuss with a senior if the patient is fluid overloaded"}, {"lead": "Ultrasound only if indicated", "text": "Do not routinely request an ultrasound if the cause is already clear; if there is no identified cause or any risk of obstruction, arrange an urgent ultrasound within 24 hours (within 6 hours if pyonephrosis is suspected); if ultrasound shows upper urinary tract obstruction, refer to urology (immediately if there is pyonephrosis, an obstructed solitary kidney, bilateral obstruction or complications of AKI caused by the obstruction)"}, {"lead": "Referral: now or within 24 h", "text": "Discuss with nephrology as soon as possible and within 24 hours if there is stage 3 AKI, no clear cause, inadequate response to treatment, complications of AKI, a possible condition needing specialist treatment (such as vasculitis or glomerulonephritis), a renal transplant, or background CKD stage 4–5; refer immediately to nephrology or critical care if hyperkalaemia, metabolic acidosis, uraemic complications (such as pericarditis or encephalopathy), fluid overload or pulmonary oedema are not responding to medical management"}], "can_i_do_alone": {"alone": "Reviewing fluid balance and trends, examining the patient, withholding medicines that can cause or worsen AKI where appropriate, with pharmacist advice, sending bloods, and giving a 500 ml crystalloid bolus over less than 15 minutes and reassessing in a patient who is clinically dehydrated with no signs of fluid overload", "senior_opinion": "Any uncertainty about fluid status, a rising potassium, or a patient not responding to an initial fluid challenge", "senior_in_person": "A potassium of 6.5 mmol/litre or above or ECG changes, signs of fluid overload with worsening kidney function, suspected obstruction, or a patient who is unwell with AKI; any of these means a senior needs to see the patient now, not just discuss by phone"}, "escalate_now_if": ["Potassium is 6.5 mmol/litre or above, or there are ECG changes of hyperkalaemia", "There are signs of pulmonary oedema or fluid overload alongside worsening kidney function", "Urine output remains very low despite an appropriate fluid challenge", "There is suspected urinary tract obstruction", "The patient is becoming unwell or acidotic"], "document": "Record the fluid balance trend, examination findings on fluid status, medications stopped, bloods sent and results, fluid given and the response, and the plan agreed with the senior including any follow-up blood tests arranged.", "fail": "An unsafe response ignores a rising potassium, gives large volumes of fluid to a patient who is already overloaded, or continues a nephrotoxic medication unnecessarily.", "pass": "A safe response stages the AKI appropriately, assesses fluid status before treating, withholds medicines that can worsen AKI where appropriate, and escalates when there are high-risk features.", "high_performance": "An excellent response checks for a reversible cause such as catheter blockage or obstruction before assuming a purely medical cause, proactively arranges follow-up bloods to track the trend, and explains to the patient in plain terms why certain medications have been stopped.", "one_thing": "If you only remember one thing: assess fluid status clinically before giving fluid, and always check the potassium.", "img_note": "In UK practice, AKI is often flagged automatically by the laboratory system as a staged alert on the blood result; take this seriously even if the patient looks well. Reviewing and withholding medicines that can cause or worsen AKI (such as NSAIDs, ACE inhibitors/ARBs and diuretics) is a key early action, and a dipstick plus a clear plan for ultrasound and nephrology referral timing (both have explicit NICE timeframes) completes the initial work-up.", "source": "NICE guideline NG148, Acute kidney injury: prevention, detection and management (published 18 December 2019, last updated 16 October 2024; replaced CG169): sets the AKI detection criteria (creatinine rise of 26 micromol/litre or more within 48 hours, a 50% rise within 7 days, or urine output under 0.5 ml/kg/hour for more than 6 hours in adults), urine dipstick on suspicion, ultrasound within 24 hours (within 6 hours if pyonephrosis is suspected), and when to refer to nephrology immediately or within 24 hours. Fluid resuscitation principles follow NICE CG174, Intravenous fluid therapy in adults in hospital (last updated May 2017). KDIGO Clinical Practice Guideline for Acute Kidney Injury (March 2012), for staging (stage 2 = 2.0–2.9 times baseline).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Patel on ward 14. She's passed only 60 millilitres of urine in 6 hours, and her creatinine has risen from 68 before surgery to 142 micromol/litre, just over twice baseline, so stage 2 AKI.", "B": "she's day two post major abdominal surgery and has been on an NSAID for pain. She weighs about 70 kg.", "A": "she looks clinically dry, BP is on the lower side, I've stopped the NSAID, sent bloods including potassium, and given a fluid challenge.", "R": "I'd like your advice on further fluid management and whether she needs a catheter to monitor output closely, can you review her."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-05", "title": "Hyperkalaemia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"The lab just rang, Mr Owusu's potassium has come back at 6.8, they said to call you urgently.\"", "nurse_call": [{"lead": "Monitor + ECG now", "text": "Ask the nurse to put the patient on a cardiac monitor immediately and get a 12-lead ECG done now"}, {"lead": "Haemolysed? Don't assume", "text": "Ask whether the sample could have been haemolysed or taken poorly, but don't assume the result is spurious — the ECG comes first, and treat straight away if it shows changes; a blood-gas potassium can itself be affected by haemolysis, so it neither confirms nor excludes a spurious result"}, {"lead": "Repeat sample + VBG", "text": "Ask for a repeat lithium-heparin sample to be sent to the lab, plus a VBG for a rapid potassium result"}, {"lead": "Calcium + insulin–glucose ready", "text": "Ask the nurse to have IV access, calcium gluconate, and an insulin and dextrose infusion ready at the bedside"}, {"lead": "Meds + renal history", "text": "Ask about any recent medication changes, particularly anything that raises potassium, and the patient's renal function history"}], "first_five_minutes": [{"lead": "Read the ECG", "text": "Look at the ECG yourself immediately for peaked (tented) T waves, flattened or absent P waves, a broad QRS complex, bradycardia, a sine-wave pattern or VT"}, {"lead": "ECG changes → calcium gluconate", "text": "If there are ECG changes, give IV calcium gluconate straight away to stabilise the heart — UKKA's dose is 30 ml 10% calcium gluconate by slow IV injection over 10 minutes into a large vein; repeat the ECG and consider a further dose after 5 minutes if changes persist (check BNF/local protocol). In cardiac arrest or peri-arrest, the resus team or a senior gives calcium chloride instead. Use the calcium salt your trust's protocol specifies."}, {"lead": "Insulin–glucose", "text": "Give IV insulin with glucose to shift potassium into cells — the UKKA regimen is 10 units soluble insulin in 25 g glucose by IV infusion over 15–30 minutes (recommended at potassium 6.5 mmol/L or above, suggested at 6.0–6.4 mmol/L; check BNF/local protocol for the glucose preparation: 250 ml 10%, 125 ml 20% or 50 ml 50%). Check blood glucose before starting and at 0, 30, 60, 90, 120, 180, 240, 300 and 360 minutes; if the pre-treatment glucose is below 7.0 mmol/L, follow with 10% glucose IV at 50 ml/hour for 5 hours to prevent hypoglycaemia"}, {"lead": "Salbutamol as an add-on", "text": "Give nebulised salbutamol 10-20 mg as an adjunct to insulin–glucose at potassium 6.5 mmol/L or above (it may be used at 6.0-6.4 mmol/L) — never on its own; consider only 10 mg if the patient has ischaemic heart disease"}, {"lead": "Stop K⁺-raising drugs", "text": "Stop medicines that raise potassium: ACE inhibitors, ARBs, mineralocorticoid receptor antagonists (spironolactone, eplerenone), potassium-sparing diuretics (amiloride), trimethoprim, NSAIDs, potassium supplements, and potassium-containing IV fluids"}, {"lead": "Potassium binder", "text": "Once the acute threat is treated, ask your senior about a potassium binder; they will decide which, per your trust's protocol"}, {"lead": "Repeat K⁺", "text": "Repeat the potassium to check the response and catch rebound — UKKA suggests at least 1, 2, 4, 6 and 24 hours after treatment; follow your local protocol"}, {"lead": "Treat the cause", "text": "Establish the underlying cause, particularly AKI, and treat it alongside the potassium"}], "can_i_do_alone": {"alone": "Getting an urgent ECG, taking a repeat sample, stopping potassium-raising medications, and giving calcium gluconate, insulin–glucose and nebulised salbutamol as an adjunct (never on its own) following a clear local protocol, provided you are competent and supported to prescribe these", "senior_opinion": "A potassium between 6.0 and 6.4 mmol/L with no ECG changes and a clear, reversible cause already being corrected", "senior_in_person": "A potassium of 6.5 mmol/L or above, or any ECG changes at any potassium level — 6.5 or above is UKKA's severe band, and ECG changes at any level need emergency treatment. Get a senior there now rather than settling for a phone call."}, "escalate_now_if": ["There are ECG changes consistent with hyperkalaemia", "Potassium is 6.5 mmol/L or above", "The patient becomes unwell, has palpitations, or collapses", "Potassium does not fall despite treatment", "There is underlying AKI that may need dialysis"], "document": "Record the potassium result and time received, the ECG findings with a copy filed, all treatments given with doses and times, repeat blood results, and the escalation discussion including the time the senior was contacted.", "fail": "An unsafe response waits for a senior before giving calcium gluconate in the presence of ECG changes, or forgets to monitor blood glucose for six hours after insulin–glucose.", "pass": "A safe response gets an immediate ECG, treats promptly according to a recognised protocol, and escalates any significant or symptomatic hyperkalaemia.", "high_performance": "An excellent response identifies and addresses the underlying cause early, anticipates the need for renal input in a patient with CKD, and arranges repeat potassium monitoring at an appropriate interval without being asked.", "one_thing": "If you only remember one thing: if there are ECG changes, give calcium gluconate immediately, it does not lower potassium but it protects the heart while you treat the underlying level.", "img_note": "This is one of the few situations on the ward where you should act before waiting for a senior to arrive if there are ECG changes; familiarise yourself with your trust's specific hyperkalaemia protocol and drug doses on your first week, as insulin–glucose regimens and monitoring requirements vary slightly between trusts.", "source": "UK Kidney Association, Clinical Practice Guideline: Treatment of Acute Hyperkalaemia in Adults (updated July 2026; first published July 2020) — severity bands (mild 5.5–5.9, moderate 6.0–6.4, severe 6.5 mmol/L or above) and the hospital algorithm used here: calcium gluconate for ECG changes (calcium chloride preferred in cardiac arrest or peri-arrest), insulin–glucose with a 10% glucose follow-on if pre-treatment glucose is below 7.0 mmol/L, 6-hour glucose monitoring, salbutamol as an adjunct, SZC or patiromer, and potassium checks at 1, 2, 4, 6 and 24 hours. The July 2026 update graded the evidence for IV calcium as 'suggest' (2C) but keeps it for ECG changes. Resuscitation Council UK 2025 Special Circumstances Guidelines (published 27 October 2025) give the same insulin–glucose and salbutamol doses and prefer 10 ml 10% calcium chloride where available. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Owusu on ward 9, his potassium has come back at 6.8 and his ECG shows tented T waves.", "B": "he has known CKD and was recently started on an additional BP medication.", "A": "I've given 30 ml of 10% calcium gluconate, his pre-treatment glucose was 6.1, so I've given insulin with dextrose and started 10% glucose at 50 ml an hour, with glucose checks for 6 hours. I've stopped the new BP medication, and a repeat sample is sent.", "R": "I'd like you to come and review him now, and I think we need to discuss renal input given his background kidney disease in case he needs dialysis."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-06", "title": "Hypoglycaemia in an inpatient", "fpc_tags": ["Clinical assessment", "Communication and care"], "scenario": "Nurse bleeps: \"Mrs Lewis's blood glucose is 2.8, she's a known diabetic and seems a bit drowsy but is talking to us.\"", "nurse_call": [{"lead": "Conscious? Can swallow?", "text": "Ask whether the patient is conscious, able to swallow safely, and able to cooperate with treatment"}, {"lead": "Oral glucose now", "text": "If conscious and able to swallow, ask the nurse to give a fast-acting carbohydrate immediately, such as a glucose drink or tablets, rather than waiting for you"}, {"lead": "Insulin/meds + stop IV insulin", "text": "Ask about recent insulin or oral hypoglycaemic doses and the timing of the last meal — and if an IV insulin infusion is running, stop it now"}, {"lead": "Recheck in 10–15 min", "text": "Ask for a repeat blood glucose to be checked in 10 to 15 minutes after initial treatment"}, {"lead": "Stay with the patient", "text": "Ask the nurse to stay with the patient and monitor consciousness closely until it is resolved"}], "first_five_minutes": [{"lead": "On IV insulin? Stop it", "text": "If the patient is on an IV insulin infusion, stop it immediately, then treat; once glucose is above 4.0 mmol/L and the hypo is fully treated, restart the infusion after reviewing the rate (and whether 10% glucose should run alongside) with a senior or the diabetes team — do not leave it off, especially in type 1 diabetes"}, {"lead": "Treat on the bedside reading", "text": "Treat on the bedside capillary glucose reading without delay; do not wait for a laboratory result before treating"}, {"lead": "Swallowing: 15–20 g oral or gel", "text": "If the patient is conscious, cooperative and able to swallow safely, give 15 to 20 grams of fast-acting carbohydrate by mouth; if confused or uncooperative but still able to swallow, the guideline suggests 2 tubes of 40% glucose gel squeezed between the teeth and gums, or glucagon 1 mg IM if the gel is ineffective"}, {"lead": "Can’t swallow: IV glucose / IM glucagon", "text": "If the patient is unconscious, fitting or unable to swallow safely, assess ABCDE (airway first, give oxygen) and call for help, then give IV glucose: JBDS gives 100 ml of 20% glucose or 200 ml of 10% glucose over 15 minutes, using the smallest possible volume in renal or cardiac failure and the preparation your trust stocks; if using a larger bag, set the pump so the whole bag is not given. If there is no IV access, give glucagon 1 mg IM and keep trying for IV access; glucagon works less well after a sulfonylurea, alcohol excess, liver disease or poor intake; use caution if anticoagulated, and give it only once"}, {"lead": "Recheck at 10–15 min", "text": "Recheck blood glucose 10 to 15 minutes after oral treatment (10 minutes after IV glucose or glucagon) and repeat the treatment if still below 4.0 mmol/L; if it is still below 4.0 mmol/L after 3 oral treatments or 30 to 45 minutes, move to IV glucose or IM glucagon"}, {"lead": "Then longer-acting carbohydrate", "text": "Once glucose is above 4.0 mmol/L and the patient has recovered, give a longer-acting carbohydrate snack of about 20 grams, such as two biscuits or a slice of bread, or the next meal if due; give double (about 40 grams) if glucagon was used"}, {"lead": "Find the cause", "text": "Review the cause: check the timing and dose of diabetes medication, recent food intake, and renal function. If a sulfonylurea or long-acting insulin caused it, the risk of hypoglycaemia can persist for up to 24 to 36 hours after the last dose, especially with renal impairment, and some patients need a continuous glucose infusion, so discuss this with your senior or the diabetes team"}, {"lead": "Adjust the plan", "text": "Adjust the diabetes medication plan for the next dose if needed, in discussion with the diabetes team or senior"}, {"lead": "Don’t omit insulin that’s due", "text": "Don’t omit an insulin injection that is due — the dose about to be given is unlikely to be the one active at the time of the hypo. Review which dose was active at the time and adjust the regimen with a senior or the diabetes team; if unsure about the next dose, discuss it with the diabetes team"}], "can_i_do_alone": {"alone": "Giving oral fast-acting carbohydrate to a conscious patient able to swallow safely, giving IV glucose or IM glucagon to a patient who is unconscious or cannot swallow safely (a drowsy patient who can still swallow gets oral glucose or 40% glucose gel) following a clear local protocol, and making sure glucose monitoring continues and insulin that is due is not omitted (any decision to hold a dose, such as a mealtime dose when the patient is not eating, is made with the diabetes team or a senior)", "senior_opinion": "Recurrent hypoglycaemia despite treatment, uncertainty about why it happened, or a need to change a longer-term insulin regimen", "senior_in_person": "A patient who remains unconscious or does not improve despite appropriate treatment, or any seizure associated with the hypoglycaemia; this needs a senior at the bedside now, as it may indicate a cause beyond simple hypoglycaemia"}, "escalate_now_if": ["Consciousness does not improve despite appropriate treatment", "There is a seizure", "Hypoglycaemia recurs repeatedly despite treatment and dietary measures", "The patient cannot swallow safely and you cannot get IV access, or glucose is still below 4.0 mmol/L 10 minutes after IM glucagon — keep trying for IV access and get a senior to the bedside now (intraosseous access is a senior decision)", "There is no clear explanation for the hypoglycaemia"], "document": "Record the initial and repeat blood glucose readings with times, the treatment given, the patient's response, the likely cause identified, any changes made to the diabetes medication plan, and the plan for regular capillary glucose monitoring for at least the next 24 to 48 hours.", "fail": "An unsafe response waits for a doctor to arrive before treating a conscious patient, gives oral carbohydrate to a patient who cannot swallow safely, or does not recheck the glucose after treatment.", "pass": "A safe response treats the hypoglycaemia promptly according to the patient's conscious level, rechecks glucose, and identifies the likely cause.", "high_performance": "An excellent response proactively agrees an adjusted insulin plan with the diabetes team or a senior to prevent recurrence, communicates clearly with the patient about why this happened, and involves the diabetes specialist team when the pattern is recurrent or the regimen is complex.", "one_thing": "If you only remember one thing: treat the hypoglycaemia first, based on the point-of-care glucose, before you work out why it happened.", "img_note": "Many UK wards keep a \"hypo box\" of fast-acting glucose treatments, and nursing staff are usually trained to treat a conscious hypoglycaemic patient immediately without waiting for you; where agreed locally, IV glucose or IM glucagon may also be given under a patient group direction, and JBDS recommends a PRN rescue prescription for everyone on insulin or a sulfonylurea. Your role is often more about reviewing the cause and adjusting the medication plan afterwards.", "source": "Joint British Diabetes Societies for Inpatient Care (JBDS-IP), JBDS 01: The Hospital Management of Hypoglycaemia in Adults with Diabetes Mellitus, revised January 2023 — sets the <4.0 mmol/L treatment threshold, 15–20 g oral carbohydrate with 10–15 minute rechecks, IV glucose and IM glucagon doses, 20 g (40 g after glucagon) follow-on carbohydrate, not omitting insulin that is due, and 24–36 hour persistence with sulfonylureas or long-acting insulin. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Lewis on ward 3, her blood glucose was 2.8 and she was drowsy but conscious.", "B": "she's an insulin-treated diabetic admitted for a chest infection and has been eating poorly.", "A": "I gave oral fast-acting carbohydrate; her repeat glucose is now 5.2, she's had a follow-on snack of two biscuits and is back to her normal self, but her insulin doses haven't been adjusted for her reduced appetite.", "R": "I'd like your advice on adjusting her insulin regimen while her appetite is reduced, and whether the diabetes team should review her."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-07", "title": "A fall on the ward", "fpc_tags": ["Clinical assessment", "Holistic planning", "Quality improvement"], "scenario": "Nurse bleeps: \"Mr Thompson's had a fall getting out of bed, he's on the floor, conscious, but says his hip hurts.\"", "nurse_call": [{"lead": "Safe to move?", "text": "Ask the nurse to check for immediate danger and obvious injury before any move; a patient with no suspected major injury can usually be safely assisted up, but suspected fracture or spinal injury needs trauma precautions and flat-lifting equipment rather than a standard hoist"}, {"lead": "Conscious? Head strike?", "text": "Ask whether the patient is conscious, talking normally, and whether there was any head strike or loss of consciousness"}, {"lead": "Anticoagulants?", "text": "Ask whether the patient is on any blood-thinning medication"}, {"lead": "Obs once safe", "text": "Ask for a full set of observations to be done once it is safe to do so"}, {"lead": "Warm + equipment", "text": "Ask the nurse to keep the patient warm and comfortable, and, because a hip fracture is possible, to have flat-lifting equipment ready (such as a scoop stretcher or flat-lift device) — not a sling hoist"}], "first_five_minutes": [{"lead": "Assess before moving", "text": "Assess for injury before moving the patient; move them safely once assessed, using flat-lifting equipment and trauma precautions if a fracture or spinal injury is suspected — being on the floor isn't itself a reason to leave them there"}, {"lead": "Head injury?", "text": "Ask about and look for any head injury — treat an unwitnessed fall, or one the patient can't clearly recall, as a possible head injury even with no reported strike, and ask for neurological observations per your trust's post-fall protocol"}, {"lead": "Hip fracture signs", "text": "Examine for signs of limb fracture, particularly looking for a shortened and externally rotated leg suggesting a hip fracture. If a hip fracture is suspected, offer immediate analgesia, including if the patient is cognitively impaired (drug and dose per local protocol), and refer urgently to orthopaedics"}, {"lead": "Anticoagulated → CT pathway", "text": "If a head injury has occurred or can't be excluded, check whether the patient is on an anticoagulant or antiplatelet (other than aspirin alone) — with no other indication for a CT head, NICE NG232 says consider a CT head within 8 hours of the injury, or within the hour if more than 8 hours have passed. Whether or not they are anticoagulated, anyone who has had any loss of consciousness or amnesia since the injury and is 65 or over (or has a bleeding or clotting disorder) needs a CT head within 8 hours of the injury, or within the hour if more than 8 hours have already passed. This is a standard pathway decision, not something that needs to wait for a senior to review first unless you're unsure — request it in line with your trust's imaging referral rules"}, {"lead": "Warfarin: INR + bloods", "text": "Check the INR, FBC, U&E and group and save, and discuss with a senior whether to withhold or reverse the warfarin — this matters for both the CT head result and hip surgery"}, {"lead": "Obs + glucose", "text": "Take a full set of observations and a blood glucose. Leave lying and standing BP until a hip fracture has been excluded — it belongs in the later falls assessment"}, {"lead": "Imaging", "text": "Arrange appropriate imaging based on findings, such as a hip or limb X-ray or a CT head scan if indicated"}, {"lead": "Incident report + cause", "text": "Complete your trust's falls incident report and consider what caused the fall"}], "can_i_do_alone": {"alone": "A full assessment of a conscious patient with no obvious serious injury, arranging appropriate X-rays, applying the NG232 CT-timing pathway after a possible head injury in a patient on anticoagulants or antiplatelets (other than aspirin alone), and completing the incident report and falls risk reassessment", "senior_opinion": "Any uncertainty about whether the NG232 CT criteria apply, a new neurological finding, or any case where the mechanism or history is genuinely unclear", "senior_in_person": "Reduced consciousness, a new focal neurological deficit, a seizure, more than one episode of vomiting, signs of a skull fracture, suspected spinal injury, or neurological deterioration on neuro obs (such as a GCS drop sustained for 30 minutes or more) need a senior now. A suspected hip or long-bone fracture with no neurological concern is usually an orthopaedic referral plus analgesia, not an automatic senior-at-bedside call"}, "escalate_now_if": ["There is new confusion or a reduced level of consciousness after the fall (a brief loss of consciousness with full recovery follows the NG232 CT pathway below — tell your senior)", "He is anticoagulated and the CT head shows any intracranial injury, or the CT can't be done within the NG232 time window", "Suspected spinal injury — keep him flat with trauma precautions and get a senior now (a suspected hip fracture alone needs urgent orthopaedic referral and analgesia)", "There is any new focal neurological deficit, a post-traumatic seizure, more than one episode of vomiting, or any sign of an open, depressed or basal skull fracture — NG232 says CT head within 1 hour", "Neurological observations show deterioration — a sustained drop in GCS (even 1 point for at least 30 minutes), new agitation or abnormal behaviour, severe or increasing headache, persistent vomiting, or new signs such as unequal pupils — NG232 says urgently reassess and consider an immediate CT head", "Observations are abnormal or the patient does not return to their baseline"], "document": "Record the circumstances of the fall as described, examination findings including neurological and limb assessment, anticoagulation status, observations, imaging arranged, the falls incident report, and any safety measures put in place afterwards.", "fail": "An unsafe response moves a patient with a suspected fracture before adequate assessment, misses a head injury in a patient on anticoagulation, or fails to complete an incident report.", "pass": "A safe response assesses for injury before moving the patient, checks anticoagulation status, arranges appropriate imaging, and documents the incident properly.", "high_performance": "An excellent response also reviews why the fall happened, such as medication, mobility aids, or environmental factors, and updates the falls risk assessment and care plan to try to prevent a repeat event.", "one_thing": "If you only remember one thing: assess before you move them, and treat an unwitnessed or unclear fall as a possible head injury even with no reported strike — especially if they're anticoagulated.", "img_note": "Falls are a recognised patient safety incident in the National Health Service and must be formally reported through your trust's incident reporting system, usually an electronic system; this is not just paperwork, it feeds into ward-level falls prevention reviews, and completing it properly is a genuine part of good practice, not an optional extra.", "source": "NICE guideline NG232, Head injury: assessment and early management (May 2023, replaced CG176): rec 1.5.13 — for people with a head injury on anticoagulant or antiplatelet treatment (excluding aspirin monotherapy) and no other CT indication, consider CT head within 8 hours of injury, or within the hour if presenting more than 8 hours after it; rec 1.5.9 — do CT head within 8 hours of injury (or within the hour if more than 8 hours have passed) if loss of consciousness or amnesia plus age 65 or over; rec 1.5.8 — 1-hour CT criteria; recs 1.9.13 and 1.9.15 — signs of neurological deterioration needing urgent reassessment and consideration of immediate CT. NICE quality standard QS86, Falls (2015, updated April 2025), statements 4–6: after an inpatient fall, check for fracture and spinal injury before moving, use safe manual handling if either is suspected, and complete a medical examination; post-fall protocols include neurological observations where head injury has occurred or can't be excluded (e.g. unwitnessed falls). NICE guideline NG249, Falls: assessment and prevention in older people and in people 50 and over at higher risk (April 2025, replaced CG161), for the inpatient comprehensive falls assessment (including lying and standing BP and medication review); it does not cover immediate post-fall medical assessment. NICE CG124, Hip fracture: management (last updated January 2023), rec 1.3.2, for immediate analgesia in suspected hip fracture", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Thompson on ward 6, he's had a fall and I'm concerned about a possible hip fracture.", "B": "he's 82, on warfarin for AF, and was trying to get to the bathroom unassisted; he doesn't clearly recall the fall, so I'm treating it as a possible head injury even though no strike was witnessed.", "A": "he's conscious, GCS 15, his right leg is shortened and externally rotated, observations are stable.", "R": "I'm arranging an urgent hip X-ray, orthopaedic referral, analgesia, and an INR with group and save. Because he's 82 and can't recall the fall, NG232 says do a CT head within 8 hours of the injury (within the hour if more than 8 hours have passed), and he's also on warfarin. Can you confirm you're happy with that plan, and advise on the warfarin?"}, "checked": "3 Oct 2026"}, {"id": "BLEEP-08", "title": "Post-operative fever", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"Mrs Hughes's temperature has gone up to 38.6, she's four days post her bowel operation.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the current NEWS2 score"}, {"lead": "Localising symptoms?", "text": "Ask whether there are any localising symptoms: cough, urinary symptoms, wound redness or discharge, calf swelling, or line site concerns"}, {"lead": "Check wound + lines", "text": "Ask the nurse to check the wound and all line sites now; you'll decide which samples to send when you assess, but take any blood cultures or other microbiology samples before the first antibiotic dose, and don't wait for a confirmed source before taking blood cultures if the NEWS2 is 5 or more and you suspect infection"}, {"lead": "Looks unwell?", "text": "Ask whether the patient looks generally unwell or is behaving as usual"}, {"lead": "Operation + date", "text": "Ask for the operation date and type to be confirmed so you can think about the likely time course of complications"}], "first_five_minutes": [{"lead": "NEWS2 first", "text": "Review the NEWS2 score and decide urgency before working through the differential in detail: if you suspect infection, NICE NG253 treats a score of 7 or more as high risk, 5 or 6 as medium risk, 1 to 4 as low risk and 0 as very low risk, and a single parameter scoring 3 needs a high-priority review by a clinician at FY2 level or above"}, {"lead": "Work through the causes", "text": "Work through the common post-operative fever causes systematically: the wound and surgical site, the chest, the urinary tract, a DVT, any drip or line site, and — critically, this many days after bowel surgery — a possible intra-abdominal source such as an anastomotic leak or collection"}, {"lead": "Wound", "text": "Examine the surgical wound for redness, discharge, or dehiscence"}, {"lead": "Chest", "text": "Listen to the chest for signs of a respiratory infection; don't default to assuming atelectasis without actually examining for signs of infection"}, {"lead": "Urine", "text": "Check for urinary symptoms and consider urine analysis; if a catheter is in place, send a catheter specimen (from the sampling port, aseptically, and from the new catheter if it has been changed) for culture before any antibiotic, and don't dipstick catheter urine; if the catheter has been removed, send a midstream specimen"}, {"lead": "Lines + abdomen", "text": "Examine all cannula and line sites for redness or discharge, and consider whether an infected line needs to come out — and after bowel surgery, keep a low threshold for blood cultures (before any antibiotic), FBC, CRP and lactate, and for a CT abdomen if there's any abdominal pain, distension, new ileus or systemic concern, since an anastomotic leak can present as 'just a fever'"}, {"lead": "Calves + VTE prophylaxis", "text": "Check calves for swelling or tenderness as a prompt for possible DVT, and because her clinical condition has changed, reassess her VTE and bleeding risk and check that the thromboprophylaxis prescribed is actually being given"}], "can_i_do_alone": {"alone": "A systematic assessment working through the common causes, examining the wound and line sites, sending investigations that are actually indicated by what you find (not a reflex set of cultures and swabs — but at NEWS2 5 or more with suspected infection, NICE NG253 sets out a blood panel that includes blood cultures and lactate), starting simple measures such as antipyretics and encouraging mobilisation and deep breathing exercises, and giving 250 ml crystalloid boluses (ideally over 10 to 15 minutes) if high-risk sepsis criteria are met, unless contraindicated, reassessing after each, up to 1,000 ml in total including fluid already given (get senior advice if not improved by then), and giving the first dose of broad-spectrum IV antibiotics within 1 hour of the NEWS2 being calculated per your trust's sepsis pathway", "senior_opinion": "Any suspected wound infection needing a decision about antibiotics or a return to theatre, or any case where the source remains unclear after initial assessment; if you suspect infection at low risk (NEWS2 1 to 4), NICE NG253 asks for assessment by a clinician at FY2 level or above to decide whether antibiotics can be deferred for up to 6 hours while the source is clarified", "senior_in_person": "A patient with suspected infection and a NEWS2 of 5 or more or a single parameter scoring 3, mottled or ashen skin, suspected wound dehiscence or an intra-abdominal collection, or any deterioration; NICE NG253 expects review by a clinician at FY2 level or above within 1 hour at medium risk and urgent assessment with antibiotics within 1 hour at high risk, so these need the surgical registrar or on-call team to see the patient promptly, not just a phone discussion"}, "escalate_now_if": ["NEWS2 of 7 or more with suspected or confirmed infection (high risk under NICE NG253): urgent assessment by a clinician at FY2 level or above and broad-spectrum IV antibiotics within 1 hour; refer to the senior clinical decision maker (ST3 or above), and give an IV fluid bolus within 1 hour unless contraindicated, starting with 250 ml of crystalloid, ideally over 10–15 minutes", "NEWS2 of 5 or 6 with suspected or confirmed infection (medium risk under NICE NG253): review by a clinician at FY2 level or above within 1 hour, and treat as high risk if lactate is over 2 mmol/litre or there is acute kidney injury", "A single NEWS2 parameter scoring 3 with suspected or confirmed infection: request a high-priority review by a clinician at FY2 level or above", "Mottled or ashen skin, cyanosis, a non-blanching rash, or deterioration or no improvement since the last NEWS2 or intervention — NICE NG253 says to consider treating the risk as higher than the score alone suggests", "There are signs of wound dehiscence or an abdominal collection", "There is a suspected DVT or PE", "The fever is associated with hypotension or confusion suggesting sepsis", "No clear source is found and the patient remains febrile and unwell"], "document": "Record the NEWS2 score and the time it was calculated, the sepsis risk level if you suspect infection, the temperature trend, the systematic examination findings for each potential source, investigations sent, any treatment given, and the plan agreed including the time of any senior review.", "fail": "An unsafe response starts broad-spectrum antibiotics without examining the wound or considering other sources, dismisses a fever in an unwell-looking patient as routine post-operative fever without proper assessment, or delays senior review and antibiotics in a patient with suspected infection at high risk on NEWS2.", "pass": "A safe response works through the common causes systematically, sends appropriate investigations, and escalates in line with the NEWS2 risk level, or if the patient looks unwell or no clear benign cause is found.", "high_performance": "An excellent response considers the specific operation type and timeline when weighing up the differential, for example being more concerned about an intra-abdominal source after bowel surgery than after a straightforward orthopaedic procedure, and communicates proactively with the surgical team rather than treating this purely as a medical issue.", "one_thing": "If you only remember one thing: after bowel surgery, a 'routine' post-op fever still needs intra-abdominal infection actively excluded, not just the wound and chest checked off a list.", "img_note": "On surgical wards, the operating surgical team should usually be kept informed of any post-operative complication even if a medical doctor reviews first, since decisions about wound exploration or return to theatre sit with them; find out early who covers the surgical on-call rota out of hours.", "source": "No single national guideline covers post-operative fever: the systematic source-by-source approach (including actively excluding an anastomotic leak after bowel surgery) is standard UK surgical practice, not guideline text. Guideline-backed parts: NICE NG253, Suspected sepsis in people aged 16 and over: recognition, assessment and early management (published Nov 2025, last updated Sep 2026), for NEWS2-based risk levels, FY2-or-above review, blood panel and antibiotic timings, and its note that a temperature rise can be a physiological response after surgery; NICE NG125, Surgical site infections: prevention and treatment (2019, last updated Aug 2020; last reviewed May 2023, no update planned), which recommends antibiotics covering likely organisms when SSI is suspected by cellulitis; NICE NG89, Venous thromboembolism in over 16s (2018, updated 2019; last reviewed Sep 2024, no update planned), for reassessing VTE and bleeding risk when clinical condition changes; and NICE NG113 (rec 1.1.4) for catheter and midstream urine sampling, with the UKHSA catheter UTI diagnostic tool (v4.0, May 2025; a primary-care quick reference tool, applied to the ward by extrapolation) for not dipsticking catheter urine.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Hughes on ward 11, she's four days post a bowel resection with a temperature of 38.6.", "B": "her recovery had otherwise been unremarkable until today.", "A": "her wound looks mildly red at one edge with no discharge, chest is clear, no urinary symptoms, NEWS2 is 3 with no single parameter scoring 3, so low risk under the NICE sepsis guideline, but given she's four days post bowel surgery I'm not reassured by a mild wound finding alone — I've taken blood cultures before any antibiotic is started and sent FBC, CRP and lactate, and I'm keeping intra-abdominal infection on the differential.", "R": "I'd like your opinion on whether she needs a CT abdomen now or whether we can watch and reassess in a few hours. She's low risk, so I'd also like your decision on whether antibiotics can be deferred for up to 6 hours while we clarify the source. Can you come and review her with me?"}, "checked": "3 Oct 2026"}, {"id": "BLEEP-09", "title": "New-onset atrial fibrillation on the ward", "fpc_tags": ["Clinical assessment", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Clarke, who's on antibiotics for a chest infection, has an irregular rhythm on his heart rate monitor at 140, and he says he feels a bit dizzy.\"", "nurse_call": [{"lead": "Obs incl. BP", "text": "Ask for the full set of observations including BP, and whether the patient is alert and talking normally"}, {"lead": "12-lead ECG now", "text": "Ask the nurse to get a 12-lead ECG done now to confirm the rhythm"}, {"lead": "New or known — since when?", "text": "Ask whether this is a known arrhythmia or a new finding, and when it was first noticed (check the monitor and obs chart), because the time of onset changes the management"}, {"lead": "Rest, monitor, IV kit", "text": "Ask the nurse to keep the patient resting and monitored, and have IV access equipment ready"}, {"lead": "Chest pain? Breathless? Collapse?", "text": "Ask about any chest pain, breathlessness, or collapse associated with the dizziness"}], "first_five_minutes": [{"lead": "Confirm on a 12-lead", "text": "Confirm the rhythm with a 12-lead ECG rather than relying on the monitor alone"}, {"lead": "Stable or unstable?", "text": "Assess for life-threatening features: shock (low BP with signs of poor perfusion), syncope with severe or ongoing hypotension, myocardial ischaemia (chest pain or ischaemic ECG changes), or severe heart failure with pulmonary oedema"}, {"lead": "Infection + HR 140 = sepsis check", "text": "A heart rate of 140 scores 3 on NEWS2, and he has an infection: calculate the full NEWS2, run the NICE NG253 sepsis risk assessment, and request the high-priority FY2-or-above review it requires. Treat sepsis and fluid status before rate control — a fast AF can be driven by sepsis and hypovolaemia"}, {"lead": "Unstable → emergency", "text": "If the patient has life-threatening features caused by the arrhythmia, this is an emergency: get immediate senior and cardiology involvement, and the crash team if needed — the treatment is synchronised DC cardioversion by a skilled senior"}, {"lead": "Stable → find the trigger", "text": "If stable, identify and treat any obvious precipitant, such as infection, electrolyte disturbance, pain, or excess alcohol or caffeine"}, {"lead": "K⁺, Mg²⁺ ± troponin", "text": "Check electrolytes, including potassium and magnesium, and correct any abnormality; also check troponin if there's any chest pain or concern about an ischaemic precipitant"}, {"lead": "Rate or rhythm control", "text": "Establish the time of onset (under 48 hours, over 48 hours or uncertain) — it shapes the rate-or-rhythm strategy, which your senior decides. Your senior chooses the rate-control drug; never give a calcium-channel blocker (such as verapamil or diltiazem) in suspected acute decompensated heart failure or known heart failure with reduced ejection fraction"}, {"lead": "Heparin, stroke + bleeding risk", "text": "Assess stroke risk with CHA₂DS₂-VASc and bleeding risk with ORBIT. NICE advises offering heparin at initial presentation of new-onset AF unless contraindicated — so discuss heparin with your senior now rather than deferring it by default"}], "can_i_do_alone": {"alone": "Arranging an immediate ECG, checking and correcting electrolytes, and starting rate control in a stable patient only once a senior has agreed the strategy and the drug", "senior_opinion": "Any new AF in a stable patient where you are deciding between rate and rhythm control or on rate-control drug choice, or any question about starting heparin or longer-term anticoagulation", "senior_in_person": "Any patient with life-threatening features caused by the arrhythmia, meaning shock, syncope with severe or ongoing hypotension, myocardial ischaemia, or severe heart failure with pulmonary oedema; this is an emergency needing the medical registrar or cardiology team and potentially the crash team now"}, "escalate_now_if": ["The patient is in shock (low BP with signs of poor perfusion), has myocardial ischaemia (chest pain or ischaemic ECG changes), or has severe heart failure with pulmonary oedema attributable to the arrhythmia", "There is syncope or collapse with severe or ongoing hypotension, or reduced consciousness", "The heart rate is very fast and not responding to initial measures", "There is a significant electrolyte abnormality contributing to the rhythm", "You are unsure whether this is new AF or a different arrhythmia"], "document": "Record the time the arrhythmia was noted and the best estimate of onset (or that onset is uncertain), the ECG findings, haemodynamic assessment, electrolyte results and correction, any rate control treatment given, stroke (CHA₂DS₂-VASc) and bleeding (ORBIT) risk, and the plan for heparin or anticoagulation and further monitoring agreed with the senior.", "fail": "An unsafe response treats new AF with a fast rate control drug without checking for haemodynamic instability, or ignores a correctable precipitant such as a low potassium.", "pass": "A safe response confirms the rhythm with an ECG, assesses for instability, corrects any obvious precipitant, and escalates promptly if the patient is unstable.", "high_performance": "An excellent response looks actively for the underlying trigger given the clinical context, such as infection in this scenario, establishes the time of onset because it shapes rate versus rhythm control, discusses heparin and anticoagulation risk and benefit with the senior rather than deferring the whole decision, and explains the new diagnosis to the patient in plain language.", "one_thing": "If you only remember one thing: decide first whether the patient is haemodynamically stable, this determines whether you are managing an emergency or a straightforward new diagnosis.", "img_note": "New AF in an acutely unwell patient, such as someone with an infection, can be linked to the acute illness, so look for and treat the trigger — but don't assume it will settle on its own. Don't assume anticoagulation automatically waits until the next day — NICE advises offering heparin at initial presentation of new-onset AF unless contraindicated, so assess stroke and bleeding risk and discuss it with a senior rather than deferring by default.", "source": "NICE guideline NG196, Atrial fibrillation: diagnosis and management — published April 2021, last updated June 2021, with minor changes in March 2025 that replaced links to technology-appraisal recommendations without changing the clinical recommendations; recs 1.1.2 (12-lead ECG to diagnose), 1.2.1–1.2.2 (CHA₂DS₂-VASc for stroke risk, ORBIT for bleeding risk), 1.7.3 (in heart failure, follow NICE's chronic heart failure guideline) and 1.8.1–1.8.10 (acute presentation: emergency cardioversion for life-threatening instability, rate or rhythm control by onset under 48 hours, or rate control if over 48 hours or uncertain, no calcium-channel blocker in acute decompensated heart failure, heparin at initial presentation). NICE NG106, Chronic heart failure in adults: diagnosis and management (published September 2018, last updated September 2025), rec 1.4.12: avoid verapamil and diltiazem in heart failure with reduced ejection fraction. Used alongside the Resuscitation Council UK adult tachyarrhythmia algorithm (2025 Guidelines, V3 updated March 2026) and its 2025 Adult advanced life support guideline for life-threatening features, synchronised cardioversion, \"identify and treat reversible causes\", and rate-control drug choice by ejection fraction. Alcohol and caffeine as precipitants: NG196 rec 1.7.14 names them as known precipitants in paroxysmal AF; looking for them in new-onset AF is standard clinical practice, not guideline text; NICE NG253, Suspected sepsis in people aged 16 or over (published 19 November 2025, last updated 23 September 2026), recommendation 1.6.2, requires a high-priority review by a clinician at FY2 or above when a single NEWS2 parameter scores 3; RCP NEWS2 (2017) scores a heart rate of 131 or above as 3.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Clarke on ward 7, he's gone into new AF with a rate of 140 and feels dizzy.", "B": "He's 72 with hypertension, being treated for a chest infection, no known heart problems previously; his CHA₂DS₂-VASc is 2.", "A": "his BP is 110 over 70, he's alert, ECG confirms AF, I've checked and his potassium and magnesium are normal, his NEWS2 heart-rate score is 3, so I've started the sepsis assessment, and his lactate and cultures are sent.", "R": "I'd like your advice on rate or rhythm control and on starting heparin or anticoagulation, can you review him given this is new and he's systemically unwell with infection."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-10", "title": "Acute confusion and possible delirium", "fpc_tags": ["Clinical assessment", "Ethics and law", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Bennett, who's being treated for a chest infection, has suddenly become confused and is trying to pull out his cannula, he wasn't like this yesterday.\"", "nurse_call": [{"lead": "Safe right now?", "text": "Ask whether the patient is at risk of harming himself or others right now, and ask the nurse to keep him safe while you arrive"}, {"lead": "Change from baseline?", "text": "Ask whether this is a sudden change from his normal baseline, and what his usual cognitive state is"}, {"lead": "Obs + glucose", "text": "Ask for a full set of observations and a blood glucose, as a treatable cause must be excluded first"}, {"lead": "New meds? Bladder/bowels?", "text": "Ask about any new medications started recently, and whether he has passed urine or opened his bowels normally"}, {"lead": "Calm reorientation", "text": "Ask the nurse to try calm reorientation and to avoid physical restraint unless there is an immediate safety risk"}], "first_five_minutes": [{"lead": "Glucose, sats, obs", "text": "Check blood glucose, oxygen saturations, and a full set of observations immediately, as acute confusion can be a sign of serious underlying illness. New confusion scores 3 on NEWS2 on its own; with his chest infection, that needs a high-priority sepsis review by a clinician at FY2 or above (NICE NG253)"}, {"lead": "Collateral history", "text": "Take a collateral history from nursing staff or family about the patient's normal baseline and the exact time course of the change"}, {"lead": "Look for causes", "text": "Examine for signs of infection, pain, urinary retention, constipation, or alcohol or drug withdrawal"}, {"lead": "Review the drug chart", "text": "Review the drug chart for any new or recently changed medications that could cause confusion"}, {"lead": "Capacity (decision-specific)", "text": "Assess capacity for the specific decision in front of you if there's reason to doubt he can make it — capacity is decision-specific and time-specific, not an all-or-nothing label"}, {"lead": "4AT", "text": "Use the 4AT tool to assess for delirium"}, {"lead": "Treat the cause first", "text": "Treat the underlying cause rather than just sedating the confusion, and use non-drug measures such as reorientation and a calm environment first"}, {"lead": "Drugs = last resort", "text": "If medication for agitation is genuinely needed because verbal and non-verbal de-escalation has failed or is inappropriate and he is distressed or a risk to himself or others, treat it as a last resort, not a first response — your senior decides on any drug (usually short-term haloperidol at the lowest dose, per local protocol); never give haloperidol in Parkinson's disease, dementia with Lewy bodies, known QTc prolongation or with other QT-prolonging drugs, and get a baseline ECG and correct electrolytes first; other antipsychotics are also dangerous in Parkinson's disease and Lewy body dementia, so get senior or specialist advice before any drug for agitation in these patients"}, {"lead": "Alcohol? Thiamine", "text": "If alcohol may be involved, offer parenteral thiamine if Wernicke's encephalopathy is suspected (keep a high index of suspicion, particularly if he is intoxicated), and prophylactic thiamine if he is a harmful or dependent drinker who is malnourished or at risk of malnourishment, has decompensated liver disease or is in acute withdrawal (dose and route per local protocol)"}], "can_i_do_alone": {"alone": "A full assessment for reversible causes, sending basic investigations, reviewing medications, and starting non-drug management such as reorientation, good lighting, and involving family or carers to help calm the patient", "senior_opinion": "Any patient requiring consideration of sedative medication for agitation, any uncertainty about capacity and best interests decisions, or if no clear cause is found", "senior_in_person": "A patient who is a danger to himself or others despite simple measures, significant physiological instability underlying the confusion, or any situation requiring an urgent capacity and best interests decision about treatment; these need a senior present, not just advice by phone"}, "escalate_now_if": ["The patient is a genuine danger to himself or others and simple de-escalation is not working", "There are signs of serious underlying illness, such as hypoxia, hypoglycaemia, or sepsis", "There is a new focal neurological deficit alongside the confusion", "You are considering any medication for agitation — discuss it with a senior before giving it", "Capacity assessment for a specific decision suggests the patient lacks capacity and a best-interests decision under the Mental Capacity Act is needed urgently"], "document": "Record the baseline cognitive state as described by others, the time course of the change, examination and investigation findings, medications reviewed, any capacity assessment made for the specific decision in question and its outcome, and the management plan including any non-drug or drug measures used.", "fail": "An unsafe response sedates an agitated patient before excluding a reversible physical cause, or makes treatment decisions without properly assessing capacity when the patient is refusing care.", "pass": "A safe response excludes dangerous reversible causes first, uses non-drug measures as the initial approach, and escalates when safety or capacity concerns require senior input.", "high_performance": "An excellent response actively involves family or carers to help reorient the patient, documents a clear capacity assessment when relevant, and addresses the underlying cause rather than just managing the behaviour, while keeping the patient's dignity central throughout.", "one_thing": "If you only remember one thing: acute confusion means look for a reversible physical cause first, do not reach for sedation before you have checked the basics.", "img_note": "New confusion in an older inpatient is extremely common on UK wards and is usually delirium rather than a new diagnosis of dementia; capacity in England and Wales is assessed under the Mental Capacity Act, and if you are ever unsure whether a patient can consent to or refuse treatment in this state, say so and ask a senior rather than guessing.", "source": "NICE clinical guideline CG103, Delirium: prevention, diagnosis and management in hospital and long-term care (published 28 July 2010, last updated 18 January 2023; link to the 4AT added August 2026): recommendation 1.6.1 [2023] sets the 4AT as the assessment tool (CAM-ICU or ICDSC in critical care or the recovery room after surgery), 1.7.1–1.7.3 set treating the underlying cause, reorientation and de-escalation first, and 1.7.4 limits drug treatment to considering short-term haloperidol at the lowest clinically appropriate dose; MHRA Drug Safety Update, Haloperidol (Haldol): reminder of risks when used in elderly patients for the acute treatment of delirium (10 December 2021) lists Parkinson's disease and dementia with Lewy bodies as contraindications (as are known QTc prolongation and other QT-prolonging drugs) and recommends a baseline ECG and correction of electrolyte disturbances before starting; NICE NG97, Dementia (published 20 June 2018), recommendation 1.7.4, warns that antipsychotics can worsen motor features and cause severe antipsychotic sensitivity reactions in dementia with Lewy bodies or Parkinson's disease dementia, and NICE NG71, Parkinson's disease in adults (published 19 July 2017), recommendation 1.5.20, that other antipsychotics such as phenothiazines and butyrophenones can worsen the motor features of Parkinson's disease; NICE CG100, Alcohol-use disorders: diagnosis and management of physical complications (published 2 June 2010, last updated 12 April 2017; NICE is updating this guideline), recommendations 1.2.1.1–1.2.1.4, on prophylactic thiamine for at-risk harmful or dependent drinkers and parenteral thiamine for suspected Wernicke's encephalopathy; Mental Capacity Act 2005 sections 1–2 and its Code of Practice (2007, paragraph 4.4) establish that capacity is presumed and is assessed for a specific decision at the time it needs to be made; NICE NG253, Suspected sepsis in people aged 16 or over (published 19 November 2025, last updated 23 September 2026), recommendation 1.6.2, requires a high-priority review by a clinician at FY2 or above when a single NEWS2 parameter scores 3; RCP NEWS2 (2017) scores new confusion (C in ACVPU) as 3.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Bennett on ward 15, he's suddenly become confused and agitated, trying to pull out his cannula.", "B": "he's 79, admitted with a chest infection, no known cognitive impairment according to his family.", "A": "blood glucose and oxygen saturations are normal, he has a raised white cell count and looks unwell, I think this is delirium related to his infection, I've started simple reorientation measures and he's calmer with his daughter at the bedside.", "R": "I'd like your advice on whether he needs any medication for agitation, and, because new confusion scores 3 on NEWS2 and he has an infection, I need a high-priority sepsis review and his antibiotics checked, can you review the overall plan."}, "checked": "3 Oct 2026"}, {"id": "BLEEP-11", "title": "Acute breathlessness and heart failure decompensation", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mrs Fraser's really struggled to breathe overnight, she's on 4 litres now and she's got crackles halfway up her chest, she's known heart failure.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for a full set of observations and the NEWS2. If it is 7 or more, call your registrar now, not after you have seen the patient"}, {"lead": "Sit up + oxygen", "text": "Sit the patient upright and give oxygen to 94–98%, or 88–92% if at risk of hypercapnic respiratory failure (for example COPD) pending a blood gas; have a cannula and the ECG machine ready"}, {"lead": "Fluid balance + weight", "text": "Ask for the recent fluid balance and any change in weight — this tells you whether this is fluid overload"}, {"lead": "Drug chart + IV fluids", "text": "Ask which diuretic and other heart failure medicines she takes, whether doses have actually been given since admission (or held, and why), and whether she has had IV fluids in the last 24 hours — if maintenance or replacement IV fluids are running, ask the nurse to pause them until you have assessed her (but not glucose-containing fluid running with an insulin infusion)"}, {"lead": "Baseline exercise tolerance", "text": "Ask her usual exercise tolerance, so you know what a change looks like for her"}], "first_five_minutes": [{"lead": "NEWS2 7+: registrar now; sit up, oxygen", "text": "NEWS2 7 or more: call the registrar to the bedside now — emergency response, continuous monitoring. Sit her up and give oxygen to 94–98% (88–92% if at risk of hypercapnic respiratory failure). IV diuretic is the first-line treatment: agree the drug and dose with a senior, never from memory — have the usual dose, weight and renal function ready"}, {"lead": "ABCDE", "text": "Assess ABCDE: listen for crackles, wheeze and a third heart sound; look for a raised JVP and peripheral oedema"}, {"lead": "Oxygen not reaching target", "text": "Prescribe oxygen to the target range. If nasal cannulae or a simple face mask can't reach it, change to a reservoir mask and get senior advice (start with one at 15 L/min if critically ill, shocked or below 85%)"}, {"lead": "ECG, chest X-ray, bloods, ABG", "text": "ECG and portable chest X-ray (pulmonary oedema, cardiomegaly, or pneumonia or pneumothorax instead). FBC, renal function, electrolytes, and troponin if you suspect ischaemia. Arterial blood gas for anyone needing oxygen to reach target; acidaemia with severe breathlessness means a senior now — NIV is a senior decision"}, {"lead": "Drug chart: what to give, what to hold", "text": "Look for missed or held diuretic doses. Continue any beta-blocker unless heart rate is below 50, there is second- or third-degree heart block, or shock. Hold diltiazem or verapamil (including for new AF) and tell your senior — they must not be given in decompensated heart failure. No routine opiates or nitrates"}, {"lead": "Find the trigger", "text": "Missed diuretic, infection, ischaemia, arrhythmia (particularly new AF) or an iatrogenic fluid load. Keep pneumonia and PE open; if infection is possible, assess for sepsis"}, {"lead": "Urine output + recheck NEWS2", "text": "Consider a catheter to measure urine output if giving IV diuretics. Recalculate NEWS2: 5–6, or a single parameter of 3, needs an urgent review; 7 or more needs an emergency response — at least a registrar, a critical-care-competent team and continuous monitoring. Escalate at any score if worried"}], "can_i_do_alone": {"alone": "Sitting her upright, prescribing and titrating oxygen to target, a focused history and examination, checking the drug chart for missed doses, holding a due dose of diltiazem or verapamil (and telling your senior), ECG, chest X-ray, bloods, an arterial blood gas, and accurate fluid balance and weight", "senior_opinion": "The IV diuretic drug and dose, any doubt whether this is heart failure or something else (such as pneumonia or PE), any held diltiazem or verapamil, or a patient not improving with initial oxygen", "senior_in_person": "Severe breathlessness at rest, saturations below target despite a reservoir mask, hypotension, acidaemia, a new tachyarrhythmia, or a NEWS2 of 7 or more — a senior at the bedside now, not a phone call"}, "escalate_now_if": ["NEWS2 is 7 or more — call the registrar now; at 5–6 or a single parameter of 3 get an urgent review, and escalate at any score if worried.", "Saturations stay below the target range on a reservoir mask at 15 L/min.", "She is hypotensive or has signs of cardiogenic shock.", "There is new chest pain with the breathlessness, suggesting an ischaemic trigger.", "There is a new tachyarrhythmia such as fast AF (not sinus tachycardia) — with pulmonary oedema this is life-threatening, so get expert help to the bedside now.", "She is exhausted, cannot complete sentences, has a falling consciousness level, or the gas shows acidaemia or a rising CO2."], "document": "Record the time of the bleep, observations and NEWS2, examination findings including JVP and oedema, oxygen and target range, investigations, fluid balance and weight, missed diuretic doses and why, any held diltiazem or verapamil, the diuretic decision and who authorised it, and the plan agreed with the senior and when. Report doses missed through a prescribing error as a medicines incident per local policy.", "fail": "An unsafe response gives a diuretic dose from memory without checking the baseline, simply restarts the oral diuretic without discussing IV treatment with a senior, gives diltiazem or verapamil, fails to consider an infective or ischaemic trigger, or sits on a NEWS2 of 7 or more without escalating.", "pass": "A safe response does a structured assessment, starts oxygen at an appropriate target, requests the right first-line investigations, and escalates promptly when the red flags are met.", "high_performance": "An excellent response also considers cardiac function when thinking about rate control for any new AF, pre-empts what the senior will ask about diuretic dosing (usual dose, renal function, weight), and documents and hands over clearly.", "one_thing": "If you only remember one thing: sit her up, give oxygen to the right target and get a senior to the bedside early — acute heart failure with a NEWS2 of 7 or more is an emergency, and the IV diuretic dose is a senior conversation, not a guess.", "img_note": "UK hospitals that admit acute heart failure are expected to have a specialist heart failure team, and NICE says every admission should get early input from it — refer early through your trust's system. Notes often code the type as HFrEF (reduced ejection fraction) or HFpEF (preserved); find out which the patient has, as it shapes the rate-control and diuretic discussion with the senior.", "source": "NICE, Acute heart failure (CG187), last updated Nov 2021; NICE, Chronic heart failure in adults (NG106), last updated Sep 2025 (rec 1.4.12: avoid verapamil, diltiazem and short-acting dihydropyridines in HFrEF); verapamil and diltiazem SmPCs (emc), section 4.3 contraindications (verapamil: uncompensated heart failure; diltiazem: left ventricular failure with pulmonary stasis); BTS, Guideline for oxygen use in adults in healthcare and emergency settings, 2017; RCP, NEWS2, 2017; RCUK, Adult tachyarrhythmia algorithm (2025, V3 Mar 2026); NICE NG253 (sepsis), Sep 2026; NICE NG5 (medicines optimisation), 2015. Troponin, catheterisation and the precipitant list are standard practice; diuretic dose per local protocol.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Fraser on ward 12, she's become acutely breathless overnight and is now on 4 litres of oxygen.", "B": "She has known heart failure with reduced ejection fraction and no COPD, and takes oral furosemide at home. It was left off her drug chart on admission, so she's had none for 3 days, and her weight is up 2 kg.", "A": "Her saturations are 92% on 4 litres, respiratory rate is 28, pulse 88, BP 124/70, alert, temperature 36.8, she has crackles halfway up her chest and a raised JVP — her NEWS2 is 7. I've sat her up, prescribed oxygen to 94–98% and am titrating it up, and I've requested a chest X-ray, ECG, bloods and an arterial blood gas. I think this is acute decompensation from the missed furosemide, but I haven't excluded pneumonia or PE.", "R": "With a NEWS2 of 7, please come and review her now, and I need your decision on the IV diuretic and dose given her usual furosemide and renal function."}, "checked": "Oct 2026"}, {"id": "BLEEP-12", "title": "Tachycardia, not AF", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"Mr Grant's heart rate is 150 on the monitor and he says he feels light-headed, but the rhythm looks regular, not like AF. He's on antibiotics for a chest infection.\"", "nurse_call": [{"lead": "Full obs + BP", "text": "Ask for the full set of observations including BP, and whether the patient is alert and talking normally; a pulse of 150 scores 3 on NEWS2, so obs at least hourly"}, {"lead": "12-lead ECG now", "text": "Ask the nurse to get a 12-lead ECG done now — the monitor alone is not enough to characterise the rhythm"}, {"lead": "Chest pain? Breathless? Blackout?", "text": "Ask about any chest pain, breathlessness, blackout or collapse with the light-headedness"}, {"lead": "Recent meds + caffeine", "text": "Ask about any recent medication changes (including dipyridamole or theophylline), any asthma, and caffeine or alcohol intake"}, {"lead": "IV access + monitor", "text": "Ask the nurse to keep the patient on a cardiac monitor and have IV access equipment ready"}], "first_five_minutes": [{"lead": "Confirm the rhythm on a 12-lead", "text": "Assess ABCDE (oxygen only if SpO2 is below 94%) and confirm the rhythm with a 12-lead ECG — look at the rate, whether it is regular, the QRS width (narrow is under 0.12 s), and whether P waves or flutter waves are present"}, {"lead": "Life-threatening features?", "text": "Look for RCUK's life-threatening features: shock, syncope with severe or ongoing hypotension, myocardial ischaemia, or severe heart failure with pulmonary oedema"}, {"lead": "Unstable → call for help", "text": "If any is caused by the arrhythmia, call 2222 or your medical emergency team now — a senior or the crash team will carry out synchronised cardioversion"}, {"lead": "Broad and regular = VT", "text": "If the QRS is broad and the rhythm regular, treat it as ventricular tachycardia and get senior help now — do not give a rate-control drug"}, {"lead": "Narrow and regular: vagal first", "text": "For a stable regular narrow-complex tachycardia, try vagal manoeuvres (such as the modified Valsalva) on a monitor with a rhythm strip running, and phone your senior (RCUK: seek expert help when stable). If they fail, adenosine is next unless there is pre-excitation, asthma, AV block or sick sinus syndrome without a pacemaker, long QT, severe hypotension or decompensated heart failure. Give adenosine with a senior present, on continuous ECG monitoring and with resuscitation equipment ready (dose per BNF/local protocol). Adenosine terminates SVT and can unmask flutter waves"}, {"lead": "Rate around 150? Think flutter", "text": "A regular rate of about 150 should make you think of atrial flutter with 2:1 block — look carefully for sawtooth flutter waves, especially in the inferior leads"}, {"lead": "Trigger and electrolytes", "text": "Check potassium, magnesium and thyroid function and treat any precipitant (sepsis, pain, hypovolaemia, hypoxia); never treat sinus tachycardia with antiarrhythmics or cardioversion. With infection and a pulse scoring 3, NICE NG253 asks for a high-priority FY2-or-above review to decide his sepsis risk and antibiotic urgency"}], "can_i_do_alone": {"alone": "Arranging an immediate 12-lead ECG and monitoring, vagal manoeuvres such as the modified Valsalva in a stable regular narrow-complex tachycardia while you call your senior, checking and correcting potassium and magnesium, and treating an obvious precipitant such as sepsis, pain or dehydration", "senior_opinion": "Adenosine (agreed with your senior, patient monitored), any rate-control or antiarrhythmic drug, suspected flutter, any doubt about the rhythm, and the FY2-or-above sepsis review (NG253). Never give adenosine with dipyridamole; within a year of a heart transplant, adenosine is a senior decision", "senior_in_person": "Any life-threatening feature caused by the arrhythmia — shock, syncope with hypotension, myocardial ischaemia or severe heart failure — or any broad-complex tachycardia (presume VT): this needs the medical registrar or crash team at the bedside now"}, "escalate_now_if": ["Shock, myocardial ischaemia or severe heart failure caused by the arrhythmia", "Syncope, collapse or reduced consciousness", "The QRS is broad (presume VT) or you are unsure whether the rhythm is supraventricular or ventricular", "Vagal manoeuvres fail and the rate stays fast", "There is a significant electrolyte abnormality contributing to the rhythm", "NEWS2 of 5 or more (urgent response) or 7 or more (emergency response)"], "document": "Record the time the arrhythmia was noted, the ECG findings including rate, regularity and QRS width, haemodynamic assessment with NEWS2, electrolyte results and correction, any treatment given, when the FY2-or-above sepsis review happened, and the plan agreed with the senior.", "fail": "An unsafe response gives a rate-control drug without checking for life-threatening features, treats a broad-complex tachycardia as SVT, tries to slow a sinus tachycardia instead of treating its cause, or acts on the monitor without a 12-lead ECG.", "pass": "A safe response confirms the rhythm with a 12-lead ECG, checks for life-threatening features, tries vagal manoeuvres in a stable regular narrow-complex tachycardia, corrects electrolytes, and escalates promptly if the patient is unstable or the complexes are broad.", "high_performance": "An excellent response names the specific rhythm (SVT, flutter with 2:1 block, sinus tachycardia) rather than just 'tachycardia', records a rhythm strip during any vagal manoeuvre or adenosine so the response can be read, looks actively for the trigger, and explains to the patient what is happening.", "one_thing": "If you only remember one thing: life-threatening features first, then QRS width — an unstable patient needs cardioversion by the crash team, and a regular broad-complex tachycardia is treated as VT.", "img_note": "In UK hospitals, synchronised cardioversion of an unstable patient is done by the crash or medical emergency team with an anaesthetist for sedation — your job is to recognise it and call 2222 early. Adenosine is often kept on CCU or in the emergency drug cupboard rather than on every ward; find out where it is on your site and who is expected to give it.", "source": "Resuscitation Council UK, Adult advanced life support guidelines, Oct 2025; Resuscitation Council UK, Adult tachyarrhythmia algorithm (v3), Mar 2026; adenosine 3 mg/ml SmPCs (emc, 2025–26); BNF, Adenosine (accessed Oct 2026); NICE NG253 Suspected sepsis (updated 23 Sep 2026), recs 1.6.2, 1.8.24; RCP NEWS2 (2017). Standard practice, not guideline: flutter at about 150, caffeine and alcohol.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Grant on ward 8, he has a new regular tachycardia at 150 and feels light-headed.", "B": "He's being treated for a chest infection, no known cardiac history.", "A": "BP 105/65, he's alert, with no chest pain, blackout or signs of heart failure. The 12-lead shows a regular narrow-complex tachycardia at exactly 150 — I think this could be atrial flutter with 2:1 block rather than SVT. A modified Valsalva on the monitor didn't change it. Potassium and magnesium are sent.", "R": "Could you come and look at the ECG with me — I'd like your decision on adenosine and, if this is flutter, on rate control, and he needs an FY2-or-above sepsis review. I'll call 2222 if he develops any life-threatening features."}, "checked": "Oct 2026"}, {"id": "BLEEP-13", "title": "Bradycardia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"Mrs Khan's heart rate has dropped to 42, she's a bit dizzy but she's talking to me.\"", "nurse_call": [{"lead": "Full obs + BP", "text": "Ask for the full set of observations including BP, and whether the patient is alert and talking normally"}, {"lead": "12-lead ECG now", "text": "Ask the nurse to get a 12-lead ECG done now and to put the patient on a cardiac monitor"}, {"lead": "Symptoms?", "text": "Ask about dizziness, blackouts, chest pain, breathlessness, or confusion"}, {"lead": "Recent meds", "text": "Ask about any recent medication changes, particularly beta-blockers, rate-limiting calcium-channel blockers, digoxin, or anything that slows the heart"}, {"lead": "Monitor + IV access", "text": "Ask the nurse to keep the patient monitored, have IV access equipment ready, and tell you at once about any pauses"}], "first_five_minutes": [{"lead": "ABCDE and IV access", "text": "Assess ABCDE, site IV access, and give oxygen only if below target saturation (94–98%, or 88–92% if at risk of hypercapnia)"}, {"lead": "Confirm the rhythm on a 12-lead", "text": "Confirm the rhythm with a 12-lead ECG — rate, whether P waves are present and related to the QRS, and the QRS width: sinus bradycardia, slow AF, or which degree of heart block"}, {"lead": "Life-threatening features?", "text": "Look for the Resuscitation Council UK life-threatening features: shock, syncope, myocardial ischaemia, severe heart failure, or immediately after a cardiac arrest (post-ROSC)"}, {"lead": "Unstable → atropine and help", "text": "If present, call for help now and follow the RCUK bradyarrhythmia algorithm: atropine 500 micrograms IV, repeated every 3–5 minutes to a maximum of 3 mg (check BNF/local protocol), then, if there is no response, your senior will decide on further drugs or pacing — tell them if a beta-blocker or calcium-channel blocker may be the cause. Do not give atropine after a heart transplant (it can cause high-degree block or sinus arrest), and do not give it in high-degree AV block with a broad QRS: it is ineffective and may worsen the block"}, {"lead": "Risk of asystole?", "text": "If there are no life-threatening features, or after a good response to atropine, still get expert help now if there is recent asystole, Mobitz II AV block, complete heart block with a broad QRS, or a ventricular pause over 3 seconds"}, {"lead": "Treat reversible causes", "text": "In every patient, identify and treat reversible causes: medications, electrolyte disturbance (particularly hyperkalaemia), myocardial ischaemia, hypothermia, hypothyroidism, or raised intracranial pressure"}, {"lead": "Review the drug chart", "text": "Review the drug chart for rate-limiting medications and withhold the next dose while you seek advice"}, {"lead": "Bloods incl. digoxin level", "text": "Send potassium, magnesium, calcium, renal and thyroid function, and a digoxin level if the patient takes it (note the time of the last dose: a level taken less than 6 hours after a dose can read falsely high). Read the level with the clinical picture: toxicity can occur at lower levels, and low potassium, low magnesium, high calcium, hypoxia and renal impairment all increase the risk"}], "can_i_do_alone": {"alone": "Arranging an immediate 12-lead ECG and monitoring, sending bloods including a digoxin level, correcting low potassium, withholding the next dose of a rate-limiting drug while you seek advice — documenting why — and giving atropine 500 micrograms IV for life-threatening features while help arrives (not after a heart transplant, and not in high-degree AV block with a broad QRS)", "senior_opinion": "A stable patient with a new bradycardia: whether and when to stop or restart rate-limiting drugs, any new AV block, or any uncertainty about the rhythm", "senior_in_person": "Any life-threatening feature (shock, syncope, myocardial ischaemia, severe heart failure, or immediately after a cardiac arrest) or any asystole-risk feature (recent asystole, Mobitz II, complete heart block with broad QRS, pause over 3 seconds) — medical registrar or cardiology at the bedside now, crash team if peri-arrest"}, "escalate_now_if": ["Shock, syncope, myocardial ischaemia (e.g. chest pain) or severe heart failure attributable to the bradycardia", "Recent asystole, Mobitz II, complete heart block with a broad QRS, or a pause over 3 seconds on the monitor", "No response to atropine", "A significant electrolyte abnormality, particularly hyperkalaemia", "Suspected digoxin toxicity, or you are unsure of the rhythm"], "document": "Record the time the bradycardia was noted, the ECG findings including rate and rhythm, haemodynamic assessment, electrolyte and digoxin results and any correction, any medications withheld, and the plan agreed with the senior.", "fail": "An unsafe response ignores a symptomatic bradycardia, fails to get a 12-lead ECG, continues a rate-limiting medication without reviewing it, gives atropine to a heart transplant patient, or is reassured by a normal BP in a patient with an asystole-risk rhythm.", "pass": "A safe response confirms the rhythm with an ECG, assesses for instability, corrects any obvious precipitant, and escalates promptly if the patient is unstable.", "high_performance": "An excellent response identifies the specific rhythm from the ECG, thinks of digoxin toxicity and its potentiators (low potassium, renal impairment), reviews the drug chart thoroughly, and contacts cardiology proactively if pacing may be needed.", "one_thing": "If you only remember one thing: decide first whether there are life-threatening features — then, even in a stable patient, look for the rhythms that risk asystole.", "img_note": "In UK hospitals, temporary transvenous pacing is usually arranged through the on-call cardiology registrar, sometimes by transfer to another site's cath lab, so involve them early. Transcutaneous pacing is delivered through the defibrillator on the resuscitation trolley — check on your first shift whether yours can pace and who can set it up.", "source": "Resuscitation Council UK, Adult advanced life support guidelines and Adult bradyarrhythmia algorithm, Oct 2025; ERC Guidelines 2025: Adult Advanced Life Support; Digoxin SmPC (emc), Feb 2026; BTS oxygen guideline, 2017. Reversible causes beyond drugs and electrolytes are standard clinical practice. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Khan on ward 3, her heart rate has dropped to 42 and she's feeling dizzy.", "B": "She has AF on bisoprolol and was recently started on digoxin for rate control.", "A": "BP 100/60, sats 96% on air, she's alert, no blackout, chest pain or heart failure. The ECG shows slow AF at 42 with a narrow QRS and no pauses on the monitor. Her potassium is 3.3 — I've started replacement because low potassium potentiates digoxin — and I've sent a digoxin level, magnesium and renal function. I've withheld tonight's bisoprolol and digoxin.", "R": "This could be digoxin toxicity, so could you come and review her now? I'd also like your advice on when to restart them and whether she needs cardiology review. I'll call you straight away if she develops life-threatening features or pauses."}, "checked": "Oct 2026"}, {"id": "BLEEP-14", "title": "Severe inpatient hypertension", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Hughes's BP is 210 over 110, he says he's got a bit of a headache but otherwise feels fine.\"", "nurse_call": [{"lead": "Full obs + repeat BP", "text": "Ask for a full set of observations and a repeat BP with the correct cuff size, with the patient rested, quiet and seated"}, {"lead": "Symptoms?", "text": "Ask specifically about headache, visual changes, chest pain, breathlessness, confusion, palpitations or sweating"}, {"lead": "Usual meds given?", "text": "Ask about the patient's usual antihypertensive medications and whether they have been given in hospital"}, {"lead": "Baseline BP", "text": "Ask what the patient's usual BP is — a reading that would be alarming in a normotensive patient may be their normal"}, {"lead": "Pain, bladder, urine dip", "text": "Ask whether the patient is in pain, when they last passed urine (retention can drive the BP up), and for a urine dip for blood and protein"}], "first_five_minutes": [{"lead": "Repeat BP properly", "text": "Repeat the BP yourself with the correct cuff size and the patient rested — a single high reading is not a diagnosis"}, {"lead": "Look for target-organ damage", "text": "Look for signs of hypertensive emergency: chest pain, breathlessness or heart failure, new confusion or neurological signs, visual disturbance, or acute kidney injury"}, {"lead": "Examine the fundi", "text": "Do fundoscopy yourself in everyone with severe hypertension (systolic 180 or higher, or diastolic 120 or higher) — retinal haemorrhage or papilloedema (accelerated hypertension) means same-day specialist assessment"}, {"lead": "Treat inpatient drivers", "text": "Check the drug chart first: omitted usual antihypertensives are a common, easily fixed cause. If the patient is nil by mouth, check with the anaesthetic or procedural team before giving oral medicines; if nil by mouth because of an unsafe swallow or bowel obstruction, discuss with your senior or a pharmacist. Then look for and treat other inpatient causes: pain, urinary retention, alcohol or drug withdrawal, and anxiety. Think of phaeochromocytoma if the BP is labile with headache, palpitations, pallor or sweating"}, {"lead": "Bloods, urine and ECG", "text": "Send renal function and electrolytes, send urine for albumin:creatinine ratio and dip it for blood, and request a 12-lead ECG"}, {"lead": "Emergency or not?", "text": "Decide whether this is a hypertensive emergency (acute target-organ damage — needs senior-led, monitored IV treatment) or severe hypertension without acute target-organ damage (usually managed by restarting or adjusting oral medication)"}, {"lead": "Do not drop the BP rapidly", "text": "If treatment is needed, the aim is a gradual reduction, not rapid normalisation — rapid drops can cause cerebral or myocardial ischaemia. Agree the approach with a senior"}], "can_i_do_alone": {"alone": "Repeating the BP properly, examining the fundi, treating pain or urinary retention, reviewing the drug chart for omitted medications, sending bloods and urine, and requesting an ECG", "senior_opinion": "Any decision to start or change antihypertensive treatment, any uncertainty about whether there is target-organ damage, or suspected phaeochromocytoma", "senior_in_person": "Any patient with signs of hypertensive emergency — chest pain, breathlessness, new confusion or neurological signs, visual disturbance, retinal haemorrhage or papilloedema, or acute kidney injury — this needs a senior at the bedside now"}, "escalate_now_if": ["There is chest pain, breathlessness, or signs of heart failure", "There is new confusion, severe headache, visual disturbance or focal neurology", "Fundoscopy shows retinal haemorrhage or papilloedema (accelerated hypertension)", "There is acute kidney injury or a significant rise in creatinine", "You suspect phaeochromocytoma (labile BP or postural hypotension, headache, palpitations, pallor, abdominal pain or sweating) — do not give a beta-blocker until a senior has reviewed", "The patient is pregnant or has recently given birth — involve the obstetric team now"], "document": "Record the BP readings with the cuff size and patient position, symptoms asked about and reported, examination findings, investigations ordered, medications reviewed, and the plan agreed with the senior including any treatment given and the target BP.", "fail": "An unsafe response treats a high reading in an asymptomatic patient with a rapid-acting drug, or decides on management without examining the fundi and looking for target-organ damage.", "pass": "A safe response repeats the BP properly, examines the fundi, assesses for target-organ damage, treats inpatient drivers such as pain or retention, reviews medications, and escalates if there is any evidence of hypertensive emergency.", "high_performance": "An excellent response separates hypertensive emergency from severe hypertension without acute target-organ damage, considers whether usual medications have been omitted in hospital, and explains to the patient why a gradual approach is safer than a rapid drop.", "one_thing": "If you only remember one thing: the number itself matters less than whether there is end-organ damage — look for that before you treat the number.", "img_note": "In UK hospitals, IV antihypertensive infusions (for example labetalol or GTN) are usually given only in a monitored area such as HDU, CCU or the acute medical unit under senior direction, not on a general ward.", "source": "NICE, Hypertension in adults: diagnosis and management (NG136), last updated Feb 2026 — 1.3.3 and 1.5.1–1.5.3: target-organ damage work-up (including fundi) at 180/120 or higher, and who needs same-day specialist assessment. NG136 covers adults with primary hypertension, not inpatients specifically; pregnancy follows NICE NG133. Treating inpatient drivers, gradual lowering, and avoiding beta-blockers in suspected phaeochromocytoma are standard clinical practice, not NG136.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Hughes on ward 6, his BP is 210 over 110 and he has a headache.", "B": "He has a history of hypertension and his usual medications have not been given for the last two days because he was nil by mouth.", "A": "His repeat BP after rest with the right cuff is 205 over 105. He has a mild headache but no visual symptoms, chest pain or confusion. Fundoscopy shows no haemorrhages or papilloedema, the ECG and urine dip are unremarkable, his creatinine is at baseline, and he isn't in pain or retention.", "R": "I don't think this is a hypertensive emergency. He's eating again, so I'd like to restart his usual oral antihypertensives tonight — are you happy with that and with no acute IV treatment?"}, "checked": "Oct 2026"}, {"id": "BLEEP-15", "title": "Peri-arrest recognition and the 2222 call", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Patel's really not right, he's barely responsive and his breathing looks abnormal, I think you need to come now.\"", "nurse_call": [{"lead": "Call 2222 if unsure", "text": "If the patient looks peri-arrest — barely responsive, abnormal breathing, or you are genuinely unsure — ask the nurse to pull the emergency bell and call 2222 (or your trust's medical emergency number) now, before you even arrive"}, {"lead": "Not breathing normally → CPR", "text": "If the patient is unresponsive and not breathing normally, or there is any doubt, treat it as cardiac arrest: start CPR, call 2222 and bring the defibrillator — do not wait for you"}, {"lead": "Obs, NEWS2, monitoring", "text": "Ask for a full set of observations and the NEWS2 score if this can be done safely while waiting, and for continuous monitoring"}, {"lead": "Reversible causes", "text": "Ask whether there is any obvious reversible cause — a recent medication, a procedure, or a known deterioration"}, {"lead": "Trolley, defibrillator, ReSPECT form", "text": "Ask the nurse to bring the resuscitation trolley and defibrillator, and the notes and drug chart with any ReSPECT form or DNACPR decision"}], "first_five_minutes": [{"lead": "Arrest or peri-arrest?", "text": "Unresponsive and not breathing normally, or any doubt, means cardiac arrest: start CPR, attach the defibrillator and follow the ALS algorithm. If there is a pulse and breathing, work through ABCDE and decide whether this is peri-arrest"}, {"lead": "Call 2222 early", "text": "If you think this could be peri-arrest, call 2222 (or your trust's medical emergency number) — it is always better to call and stand down than to delay. The outreach or registrar pathway is for a deteriorating patient who is clearly not peri-arrest"}, {"lead": "Airway, oxygen, access", "text": "Open the airway (head tilt–chin lift, adjuncts), give oxygen by reservoir mask at 15 L/min aiming for 94–98%, and gain IV access with bloods, blood cultures, a blood gas and a glucose — without delaying the 2222 call, and support breathing with a bag-valve-mask if it is slow or shallow; check the drug chart for opioids (naloxone)"}, {"lead": "Reversible causes", "text": "Work through the reversible causes: hypoxia, hypovolaemia, hypo/hyperkalaemia and other metabolic causes, hypo/hyperthermia, thrombosis, tension pneumothorax, tamponade, toxins"}, {"lead": "Sepsis: antibiotics and fluids", "text": "Suspected infection with NEWS2 7 or more is high-risk sepsis (NICE NG253): IV antibiotics within 1 hour per trust policy, and 250 ml crystalloid boluses unless contraindicated, reassessing after each, up to 1,000 ml"}, {"lead": "Resuscitation status", "text": "Check for a ReSPECT form or DNACPR decision: DNACPR applies only to CPR, and all other treatment continues. If none is recorded, presume CPR"}, {"lead": "2222 is a short message", "text": "The 2222 call is not an SBAR: say clearly 'adult cardiac arrest' or 'adult medical emergency', the ward and the site, then go back to the patient"}, {"lead": "Document the time", "text": "Note the time you called 2222 and the time the team arrived — this matters for the notes and for any incident review"}, {"lead": "Hand over clearly", "text": "When the team arrives, give a short SBAR handover: who the patient is, what happened, what you have done, and what you think is going on"}], "can_i_do_alone": {"alone": "Recognising arrest or peri-arrest, calling 2222, CPR, airway manoeuvres, bag-valve-mask ventilation, reservoir-mask oxygen, IV access, bloods and cultures, fluid boluses and IV antibiotics per trust policy — all within F1 scope; never wait for permission to call 2222", "senior_opinion_lead": "If you are unsure whether it is peri-arrest, that uncertainty means call 2222.", "senior_opinion": ["A deteriorating patient who is clearly not peri-arrest (NEWS2 5–6, or a single parameter scoring 3) needs urgent review by your registrar or outreach through your trust's pathway"], "senior_in_person": "Any patient who is peri-arrest or arrested — a 2222 call, with the team there now, not a phone discussion. NEWS2 7 or more also needs an emergency bedside response with critical care and airway skills"}, "escalate_now_if": ["The patient is unresponsive and not breathing normally, or there is any doubt — start CPR and call 2222 immediately", "The patient has a falling GCS or is barely responsive", "There are signs of airway obstruction or inadequate breathing, or SpO2 stays below target despite a reservoir mask at 15 L/min", "The patient is hypotensive with signs of poor perfusion", "NEWS2 is 7 or more", "You or the nurse are worried, or you are genuinely unsure whether this is peri-arrest — call 2222, do not wait"], "document": "Record the time of the bleep, the time you called 2222, the patient's observations and GCS at the time, what you did before the crash team arrived, the time the crash team arrived, and the outcome. This is a high-acuity event and the notes need to be clear and contemporaneous.", "fail": "An unsafe response delays calling 2222 because you are unsure, fails to start CPR in an unresponsive patient who is not breathing normally, withholds other treatment because of a DNACPR decision, or spends the 2222 call giving a long history.", "pass": "A safe response recognises arrest or peri-arrest early, calls 2222 without hesitation with a short clear message, starts CPR or airway and oxygen support as needed, and hands over clearly when the team arrives.", "high_performance": "An excellent response anticipates the peri-arrest before it happens — recognising the deteriorating patient earlier and escalating before a 2222 call is needed — and documents the event clearly for any subsequent review.", "one_thing": "If you only remember one thing: if you are unsure whether to call 2222, call it — you can always stand down, but you cannot get back the time you spent hesitating.", "img_note": "RCUK recommends 2222 as the standard cardiac arrest call number. Whether a peri-arrest call also goes through 2222, and which team responds (medical emergency or critical care outreach), varies by trust. Find out on your first day which number to call for a peri-arrest patient, and which for a deteriorating but not yet peri-arrest patient.", "source": "Resuscitation Council UK, Adult advanced life support guidelines and in-hospital algorithm, Oct 2025; RCP, National Early Warning Score (NEWS) 2, Dec 2017; NICE NG253, Suspected sepsis in people aged 16 or over (updated Sep 2026), recs 1.8.1–1.8.8; BTS oxygen guideline, 2017; RCUK CPR decisions FAQ and BMA/RCUK/RCN Decisions relating to CPR, 2016. The 2222 message format is standard practice, not guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "(2222 call: 'Adult medical emergency, ward 9, [site name].') Handover when the team arrives: this is Mr Patel, he's peri-arrest — barely responsive, with a pulse.", "B": "He's day three after a bowel resection and has been deteriorating over the last hour.", "A": "GCS 6, his airway needs a jaw thrust, respiratory rate 8 and shallow, saturations 85% on a reservoir mask at 15 litres, pulse 130, BP 75/40, temperature 38.4 — NEWS2 17. I'm ventilating him with a bag-valve-mask and an oropharyngeal airway. I have IV access, a 250 ml bolus is running, cultures, bloods and a gas are sent, IV antibiotics are going in, and his glucose is 5.8. He has a morphine PCA, so I've stopped it and given naloxone. I'm worried about sepsis from an anastomotic leak, or bleeding.", "R": "He needs airway support and resuscitation now — please take over the airway; I'll call the surgical registrar."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-16", "title": "Suspected pulmonary embolism", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mrs Taylor's suddenly become breathless and she's got a sharp pain in her chest when she breathes in, she had a knee replacement two weeks ago.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score"}, {"lead": "Oxygen", "text": "Ask the nurse to sit the patient upright and give oxygen to keep saturations at 94–98% (88–92% if at risk of hypercapnic respiratory failure, pending a blood gas); reservoir mask at 15 L/min if below 85% or shocked"}, {"lead": "12-lead ECG now", "text": "Ask for a 12-lead ECG to be done now"}, {"lead": "Risk factors", "text": "Ask about recent surgery, immobility, previous VTE, active cancer, pregnancy, or oestrogen-containing medication"}, {"lead": "Bleeding risk", "text": "Ask about active or recent bleeding (including the wound), a known bleeding disorder, and when any anticoagulant or VTE prophylaxis was last given — this matters before any anticoagulation"}], "first_five_minutes": [{"lead": "ABCDE with attention to breathing", "text": "Assess airway, breathing, circulation, disability and exposure — look specifically for hypotension or other signs of haemodynamic compromise"}, {"lead": "Two-level PE Wells score", "text": "Calculate the two-level PE Wells score: DVT signs 3; alternative diagnosis less likely than PE 3; heart rate over 100 1.5; immobilisation over 3 days or surgery in the last 4 weeks 1.5; previous DVT or PE 1.5; haemoptysis 1; malignancy 1. More than 4 means PE is likely; 4 or less means PE is unlikely"}, {"lead": "ECG and chest X-ray", "text": "Read the ECG yourself (look for an acute coronary syndrome and right heart strain) and request a chest X-ray to exclude other causes"}, {"lead": "Wells above 4: CTPA now", "text": "If PE is likely (two-level Wells score above 4), request a CTPA immediately — no D-dimer is needed. If the scan cannot be done immediately, give interim therapeutic anticoagulation per trust protocol once you have checked bleeding risk"}, {"lead": "Wells 4 or less: D-dimer", "text": "If PE is unlikely, send a D-dimer before starting any anticoagulant, with the result available within 4 hours if possible; if positive, request a CTPA immediately, with interim anticoagulation if the scan is delayed; if negative, stop any interim anticoagulation and think again. If the result won't be back within 4 hours, give interim anticoagulation as above"}, {"lead": "Baseline bloods, don't wait", "text": "Send FBC, renal and liver function, PT and APTT before anticoagulating — but do not wait for the results before starting interim anticoagulation"}, {"lead": "Unstable: possible high-risk PE", "text": "Hypotension or shock may be high-risk PE, but after surgery also think of bleeding, sepsis or ACS: get the medical registrar and critical care to the bedside now (2222 if she arrests) — unfractionated heparin and thrombolysis are senior decisions"}], "can_i_do_alone": {"alone": ["Starting oxygen and calculating the Wells score", "Arranging an ECG, chest X-ray, bloods and a D-dimer when indicated", "Requesting an immediate CTPA when PE is likely", "Prescribing interim therapeutic anticoagulation per trust protocol when the scan is delayed and there is no bleeding concern, dosed by weight and renal function per protocol — treatment doses are higher than prophylactic doses and vary by drug, so check the BNF/trust VTE protocol and when the last prophylactic dose was given; never with an epidural catheter in situ without anaesthetic advice"], "senior_opinion": "Interim anticoagulation when there is a bleeding concern (such as surgery in the last few weeks, active bleeding or low platelets), contrast allergy, severe renal impairment (estimated creatinine clearance below 30 ml/min — this changes the anticoagulant choice and dose as well as the imaging) or high radiation risk needing alternative imaging, or any uncertainty about the diagnosis", "senior_in_person": "Any patient who is haemodynamically unstable with suspected PE, has NEWS2 7 or more, or needs a reservoir mask — registrar and critical care team at the bedside now; thrombolysis is a senior decision"}, "escalate_now_if": ["The patient is hypotensive, has had syncope, or has signs of shock", "NEWS2 is 7 or more (emergency response, continuous obs), or 5–6 or a single parameter of 3 (urgent review)", "Saturations are below 85%, or the target can't be held without a reservoir mask", "There are signs of right heart strain on the ECG or echocardiogram", "PE is likely, the scan is delayed and the patient is deteriorating", "There is active bleeding or a high bleeding risk that complicates anticoagulation"], "document": "Record the time of onset, the observations and NEWS2 score, the clinical probability score and its components, ECG and chest X-ray findings, bloods sent and results, any anticoagulation given and who authorised it, and the plan for imaging including the time it was requested.", "fail": "An unsafe response sends a D-dimer and waits when the Wells score is above 4, leaves a PE-likely patient without anticoagulation while the scan is delayed and without a documented reason, or anticoagulates without checking bleeding risk.", "pass": "A safe response calculates the Wells score, follows the matching pathway (immediate CTPA if likely, D-dimer if unlikely), covers a delayed scan with interim anticoagulation after checking bleeding risk, and escalates promptly if the patient is unstable.", "high_performance": "An excellent response also scores the \"alternative diagnosis\" item honestly, considers alternatives (such as pneumonia, pneumothorax, or ACS), and tells radiology how urgent the CTPA is.", "one_thing": "If you only remember one thing: a Wells score above 4 means CTPA now, not a D-dimer — and interim anticoagulation if the scan is delayed, once you've checked bleeding risk.", "img_note": "CTPA is the standard imaging for suspected PE in the UK, but out-of-hours access varies, and some trusts use a V/Q scan for renal impairment or contrast allergy. On your first day, find out what imaging your site offers out of hours and who to call to arrange it urgently.", "source": "NICE NG158, Venous thromboembolic diseases: diagnosis, management and thrombophilia testing (last updated Aug 2023, reviewed May 2026; recs 1.1.15–1.1.21, 1.3.3–1.3.4, 1.3.12, 1.6.2); Resuscitation Council UK Guidelines 2025, Special circumstances (PE); BTS oxygen guideline 2017; RCP NEWS2 2017. Drug chart, bleeding and epidural checks are standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Taylor on ward 4, she's suddenly become breathless with pleuritic chest pain.", "B": "She had a knee replacement two weeks ago and has been less mobile since; no active bleeding.", "A": "On air: saturations 92%, respiratory rate 26, heart rate 112, BP 128/76, temperature 37.1, alert — NEWS2 7; now 95% on 2 litres, NEWS2 8. Her two-level Wells score is 6, so PE is likely — I've requested an immediate CTPA but radiology can't scan her for about 3 hours. The ECG shows sinus tachycardia, the chest X-ray is clear, and baseline bloods are sent.", "R": "NICE advises interim anticoagulation while she waits. She's two weeks post-op. Her NEWS2 is 8, so I'd like you to see her now and decide on her bleeding risk before I prescribe it; I've also called outreach — and I'll call you straight away if she becomes hypotensive."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-17", "title": "Acute exacerbation of COPD", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Cooper's really wheezy and struggling to breathe, he's got known COPD and he's using his inhaler every few minutes.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations including respiratory rate, saturations, heart rate, BP, consciousness, and the NEWS2 score, and which SpO2 scale is used (Scale 2 only if hypercapnic failure is confirmed and documented)"}, {"lead": "Sit up + controlled oxygen", "text": "Ask the nurse to sit the patient upright and give controlled oxygen if needed to a target of 88–92% pending a blood gas (24% Venturi at 2–3 L/min or nasal cannulae at 1–2 L/min) — COPD puts him at risk of hypercapnic respiratory failure"}, {"lead": "Air-driven nebulisers", "text": "Ask the nurse to give nebulised bronchodilators (salbutamol, with ipratropium) as prescribed, driven by air rather than oxygen if he may be hypercapnic, with oxygen via nasal cannulae at the same time if needed, with saturations monitored throughout"}, {"lead": "Steroids", "text": "Ask whether the patient is on any regular steroid and whether they have had a course recently"}, {"lead": "Previous NIV/ICU + ReSPECT", "text": "Ask about previous ICU admission or NIV, home oxygen, and whether there is a ReSPECT form or documented ceiling of treatment"}], "first_five_minutes": [{"lead": "ABCDE, assess severity", "text": "Assess airway, breathing, circulation, disability and exposure — look for severity: inability to complete sentences, accessory muscle use, cyanosis, exhaustion, drowsiness or confusion. Oximeters can over-read in dark skin"}, {"lead": "Arterial blood gas", "text": "Take an arterial blood gas and record the inspired oxygen — oximetry tells you nothing about CO2 or pH. Repeat it at 30–60 minutes (sooner if he deteriorates), even if the first is normal"}, {"lead": "Chest X-ray and ECG", "text": "Request a chest X-ray (pneumonia, pneumothorax) and an ECG"}, {"lead": "Bloods and cultures", "text": "Send FBC, CRP, renal function and electrolytes (beta-agonists can cause hypokalaemia); blood cultures if febrile, sputum culture if purulent, and a theophylline level if he takes it"}, {"lead": "Prednisolone; consider antibiotics", "text": "Give prednisolone 30 mg orally daily for 5 days unless significantly contraindicated (check BNF/local protocol). Consider an antibiotic per your trust guideline, weighing severity and sputum change (many exacerbations are not bacterial), and assess sepsis risk (NG253) if infection is possible"}, {"lead": "Set the target from the gas", "text": "If the CO2 is normal and there is no history of hypercapnic failure needing NIV or ventilation, the target can move to 94–98%; if the CO2 is raised, keep 88–92% and keep nebulisers air-driven — never stop oxygen suddenly (rebound hypoxaemia). Recheck the gas after any change"}, {"lead": "Think NIV early", "text": "Any respiratory acidosis (pH below 7.35 with a raised CO2): call your senior now, not after a repeat gas. NIV and the ceiling of treatment are senior decisions"}], "can_i_do_alone": {"alone": "Controlled oxygen titrated to 88–92%, air-driven nebulised bronchodilators, taking a blood gas, chest X-ray, ECG and bloods, prescribing prednisolone 30 mg daily for 5 days, and antibiotics per trust guideline if indicated", "senior_opinion": "A NEWS2 of 5–6 or a 3 in any one parameter, a patient not improving after initial nebulisers, IV theophylline, or uncertainty about the diagnosis (such as pneumothorax, heart failure or PE)", "senior_in_person": "Any respiratory acidosis, a NEWS2 of 7 or more, rising oxygen need, exhaustion, drowsiness or new confusion — NIV and ceiling-of-treatment decisions need a senior at the bedside now"}, "escalate_now_if": ["The patient is exhausted or cannot complete sentences", "There is a falling consciousness level or new confusion", "Saturations stay below 88% despite controlled oxygen, or he needs more oxygen to stay at 88–92%", "Any blood gas shows a pH below 7.35 with a raised CO2, or the CO2 is rising on a repeat gas", "The NEWS2 is 7 or more", "The patient is not improving after nebulisers, steroids and controlled oxygen"], "document": "Record the observations and NEWS2 score at review with the SpO2 scale used, the oxygen device, flow and target range, nebulisers given with the driving gas and the response, blood gas results with the inspired oxygen, investigations ordered, steroids and antibiotics prescribed, and the plan agreed with the senior including any decision about NIV and the ceiling of treatment.", "fail": "An unsafe response gives uncontrolled high-concentration oxygen or oxygen-driven nebulisers to a hypercapnic patient, does not take a blood gas, or delays escalation in a patient who is tiring or acidotic.", "pass": "A safe response assesses severity, gives controlled oxygen to 88–92%, takes and repeats a blood gas, gives air-driven nebulisers and prednisolone, and escalates promptly on any respiratory acidosis or if the patient is not improving.", "high_performance": "An excellent response anticipates the need for NIV early, checks for a ReSPECT form or documented ceiling of treatment before the senior arrives, and communicates clearly with the patient about what is happening.", "one_thing": "If you only remember one thing: in COPD, start at 88–92% and get a blood gas — the gas, not a guess, decides the oxygen target and whether he needs NIV.", "img_note": "In UK hospitals, acute NIV is usually started on a respiratory or acute medical unit by trained staff, after a senior decision that includes the ceiling of treatment. Patients may carry a ReSPECT form or an oxygen alert card stating their target saturations — look for both.", "source": "NICE NG115, COPD in over 16s: diagnosis and management, last updated Jul 2019; NICE NG114, COPD (acute exacerbation): antimicrobial prescribing, 2018; BTS, Guideline for oxygen use in adults in healthcare and emergency settings, 2017 (replacement on target saturations due 2026); BTS/ICS, ventilatory management of acute hypercapnic respiratory failure, 2016 (NIV threshold, rec 25); RCP NEWS2, 2017 (Scale 2). Bronchodilator choice, CRP and signs of exhaustion are standard practice. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Cooper on ward 7, he's having a severe COPD exacerbation and is not improving with nebulisers.", "B": "He has severe COPD with an exercise tolerance of 50 metres and two previous ICU admissions; there's no ReSPECT form in the notes.", "A": "Saturations 88% on a 28% Venturi mask, respiratory rate 30, using accessory muscles, alert. His ABG shows pH 7.30 and CO2 8.5 kPa. I've given air-driven salbutamol and ipratropium nebulisers with oxygen by nasal cannulae and prednisolone 30 mg, and the chest X-ray shows no pneumothorax.", "R": "He has a respiratory acidosis despite treatment — please come now to decide on NIV and his ceiling of treatment. I'm repeating his gas in the meantime."}, "checked": "Oct 2026"}, {"id": "BLEEP-18", "title": "Haemoptysis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Reid's just coughed up a mouthful of blood, it looks fresh and he's quite frightened.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score"}, {"lead": "Amount and character", "text": "Ask how much blood there was, whether it was fresh or altered, and whether it was a single episode or ongoing"}, {"lead": "Oxygen", "text": "Ask the nurse to sit the patient upright and, if saturations are below target, give oxygen to keep them at 94–98% (88–92% if at risk of hypercapnic respiratory failure, for example COPD or bronchiectasis, pending a blood gas)"}, {"lead": "Airway protection", "text": "If the patient is coughing up large amounts of blood, ask the nurse to position them so the airway is protected and to have suction available"}, {"lead": "Anticoagulants: hold next dose", "text": "Ask whether the patient is on any anticoagulant or antiplatelet, to hold the next dose until you have reviewed them (not if they have a mechanical heart valve or a recent coronary stent — you will discuss these with your senior first), and whether there is any other bleeding"}], "first_five_minutes": [{"lead": "ABCDE with attention to airway", "text": "Assess airway, breathing, circulation, disability and exposure, airway first. Confirm the blood is coughed up, not vomited or from the nose or mouth"}, {"lead": "Assess severity", "text": "Decide whether this is minor (streaking or small amounts) or large or ongoing bleeding. No agreed volume defines major haemoptysis (BTS): judge it by the airway, oxygenation and circulation"}, {"lead": "Chest X-ray and TB precautions", "text": "Request a chest X-ray to look for a cause — pneumonia, tumour, cavitation, or a foreign body. If TB is possible, use a single room, send 3 sputum samples for TB microscopy and culture, and give nebulisers only in a suitably ventilated room (NICE NG33)"}, {"lead": "Access, bloods and crossmatch", "text": "Put in a large-bore cannula and send FBC, CRP, renal function and clotting (including an INR if on warfarin), with a crossmatch if the bleeding is large or ongoing, otherwise a group and save, per local protocol"}, {"lead": "Consider the cause", "text": "Work through the likely causes: infection (pneumonia, bronchiectasis exacerbation, TB), malignancy, PE with infarction, trauma, or a bleeding disorder or over-anticoagulation. A high INR can make bleeding worse but doesn't explain it — look for the source (BSH)"}, {"lead": "Protect the airway", "text": "If bleeding is heavy and you know the side, lie the patient bleeding side down (standard practice); call 2222 if they can't clear their airway or are peri-arrest, and get senior and critical care help early. With major bleeding or critical illness, give oxygen by reservoir mask at 15 L/min aiming for 94–98%, even with hypercapnic risk, until blood gases (BTS). IV antibiotics for bronchiectasis and tranexamic acid are senior-led options"}, {"lead": "Hold anticoagulants, plan reversal", "text": "Hold the next anticoagulant or antiplatelet dose and document why — but if he has a recent coronary stent or a mechanical heart valve, discuss with a senior before holding. Reversal of any anticoagulant is a senior decision, usually with haematology"}], "can_i_do_alone": {"alone": ["Giving oxygen and assessing the severity of the bleeding", "Arranging a chest X-ray, a cannula, bloods including clotting and a crossmatch or group and save, and a single room if TB is possible", "Holding the next anticoagulant or antiplatelet dose while you seek same-day advice, except in a patient with a recent coronary stent or a mechanical heart valve, where you discuss before holding"], "senior_opinion": "Any patient with more than a small amount of haemoptysis, any uncertainty about the cause, any decision to reverse anticoagulation or give tranexamic acid", "senior_in_person": "Any patient with massive haemoptysis, airway compromise, haemodynamic instability or NEWS2 7 or more — this needs a senior at the bedside now, and may need critical care, respiratory and interventional radiology"}, "escalate_now_if": ["The bleeding is large or ongoing", "There is airway compromise or the patient is unable to clear the blood: call 2222", "The patient is hypotensive or has signs of shock", "There is significant hypoxia despite oxygen", "The patient is anticoagulated and the bleeding is more than streaking", "NEWS2 of 7 or more (emergency response), or 5–6 or a single parameter of 3 (urgent review)"], "document": "Record the time of onset, the amount and character of the blood, the observations and NEWS2 score, examination findings, investigations ordered including clotting results, anticoagulant doses held, any treatment given, and the plan agreed with the senior including any decision about reversal.", "fail": "An unsafe response dismisses a small haemoptysis without arranging a chest X-ray, puts the bleeding down to a high INR without looking for a cause, or fails to protect the airway in a patient with significant bleeding.", "pass": "A safe response assesses severity, arranges oxygen and a chest X-ray, sends appropriate bloods, and escalates promptly if the bleeding is significant or the patient is unstable.", "high_performance": "An excellent response considers the full differential including TB and malignancy, communicates clearly with the patient to reduce anxiety, anticipates the need for interventional radiology or bronchoscopy if bleeding is significant, and makes sure unexplained haemoptysis at 40 or over gets a suspected lung cancer referral (NICE NG12).", "one_thing": "If you only remember one thing: always arrange a chest X-ray in a patient with haemoptysis — even a small amount can be the first sign of something serious.", "img_note": "Out of hours, haematology advice and interventional radiology (which may mean a network rota or transfer to another hospital) are reached through switchboard — know how to reach both.", "source": "BTS, Guideline for bronchiectasis in adults, 2019; BTS, Guideline for oxygen use in adults, 2017; BSH, Guidelines on oral anticoagulation with warfarin (4th edition), 2011; BSH, Guideline on the management of bleeding in patients on antithrombotic agents, 2012 (BJH 2013); NICE NG33 Tuberculosis; NICE NG12 Suspected cancer; RCP NEWS2, 2017. Confirming the source, positioning, cannulation and the 2222 trigger are standard clinical practice", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Reid on ward 5, he's coughed up about a mouthful of fresh blood and is still coughing up small amounts.", "B": "He has known bronchiectasis and is on warfarin for a previous PE.", "A": "Saturations 93% on air, BP 132/80, heart rate 98, airway clear and he's sitting up with suction ready. His INR is 3.8. I've held his warfarin, sent FBC, clotting and a crossmatch, and requested a chest X-ray.", "R": "Please come and review him — I need your decision on reversing his warfarin given his PE history, and on involving respiratory and interventional radiology if the bleeding continues."}, "checked": "Oct 2026"}, {"id": "BLEEP-19", "title": "New seizure on the ward", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Whitfield's just had a fit, it lasted about two minutes and he's stopped now but he's still drowsy.\"", "nurse_call": [{"lead": "Is it still going?", "text": "Ask whether the seizure is still going right now. If it is, time it from onset — a convulsive seizure lasting 5 minutes or more is status epilepticus: attend immediately, call 2222, and have the first-line benzodiazepine ready"}, {"lead": "Time it started", "text": "Ask what time the seizure started and how long it lasted, or is lasting"}, {"lead": "Airway and position", "text": "Ask the nurse to protect the airway, put the patient in the recovery position once the seizure stops, give high-concentration oxygen while they are fitting, and not to restrain them or put anything in their mouth"}, {"lead": "Full obs + glucose", "text": "Ask for a full set of observations once safe and a bedside blood glucose — hypoglycaemia is a reversible cause you must exclude immediately"}, {"lead": "Epilepsy? Plan? Missed doses?", "text": "Ask whether the patient has known epilepsy and an individualised emergency management plan, what antiseizure medication they take, and whether any doses have been missed"}, {"lead": "New meds or triggers?", "text": "Ask about any new medications, alcohol withdrawal, or recent illness that could have triggered this"}], "first_five_minutes": [{"lead": "ABCDE, protect airway", "text": "Assess airway, breathing, circulation, disability and exposure — the priority is a patent airway and adequate oxygenation, not the neurological detail yet. Once oximetry is reliable, titrate oxygen to 94–98% (88–92% if at risk of hypercapnic respiratory failure)"}, {"lead": "Check glucose", "text": "Check blood glucose immediately — if below 4.0 mmol/L, treat as hypoglycaemia before assuming this is an epileptic seizure"}, {"lead": "Seizing at 5 minutes: treat", "text": "A convulsive seizure lasting 5 minutes or more is status epilepticus. Follow the patient's emergency management plan if available; otherwise give IV lorazepam 4 mg (about half in elderly or debilitated patients), or buccal midazolam 10 mg if there is no IV access — don't delay the first dose to get a cannula in (check BNF/local protocol). Give a second dose (lorazepam 4 mg IV or buccal midazolam 10 mg) if the seizure has not stopped 5–10 minutes after the first, and watch for respiratory depression with a bag-valve mask ready. Count any dose already given (for example the patient's own buccal midazolam): no more than 2 benzodiazepine doses in total before second-line treatment"}, {"lead": "Two doses failed: second-line", "text": "If 2 doses of benzodiazepine have not worked (unless the patient is pregnant or has recently given birth — then call the obstetric team for magnesium sulfate), the next step is IV levetiracetam, phenytoin or sodium valproate under expert guidance — the medical registrar and anaesthetist need to be there"}, {"lead": "Consider the cause", "text": "Work through the reversible causes: hypoglycaemia, hyponatraemia, hypocalcaemia, infection, alcohol withdrawal, missed antiseizure medication, drug toxicity, a new structural lesion, or eclampsia (pregnant or recently given birth)"}, {"lead": "Restart missed antiseizure doses", "text": "If doses were missed, restart the usual antiseizure medication now — if the patient is nil by mouth, levetiracetam can be given IV at the same dose (check BNF/local protocol)"}, {"lead": "Bloods and imaging", "text": "Send FBC, renal function, electrolytes, calcium, magnesium and glucose. Consider a CT head for a first seizure, focal neurology, anticoagulation or head injury"}, {"lead": "Post-ictal assessment", "text": "Once the seizure has stopped, reassess consciousness, check for focal neurological deficit, and look for injuries from the seizure"}], "can_i_do_alone": {"alone": "Protecting the airway, checking glucose, giving the first-line benzodiazepine for a seizure lasting 5 minutes or more (per the patient's plan or local protocol), and a second dose if it has not stopped 5–10 minutes after the first, while help arrives, restarting missed antiseizure medication (IV levetiracetam if nil by mouth), sending bloods, arranging a CT head if indicated, and documenting the event", "senior_opinion": "Starting a new antiseizure medication or changing a dose, any patient with a first seizure, or any uncertainty about the cause", "senior_in_person": "Any patient in status epilepticus, any patient who is not recovering consciousness between seizures, or any patient with a new focal neurological deficit — this needs a senior at the bedside now and may need critical care"}, "escalate_now_if": ["The seizure has lasted 5 minutes or more, or seizures recur without recovery in between — status epilepticus", "The patient is not breathing adequately or the airway is compromised", "Breathing becomes slow or shallow after a benzodiazepine", "A further seizure, especially 3 or more in 24 hours (managed as a medical emergency)", "There is a new focal neurological deficit after the seizure", "The patient is pregnant or has recently given birth — treat as possible eclampsia: call the obstetric team now (2222 if still fitting); magnesium sulfate, not a second-line antiseizure drug, is the senior/obstetric treatment", "The patient remains unconscious or does not return to their baseline consciousness", "There is a significant electrolyte abnormality or hypoglycaemia driving the seizure"], "document": "Record the time the seizure started and stopped, what was witnessed (including which limbs moved, eye deviation, and whether the patient was incontinent), the post-ictal state and GCS, glucose and other blood results, any medication given and the time, and the plan agreed with the senior.", "fail": "An unsafe response fails to check glucose, restrains the patient during a seizure, delays a benzodiazepine for a seizure lasting 5 minutes or more, or leaves missed antiseizure doses unreplaced.", "pass": "A safe response protects the airway, checks glucose, times the seizure, treats status epilepticus promptly, restarts missed antiseizure medication, and escalates if the seizure is prolonged or the patient does not recover.", "high_performance": "An excellent response also documents a clear eyewitness account for the notes (which matters for diagnosis), considers the full reversible-cause differential, and anticipates the need for neurology input if the patient has a first seizure or a change in seizure pattern.", "one_thing": "If you only remember one thing: check the glucose — hypoglycaemia is a reversible cause of a seizure and you must exclude it before assuming epilepsy.", "img_note": "People with epilepsy who have had prolonged or repeated seizures should have an individualised emergency management plan, often with prescribed buccal midazolam — check the notes, the drug chart and with the family, and follow it. Sodium valproate is subject to MHRA safety measures, so check them before it is used as a second-line option.", "source": "NICE, Epilepsies in children, young people and adults (NG217), chapter 7, last updated 5 Aug 2026; NICE NG133, Hypertension in pregnancy (rec 1.8.5: magnesium sulfate, not other anticonvulsants, for eclampsia); BTS guideline for oxygen use in adults (2017), E4; lorazepam injection and levetiracetam infusion SmPCs (emc); BNF online, Lorazepam, Midazolam and Levetiracetam (accessed Oct 2026); BUCCOLAM 10 mg oromucosal solution SmPC (emc 7460, revised Oct 2024). Recovery position without restraint, the wider list of causes, bloods and CT triggers are standard practice rather than guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Whitfield on ward 12, he had a seizure lasting two minutes and he's now post-ictal and drowsy.", "B": "He has known epilepsy on levetiracetam, but he's been nil by mouth since admission and missed two doses.", "A": "His glucose is 6.2, he's maintaining his airway, GCS 13 and improving, no focal deficit, no head injury and he's not anticoagulated. I've prescribed his usual levetiracetam dose IV and it's been given.", "R": "I don't think he's in status or needs a CT head tonight, but I'd like you to know and to agree the plan. Neuro observations are hourly and I'll call you immediately if he has another seizure or his GCS falls."}, "checked": "Oct 2026"}, {"id": "BLEEP-20", "title": "Reduced GCS / unresponsive patient", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Campbell's become really drowsy, he was talking to us an hour ago and now he's barely rousable.\"", "nurse_call": [{"lead": "Airway and breathing", "text": "Ask the nurse to check airway, breathing and circulation now, and to call 2222 if the patient can't keep their airway open, or call 2222 and start CPR if they are not breathing normally"}, {"lead": "Full obs + glucose", "text": "Ask for a full set of observations with NEWS2, GCS, pupils, and a bedside blood glucose — hypoglycaemia is a reversible cause you must exclude immediately"}, {"lead": "Oxygen and position", "text": "Ask the nurse to give oxygen if saturations are low (target 94–98%, or 88–92% if at risk of hypercapnia) and to position the patient in the recovery position if the airway is at risk"}, {"lead": "Recent events", "text": "Ask what changed: any new medication (especially opioids or sedatives), an anticoagulant, a procedure, a fall or head strike, or a seizure"}, {"lead": "Baseline GCS", "text": "Ask what the patient's baseline GCS and cognitive state is — a GCS of 13 in a patient who is normally 15 is very different from a patient with a baseline of 13"}], "first_five_minutes": [{"lead": "ABCDE, call for help", "text": "Assess airway, breathing, circulation, disability and exposure — if the patient is not protecting their airway, call 2222 and get senior and critical care help now"}, {"lead": "Check glucose and pupils", "text": "Check glucose immediately and treat below 4.0 mmol/L per JBDS/trust protocol: oral glucose if they can swallow safely, otherwise IV (100 ml of 20% or 200 ml of 10% over 15 minutes; glucagon 1 mg IM only if no IV access). Check the pupils — pinpoint suggests opioids, unequal a structural lesion"}, {"lead": "Assess GCS and repeat it", "text": "Assess GCS using the full scale (eye, verbal, motor), document each component, and repeat it every 15 minutes — a falling GCS is a red flag whatever the cause"}, {"lead": "Consider the cause", "text": "Work through the reversible causes: hypoglycaemia, hypoxia, hypercapnia, opioid or sedative toxicity, alcohol, sepsis, hepatic or renal encephalopathy, stroke, or a post-ictal state"}, {"lead": "Bloods, renal function, gas", "text": "Send FBC, renal function, electrolytes, calcium, glucose, ammonia if liver disease, and a blood gas (saturations don't show CO2). Opioids such as oxycodone accumulate when the kidneys are failing"}, {"lead": "Infection? Think sepsis", "text": "With suspected infection, new reduced consciousness scores 3 on NEWS2 on its own: NICE asks for a high-priority FY2-or-above review of sepsis risk. Add cultures, lactate, CRP, LFTs and clotting"}, {"lead": "Naloxone if breathing depressed", "text": "Give naloxone only for respiratory depression (respiratory rate 8 or less with the patient barely rousable, unconscious or cyanosed) or an immediate threat to life, not for drowsiness with adequate breathing. On regular opioids for pain, use the low-dose IV regimen: 100–200 micrograms, then 100 micrograms at 1-minute intervals for up to 2 doses if there is no response to the previous dose, continuing to a maximum of 2 mg, titrating to restore breathing, not full wakefulness (BNF; check local protocol)"}, {"lead": "Watch for re-sedation", "text": "Naloxone can wear off before the opioid does — hold the opioid, keep the patient on close observation for at least 4 hours after the last naloxone dose, and involve a senior about an infusion if sedation returns"}, {"lead": "Stroke or head injury?", "text": "New focal deficit: suspected stroke, call the stroke team (NICE: immediate CT if GCS is below 13). Possible head injury: CT within 1 hour if GCS 12 or less, GCS below 15 two hours after the injury, new focal deficit, post-traumatic seizure, more than 1 vomit, or signs of skull fracture (NG232). On an anticoagulant or antiplatelet (not aspirin alone) with none of these, consider CT within 8 hours of the injury. Otherwise agree imaging with your senior"}], "can_i_do_alone": {"alone": "Checking and treating glucose per protocol, assessing GCS and pupils, oxygen to target, bloods including a blood gas, titrated naloxone for opioid respiratory depression, and holding the opioid", "senior_opinion": "A reduced GCS whose cause is unclear after initial assessment, suspected infection (NICE asks for a high-priority FY2-or-above sepsis review), advice on analgesia or a naloxone infusion, or uncertainty about imaging", "senior_in_person": "Any patient who is not protecting their airway, a GCS of 8 or below or a falling GCS, respiratory depression, a NEWS2 of 7 or more, or a suspected structural cause — this needs a senior at the bedside now and may need critical care"}, "escalate_now_if": ["The patient is not protecting their airway or is not breathing adequately — call 2222", "The GCS is falling, or is 8 or below", "The respiratory rate is 8 or less, saturations stay below target despite oxygen, or the blood gas shows a raised CO2 with acidosis", "NEWS2 is 7 or more, or there are signs of shock", "There are unequal or unreactive pupils", "There is a new focal neurological deficit, or a possible head injury", "The glucose is low and does not correct with treatment, or sedation returns after naloxone"], "document": "Record the time of onset, the full GCS (eye, verbal, motor) and how it has changed, pupils, glucose, observations with NEWS2, all blood results, each naloxone dose and the time and response, and the plan agreed with the senior including any imaging requested.", "fail": "An unsafe response fails to check glucose or pupils, gives naloxone to a patient who is breathing adequately, gives a large bolus of naloxone to a patient on regular opioids for pain instead of titrating, assumes one naloxone dose has fixed the problem, or leaves a patient with a GCS of 8 or below without urgent senior and airway help.", "pass": "A safe response assesses ABCDE, checks glucose and pupils, gives titrated naloxone for opioid-induced respiratory depression, watches for re-sedation, and escalates promptly if the patient is not protecting their airway or the GCS is falling.", "high_performance": "An excellent response considers the full reversible-cause differential, looks for why the opioid has accumulated (such as an AKI), reassesses the GCS frequently rather than once, and tells the nursing staff exactly what to watch for while waiting for the senior.", "one_thing": "If you only remember one thing: check the glucose and the pupils — both are quick, both change your management, and both are easy to forget under pressure.", "img_note": "An NHS England Patient Safety Alert warned that large naloxone doses in patients on long-term opioids for pain, or who are physically dependent on opioids, can cause severe pain, distress and acute withdrawal, so UK practice is to titrate. Opioid toxicity from a prescribed dose is a patient safety incident — report it through your trust's incident system (such as Datix) so it is reviewed under PSIRF.", "source": "Resuscitation Council UK, ABCDE approach (Jul 2024) and Adult ALS guidelines (Oct 2025); RCP NEWS2 (2017); NICE NG253 (updated 23 Sep 2026), rec 1.6.2; JBDS 01 (Jan 2023); BTS oxygen guideline (2017); NHS SPS, Reversing an adult opioid overdose with naloxone (Mar 2026); Naloxone 400 micrograms/ml solution for injection (AOP Orphan, PL 30414/0004) SmPC, emc 8967, text revised Apr 2019; BNF (the naloxone repeat interval follows the BNF low-dose regimen; the SmPC and SPS give 2–3 minutes); NHS England Patient Safety Alert NHS/PSA/W/2014/016 (Nov 2014); NICE NG128 rec 1.3.2; NICE NG232 recs 1.5.8, 1.5.13. The GCS 8 airway threshold outside head injury, the CO2 trigger, 15-minute GCS checks and non-trauma CT decisions are standard practice, not guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Campbell on ward 3, his GCS dropped from 15 to 11 (E2 V4 M5) over the last hour.", "B": "He's being treated for a urinary tract infection and was started on regular oxycodone for pain yesterday.", "A": "His glucose was 7.2, pupils pinpoint, respiratory rate 8. I've given naloxone IV, 200 micrograms then 100 micrograms — his respiratory rate is now 16 and GCS 14 — and I've held the oxycodone. I've sent a venous gas and cultures. His creatinine has risen from 90 to 160, so the oxycodone is probably accumulating.", "R": "Can you come and review him now, including a high-priority sepsis review as his new confusion still scores 3 on NEWS2? Naloxone may wear off before the oxycodone, so I'd like your advice on an infusion if he re-sedates and on his analgesia with this AKI. He's on 15-minute observations."}, "checked": "Oct 2026"}, {"id": "BLEEP-21", "title": "Inpatient stroke (FAST positive)", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mrs Williams's face has drooped on the right side and her speech is slurred, it came on about twenty minutes ago.\"", "nurse_call": [{"lead": "Time of onset", "text": "Ask exactly what time the symptoms started or when the patient was last seen well — this determines whether thrombolysis or thrombectomy is an option"}, {"lead": "Coming now; confirm FAST", "text": "Tell the nurse you are coming now. Ask them to confirm the FAST findings (facial droop, arm weakness, speech disturbance) and to stay with her"}, {"lead": "Full obs + glucose", "text": "Ask for a full set of observations including BP and a bedside blood glucose — hypoglycaemia can mimic a stroke and must be excluded"}, {"lead": "Nil by mouth, medicines too", "text": "Ask the nurse to keep the patient nil by mouth, including oral medicines, until a swallow screen has been done"}, {"lead": "Anticoagulants? Last dose?", "text": "Ask whether the patient is on any anticoagulant and when the last dose was given — this affects imaging urgency and the thrombolysis decision. Hold further doses until the stroke team advises"}, {"lead": "Baseline function", "text": "Ask what the patient's baseline functional state is — this matters for the treatment decision and for the family discussion"}], "first_five_minutes": [{"lead": "Call the stroke team first", "text": "Call the stroke team immediately through your hospital's stroke bleep or pathway, with the onset time — don't delay the call to decide eligibility; that is their decision. Then let your medical registrar know"}, {"lead": "Confirm onset time", "text": "Establish the exact time of onset or the time the patient was last seen well — this is the single most important piece of information for the stroke team"}, {"lead": "ABCDE and glucose", "text": "Assess airway, breathing, circulation, disability and exposure — check glucose immediately, as hypoglycaemia is a common stroke mimic; if it is low, treat it now using your hypoglycaemia protocol, by a route that suits her swallow. Give oxygen only if saturations drop below 95%"}, {"lead": "Immediate CT head", "text": "Request a non-contrast CT head immediately — NICE recommends immediate imaging for anyone who may be a thrombolysis or thrombectomy candidate or is on an anticoagulant"}, {"lead": "Assess stroke severity", "text": "Assess the severity using a stroke scale if available (such as the NIHSS), and document the findings clearly. FAST can miss some strokes, such as sudden visual loss or cerebellar signs"}, {"lead": "Cannula, bloods and ECG", "text": "Insert a cannula, send bloods including FBC, clotting, renal function, and glucose, and request an ECG — look for atrial fibrillation as a cause"}, {"lead": "Leave the BP to the team", "text": "Do not lower the BP routinely, and do not give aspirin or any antiplatelet until the CT has excluded a bleed. BP treatment and antiplatelets are the stroke team's decision"}, {"lead": "Nil by mouth", "text": "Keep the patient nil by mouth, including oral medicines, until a swallow screen has been done, and position them safely if there is any vomiting"}], "can_i_do_alone": {"alone": "Calling the stroke team, establishing the onset time, checking glucose and treating it if low, a cannula, bloods, an ECG and an immediate CT head request, nil by mouth including oral medicines, and holding the next anticoagulant dose until the stroke team advises", "senior_opinion": "Any blood pressure treatment, whether the patient is a thrombolysis candidate (including the timing of the last anticoagulant dose), or any patient where the diagnosis is unclear — the stroke team decides", "senior_in_person": "Any patient with a suspected stroke who may be a thrombolysis or thrombectomy candidate, or whose GCS falls or airway is at risk — this needs the stroke team, and usually the medical registrar, at the bedside now. Call 2222 for airway compromise or arrest"}, "escalate_now_if": ["Any suspected new stroke — call the stroke team immediately, whatever the time since onset", "There is a reduced GCS or the patient is not protecting their airway", "There is a severe headache or vomiting suggesting a haemorrhage", "The patient is on an anticoagulant and may be having a haemorrhagic stroke", "There is a rapidly deteriorating neurological picture"], "document": "Record the exact time of onset or time last seen well, the FAST findings and any other neurological deficit, glucose and BP, the anticoagulant and time of its last dose, the time the stroke team was called, the time the CT was requested and done, and the plan agreed including any thrombolysis decision.", "fail": "An unsafe response fails to establish the time of onset, fails to check glucose, delays calling the stroke team, gives oral medicines before a swallow screen, or requests a routine rather than an immediate CT in a patient who is anticoagulated or may be a thrombolysis candidate.", "pass": "A safe response calls the stroke team first, establishes the onset time, checks glucose, assesses the FAST findings, and arranges an immediate CT head.", "high_performance": "An excellent response also considers the full differential (including hypoglycaemia, seizure, and migraine), communicates clearly with the patient and family about what is happening, and ensures the stroke team has all the information they need before they arrive.", "one_thing": "If you only remember one thing: the time of onset is the most important piece of information — get it precisely, because it determines whether the patient can be treated.", "img_note": "Most UK hospitals that admit stroke have a stroke bleep or 'code stroke' pathway into a hyperacute stroke unit; smaller hospitals may transfer patients. Thrombectomy is done in regional neuroscience centres, so the stroke team may arrange urgent transfer — learn your site's pathway on your first day.", "source": "NICE, Stroke and transient ischaemic attack in over 16s: diagnosis and initial management (NG128), last updated Apr 2022 (minor changes Mar 2025, last reviewed Mar 2026); Intercollegiate Stroke Working Party, National Clinical Guideline for Stroke for the UK and Ireland, 2023. Holding the next anticoagulant dose is standard practice, not guideline text", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling the stroke team about Mrs Williams on ward 6 — right-sided facial droop and slurred speech that started about twenty minutes ago.", "B": "She has atrial fibrillation and is on apixaban; her last dose was this morning.", "A": "Her glucose is 6.5, BP 160 over 90, GCS 15, FAST positive for face, arm and speech. She's nil by mouth, I've held her apixaban, sent bloods including clotting, and requested an immediate CT head.", "R": "She may be within the window for thrombolysis or thrombectomy — please come now. I need your decision on whether her apixaban affects the treatment options."}, "checked": "Oct 2026"}, {"id": "BLEEP-22", "title": "New severe headache", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Miss Clark's got a really bad headache, she says it came on like a thunderclap about half an hour ago and it's the worst she's ever had.\"", "nurse_call": [{"lead": "Onset and character", "text": "Ask about the onset — did it reach full intensity within about 5 minutes (thunderclap), and is it the worst headache they have ever had?"}, {"lead": "Full obs + NEWS2", "text": "Ask for a full set of observations including temperature, BP, consciousness level and the NEWS2 score"}, {"lead": "Neurological symptoms", "text": "Ask about any visual changes, weakness, numbness, confusion, vomiting, seizure, neck stiffness or a rash"}, {"lead": "Recent procedures", "text": "Ask whether the patient has had a recent lumbar puncture, epidural, or spinal procedure"}, {"lead": "Anticoagulants?", "text": "Ask whether the patient is on any anticoagulant — this matters if there is any suspicion of a bleed"}], "first_five_minutes": [{"lead": "ABCDE and GCS", "text": "Assess airway, breathing, circulation, disability (including capillary glucose) and exposure — a falling GCS in a patient with a severe headache is a red flag"}, {"lead": "Focused neurological exam", "text": "Examine for neck stiffness, photophobia, focal neurological deficit, a non-blanching rash, and fundoscopy if you are trained — papilloedema suggests raised intracranial pressure"}, {"lead": "Consider the red flags", "text": "Work through the red flags: onset peaking within 5 minutes (thunderclap), worsening headache with fever, focal neurology, papilloedema, reduced GCS or new confusion, headache that changes with posture, symptoms of giant cell arteritis, immunosuppression, or a cancer that can spread to the brain"}, {"lead": "Consider the cause", "text": "Work through the likely causes: subarachnoid haemorrhage, meningitis, intracerebral haemorrhage, cerebral venous sinus thrombosis, raised intracranial pressure, or post-dural-puncture headache"}, {"lead": "Senior review and CT", "text": "Suspected subarachnoid haemorrhage needs urgent review by a senior decision-maker — call your registrar now. If they confirm an unexplained thunderclap headache or other features of subarachnoid haemorrhage, request an urgent non-contrast CT head; CT is most accurate within 6 hours of onset"}, {"lead": "Meningitis: antibiotics now", "text": "If bacterial meningitis is suspected — fever may be absent or masked by paracetamol — take blood cultures, check for beta-lactam allergy, and give IV ceftriaxone 2 g as soon as it is suspected and within 1 hour; IV infusion over at least 30 minutes, or IV injection over 5 minutes; check BNF/local protocol. Add IV amoxicillin if there are risk factors for Listeria. Tell your registrar at the same time. Do not delay antibiotics for CT or lumbar puncture"}, {"lead": "Lumbar puncture rules", "text": "LP is a senior decision — do not do one without senior input. If a CT done within 6 hours of onset is normal, LP is not routinely offered"}, {"lead": "Analgesia and antiemetic", "text": "Give effective analgesia, including an opioid if needed, and an antiemetic — document any opioid given, as it affects GCS and pupils"}], "can_i_do_alone": {"alone": "Taking the history, checking observations including temperature, examining for red flags, checking glucose, giving analgesia and an antiemetic, taking blood cultures and giving IV ceftriaxone if bacterial meningitis is suspected, and requesting the CT head once your senior has confirmed it is needed", "senior_opinion": "Any new severe headache with a red flag where you are unsure of the cause, and any decision about lumbar puncture", "senior_in_person": "Any thunderclap headache or other suspected subarachnoid haemorrhage, suspected meningitis, reduced or falling GCS, focal neurology, papilloedema, or an anticoagulated patient with a new severe headache — NICE recommends urgent review by a senior decision-maker for suspected subarachnoid haemorrhage"}, "escalate_now_if": ["The headache is thunderclap in onset — suspect subarachnoid haemorrhage and get it excluded urgently, even though most have another cause", "You suspect bacterial meningitis (fever, neck stiffness, altered consciousness or a non-blanching rash; not all need be present) — give antibiotics now as well", "There is a reduced GCS, a seizure or a new focal neurological deficit", "There is papilloedema or other signs of raised intracranial pressure", "The patient is anticoagulated and has a new severe headache"], "document": "Record the time of onset and how quickly the headache peaked, the observations including temperature, the full neurological examination including GCS, the red flags identified, the time you called the senior, the time the CT was requested, any antibiotics or opioids given with times, and the plan agreed.", "fail": "An unsafe response dismisses a thunderclap headache as migraine, does not get urgent senior review and a CT, delays antibiotics in suspected meningitis while waiting for imaging or LP, or performs a lumbar puncture without senior input when raised intracranial pressure has not been excluded.", "pass": "A safe response takes a careful onset history, checks the temperature and examines for red flags, escalates urgently to a senior, gets an urgent CT head, gives antibiotics within the hour if meningitis is suspected, and gives effective analgesia.", "high_performance": "An excellent response also considers venous sinus thrombosis and post-dural-puncture headache, documents the red flag assessment clearly, and explains to the patient why urgent tests are needed.", "one_thing": "If you only remember one thing: a thunderclap headache needs subarachnoid haemorrhage excluded urgently — get a senior and an urgent CT; if meningitis is possible, antibiotics go in within the hour.", "img_note": "In the UK, neurosurgery is provided by regional neurosurgical centres, so most hospitals do not have neurosurgeons on site. If a subarachnoid haemorrhage is confirmed, your registrar or consultant refers to the regional centre, usually through an online referral system plus a phone call, and the patient may be transferred. Have the CT images, GCS trend and anticoagulant history ready when the referral is made.", "source": "NICE NG228, Subarachnoid haemorrhage caused by a ruptured aneurysm (Nov 2022) — thunderclap definition, senior review before CT, 6- and 12-hour LP rules, analgesia; NICE NG240, Meningitis (bacterial) and meningococcal disease (Mar 2024) — antibiotics within 1 hour, ceftriaxone at the highest BNF dose, amoxicillin for Listeria risk; BNF, Ceftriaxone (bacterial meningitis: 2 g every 12 hours, alternatively 4 g once daily; accessed Oct 2026); NICE CG150, Headaches in over 12s (updated Jun 2025) — red flags. Venous sinus thrombosis, post-dural-puncture headache and the anticoagulant trigger are standard clinical practice, not guideline recommendations.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Miss Clark on ward 9, she has a sudden severe headache that peaked within a minute, about half an hour ago — the worst she's ever had.", "B": "She has no significant past medical history and is not on any anticoagulant.", "A": "Her GCS is 15, she has neck stiffness and photophobia but no focal neurology and no rash, temperature 36.9 taken before any paracetamol, BP 140 over 85, and her other observations are normal. I've given IV paracetamol, morphine and an antiemetic. The thunderclap onset makes a bleed most likely and the neck stiffness fits that, but meningitis can present without fever, so I've taken blood cultures and, as she has no penicillin or cephalosporin allergy, given IV ceftriaxone 2 g because I can't exclude meningitis.", "R": "I'm concerned about a subarachnoid haemorrhage — please come and review her now. Are you happy for me to request an urgent non-contrast CT head in the meantime?"}, "checked": "Oct 2026"}, {"id": "BLEEP-23", "title": "Back pain with red flags", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Wright's complaining of bad back pain and he says he's been a bit numb around his back passage and he couldn't go to the toilet properly this morning.\"", "nurse_call": [{"lead": "Saddle numbness?", "text": "Ask specifically about numbness or altered sensation around the saddle area (inner thighs, buttocks, perineum, genitals) — this is a red flag for cauda equina syndrome"}, {"lead": "Bladder and bowel function", "text": "Ask about difficulty starting or feeling the flow of urine, retention, new incontinence, loss of bowel control or sensation, or new sexual dysfunction"}, {"lead": "Bilateral leg symptoms", "text": "Ask whether there is pain, weakness or numbness in both legs, and whether it is getting worse"}, {"lead": "Bladder scan + NBM", "text": "Ask for a bladder scan (pre- and post-void if he can pass urine) and to keep him nil by mouth until reviewed, in case he needs emergency surgery"}, {"lead": "Full obs + NEWS2", "text": "Ask for a full set of observations and the NEWS2 score, including temperature — fever raises the possibility of spinal infection"}, {"lead": "Anticoagulants?", "text": "Ask whether the patient is on any anticoagulant, or has had a recent spinal or epidural procedure — think of a spinal haematoma"}], "first_five_minutes": [{"lead": "Focused neurological exam", "text": "Examine the lower limbs for power, sensation and reflexes, and test saddle (S2–S5) sensation — document the findings clearly with the time"}, {"lead": "Perianal sensation", "text": "Record the patient's own report of perianal sensation and test it with a chaperone. The national pathway says a digital rectal examination is not needed to make the referral, so do not let it delay anything"}, {"lead": "Use the bladder scan", "text": "A post-void residual over 200 mL makes CES far more likely, but a low residual does not rule it out. If the scan is over 600 mL, whether he cannot void or after voiding, catheterise and record whether he feels the catheter and a catheter tug"}, {"lead": "Emergency MRI", "text": "Suspected CES needs an emergency MRI as soon as possible, and within 4 hours of the request (if there is no emergency MRI on site, arrange urgent transfer per local pathway). Discuss the request with a senior decision-maker (ST4 or above) — the spinal team does not need to agree it first"}, {"lead": "Refer if compression", "text": "If the MRI shows cauda equina compression, refer immediately to the on-call spinal surgical team and keep the patient nil by mouth"}, {"lead": "Consider the cause", "text": "Consider the likely cause: a large disc prolapse, spinal haematoma (anticoagulants, recent spinal procedure), infection, tumour, or fracture"}, {"lead": "Analgesia", "text": "Give appropriate analgesia — but do not let this delay the senior discussion or the MRI"}, {"lead": "Document the times", "text": "Record the time you suspected CES, the time you discussed it with your senior, the time the MRI was requested, and the time of any spinal referral"}], "can_i_do_alone": {"alone": "Taking the red-flag history, examining the lower limbs and saddle sensation, arranging a bladder scan, catheterising if the bladder scan is over 600 mL, keeping him nil by mouth, and giving analgesia", "senior_opinion": "Discuss every suspected CES with a senior decision-maker (ST4 or above, or a consultant) now to agree the emergency MRI request, and any back pain with red flags where you are unsure of the urgency", "senior_in_person": "Suspected CES with retention, progressive or severe bilateral leg weakness, or a suspected spinal haematoma or infection needs your senior to review promptly; confirmed compression on MRI needs the spinal surgical team immediately"}, "escalate_now_if": ["There is saddle numbness or altered perianal, perineal or genital sensation", "There is new difficulty passing urine, retention, incontinence, loss of bowel control or sensation, or new sexual dysfunction", "There is severe or progressive weakness in both legs", "The patient is anticoagulated or has had a recent spinal or epidural procedure and develops new back pain with neurological symptoms", "The MRI shows cauda equina compression — refer to the spinal team immediately"], "document": "Record the time of onset and progression of symptoms, the lower limb examination and saddle sensation, the patient's report of perianal sensation, the pre- and post-void bladder volumes, who you discussed the case with and when, the time the MRI was requested and performed, and the time of any spinal referral. CES is a frequent source of litigation, so precise timed notes matter.", "fail": "An unsafe response fails to ask about saddle sensation or bladder and bowel function, is reassured by a low bladder residual, or delays the emergency MRI by waiting for the spinal team to agree to it or for a rectal examination.", "pass": "A safe response asks about the red flags, examines the lower limbs and saddle sensation, uses the bladder scan correctly, discusses with a senior and gets an emergency MRI within 4 hours, and refers to the spinal team immediately if compression is confirmed.", "high_performance": "An excellent response also considers spinal haematoma, infection and malignancy, keeps the patient nil by mouth in case surgery is needed, documents everything with times, and explains to the patient why the tests are urgent.", "one_thing": "If you only remember one thing: ask about saddle sensation and bladder function in anyone with back pain — suspected CES needs an emergency MRI within 4 hours, and a normal bladder scan does not rule it out.", "img_note": "In England, the national suspected CES pathway sets an MRI within 4 hours of the request, says the spinal surgeons do not need to agree the scan first, and asks for an ST4-level discussion before the request. Timed, contemporaneous notes protect the patient and you.", "source": "GIRFT (NHS England), National Suspected Cauda Equina Syndrome Pathway, Feb 2023, updated Mar 2026; NICE, Low back pain and sciatica in over 16s: assessment and management (NG59), last updated Jul 2026. The anticoagulant and fever prompts are standard clinical practice; the pathway lists haematoma, infection and tumour as rarer causes", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Wright on ward 4, he has severe back pain with new saddle numbness and difficulty passing urine — I'm worried about cauda equina syndrome.", "B": "He has a previous lumbar disc prolapse and is not on any anticoagulant.", "A": "He has reduced saddle sensation and reduced perianal sensation, lower limb power is 4 out of 5 bilaterally, his post-void residual is 400 mL, and his observations are normal. I've kept him nil by mouth and given analgesia.", "R": "I'd like to request an emergency MRI now — can you agree the request and come and review him? If it shows compression I'll refer to the spinal team straight away."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-24", "title": "Hyperglycaemia and suspected DKA", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Shah's blood glucose is 28 and he's been vomiting all morning, his ketones are 3.2 and he's breathing quite deeply.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations including respiratory rate, saturations, heart rate, BP and GCS, and the NEWS2 score"}, {"lead": "IV access, fluids ready", "text": "Ask the nurse to site a large-bore cannula and have 0.9% sodium chloride ready so fluids can start as soon as you prescribe them, with a fluid balance chart and hourly monitoring"}, {"lead": "Bedside glucose + ketones", "text": "Ask for the current capillary glucose and blood ketone reading, and when they were taken"}, {"lead": "Insulin history", "text": "Ask whether the patient is known to have diabetes, what insulin they take, whether doses have been omitted, and whether they take an SGLT2 inhibitor"}, {"lead": "Precipitant", "text": "Ask about any recent illness, infection, missed insulin, or new medication — DKA almost always has a precipitant, and it must be treated alongside the DKA itself"}, {"lead": "Cardiac monitor + urine output", "text": "Ask for cardiac monitoring if available and for an accurate urine output record — consider a catheter if incontinent or no urine passed by 60 minutes"}], "first_five_minutes": [{"lead": "ABCDE, GCS, airway", "text": "ABCDE, including GCS — a drowsy patient needs senior and critical care assessment; if obtunded or persistently vomiting, consider an NG tube with airway protection"}, {"lead": "Confirm the diagnosis", "text": "Confirm all three JBDS criteria: blood glucose above 11 mmol/L or known diabetes; blood ketones above 3.0 mmol/L or urine ketones 2+ or more; and venous bicarbonate below 15 mmol/L and/or venous pH below 7.3"}, {"lead": "VBG and bloods", "text": "Take a venous blood gas for pH, bicarbonate and potassium, and send U&E, FBC, lab glucose and blood cultures, with an ECG, a pregnancy test in women of child-bearing age, and a chest X-ray if indicated"}, {"lead": "Start IV fluids", "text": "Give 0.9% sodium chloride: 1 litre over the first hour if systolic BP is 90 or more; if below 90, give 500 mL over 10–15 minutes and reassess. Be more cautious in the elderly, the young (18–25), pregnancy, and heart or kidney failure"}, {"lead": "Check K, then start the FRIII", "text": "Once fluids are running, check the potassium on the gas. If it is below 3.5 mmol/L, get senior review before starting insulin. Otherwise start a fixed-rate intravenous insulin infusion (FRIII) at 0.1 units/kg/hour (estimated weight) per your local DKA protocol — no priming bolus, not a sliding scale. Continue it until ketones are below 0.6 mmol/L and venous pH is above 7.3 — do not use bicarbonate to judge resolution"}, {"lead": "Continue basal insulin", "text": "Continue the patient's usual long-acting insulin at the usual dose and time — it prevents rebound ketosis when the infusion stops"}, {"lead": "Replace and recheck potassium", "text": "After the first litre, use the JBDS potassium rules: K above 5.5 — none; K 3.5–5.5 — 40 mmol/L in each bag if passing urine (use premixed bags); K below 3.5 — senior review, as more potassium is needed. Insulin drops K fast: repeat the gas at 1 hour, 2 hours, then 2-hourly (hourly if K is outside 4.0–5.5)"}, {"lead": "Add glucose when below 14", "text": "When glucose falls below 14 mmol/L, add 10% glucose at 125 mL/hour alongside the saline — do not stop the insulin"}, {"lead": "Treat precipitant, give LMWH", "text": "Identify and treat the precipitant — infection, missed insulin, myocardial infarction, SGLT2 inhibitor (stop it) — and give prophylactic LMWH unless contraindicated"}], "can_i_do_alone": {"alone": "Taking the venous blood gas and bloods, starting IV fluids and, if potassium is 3.5 mmol/L or above, the fixed-rate insulin infusion following your local DKA protocol, continuing basal insulin, replacing potassium per the JBDS rules when K is 3.5–5.5, adding 10% glucose, prescribing LMWH, and monitoring glucose and ketones hourly", "senior_opinion": "K still outside 4.0–5.5 mmol/L an hour after adjusting replacement, any uncertainty about the diagnosis or the precipitant, or ketones not falling by at least 0.5 mmol/L/hour (or, only if blood ketones cannot be measured, bicarbonate not rising by 3 mmol/L/hour) despite a working infusion", "senior_in_person_lead": "Any of these needs consultant review and consideration of HDU:", "senior_in_person": ["Any JBDS severity marker — ketones above 6, bicarbonate below 5, pH below 7.0, K below 3.5 on admission, GCS below 12, SpO2 below 92% on air, systolic BP below 90, pulse over 100 or below 60, or anion gap above 16", "Pregnancy, or heart or kidney failure"]}, "escalate_now_if": ["The GCS is below 12 or falling, or the patient is drowsy or obtunded — if it falls on treatment, check glucose at once and consider urgent brain imaging (cerebral oedema)", "Potassium is below 3.5 mmol/L at any point — get senior review now, as more potassium is needed, and do not start insulin until a senior has reviewed", "Systolic BP is below 90 despite fluids, urine output is below 0.5 mL/kg/hour, or there is no IV access (call critical care)", "Any other JBDS severity marker: ketones above 6 mmol/L, bicarbonate below 5 mmol/L, pH below 7.0, SpO2 below 92% on air, pulse over 100 or below 60, or anion gap above 16", "The patient is pregnant (get senior obstetric help too), or has heart or kidney failure, or other serious comorbidity", "Ketones are not falling by at least 0.5 mmol/L/hour despite a working infusion, or DKA has not resolved by 24 hours"], "document": "Record the three diagnostic values and their times, the severity markers, the fluid and insulin prescriptions with start times, the potassium level and replacement, hourly glucose and ketones, the precipitant identified, the GCS monitoring, and the plan agreed with the senior including any HDU referral.", "fail": "An unsafe response uses a sliding scale instead of a fixed-rate infusion, starts insulin with potassium below 3.5 without senior review, stops the basal insulin, stops the insulin when the glucose falls instead of adding glucose, omits or fails to recheck potassium, or misses the severity markers that need HDU.", "pass": "A safe response confirms the three criteria, starts fluids and a fixed-rate insulin infusion, continues basal insulin, replaces potassium by the JBDS thresholds, adds 10% glucose below 14 mmol/L, gives LMWH, and monitors glucose and ketones hourly.", "high_performance": "An excellent response also considers euglycaemic DKA in patients on SGLT2 inhibitors, monitors the GCS for cerebral oedema (especially in young adults), and involves the diabetes team early.", "one_thing": "If you only remember one thing: DKA is bicarbonate below 15 and/or pH below 7.3 with ketones above 3 — start the fixed-rate insulin, keep the basal insulin, and add glucose when the glucose falls below 14 rather than stopping the insulin.", "img_note": "UK hospitals use a JBDS-based DKA care pathway — a paper or electronic proforma with hourly glucose and ketone checks and timed blood gases. Ask where it is kept on your first day. Every adult with DKA should be referred to the hospital's inpatient diabetes team (often a diabetes specialist nurse) as early as possible, ideally within 24 hours, to look at why it happened and prevent a repeat.", "source": "Joint British Diabetes Societies for Inpatient Care (JBDS 02), The management of diabetic ketoacidosis in adults, revised Mar 2023, and its pathway. Delaying insulin when K is below 3.5 mmol/L: Hyperglycaemic crises in adults with diabetes, consensus report (ADA, EASD, JBDS, AACE, DTS), 2024. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Shah on ward 7 — he has DKA: glucose 28, ketones 3.2, venous pH 7.15 and bicarbonate 12.", "B": "He has type 1 diabetes and has been nil by mouth since admission, and has missed his insulin.", "A": "RR 26, HR 96, BP 118 over 70, SpO2 97% on air, GCS 15, potassium 4.6. Sodium 136, chloride 100, bicarbonate 12, so his anion gap including potassium is about 29 — that's a JBDS severity marker; everything else is below the thresholds. I've given the first litre of saline, started the fixed-rate insulin infusion at 0.1 units/kg/hour, continued his basal insulin, and prescribed potassium in the next bags and LMWH.", "R": "Could you come and review him now? He meets a JBDS severity marker, so I think he needs consultant review and consideration of HDU. I am checking glucose and ketones hourly and a venous gas at 1 and 2 hours, and I'll call you straight away if he develops any severity marker or the ketones aren't falling."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-25", "title": "Hyperosmolar hyperglycaemic state (HHS)", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mrs Osei's glucose is 38 and she's really drowsy, her mouth is dry and she's been passing lots of urine, she's a type 2 diabetic.\"", "nurse_call": [{"lead": "Full obs + GCS", "text": "Ask for the full set of observations including GCS and temperature, and the NEWS2 score — confusion and drowsiness are common in HHS"}, {"lead": "IV access, fluids ready", "text": "Ask the nurse to site IV access and have 0.9% sodium chloride ready so fluids can start as soon as you prescribe them — fluid replacement is the priority in HHS"}, {"lead": "Glucose and ketones", "text": "Ask for the current capillary glucose and blood ketone reading — in HHS ketones are usually low, and the ketone level decides whether insulin starts straight away"}, {"lead": "Fluid balance and weight", "text": "Ask for the recent fluid balance and the patient's weight — the fluid deficit in HHS is large and develops over days"}, {"lead": "Precipitant and medications", "text": "Ask about recent illness, infection, or any new medication (particularly steroids, thiazides, or antipsychotics) that could have precipitated this"}, {"lead": "Heels and pressure areas", "text": "Ask the nurse to check the feet and heels and offload them — patients with HHS are at high risk of pressure ulceration"}], "first_five_minutes": [{"lead": "ABCDE, protect airway", "text": "Assess airway, breathing, circulation, disability and exposure — if the GCS is reduced, protect the airway and get senior and critical care help early; with no IV access, request critical care support now"}, {"lead": "Confirm the diagnosis", "text": "Confirm the JBDS features: marked hyperglycaemia (30 mmol/L or more), osmolality usually 320 mOsm/kg or more (2Na + glucose + urea), hypovolaemia, ketones 3.0 mmol/L or less, and no significant acidosis (pH 7.3 or more, bicarbonate 15 mmol/L or more)"}, {"lead": "VBG and bloods", "text": "Take a venous blood gas (pH, bicarbonate, lactate) and send U&E, osmolality, FBC, CRP and blood cultures if infection is suspected, with an ECG"}, {"lead": "Fluids first", "text": "Give 0.9% sodium chloride, 1 litre over the first hour (consider faster if systolic BP is below 90), reassessing for fluid overload, especially in heart or kidney failure"}, {"lead": "Insulin depends on ketones", "text": "Do not start insulin at first unless ketones are above 1.0 mmol/L — IV fluids alone will lower the glucose; your senior decides when to start insulin if the glucose stops falling. Ketones above 1.0 mmol/L and not acidotic (venous pH above 7.3 and bicarbonate above 15): start the fixed-rate insulin infusion at 0.05 units/kg/hour now, and tell your senior at the same time."}, {"lead": "Mixed DKA/HHS?", "text": "If ketones are above 3.0 mmol/L with pH below 7.3 and bicarbonate below 15, this is mixed DKA/HHS — follow the DKA pathway: check the potassium first (below 3.5 mmol/L, senior review before insulin), start fixed-rate insulin at 0.1 units/kg/hour, and call your senior now. If it fits neither pattern (for example pH below 7.3 with bicarbonate above 15), or it is unclear whether this is HHS or mixed DKA/HHS, get early specialist advice"}, {"lead": "Keep the falls gradual", "text": "Glucose should fall by no more than 5 mmol/L/hour, osmolality by 3–8 mOsm/kg/hour, and sodium should change by no more than 10 mmol/L in 24 hours; an early rise in sodium is expected and alone isn't a reason for 0.45% saline. Check glucose, osmolality and ketones hourly, GCS every 1–2 hours"}, {"lead": "Potassium", "text": "No potassium in the first litre. Then replace by the JBDS rules: above 5.5 — none; 3.5–5.5 — 40 mmol/L in each bag (premixed); below 3.5 — senior review"}, {"lead": "Precipitant, sepsis, LMWH, feet", "text": "Treat the precipitant (infection, MI, stroke, drugs). Suspected infection with NEWS2 7 or more is NICE NG253 high risk: urgent FY2-or-above review and IV antibiotics within 1 hour unless already given. Give prophylactic LMWH unless contraindicated, protect the heels with daily foot checks, and refer early to the diabetes team"}], "can_i_do_alone": {"alone": "Taking the venous blood gas and bloods, starting 0.9% sodium chloride per your local HHS protocol, replacing potassium when it is 3.5–5.5, starting the fixed-rate insulin infusion at 0.05 units/kg/hour if ketones are above 1.0 and no more than 3.0 mmol/L and she is not acidotic (telling your senior at the same time), prescribing IV antibiotics per trust policy for suspected sepsis, prescribing LMWH, arranging heel protection, referring to the diabetes team, and monitoring glucose, ketones and osmolality", "senior_opinion": "Every HHS patient, early (JBDS calls this essential); tell your senior when insulin is started; and any decision about changing insulin, fluid rates in heart or kidney failure, potassium below 3.5, or glucose, osmolality or sodium changing faster than the limits", "senior_in_person": ["Any JBDS marker for HDU care — osmolality above 350, sodium above 160, pH below 7.1, potassium below 3.5 or above 6 on admission, GCS below 12 or abnormal AVPU, SpO2 below 92% on air, systolic BP below 90, pulse over 100 or below 60", "The other JBDS HDU markers — urine output below 0.5 mL/kg/hour, creatinine above 200 or AKI, hypothermia, a new MI or stroke, or other serious co-morbidity", "Any new drowsiness or fall in GCS, NEWS2 of 7 or more, or no IV access"]}, "escalate_now_if": ["The GCS is below 12 or falling, or AVPU is abnormal", "Systolic BP is below 90 or there is shock despite fluids", "Osmolality is above 350 mOsm/kg or sodium is above 160 mmol/L", "Potassium is below 3.5 mmol/L, or 6.0 mmol/L or above", "Ketones are above 3.0 (with acidosis, this is mixed DKA/HHS), or there is a new MI, stroke, or heart or kidney failure complicating fluid management", "NEWS2 is 7 or more, or you cannot get IV access"], "document": "Record the diagnostic values with times, the calculated osmolality, the ketone level and the insulin decision, the fluid prescriptions with start times, potassium given, hourly glucose and osmolality with the rate of fall, sodium trend, GCS and NEWS2, foot check, LMWH, the precipitant and any antibiotics with times, and the plan agreed with the senior.", "fail": "An unsafe response starts insulin at DKA rates before fluids in a patient without ketonaemia, lets the glucose or sodium fall too fast, misses a raised ketone level that needs insulin now, or forgets LMWH and heel protection.", "pass": "A safe response confirms the diagnosis, starts 0.9% sodium chloride first, uses the ketone level to decide on insulin, keeps glucose, osmolality and sodium within the JBDS limits, replaces potassium, gives LMWH, protects the feet, and escalates any HDU marker.", "high_performance": "An excellent response also recognises a mixed DKA/HHS picture, weighs the fluid plan against heart and kidney function, looks for a vascular precipitant, and anticipates HDU care early.", "one_thing": "If you only remember one thing: in HHS, fluids come first and the ketones decide the insulin — and glucose, osmolality and sodium must fall slowly.", "img_note": "In UK hospitals a pressure ulcer that develops in hospital is a reportable patient safety incident, logged on the trust's incident system (such as Datix or the national LFPSE service) and reviewed under PSIRF. HHS patients are often older, drowsy and immobile, so prescribe and document heel protection and daily foot checks on admission.", "source": "Joint British Diabetes Societies for Inpatient Care (JBDS 06), The management of the hyperosmolar hyperglycaemic state (HHS) in adults, Feb 2022, with its 2022 care pathway. NICE NG253 Suspected sepsis (updated 23 Sep 2026), recs 1.8.2–1.8.3, for high-risk sepsis; RCP NEWS2 (2017). The precipitant drug examples and incident reporting are standard UK practice, not JBDS. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Osei on ward 4 — she has HHS: glucose 38, calculated osmolality 335, and she is drowsy.", "B": "She has type 2 diabetes, was admitted with a chest infection, and hasn't been able to take her metformin.", "A": "GCS 13 — she responds to voice — BP 104 over 60, HR 96, sodium 142, urea 13, potassium 4.2, ketones 0.4, pH 7.35, bicarbonate 20, creatinine 110 (baseline 95), urine output 40 mL an hour, RR 20, SpO2 95% on air, temperature 37.6 — NEWS2 6, including 3 for her new drowsiness — and she is already on IV antibiotics for the chest infection. She has one JBDS HDU marker, abnormal AVPU. I've started 0.9% saline, 1 litre over the first hour, with potassium 40 mmol/L in each bag from the second litre, prescribed LMWH and heel protection, and I'm checking glucose and osmolality hourly. With ketones of 0.4 I haven't started insulin.", "R": "Please come and review her in person — her reduced conscious level is an HDU marker — and agree the fluid plan, HDU care, and when to start insulin if the glucose stops falling."}, "checked": "Oct 2026"}, {"id": "BLEEP-26", "title": "Hyponatraemia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"The lab just rang, Mrs Blackwell's sodium has come back at 122 and she's been a bit confused this morning.\"", "nurse_call": [{"lead": "Full obs + GCS", "text": "Ask for the full set of observations and the current GCS — symptoms, not the number, decide how urgent this is"}, {"lead": "Symptoms", "text": "Ask about headache, confusion, nausea, vomiting, drowsiness or any seizure, and to be called back at once if she vomits, fits or becomes harder to rouse"}, {"lead": "Onset and previous results", "text": "Ask whether this is new and what previous sodium results show — unless it is documented to have developed within 48 hours, treat it as chronic"}, {"lead": "Medications", "text": "Ask about thiazide diuretics, SSRIs, carbamazepine, PPIs and any recent medication changes"}, {"lead": "Fluids and fluid balance", "text": "Ask what IV fluids she is on and for the fluid balance — hypotonic fluids can drop the sodium quickly"}, {"lead": "Glucose", "text": "Ask for a bedside glucose — hyperglycaemia lowers the measured sodium and must be excluded"}], "first_five_minutes": [{"lead": "Classify symptoms, then escalate", "text": "Severe — vomiting, cardiorespiratory distress, deep somnolence, seizures or coma: registrar to the bedside now and an emergency call per your trust, for immediate hypertonic saline in a monitored setting (a senior decision; don't wait to repeat the sodium). Moderately severe — nausea without vomiting, confusion or headache: registrar to review her now. Not sure which: call the registrar now"}, {"lead": "ABCDE, GCS, acute or chronic", "text": "Assess ABCDE and GCS. Acute means documented to have developed within 48 hours — discuss it with your senior now; otherwise treat it as chronic"}, {"lead": "Confirm the true sodium", "text": "Repeat the sodium and check glucose and serum osmolality — if the glucose is high, correct the sodium for it before calling this true hyponatraemia"}, {"lead": "Adrenal crisis? Hydrocortisone", "text": "Hypotension, hypoglycaemia or vomiting: take a cortisol sample and, if she is unwell, give hydrocortisone 100 mg IV/IM straight after it without waiting for the result — then involve endocrinology"}, {"lead": "Stop thiazide + hypotonic fluids", "text": "Hold a thiazide and stop any hypotonic IV fluids; discuss stopping other contributors (SSRIs, carbamazepine, PPIs) with your senior"}, {"lead": "Paired tests + volume status", "text": "Send paired serum and urine osmolality and urine sodium, plus TFTs and a cortisol, ideally before treatment changes the picture — never delay treating severe symptoms for them. Assess pulse, BP (postural drop if safe), JVP, mucous membranes and oedema; this is often inaccurate, so the paired tests matter more"}, {"lead": "Write the correction limit", "text": "Sodium to rise no more than 10 mmol/L in the first 24 hours and 8 in each 24 hours after; lower limits if high risk of osmotic demyelination, as set by your senior. These are limits, not targets. Higher risk: thiazides, antidepressants, alcohol misuse, liver disease, profound or long-standing hyponatraemia. Agree any potassium replacement with your senior, as it also raises the sodium. If active treatment is started for moderately severe symptoms, recheck at 1, 6 and 12 hours; with hypertonic saline for severe symptoms, the sodium is rechecked after 20 minutes and then as set by your senior. Use the same method (lab or gas) each time"}], "can_i_do_alone": {"alone": "Repeating the sodium, checking glucose, assessing volume status, holding a thiazide and stopping hypotonic fluids, sending paired serum and urine osmolality, urine sodium, TFTs and cortisol, and giving hydrocortisone after the cortisol sample if adrenal crisis is suspected", "senior_opinion": "Discuss now any acute hyponatraemia, any doubt about which symptom group she is in, stopping any drug other than a thiazide, and any uncertainty about the cause or the correction plan", "senior_in_person": "Moderately severe symptoms (new confusion, headache, nausea without vomiting): registrar review now to decide on hypertonic saline. Severe symptoms (vomiting, cardiorespiratory distress, deep somnolence, seizures or coma) or a sodium rising faster than the limit: senior at the bedside now; severe symptoms need immediate hypertonic saline, monitored"}, "escalate_now_if": ["There are severe symptoms: vomiting, a seizure, cardiorespiratory distress, or deep somnolence or coma.", "There are new moderately severe symptoms such as confusion — the registrar needs to review her now.", "You cannot tell which symptom group she is in.", "The hyponatraemia is acute (documented to have developed within 48 hours).", "Adrenal insufficiency is suspected (hypotension, hypoglycaemia, vomiting) — give hydrocortisone and get senior help.", "The sodium is rising faster than the agreed limit (no more than 10 mmol/L in the first 24 hours and 8 in each 24 hours after, or lower if set by your senior), or urine output suddenly rises with dilute urine — call before the limit is reached.", "The sodium keeps falling despite treatment, or symptoms don't improve as it rises (look for another cause)."], "document": "Record the sodium, glucose and osmolality with times, previous results and likely duration, symptoms and GCS, volume status, drugs and fluids stopped, the paired samples sent, the agreed correction limit, the timing of repeat sodium checks, and the plan agreed with the senior.", "fail": "An unsafe response treats a confused patient with a sodium of 122 as routine, lets the sodium rise by more than 10 mmol/L in the first 24 hours or 8 in any 24 hours after, gives hypertonic saline without senior input, or misses adrenal insufficiency in a hypotensive, hyponatraemic patient.", "pass": "A safe response classifies by symptoms and escalates first, confirms the result, assesses duration and volume status, stops offending drugs and fluids, sends paired tests, and writes the correction limit in the notes.", "high_performance": "An excellent response also recognises when the cause is multifactorial in an older patient, watches for an overshoot once the thiazide is stopped (a brisk water diuresis can raise the sodium quickly), and makes sure the limit is written in the notes for the night team.", "one_thing": "If you only remember one thing: symptoms matter more than the number — new confusion with a sodium of 122 needs the registrar now, and the sodium must rise no more than 10 mmol/L in the first 24 hours and 8 in each 24 hours after.", "img_note": "UK laboratories phone critical results, such as a sodium of 120 mmol/L or below (labs may set their own local limits), to the ward, often to the nurse in charge, under Royal College of Pathologists guidance. Write in the notes who called, when, and what you did. If hypertonic saline is needed, it is usually given on a monitored unit after a registrar or consultant decision, so involve your senior early.", "source": "ESE/ERA-EDTA/ESICM, Clinical practice guideline on diagnosis and treatment of hyponatraemia, Eur J Endocrinol 2014 (symptom classification; rec 7.4.1.4: avoid a rise of >10 mmol/l in the first 24 h and >8 mmol/l in every 24 h thereafter; chronic assumed unless reasons to assume acute); Society for Endocrinology, Emergency management of severe symptomatic hyponatraemia in adult patients, Endocr Connect 2016; NICE NG243, Adrenal insufficiency: identification and management, Aug 2024; RCPath G158, The communication of critical and unexpected pathology results, May 2026; BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Blackwell on ward 6 — her sodium is 122 and she has been newly confused this morning.", "B": "She started a thiazide two weeks ago for hypertension, and her sodium was normal before that.", "A": "GCS 14, no vomiting or seizures. RR 16, SpO2 97% on air, BP 138 over 76, HR 82, temperature 36.8 — NEWS2 3, all from the new confusion, so a single red score. Glucose 6.8, she looks euvolaemic. I've stopped the thiazide, sent paired serum and urine osmolality, urine sodium, TFTs and cortisol, and I've written a provisional limit in the notes of no more than 10 mmol/L in the first 24 hours and 8 in each 24 hours after.", "R": "She has moderately severe symptoms, so could you come and see her now to decide whether she needs hypertonic saline or just the thiazide stopped, confirm the correction limit given she's on a thiazide, and agree how often to recheck the sodium?"}, "checked": "Oct 2026"}, {"id": "BLEEP-27", "title": "Hypernatraemia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"The lab has rung, Mr Price's sodium is 156 and he's been a bit drowsy since this morning.\"", "nurse_call": [{"lead": "Full obs + GCS", "text": "Ask for the full set of observations, temperature, current GCS and NEWS2 — new drowsiness scores 3 on its own, which means urgent review"}, {"lead": "Fluid balance and intake", "text": "Ask for the recent fluid balance, and whether the patient can drink or is relying on staff or an NG tube for water"}, {"lead": "IV fluids and feeds", "text": "Ask what IV fluids and feeds the patient is on, and whether prescribed water flushes have been given"}, {"lead": "Urine output", "text": "Ask about urine output — large volumes of urine suggest diabetes insipidus (pale, dilute urine) or an osmotic diuresis rather than simple lack of water"}, {"lead": "Previous results", "text": "Ask what the previous sodium results show and how quickly it has risen"}, {"lead": "Diabetes insipidus? Desmopressin?", "text": "Ask about known cranial diabetes insipidus and whether any desmopressin doses have been missed"}], "first_five_minutes": [{"lead": "Assess the patient", "text": "Assess GCS and look for a new neurological deficit, sepsis or hyperglycaemia — drowsiness may be due to a new stroke or infection rather than the sodium itself"}, {"lead": "Assess fluid status", "text": "Most hospital hypernatraemia is a water deficit (poor intake, fever, diarrhoea, osmotic diuresis) and the patient often looks dry; less often it follows sodium gain from saline or sodium-containing drugs"}, {"lead": "Restore volume first", "text": "If the patient is hypovolaemic and may need urgent fluid resuscitation (for example systolic BP below 100 mmHg, heart rate above 90, respiratory rate above 20, NEWS2 5 or more), give 500 ml of crystalloid (sodium 130–154 mmol/L) over less than 15 minutes, reassess, and tell your senior before any further boluses (if sepsis is possible, give 250 ml boluses over 10–15 minutes instead, reassessing after each, and get senior advice if not improved after 1,000 ml) — before replacing water"}, {"lead": "Check fluids and drugs", "text": "Review the fluid chart, feed regime and drug chart — stop or reduce 0.9% sodium chloride and sodium-rich drugs unless clearly needed. In known cranial diabetes insipidus, never omit desmopressin; if the patient is drowsy, the route and dose are an urgent senior decision"}, {"lead": "Send paired tests", "text": "Send glucose, U&E, serum osmolality and paired urine osmolality and sodium — dilute urine with a high serum sodium suggests diabetes insipidus"}, {"lead": "Give water", "text": "First-line treatment is water: oral if the patient can swallow safely, via the NG tube if the gut works, or IV 5% glucose if not. Agree the volume and rate with a senior"}, {"lead": "Correct slowly", "text": "Lower chronic hypernatraemia slowly — rapid correction risks cerebral oedema. Agree the target rate with a senior and recheck the sodium regularly"}, {"lead": "Escalate if neurological", "text": "Escalate urgently if there is a reduced or falling GCS, a seizure, or a new focal deficit"}], "can_i_do_alone": {"alone": "Assessing the patient, giving a crystalloid bolus for hypovolaemia, reviewing the fluid chart, feeds and drug chart, restarting prescribed water flushes, stopping unnecessary 0.9% sodium chloride, and sending glucose and paired serum and urine tests", "senior_opinion": "The volume, route and rate of water replacement, any IV 5% glucose prescription, or uncertainty about the cause", "senior_in_person": "Any patient with a reduced or falling GCS, a seizure, a new focal deficit, suspected sepsis, haemodynamic instability, a sodium above 160 mmol/L, or known cranial diabetes insipidus with a raised sodium — these need senior review at the bedside now"}, "escalate_now_if": ["There is a reduced or falling GCS, or a seizure", "There is a new focal neurological deficit — think of a new stroke", "There are signs of sepsis or haemodynamic instability", "The sodium is above 160 mmol/L", "The patient has known cranial diabetes insipidus with a raised sodium, or has missed desmopressin", "There is a very high urine output of dilute urine (possible diabetes insipidus)", "The glucose is high, suggesting hyperosmolar hyperglycaemic state", "The sodium is rising despite treatment, or falling faster than the rate agreed with your senior"], "document": "Record the sodium and previous results, GCS and neurological findings, fluid status, fluid balance and feed regime, drugs and fluids reviewed, the paired tests sent, the water replacement plan, the agreed correction rate, and when the next sodium is due.", "fail": "An unsafe response ignores the drowsiness, misses a new stroke, sepsis, hypovolaemia or a missed desmopressin dose, keeps giving 0.9% sodium chloride, or corrects the sodium rapidly without senior input.", "pass": "A safe response assesses for a neurological or septic cause, reviews fluids, feeds and drugs, restarts water, sends paired tests, agrees a slow correction plan with a senior, and escalates a reduced GCS in person.", "high_performance": "An excellent response also recognises a diabetes insipidus picture, works with the dietitian on the NG water regime, and makes sure nursing staff know the patient depends on them for water.", "one_thing": "If you only remember one thing: in hospital, hypernatraemia usually means the patient is not getting enough water — give water back, slowly, and look for why.", "img_note": "In UK hospitals, NG feed and water-flush regimes are set by the ward dietitian and given by nurses from the feed or drug chart. Missed flushes in stroke patients are a common, fixable cause of hypernatraemia. Cranial diabetes insipidus is not diabetes mellitus; an NHS England alert (2016) warns that omitted desmopressin has caused deaths. NICE lists a sodium of 155 mmol/L or more from a normal or low baseline, during or within 24 hours of IV fluids that included 0.9% sodium chloride and with no other cause, as a critical incident to report (such as on Datix or LFPSE).", "source": "No UK guideline covers hypernatraemia in general. NICE CG174, Intravenous fluid therapy in adults in hospital (2013, updated Dec 2025): hypovolaemia (1.2.1), resuscitation bolus (1.3.1), expert help (1.5.2), critical incidents (Table 1). NICE NG253, Suspected sepsis in people aged 16 or over (updated 23 Sep 2026), 1.8.6–1.8.9 (sepsis fluid boluses). Society for Endocrinology, inpatient cranial diabetes insipidus (2018). NHS England alert NHS/PSA/W/2016/001 (desmopressin). JBDS 06, HHS (2022). The tests, neurological red flags and causes are standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Price on ward 9 — his sodium is 156 and he has been drowsy since this morning.", "B": "He had a stroke two weeks ago and is NG fed; his prescribed water flushes have been missed. His sodium was 144 three days ago.", "A": "GCS 13, down from 15 yesterday, no new focal deficit that I can find, RR 18, SpO2 96% on air, temperature 37.2, BP 112 over 70, HR 98 — NEWS2 4, including 3 for his new drowsiness. He looks dry and his urine is low volume and concentrated. I've given a 500 ml crystalloid bolus because he looks dry with a heart rate of 98, restarted the water flushes and sent glucose, serum and urine osmolality.", "R": "Because his GCS has dropped, please come and review him now — I'd like your help to exclude a new stroke or sepsis, to review his response to the fluid bolus, and to agree how much water to give and how quickly to bring the sodium down."}, "checked": "Oct 2026"}, {"id": "BLEEP-28", "title": "Hypokalaemia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"The lab has rung, Mrs Green's potassium is 2.8 and she's been a bit weak and her heart rate is irregular on the monitor.\"", "nurse_call": [{"lead": "Full obs + monitor", "text": "Ask for the full set of observations and for the patient to go on a cardiac monitor — hypokalaemia can cause arrhythmias"}, {"lead": "12-lead ECG now", "text": "Ask for a 12-lead ECG — look for flattened or inverted T waves, U waves, ST depression, a prolonged PR, a long QT, or an arrhythmia"}, {"lead": "Symptoms", "text": "Ask about muscle weakness, cramps, palpitations, and any vomiting or diarrhoea"}, {"lead": "Medications and fluid losses", "text": "Ask about diuretics, insulin, salbutamol, laxatives and digoxin, and about any gastrointestinal losses"}, {"lead": "Magnesium", "text": "Ask whether magnesium has been checked — low magnesium makes hypokalaemia hard to correct"}], "first_five_minutes": [{"lead": "Confirm the result, ECG", "text": "Keep her on a cardiac monitor and get a 12-lead ECG now — any arrhythmia means senior review at the bedside. Repeat the potassium only if the sample may be unreliable, and do not wait for the repeat before acting if there are symptoms or the ECG is abnormal"}, {"lead": "Assess severity", "text": "Assess symptoms (weakness, cramps, palpitations), ECG changes and rhythm. Hypokalaemia is severe if it is below 2.5 mmol/L or there are any symptoms — so Mrs Green's weakness makes hers severe. Severe hypokalaemia or any arrhythmia needs senior review at the bedside"}, {"lead": "Check magnesium", "text": "If magnesium is below 0.6 mmol/L, replace it alongside the potassium per local protocol"}, {"lead": "Safe IV potassium", "text": "Use premixed bags through a pump only — never add potassium to a bag on the ward. A peripheral line usually takes no more than 40 mmol/L (check your local protocol) at no faster than 10 mmol/hour; faster rates (up to 20 mmol/hour) need a senior decision, continuous cardiac monitoring and a central line, usually in HDU/ICU — check your trust's protocol. Never give potassium as a bolus. 10 mmol/hour of a 40 mmol/L bag is 250 mL of fluid an hour — in heart failure or renal impairment, discuss the volume and rate with a senior, and use oral potassium alongside if the patient can swallow"}, {"lead": "Oral if possible", "text": "If the potassium is 2.5 mmol/L or above, there are no symptoms, the ECG is normal and the patient can swallow, oral potassium per your local protocol is usually enough"}, {"lead": "Review medications", "text": "Review diuretics, insulin, beta-agonists and laxatives — discuss stopping or changing a diuretic in heart failure with a senior rather than just stopping it"}, {"lead": "Treat the cause", "text": "Treat the cause: replace gastrointestinal losses, and send a stool sample for C. difficile and isolate the patient if there is new diarrhoea without another clear cause"}, {"lead": "Recheck and adjust", "text": "Recheck potassium per local protocol, adjust the infusion to the result aiming for 4.0 mmol/L, and monitor blood glucose"}], "can_i_do_alone": {"alone": "Getting an ECG and cardiac monitoring, checking magnesium, starting oral potassium (if 2.5 mmol/L or above, no symptoms and a normal ECG) or premixed IV potassium at up to 10 mmol/hour per local protocol, with cardiac monitoring if your trust requires it, after checking U&E and urine output, and starting magnesium replacement per local protocol, and sending a stool sample for C. difficile with isolation", "senior_opinion": "Any ECG change without arrhythmia, any patient on digoxin, any IV rate above 10 mmol/hour (needs continuous cardiac monitoring and a central line — check your trust's protocol), any IV potassium in a patient with heart failure, renal impairment or low urine output, hypokalaemia not responding to replacement, or stopping or changing a diuretic in heart failure", "senior_in_person": "Any arrhythmia, severe hypokalaemia (below 2.5 mmol/L, or any symptoms), weakness affecting breathing, or a patient on digoxin with ECG changes — these need senior review at the bedside now and possibly a higher-acuity setting"}, "escalate_now_if": ["There is an arrhythmia, including new AF or frequent ectopics", "There are ECG changes (flattened or inverted T waves, U waves, ST depression, prolonged PR, long QT)", "There is muscle weakness or paralysis, particularly if it affects breathing", "The patient is on digoxin and has ECG changes or an arrhythmia — hypokalaemia potentiates digoxin toxicity", "The potassium is below 2.5 mmol/L or not rising despite replacement"], "document": "Record the potassium and magnesium with times, the ECG findings and rhythm, symptoms, the cause identified, the replacement given (product, route, concentration, rate), the monitoring in place, any medication changes agreed with the senior, and when the next potassium is due.", "fail": "An unsafe response gives oral potassium alone to a patient with symptoms or ECG changes, gives IV potassium as a bolus, adds concentrated potassium to a bag on the ward, runs it faster than the protocol without monitoring, fails to check magnesium, or manages an arrhythmia without a senior.", "pass": "A safe response gets an ECG and monitoring, checks magnesium, replaces potassium safely with premixed bags at the right rate, looks for the cause, and escalates an arrhythmia or ECG changes promptly.", "high_performance": "An excellent response also recognises the risk with digoxin and heart failure, considers C. difficile as the cause of new diarrhoea, and plans a repeat potassium at a sensible interval.", "one_thing": "If you only remember one thing: IV potassium comes only in premixed bags at a controlled rate — never a bolus — and check the magnesium.", "img_note": "In the UK, concentrated potassium chloride ampoules are restricted following a national patient safety alert: they are stored separately, usually only in critical care, and wards use premixed bags. NICE also says potassium should not be added to IV fluid bags because it is dangerous. If the premixed bag you need is not stocked, ask pharmacy rather than improvise.", "source": "Resuscitation Council UK Guidelines 2025, Special circumstances (Oct 2025), adopting ERC Guidelines 2025 Special Circumstances (Resuscitation 2025;215:110753, Fig. 3 hypokalaemia algorithm); NICE, Intravenous fluid therapy in adults in hospital (CG174), 2013, updated Dec 2025; emc SmPCs, Potassium Chloride 0.3% and Sodium Chloride 0.9% Solution for Infusion (Baxter, June 2023; B. Braun); NPSA, Patient Safety Alert 01: Potassium chloride concentrate solutions, July 2002 (no official live copy; listed by NHS England among NPSA recommendations still in force). Oral doses, peripheral concentration and recheck timing are local protocol. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Green on ward 5 — her potassium is 2.8 and she has a new irregular rhythm on the monitor.", "B": "She's on furosemide for heart failure and has had diarrhoea for two days.", "A": "Her ECG shows new AF at 110 with flattened T waves and U waves, magnesium 0.55, BP 118 over 72. She's on a cardiac monitor with a working cannula, I've sent a stool sample for C. difficile and asked for her to be isolated.", "R": "Please come and review her now because of the new AF and symptomatic hypokalaemia. Can I start premixed IV potassium at 10 mmol/hour through a pump while you come, given her heart failure? I'd also like your advice on her furosemide and magnesium replacement, and whether she needs a higher-acuity bed."}, "checked": "Oct 2026"}, {"id": "BLEEP-29", "title": "Hypomagnesaemia and hypocalcaemia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"Mr Allen's been getting muscle cramps and tingling in his hands, and the lab says his magnesium is 0.4 and his adjusted calcium is 1.82.\"", "nurse_call": [{"lead": "Full obs + monitor", "text": "Ask for the full set of observations and for the patient to go on a cardiac monitor"}, {"lead": "12-lead ECG now", "text": "Ask for a 12-lead ECG now — both hypomagnesaemia and hypocalcaemia can prolong the QT and cause arrhythmias"}, {"lead": "Symptoms", "text": "Ask about cramps, tingling around the mouth or fingers, twitching, carpopedal spasm, stridor, or any seizure — symptoms make this an emergency"}, {"lead": "Medications and losses", "text": "Ask about PPIs, diuretics, and any diarrhoea or vomiting — common causes of low magnesium"}, {"lead": "Previous results", "text": "Ask for the previous calcium, magnesium, phosphate and albumin results, and any recent neck surgery"}], "first_five_minutes": [{"lead": "ABCDE and ECG", "text": "Assess ABCDE, watching for stridor (laryngospasm) and seizures, and get an ECG — look for a long QT or arrhythmia"}, {"lead": "Use adjusted calcium", "text": "Use the albumin-adjusted calcium. Severe hypocalcaemia is adjusted calcium below 1.9 mmol/L, or symptoms at any level below the reference range — this is a medical emergency"}, {"lead": "Give IV calcium gluconate", "text": "For severe hypocalcaemia give 10–20 mL of 10% calcium gluconate in 50–100 mL of 5% glucose IV over 10 minutes with ECG monitoring, repeated until symptoms settle — check BNF/local protocol. A peripheral line is fine: use a large, well-sited cannula and watch for extravasation. Calcium chloride is the one that needs a central line. If the patient takes digoxin, discuss with your senior before giving any IV calcium — it can cause serious digoxin toxicity"}, {"lead": "Then a calcium infusion", "text": "Follow the bolus with a calcium gluconate infusion per local protocol, agreed with your senior and titrated to the calcium"}, {"lead": "Replace magnesium too", "text": "Replace magnesium at the same time, not first — low magnesium stops calcium correcting. IV magnesium sulfate per local protocol (SfE: 24 mmol over 24 hours; reduce the dose in renal impairment)"}, {"lead": "Send the cause bloods", "text": "Send PTH, vitamin D, phosphate, U&E and magnesium, and review the drug chart — stop a PPI if it is the likely cause"}, {"lead": "Recheck and monitor", "text": "Recheck calcium and magnesium after treatment, keep the patient on a monitor, and avoid QT-prolonging drugs while the QT is long"}], "can_i_do_alone": {"alone": ["Getting an ECG and cardiac monitoring", "Giving IV calcium gluconate 10–20 mL of 10% over 10 minutes for severe or symptomatic hypocalcaemia (on dialysis: continuous ECG monitoring throughout, and discuss before any infusion; on digoxin: discuss with your senior before giving any IV calcium)", "Starting IV magnesium per local protocol (not in renal failure or heart block without discussion)", "Sending PTH, vitamin D, phosphate and magnesium, and stopping a PPI"], "senior_opinion": "Tell your senior about every patient needing IV calcium, and discuss the ongoing calcium infusion, renal impairment, renal failure or dialysis patients (large calcium infusions should not be used; IV magnesium needs a reduced dose in renal impairment and should be avoided in severe impairment), and patients on digoxin", "senior_in_person": "Any arrhythmia, seizure, laryngospasm, stridor or severe tetany, or symptoms not settling after IV calcium, or a QTc of 500 ms or more — these need a senior at the bedside now and possibly a higher-acuity setting"}, "escalate_now_if": ["There is an arrhythmia", "There is a seizure", "There is laryngospasm, stridor or severe tetany", "The QTc is 500 ms or more", "Symptoms or QT prolongation persist despite IV calcium"], "document": "Record the adjusted calcium, magnesium, phosphate and albumin with times, symptoms and signs, the ECG and QT, the calcium and magnesium given (product, dose, dilution, rate, line), the response, the cause bloods sent, drugs stopped, and the plan agreed with the senior.", "fail": "An unsafe response withholds IV calcium gluconate from a patient with symptomatic or severe hypocalcaemia, gives calcium chloride through a peripheral line outside a cardiac arrest, waits to correct magnesium before giving calcium, or does not monitor the ECG.", "pass": "A safe response uses adjusted calcium, gets an ECG and monitoring, gives IV calcium gluconate over 10 minutes for severe or symptomatic hypocalcaemia, replaces magnesium alongside it, sends the cause bloods, and escalates arrhythmias, seizures or stridor.", "high_performance": "An excellent response also links the low magnesium to long-term PPI use, considers hypoparathyroidism (especially after neck surgery) and vitamin D deficiency, and plans the follow-on calcium infusion and repeat bloods.", "one_thing": "If you only remember one thing: symptomatic or severe hypocalcaemia needs IV calcium gluconate now — 10–20 mL of 10% over 10 minutes with ECG monitoring — and replace the magnesium at the same time. If they take digoxin, discuss with your senior before giving any IV calcium.", "img_note": "For IV drugs you have not given before, UK trusts use the NHS Injectable Medicines Guide (Medusa) for dilution, rate and line advice — find out how to open it on your first day. Calcium gluconate 10% comes in 10 mL ampoules for dilution in a bag. Calcium chloride is a more irritant and more concentrated preparation — not interchangeable mL for mL — mainly used in cardiac arrest and critical care.", "source": "Society for Endocrinology, Emergency management of acute hypocalcaemia in adult patients, Endocr Connect 2016;5(5):G7–G8, with 2019 addendum (Endocr Connect 2019;8(6):X1) on calcium chloride equivalence; magnesium cautions from the BNF (renal impairment) and the magnesium sulfate SmPC, emc 3579, sections 4.3–4.4 (renal failure, heart block). The QTc 500 ms trigger, avoiding QT-prolonging drugs and peripheral-cannula advice are standard clinical practice rather than guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Allen on ward 8 — he has symptomatic hypocalcaemia, adjusted calcium 1.82, and magnesium 0.4.", "B": "He's been on omeprazole long-term and has eaten poorly since admission.", "A": "He has perioral tingling and a positive Chvostek's sign, no stridor or seizure, and he's in sinus rhythm with a QTc of 500. He's on a monitor. I've given 10 mL of 10% calcium gluconate in 100 mL of 5% glucose over 10 minutes, started IV magnesium, and sent PTH, vitamin D and phosphate.", "R": "With a QTc of 500 and a magnesium of 0.4, could you come and review him now and decide whether he needs faster magnesium, and agree the calcium infusion and recheck times?"}, "checked": "Oct 2026"}, {"id": "BLEEP-30", "title": "Addisonian / steroid crisis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mrs Clark's BP has dropped to 85 over 50 and she's been vomiting, she's on long-term steroids for her arthritis.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score"}, {"lead": "Bedside glucose, treat if low", "text": "Ask for a capillary glucose now, and to treat a low result straight away per the ward hypoglycaemia protocol"}, {"lead": "Steroid history", "text": "Ask what steroid the patient takes, at what dose, when it was last given, and whether any doses have been missed, withheld or vomited"}, {"lead": "Steroid Emergency Card", "text": "Ask whether the patient has an NHS Steroid Emergency Card — it identifies patients at risk of adrenal crisis and their emergency treatment"}, {"lead": "IV access, hydrocortisone ready", "text": "Ask the nurse to site IV access, take bloods with it, and have 100 mg hydrocortisone ready to give as soon as you arrive — if she has her own emergency hydrocortisone kit it can be given IM now, and if you cannot get there within minutes, call your senior or outreach so it is not delayed"}], "first_five_minutes": [{"lead": "ABCDE, oxygen if shocked", "text": "Assess with ABCDE. If she is shocked, give oxygen by reservoir mask at 15 L/min, aiming for 94–98%"}, {"lead": "Bloods with the cannula", "text": "Take U&E, glucose and FBC (plus blood cultures if infection is possible) as the cannula goes in, without delaying hydrocortisone. Don't send a cortisol — NICE advises against testing while she takes oral steroids at or above a physiological dose"}, {"lead": "Give hydrocortisone now", "text": "Give hydrocortisone 100 mg IV or IM immediately — do not wait for results. There is no risk of overdose from hydrocortisone in an emergency, and delay can be fatal"}, {"lead": "Rehydrate with saline", "text": "Give 0.9% sodium chloride: 1 litre IV over 30 minutes, then further fluid guided by blood pressure, urine output and electrolytes, watching for overload in the elderly and in renal or heart failure"}, {"lead": "Continue hydrocortisone", "text": "Continue hydrocortisone 200 mg per 24 hours by continuous IV infusion in 5% glucose, or 50 mg IM (or IV) every 6 hours, until she is haemodynamically stable and can take and absorb oral steroids, and make sure the infusion is not interrupted — check BNF/local protocol"}, {"lead": "Monitor glucose and electrolytes", "text": "Monitor blood pressure, heart rate, glucose and electrolytes frequently, and treat hypoglycaemia. Hyponatraemia is common; hyperkalaemia suggests primary adrenal failure (such as Addison's) and is not typical when the cause is long-term steroid use"}, {"lead": "Look for the precipitant", "text": "Identify and treat the precipitant — infection, vomiting and diarrhoea, surgery, or missed doses. Long-term steroids are a sepsis risk factor: if infection is possible, manage as suspected sepsis per NICE, with IV antibiotics within 1 hour if high risk"}, {"lead": "Involve endocrinology", "text": "Contact endocrinology for advice on the ongoing steroid plan and the underlying cause"}], "can_i_do_alone": {"alone": "Taking bloods and cultures as the cannula goes in, giving hydrocortisone 100 mg IV or IM immediately, starting oxygen if she is shocked, starting 0.9% sodium chloride, prescribing ongoing hydrocortisone per protocol, and treating hypoglycaemia", "senior_opinion": "Any uncertainty about the diagnosis or steroid history, or a patient not improving after hydrocortisone and fluids — and tell your senior about every suspected adrenal crisis", "senior_in_person": "NEWS2 of 7 or more, persistent hypotension or shock after hydrocortisone and fluids, reduced GCS, or uncertainty whether this is adrenal crisis or another cause of shock such as sepsis — these need senior and critical care review now"}, "escalate_now_if": ["NEWS2 is 7 or more — call critical care outreach as well as your senior", "Hypotension persists after hydrocortisone and the first fluid bolus", "The GCS is reduced or falling", "There is a precipitant needing urgent treatment, such as sepsis", "The patient is pregnant — give hydrocortisone immediately, exactly as for anyone else (untreated adrenal crisis can kill mother and baby), and involve the obstetric team", "You are unsure whether this is adrenal crisis or another cause of shock — give hydrocortisone anyway and get senior help"], "document": "Record the time adrenal crisis was suspected, observations and NEWS2, the bloods taken and when, the time and dose of hydrocortisone, glucose, fluids and response, any antibiotics and their time, the steroid history and Steroid Emergency Card details, the precipitant, and the plan agreed with the senior and endocrinology.", "fail": "An unsafe response delays hydrocortisone while waiting for blood results or a senior, fails to give fluids, misses hypoglycaemia, stops at adrenal crisis without looking for sepsis, or fails to recognise that a patient on long-term steroids is at risk during acute illness.", "pass": "A safe response takes bloods without delaying treatment, gives hydrocortisone 100 mg immediately, starts fluids, checks glucose, continues hydrocortisone, treats the precipitant, and involves endocrinology.", "high_performance": "An excellent response also checks for a Steroid Emergency Card, recognises who is at risk (including high-dose inhaled steroids), prescribes parenteral steroid cover whenever an at-risk patient is vomiting or nil by mouth, and makes sure sick day rules are taught before discharge.", "one_thing": "If you only remember one thing: if you suspect adrenal crisis, give 100 mg hydrocortisone straight away — send bloods with the cannula, but never wait for them.", "img_note": "The NHS Steroid Emergency Card was introduced by a 2020 National Patient Safety Alert after deaths linked to missed steroids and delayed treatment of adrenal crisis. It should be issued to everyone with adrenal insufficiency and to people taking prednisolone 5 mg a day or more (or equivalent) for 4 weeks or longer, by any route, including high-dose inhaled steroids. Never let an at-risk patient's steroid dose be missed in hospital.", "source": "NICE, Adrenal insufficiency: identification and management (NG243), Aug 2024, reviewed Dec 2024 (recs 1.2.7, 1.4.6–1.4.7, 1.6.1, 1.7.1–1.7.9); Simpson H et al, Guidance for the prevention and emergency management of adult patients with adrenal insufficiency, Clin Med 2020; Society for Endocrinology, Emergency management of acute adrenal insufficiency (adrenal crisis) in adult patients, 2016; NHS England, National Patient Safety Alert NatPSA/2020/005/NHSPS, Steroid Emergency Card, Aug 2020; NICE NG253 Suspected sepsis (updated Sep 2026; 1.2.1, 1.8.3); RCP NEWS2, 2017; BTS oxygen guideline, 2017 (E2); BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Clark on ward 3 — I think she is in adrenal crisis: BP 85 over 50 and vomiting, on long-term steroids.", "B": "She takes prednisolone 10 mg daily for arthritis, has been unable to keep it down for 24 hours, and has a Steroid Emergency Card.", "A": "On arrival RR 20, sats 96% on air, HR 112, BP 85 over 50, temp 37.4, alert: NEWS2 5. Glucose 4.8, sodium 129, potassium 4.4. I took bloods with the cannula, gave 100 mg hydrocortisone IV, and her first litre of saline is going in — BP now 92 over 56.", "R": "She is still hypotensive after hydrocortisone and fluid, so please come and review her now. I've prescribed hydrocortisone 50 mg 6-hourly and more fluid, and I'd like your view on sepsis as a precipitant and on critical care."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-31", "title": "Myxoedema coma", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mrs Turner's become really drowsy and she feels cold to touch, she's known hypothyroid but she's not been taking her levothyroxine.\"", "nurse_call": [{"lead": "Full obs + GCS", "text": "Ask for the full set of observations including GCS, respiratory rate, temperature and the NEWS2 score"}, {"lead": "Core temperature, passive warming", "text": "Ask for a core temperature — hypothermia is a key feature — and to warm the patient passively with blankets, not active heating"}, {"lead": "Bedside glucose", "text": "Ask for a capillary glucose now — hypoglycaemia is common in myxoedema coma"}, {"lead": "Thyroid history and medications", "text": "Ask about the thyroid history, usual levothyroxine dose, how long it has been missed, and any new sedatives, opioids or diuretics"}, {"lead": "IV access and bloods", "text": "Ask the nurse to site IV access and take bloods, and to have hydrocortisone ready"}], "first_five_minutes": [{"lead": "ABCDE, ventilation, glucose, cause", "text": "Assess ABCDE — watch for hypoventilation (get a blood gas for CO2), bradycardia and hypotension — and treat hypoglycaemia. Don't assume it's all thyroid: sepsis or low sodium may be the cause"}, {"lead": "Senior and critical care now", "text": "NEWS2 of 7 or more needs emergency assessment by a team with critical care competencies: call your registrar and critical care outreach now, and endocrinology early. She is likely to need HDU or ICU; mortality can reach 50%"}, {"lead": "Bloods before steroids", "text": "Send TSH, free T4, cortisol, U&E (hyponatraemia is common), glucose, CK, FBC and blood cultures before the hydrocortisone if it causes no delay — do not wait for results to treat"}, {"lead": "Give hydrocortisone", "text": "Give hydrocortisone 100 mg IV now, with ongoing doses per endocrinology or local protocol. Thyroid hormone can precipitate adrenal crisis if cortisol is also deficient"}, {"lead": "Thyroid hormone: senior decision", "text": "IV levothyroxine is needed but the dose is a senior and endocrinology decision. Many hospitals do not have IV levothyroxine readily available, so ask pharmacy early"}, {"lead": "Antibiotics and cautious fluids", "text": "Give broad-spectrum IV antibiotics until infection is excluded (fever and a high white count may be absent); with suspected infection and NEWS2 of 7 or more, within 1 hour (NICE NG253). Treat hypotension with cautious IV fluids"}, {"lead": "Passive warming, no sedatives", "text": "Warm passively with blankets — active warming can cause circulatory collapse in these vasoconstricted patients — and avoid sedatives"}], "can_i_do_alone": {"alone": "Assessing ABCDE, treating hypoglycaemia, taking bloods including cortisol and thyroid function, giving hydrocortisone 100 mg IV, starting antibiotics, passive warming, and requesting a blood gas", "senior_opinion": "The levothyroxine dose and route, how much IV fluid to give, and any patient where the diagnosis is unclear but observations are stable — tell your senior about every suspected case", "senior_in_person": "Any patient with a NEWS2 of 7 or more, reduced GCS, hypothermia, hypoventilation or a rising CO2, bradycardia with hypotension, or shock — these need senior and critical care review now"}, "escalate_now_if": ["NEWS2 of 7 or more", "There is a reduced or falling GCS", "Temperature of 35.0°C or below", "There is hypoventilation, a rising CO2, or hypoxia", "There is bradycardia with hypotension, or shock", "No response within 1 hour of any intervention", "You are unsure whether this is myxoedema coma or another cause of reduced consciousness, such as sepsis or stroke"], "document": "Record the time myxoedema coma was suspected, the full observations with the NEWS2 total, core temperature, GCS and blood gas, glucose, the bloods sent before treatment, the hydrocortisone and antibiotics given with times, fluids, warming method, the precipitant considered, and the plan agreed with the senior, endocrinology and critical care.", "fail": "An unsafe response gives levothyroxine without hydrocortisone, misses hypoglycaemia or hypoventilation, actively rewarms or sedates the patient, delays treatment while waiting for thyroid results, or does not involve critical care in a patient with reduced GCS or a NEWS2 of 7 or more.", "pass": "A safe response recognises the presentation, takes bloods without delaying treatment, gives hydrocortisone, treats hypoglycaemia, starts antibiotics, warms passively, and calls a senior, critical care outreach and endocrinology.", "high_performance": "An excellent response also uses the clinical picture rather than waiting for results, looks for the precipitant (infection, stroke, sedatives, cold exposure), and arranges IV levothyroxine through pharmacy early.", "one_thing": "If you only remember one thing: in suspected myxoedema coma, give hydrocortisone before thyroid hormone, treat the glucose and the breathing, and get critical care involved early.", "img_note": "Many hospitals do not have IV levothyroxine readily available. Out of hours, the on-call pharmacist can find or arrange it, and your registrar can reach on-call endocrinology through switchboard. Ask early so the drug is on its way while the patient is stabilised.", "source": "Taylor P et al, Management of endocrine emergencies: joint consensus statement for management of myxoedema coma (endorsed by ETA, BTA, Society for Endocrinology and WEDS), Eur Thyroid J 2026;15(4):ETJ260044, Aug 2026; expert consensus, not graded evidence. RCP NEWS2 (2017) for the response to 7 or more. NICE NG253 (updated 23 Sep 2026) for high-risk sepsis. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Turner on ward 6 — I'm worried about myxoedema coma: she's known hypothyroid, off her levothyroxine, drowsy and cold.", "B": "She was admitted with a chest infection and hasn't been able to take her usual medications.", "A": "Core temperature 34.5, GCS 12, HR 48, BP 88 over 50, RR 10, sats 95% on air — NEWS2 12. Glucose 3.6, which I've treated. I've sent bloods including TSH, free T4 and cortisol, given 100 mg hydrocortisone IV and started antibiotics, and she's being warmed with blankets. A blood gas is being done and I've called critical care outreach.", "R": "Please come and review her now. We also need to agree the levothyroxine dose and contact endocrinology."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-32", "title": "New acute abdominal pain on the ward", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Webb's got really bad abdominal pain that came on suddenly, he's doubled over and his tummy feels rigid.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for a full set of observations, including temperature, and the NEWS2 score"}, {"lead": "Nil by mouth + IV access", "text": "Ask the nurse to keep the patient nil by mouth, site IV access, and have bloods, blood cultures and a group and save ready"}, {"lead": "Pain character", "text": "Ask where the pain started, where it is now, whether it is constant or colicky, and whether it goes to the back or shoulder"}, {"lead": "Bowels, vomiting, flatus", "text": "Ask about vomiting, the last bowel motion, and whether the patient is passing wind — this matters for obstruction"}, {"lead": "Recent procedures", "text": "Ask about recent endoscopy or surgery, hernias, and anticoagulants"}], "first_five_minutes": [{"lead": "ABCDE, NEWS2 and oxygen", "text": "Do an ABCDE assessment — tachycardia, hypotension or a high NEWS2 means this is an emergency. In critical illness, including sepsis or shock, start a reservoir mask at 15 L/min aiming for 94–98%, using less once oximetry is reliable; otherwise give oxygen only if needed (88–92% if at risk of hypercapnia)"}, {"lead": "Examine the abdomen", "text": "Examine for tenderness, guarding, rigidity, distension and masses, check the hernial orifices, and feel for a pulsatile mass. Think of a ruptured AAA with new abdominal or back pain, collapse or loss of consciousness, especially if over 60, a current or ex-smoker, hypertensive or with a known AAA"}, {"lead": "Suspected ruptured AAA: no routine boluses", "text": "If a ruptured AAA is suspected, do not give fluid boluses without senior advice — a restrictive approach (permissive hypotension) may be used. Call your registrar now, ask for an immediate bedside aortic ultrasound, and discuss immediately with the vascular team if it shows or can't exclude an AAA"}, {"lead": "Think sepsis", "text": "Peritonitis is a source of sepsis. Infection with NEWS2 7 or more is high risk (so is a single parameter of 3 if a medical review confirms it): give broad-spectrum IV antibiotics per your trust policy within 1 hour, and take blood cultures first — but do not delay antibiotics to get cultures"}, {"lead": "Fluids and VBG", "text": "If high risk, give 250 mL crystalloid boluses over 10–15 minutes, reassessing after each, up to 1,000 mL — then get senior advice. Do not give boluses without senior advice if a ruptured AAA is suspected (permissive hypotension) or the patient has heart or renal failure. Send a venous gas with lactate and glucose"}, {"lead": "Bloods, ECG, pregnancy test", "text": "Send FBC, U&E, CRP, LFTs, amylase or lipase, clotting and a group and save; do an ECG (inferior MI can present as abdominal pain) and think about a pregnancy test in anyone who could be pregnant"}, {"lead": "Imaging without delay", "text": "An erect chest X-ray can show free air, but it must not delay a CT — the surgical team will usually want CT for a suspected perforation"}, {"lead": "Call the surgical team", "text": "Call the on-call surgical registrar early — do not wait for all the results before referring a patient with a rigid abdomen."}, {"lead": "Analgesia", "text": "Give adequate analgesia, including an opioid if needed — opioids do not hinder the diagnosis"}], "can_i_do_alone": {"alone": ["Assessing and examining, and keeping nil by mouth", "Sending bloods, cultures, VBG and group and save, and doing an ECG and pregnancy test", "Where your trust's sepsis protocol allows, giving IV antibiotics within 1 hour and 250 mL fluid boluses if high risk for sepsis — get senior advice first if a ruptured AAA is suspected or there is heart or renal failure", "Giving analgesia and requesting an erect chest X-ray"], "senior_opinion": "The choice of imaging (CT), fluids beyond 1,000 mL, and any patient with significant abdominal pain where the diagnosis is unclear", "senior_in_person": "Peritonitis (rigidity and guarding), haemodynamic instability, NEWS2 7 or more, a suspected perforation, ischaemia or ruptured AAA — these need the surgical registrar at the bedside now (vascular team for an AAA), plus a critical care review at NEWS2 7 or more. High-risk sepsis not responding within 1 hour of any intervention: a senior attends in person, critical care is involved and the consultant informed (NG253)"}, "escalate_now_if": ["There is abdominal rigidity and guarding suggesting peritonitis", "The patient is hypotensive, tachycardic, or has a NEWS2 of 7 or more; a total of 5 or 6, or 3 in any one parameter, needs an urgent review", "There is free air on the chest X-ray", "There is a pulsatile mass or suspected ruptured AAA, or pain out of proportion to the signs (ischaemia)", "The patient is not improving after 1,000 mL of fluid or within 1 hour of treatment", "A positive pregnancy test with abdominal pain and tenderness (refer immediately to early pregnancy or out-of-hours gynaecology)"], "document": "Record the time of onset, the pain and examination findings including hernial orifices, observations and NEWS2 with time, the time antibiotics and fluids were given, investigations and results, analgesia, and the time the surgical team was called and what was agreed.", "fail": "An unsafe response dismisses a rigid abdomen, delays antibiotics in a high-risk septic patient, waits for an X-ray or results before calling the surgeons, or withholds analgesia.", "pass": "A safe response recognises peritonitis and sepsis, gives antibiotics and fluids within the hour, sends the right bloods, ECG and VBG, gives analgesia, and calls the surgical registrar early.", "high_performance": "An excellent response also considers non-surgical mimics (inferior MI, DKA, pneumonia), ruptured AAA and mesenteric ischaemia, keeps a pregnancy test in mind, and keeps the nursing team updated on what to watch for.", "one_thing": "If you only remember one thing: a rigid abdomen with abnormal observations is surgical sepsis — antibiotics and fluids within the hour, and the surgical registrar now.", "img_note": "In UK hospitals, emergency surgical referrals go to the on-call general surgical registrar. A patient who may need an emergency laparotomy should have a documented risk assessment, with early consultant and critical care input if higher risk, so clear, timed notes help.", "source": "NICE NG253, Suspected sepsis in people aged 16 or over, last updated Sep 2026; RCP, National Early Warning Score (NEWS) 2, 2017; BTS, Guideline for oxygen use in adults, 2017; NICE NG156, Abdominal aortic aneurysm, 2020; NICE NG126, Ectopic pregnancy and miscarriage, updated Jun 2026; RCEM, Management of Acute Pain in Adults, 2024. No single guideline covers this call: the examination, ECG, amylase or lipase, CT choice and the ischaemia sign are standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Webb on ward 8 — he has sudden severe abdominal pain with a rigid abdomen, and NEWS2 7.", "B": "He had a colonoscopy five days ago and has diverticular disease.", "A": "RR 25, SpO2 95% on air, BP 105 over 65, HR 110, temperature 38.4, alert. He is rigid with guarding. I've taken blood cultures, bloods, a group and save and a VBG — lactate 3.1 — given IV antibiotics per our policy, started a 250 mL fluid bolus, given morphine, started oxygen to a target of 94–98%, and kept him nil by mouth. ECG shows sinus tachycardia.", "R": "I think this is a perforation with sepsis — please come and review him now, and can we agree a CT? I'm also calling critical care outreach."}, "checked": "Oct 2026"}, {"id": "BLEEP-33", "title": "Persistent vomiting and nausea", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mrs Nolan's been vomiting all morning, she's had three doses of cyclizine and it's not settling.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations including BP, heart rate, and the NEWS2 score"}, {"lead": "Fluid balance and urine output", "text": "Ask for the recent fluid balance and whether the patient is passing urine"}, {"lead": "What's in the vomit?", "text": "Ask about the character of the vomit — is it food, bile-stained, coffee-ground, or faeculent? This changes the differential"}, {"lead": "Recent medications and procedures", "text": "Ask about recent medication changes, opioids, antibiotics, and any recent operation or anaesthetic, and ask the nurse not to give another dose of the same antiemetic until you have reviewed her"}, {"lead": "Pain and bowel function", "text": "Ask about abdominal pain, distension, and when they last opened their bowels or passed wind"}], "first_five_minutes": [{"lead": "ABCDE and hydration", "text": "Assess airway, breathing, circulation, disability and exposure, and hydration: mucous membranes, capillary refill, pulse, BP, urine output, postural drop if safe. Signs she may need urgent fluid resuscitation include systolic BP below 100, heart rate above 90, capillary refill over 2 seconds, respiratory rate above 20 or NEWS2 of 5 or more"}, {"lead": "Abdominal examination", "text": "Examine for tenderness, distension, guarding, bowel sounds, hernial orifices and wounds — look for obstruction, ileus, peritonitis or a post-operative complication"}, {"lead": "Review the drug chart", "text": "Review the drug chart for causes: opioids, antibiotics, NSAIDs, digoxin, and any new medication — and check what antiemetics have already been given"}, {"lead": "Consider the cause", "text": "Consider medication side effects, post-operative ileus or complication, obstruction, gastroenteritis, pancreatitis, raised intracranial pressure, metabolic causes (DKA, hypercalcaemia, uraemia) and pregnancy"}, {"lead": "Bloods, VBG and pregnancy test", "text": "Send FBC, U&E, CRP, LFTs, amylase, glucose, calcium and magnesium, and a group and save; do a venous blood gas (lactate, potassium) and capillary ketones; do a pregnancy test in anyone who could be pregnant. If obstruction is suspected, agree urgent CT with a senior — don't delay it with an abdominal X-ray"}, {"lead": "Replace fluids and electrolytes", "text": "If she needs resuscitation, give a 500 ml bolus of crystalloid (sodium 130 to 154 mmol/L) over less than 15 minutes and reassess with ABCDE — if sepsis is suspected, give 250 ml boluses over 10 to 15 minutes instead, reassessing after each, up to 1,000 ml, then get senior advice; otherwise replace losses per local protocol. Replace electrolytes using ready-mixed potassium bags: NICE says potassium should not be added to IV fluid bags"}, {"lead": "NG tube if obstruction", "text": "If bowel obstruction is suspected, keep the patient nil by mouth and ask for a nasogastric tube on free drainage to decompress the stomach, and get a surgical review"}, {"lead": "Choose the antiemetic safely", "text": "Don't repeat a drug that isn't working — change class. Metoclopramide is contraindicated in mechanical obstruction, GI perforation or haemorrhage, Parkinson's disease and epilepsy; the MHRA limits it to 30 mg in 24 hours for up to 5 days, IV over at least 3 minutes. Metoclopramide and ondansetron can prolong the QT interval, so check an ECG and correct potassium and magnesium"}], "can_i_do_alone": {"alone": ["Assessing hydration, examining the abdomen and reviewing the drug chart", "Sending bloods, a VBG, ketones and a pregnancy test, and doing an ECG", "Giving a crystalloid bolus or starting IV fluids under NICE CG174 and local protocol", "Prescribing a second-class antiemetic that is not contraindicated", "Asking for an NG tube on free drainage if obstruction is suspected"], "senior_opinion": "Any uncertainty about the cause, the choice of antiemetic when the QT interval is prolonged, vomiting that is not settling despite a change of class, or a complex fluid or electrolyte problem such as abnormal sodium or renal impairment", "senior_in_person": "Any patient with suspected obstruction, peritonitis or a post-operative complication, haemodynamic instability, NEWS2 of 5 or more, or vomiting with a falling GCS — these need senior (usually surgical) review at the bedside now"}, "escalate_now_if": ["There are signs of bowel obstruction (distension, absent or tinkling bowel sounds, faeculent or bilious vomiting)", "There are signs of peritonitis (rigidity and guarding) or the patient is recently post-operative and getting worse", "The patient is haemodynamically unstable, or signs of hypovolaemia persist after a fluid bolus", "NEWS2 of 5 or more, or 3 in any single parameter (7 or more needs an emergency response)", "There is coffee-ground vomit or haematemesis suggesting upper GI bleeding", "There is a suspected metabolic cause such as DKA or hypercalcaemia, or a prolonged QT interval on the ECG", "New confusion, drowsiness or a falling GCS, severe headache or new neurological signs"], "document": "Record the onset and character of the vomiting, observations and hydration, abdominal findings, the drug chart review, investigations (including VBG, ketones, pregnancy test and ECG with QTc), antiemetics and fluids given and the response, any NG tube, and the plan agreed with the senior.", "fail": "An unsafe response repeats the same antiemetic without looking for the cause, gives metoclopramide to a patient with suspected obstruction, fails to assess hydration and send bloods, or treats a distended post-operative patient as a prescribing problem rather than asking for a surgical review.", "pass": "A safe response assesses hydration, examines the abdomen, reviews the drug chart, sends bloods, a VBG and a pregnancy test, checks the ECG before QT-prolonging antiemetics, starts IV fluids if needed, and escalates promptly if obstruction or a post-operative complication is possible.", "high_performance": "An excellent response also works through the differential, recognises that faeculent vomiting and distension point to obstruction, asks for an NG tube while waiting for the surgical team, and involves them early rather than escalating antiemetics.", "one_thing": "If you only remember one thing: vomiting that won't settle is a symptom, not a diagnosis — examine the abdomen and look for the cause before reaching for another antiemetic, and never give metoclopramide if obstruction is possible.", "img_note": "In UK hospitals, a patient on a surgical ward is under the named consultant's surgical team, so a suspected post-operative complication goes to the on-call surgical registrar, not the medical team. Antiemetics are often prescribed 'as required' on the electronic chart — check the administration record, not just the prescription, to see what has actually been given.", "source": "NICE CG174, Intravenous fluid therapy in adults in hospital, last updated May 2017 (Dec 2025: 2 resuscitation recs moved to the sepsis guidelines): 1.2.1 hypovolaemia signs, 1.3.1 bolus, 1.4.1 no potassium added to bags, 1.5.2 expert help; MHRA Drug Safety Update, metoclopramide, Aug 2013; emc SmPCs: Maxolon, Feb 2024; ondansetron injection (hameln), Oct 2022; NCEPOD Delay in Transit (2020) rec 1: prompt CT with IV contrast for suspected bowel obstruction; RCP NEWS2 (2017). No national guideline covers inpatient vomiting: the differential, extra tests, NG tube and changing antiemetic class are standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 5 calling about Mrs Nolan — she's been vomiting all morning despite three doses of cyclizine, and I'm worried about a post-operative complication.", "B": "She's day two after a laparoscopic cholecystectomy and is on regular opioids.", "A": "BP is 100 over 60, heart rate 100, she looks dry, and her abdomen is distended and tender with quiet bowel sounds. I've started IV fluids, sent bloods including LFTs and amylase, done a VBG and an ECG, and kept her nil by mouth. I haven't given metoclopramide because obstruction is possible.", "R": "Could you come and review her now for a post-operative complication such as ileus, obstruction or a bile leak? I've kept her nil by mouth and asked for an NG tube on free drainage — let me know whether you want imaging before you arrive."}, "checked": "Oct 2026"}, {"id": "BLEEP-34", "title": "Acute upper GI bleed", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Price has just vomited a large amount of fresh blood, he looks pale and his BP is 95 over 55.\"", "nurse_call": [{"lead": "Is it ongoing?", "text": "Ask whether the bleeding is ongoing right now — if there is large-volume fresh haematemesis with shock, this is a major haemorrhage and you need to attend immediately"}, {"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations including BP, heart rate, and the NEWS2 score — tachycardia and hypotension indicate significant blood loss; ask the nurse to stay with him and repeat them until you arrive"}, {"lead": "IV access + bloods", "text": "Ask the nurse to get two large-bore IV cannulas and send bloods including FBC, U&E, LFTs, clotting, and a group and save and crossmatch"}, {"lead": "Resus trolley + MHP", "text": "Ask the nurse to bring the resuscitation trolley and have the major haemorrhage protocol activation route ready (often via 2222)"}, {"lead": "Anticoagulants and antiplatelets", "text": "Ask whether the patient is on warfarin, a DOAC, aspirin, clopidogrel or another antiplatelet, and whether they have been taking NSAIDs, and ask that no further doses are given until you have reviewed them"}, {"lead": "Liver disease and previous bleeds", "text": "Ask about known liver disease or varices, alcohol, previous GI bleeds, and previous endoscopy"}], "first_five_minutes": [{"lead": "ABCDE and resuscitate", "text": "Assess airway, breathing, circulation, disability and exposure — the priority is resuscitation, not diagnosis; keep nil by mouth. With ongoing haematemesis or reduced consciousness, protect the airway (recovery position, suction ready) and tell your registrar early — an anaesthetist may need to secure the airway before endoscopy. If shocked, start oxygen via a reservoir mask at 15 L/min, target 94–98% (BTS)"}, {"lead": "Activate MHP if unstable", "text": "If the patient is shocked or bleeding heavily, activate the major haemorrhage protocol yourself — you do not need permission — and call the medical registrar and the on-call endoscopy/gastroenterology team"}, {"lead": "Blood products", "text": "If fluid is needed while blood is coming, give a 500 ml crystalloid bolus (sodium 130–154 mmol/L) over less than 15 minutes and reassess (NICE CG174). Transfuse massive bleeding with blood, platelets and clotting factors in line with the local major haemorrhage protocol. Outside major haemorrhage, base transfusion on the full clinical picture — over-transfusion can be as damaging as under-transfusion. In suspected variceal bleeding transfusion is restrictive (target haemoglobin about 70 g/L unless comorbidity needs higher) — agree it with your registrar. Tranexamic acid is not given routinely for GI bleeding"}, {"lead": "Correct anticoagulation", "text": "If the patient is on warfarin or a DOAC and actively bleeding, call your registrar and haematology now — they will decide the reversal using your trust's protocol. Tell your registrar if platelets are below 50 x 10⁹/L or the clotting is deranged. In suspected variceal bleeding or cirrhosis, do not give FFP or platelets just to correct the INR or platelet count — agree any blood products with the registrar."}, {"lead": "Suspected variceal bleed", "text": "If varices are suspected (known cirrhosis, stigmata of liver disease), terlipressin and prophylactic antibiotics are given at presentation (NICE CG141) — prescribe them with your registrar straight away, check contraindications and the BNF/local protocol, and involve the hepatology/endoscopy team"}, {"lead": "Risk score and medicines", "text": "Calculate the Glasgow-Blatchford score at first assessment. Stop NSAIDs. Do not stop aspirin or clopidogrel without discussing with your senior."}, {"lead": "No PPI before endoscopy", "text": "Do not give acid-suppression drugs before endoscopy for suspected non-variceal bleeding — they are offered after endoscopy if stigmata of recent haemorrhage are seen"}, {"lead": "Timing of endoscopy", "text": "Unstable patients with severe bleeding need endoscopy immediately after resuscitation; suspected variceal bleeds within 12 hours; all others within 24 hours of admission"}], "can_i_do_alone": {"alone": "Assessing ABCDE, oxygen if shocked, getting IV access, sending bloods including a group and save and crossmatch, starting fluid resuscitation with a first crystalloid bolus, activating the major haemorrhage protocol if the patient is unstable, stopping NSAIDs, and calculating the Blatchford score", "senior_opinion": "Transfusion decisions outside the major haemorrhage protocol, anticoagulant reversal, and what to do with antiplatelets — and any patient with a stable, minor bleed who needs an endoscopy plan within 24 hours", "senior_in_person": "Any patient with ongoing bleeding, haemodynamic instability, a NEWS2 of 7 or more, or a suspected variceal bleed — the registrar needs to be at the bedside and the endoscopist contacted now, because emergency endoscopy may be needed"}, "escalate_now_if": ["The patient is haemodynamically unstable (hypotension, tachycardia, cool peripheries, falling consciousness) — activate the major haemorrhage protocol", "NEWS2 total of 7 or more — emergency response, at least at registrar level", "The bleeding is ongoing, or the BP and pulse do not improve, despite initial resuscitation", "There is a suspected variceal bleed (known liver disease or varices) — terlipressin and antibiotics should be given at presentation", "The patient is on warfarin or a DOAC and actively bleeding — reversal is needed now", "The platelet count is below 50 x 10⁹/L and the patient is actively bleeding — your registrar decides on platelets now (in suspected variceal bleeding they are not given just to correct the count)"], "document": "Record the time the bleeding was noted, the observations and NEWS2 score, the Glasgow-Blatchford score, IV access and fluids given, when the major haemorrhage protocol was activated and blood products given, anticoagulant or antiplatelet reversal or holding, medicines stopped, the time the endoscopy/gastroenterology team was contacted, and the agreed plan and timing for endoscopy.", "fail": "An unsafe response fails to resuscitate before investigating, waits for permission before activating the major haemorrhage protocol in a shocked patient, gives acid suppression before endoscopy for non-variceal bleeding, or misses antibiotics and terlipressin in a suspected variceal bleed.", "pass": "A safe response resuscitates, activates the major haemorrhage protocol when the patient is unstable, sends bloods and crossmatch, corrects anticoagulation, uses the Blatchford score, reviews medicines, and gets the endoscopy team involved with the correct timing.", "high_performance": "An excellent response also thinks about varices early in anyone with liver disease and makes sure antibiotics and terlipressin are given at presentation, plans for restarting aspirin once haemostasis is achieved, and keeps the patient and family informed.", "one_thing": "If you only remember one thing: resuscitate first and activate the major haemorrhage protocol yourself if the patient is shocked — then think 'could this be varices?', because they need antibiotics and terlipressin at presentation.", "img_note": "In most UK hospitals, any doctor or nurse can activate the major haemorrhage protocol — often through 2222, stating 'major haemorrhage' and the location — and the transfusion laboratory then releases blood and products in set packs. Find out on your first day how your trust activates it and who runs the out-of-hours GI bleed endoscopy rota.", "source": "NICE, Acute upper gastrointestinal bleeding in over 16s: management (CG141), last updated Aug 2016; BSG, UK guidelines on the management of variceal haemorrhage in cirrhotic patients, 2015; NICE, Andexanet alfa for reversing anticoagulation (TA697), 2021, updated Jan 2025; BSG, position statement on AASLD portal hypertension and varices guidance, Frontline Gastroenterology, 2026; BSH, Use of andexanet alfa: a position statement, Br J Haematol, 2026; NICE CG174 IV fluids (updated 2017); BTS oxygen guideline, 2017; RCP NEWS2, 2017; HALT-IT Trial Collaborators, Lancet 2020;395:1927–36 (tranexamic acid in GI bleeding); ESGE, Endoscopic diagnosis and management of nonvariceal upper GI haemorrhage, Endoscopy 2021 (airway protection). Two cannulae, the blood panel, nil by mouth, holding doses and airway protection are standard practice", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 9 calling about Mr Price — he's had a large fresh haematemesis and he's shocked, BP 95 over 55 and heart rate 110. I've activated the major haemorrhage protocol.", "B": "He has a history of peptic ulcer disease and has been taking ibuprofen for back pain. He isn't on anticoagulants and has no known liver disease.", "A": "He's pale and clammy. I've got two large-bore cannulas in, started resuscitation, sent FBC, U&E, LFTs, clotting and a crossmatch, stopped the ibuprofen, and his Blatchford score is at least 3 on the observations alone — I'll complete it when the Hb and urea are back. I haven't given a PPI.", "R": "Please come to the bedside now and can we contact the on-call endoscopist — I think he needs endoscopy as soon as he's resuscitated."}, "checked": "Oct 2026"}, {"id": "BLEEP-35", "title": "Constipation and bowel not opened post-op", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Foster hasn't opened his bowels since his operation four days ago, he's complaining of abdominal discomfort and feeling bloated.\"", "nurse_call": [{"lead": "Last bowel motion + flatus", "text": "Ask when the patient last opened their bowels and whether they are passing wind — passing wind does not rule out obstruction or pseudo-obstruction, so it is not a reason to skip the examination"}, {"lead": "Abdominal symptoms", "text": "Ask about pain, distension, nausea, and vomiting — if they are vomiting or the distension is increasing, ask the nurse to give no laxative until you have seen them"}, {"lead": "Observations and NEWS2", "text": "Ask for a full set of observations with a NEWS2 score, and to call you back straight away if it is 5 or more or any single parameter scores 3"}, {"lead": "Which operation?", "text": "Ask what operation they had — after abdominal surgery this may be ileus, obstruction or a leak, and the surgical team needs to know"}, {"lead": "Medications and laxatives", "text": "Ask about opioids, anticholinergics and other constipating medication, and what laxatives have been prescribed, actually given, and worked"}, {"lead": "Diet and mobility", "text": "Ask what the patient is eating and drinking, and whether they are mobile"}], "first_five_minutes": [{"lead": "ABCDE and the NEWS2 trend", "text": "Do a quick ABCDE and check the NEWS2 trend — fever, tachycardia, hypotension or a rising score suggest something other than simple constipation"}, {"lead": "Examine the abdomen", "text": "Examine for distension, tenderness, tympany and bowel sounds, and check the wound, hernial orifices and for a full bladder — absent or tinkling bowel sounds with distension suggest obstruction, but present bowel sounds do not exclude it"}, {"lead": "Perform a rectal examination", "text": "Perform a rectal examination with consent, offer a chaperone and record both — this assesses for faecal impaction and for rectal bleeding or a mass"}, {"lead": "Think pseudo-obstruction", "text": "Marked distension after orthopaedic surgery (especially hip or knee replacement) may be acute colonic pseudo-obstruction (Ogilvie's syndrome) — request an abdominal X-ray if the abdomen is distended, and if the colon is dilated, stop laxatives and escalate; the X-ray must not delay senior review if there are features of obstruction"}, {"lead": "Review the drug chart", "text": "Review the drug chart for opioids and other constipating medications, and consider whether the opioid can be reduced or switched; check U&Es, as low potassium is common in obstruction and needs correcting"}, {"lead": "Opioid-induced: osmotic + stimulant", "text": "For opioid-induced constipation, prescribe an osmotic laxative plus a stimulant laxative (for example a macrogol with senna) — avoid bulk-forming laxatives. For other constipation, follow the stepped approach: bulk-forming (only if the patient is mobile and drinking well), then osmotic, then add a stimulant if needed"}, {"lead": "Manage faecal impaction first", "text": "If there is faecal impaction, treat this first before maintenance laxatives — the disimpaction regimen is a senior or specialist decision"}, {"lead": "Mobility, fluids, privacy", "text": "Encourage mobility and fluids, and ensure privacy and dignity when using the toilet"}, {"lead": "Escalate if obstruction suspected", "text": "If there are signs of obstruction or pseudo-obstruction (vomiting, increasing distension, tenderness, not passing wind, systemic upset), stop oral laxatives, keep nil by mouth, send FBC, U&E, CRP and lactate, start IV fluids per local protocol and call your registrar to see them — the registrar decides on further imaging and a nasogastric tube"}], "can_i_do_alone": {"alone": "Examining the abdomen, performing a rectal examination with consent and a chaperone offered, reviewing the drug chart, prescribing regular laxatives when there are no features of obstruction (osmotic plus stimulant if opioid-induced), and requesting an abdominal X-ray if the abdomen is distended", "senior_opinion": "Any patient with faecal impaction needing disimpaction, no response to regular laxatives, any uncertainty about whether this is constipation, pseudo-obstruction or obstruction, or a change to the patient's analgesia", "senior_in_person": "Any patient with signs of obstruction or pseudo-obstruction (vomiting, increasing distension, tenderness, not passing wind, systemic upset), a NEWS2 of 5 or more or any single parameter scoring 3, or new distension, vomiting or pain after bowel surgery — this needs surgical review now"}, "escalate_now_if": ["There are signs of bowel obstruction (vomiting, increasing distension, tenderness, not passing wind) — absent bowel sounds are not needed", "There is marked distension after orthopaedic surgery, or a dilated colon on X-ray — possible pseudo-obstruction", "There is rectal bleeding or a rectal mass on examination", "The abdomen is tender, guarded or rigid, or the NEWS2 is 5 or more or any single parameter scores 3", "There is new fever, tachycardia, hypotension or a raised lactate after surgery, or new distension, vomiting or pain after bowel surgery"], "document": "Record the date of the last bowel motion, whether flatus is being passed, the observations and NEWS2, the abdominal and rectal examination findings, consent and whether a chaperone was offered, accepted or declined, the drug chart review, laxatives prescribed and given, any X-ray requested and the result, the call-back criteria given to the nurses, and the plan agreed with the senior if escalation was needed.", "fail": "An unsafe response takes 'passing wind' as reassurance without examining the abdomen, prescribes a bulk-forming laxative for opioid-induced constipation, or misses a distended abdomen after orthopaedic surgery.", "pass": "A safe response examines the abdomen and performs a rectal examination, reviews the opioids, prescribes an osmotic plus stimulant laxative for opioid-induced constipation, requests an X-ray if distended, escalates if obstruction or pseudo-obstruction is suspected, and leaves the nurses clear call-back criteria.", "high_performance": "An excellent response also addresses the underlying causes (opioids, immobility, dehydration), prescribes laxatives alongside regular opioids from the start, involves the nursing team in a bowel care plan, and ensures the patient has privacy and dignity when using the toilet.", "one_thing": "If you only remember one thing: examine the abdomen and do a rectal examination — 'passing wind' does not exclude obstruction, and a distended abdomen after orthopaedic surgery needs an X-ray to look for pseudo-obstruction.", "img_note": "In UK hospitals, bowel charts (often using the Bristol Stool Chart) are kept by the nursing team — ask to see it rather than relying on memory at handover. Digital rectal examination and digital removal of faeces are covered by the Royal College of Nursing's bowel care guidance, and many wards have trained nurses who can perform them.", "source": "NICE CKS, Constipation; RCN, Bowel care: management of lower bowel dysfunction, including digital rectal examination and digital removal of faeces, 2026; NICE CG140 1.1.18 (regular laxatives with strong opioids, by analogy); WSES adhesive small bowel obstruction guidelines, 2017 update (incomplete features, bloods with lactate, nil by mouth, IV fluids, NG decompression); macrogol and senna SmPCs (contraindicated in obstruction or ileus); GMC, Intimate examinations and chaperones, 2024; RCP NEWS2, 2017. Pseudo-obstruction, ileus and anastomotic leak are standard practice rather than guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 4 calling about Mr Foster — he hasn't opened his bowels since his hip replacement four days ago and he's bloated and uncomfortable.", "B": "He had a hip replacement under spinal anaesthetic and has been on regular codeine with no laxatives.", "A": "RR 16, sats 97% on air, BP 128/76, pulse 84, alert, temperature 36.9, so NEWS2 0. His abdomen is mildly distended but soft and non-tender, bowel sounds are present, and he's passing wind and not vomiting. Rectal examination, with a chaperone, shows soft stool with no impaction. I've requested an abdominal X-ray because of the distension and prescribed regular macrogol and senna, to start once the X-ray has excluded a dilated colon.", "R": "Could you look at the X-ray with me when it's done to rule out pseudo-obstruction, and advise whether we can switch or reduce his codeine? If the colon is dilated, the laxatives won't be started. I've asked the nurses to call me if he vomits, stops passing wind, becomes more distended or tender, or his NEWS2 is 5 or more or any single parameter scores 3."}, "checked": "Oct 2026"}, {"id": "BLEEP-36", "title": "Diarrhoea, including C. diff precautions", "fpc_tags": ["Clinical assessment", "Continuity of care", "Upholding values"], "scenario": "Nurse bleeps: \"Mrs Shaw's had four loose stools today and she's been on antibiotics for a week, should we send a C. diff sample?\"", "nurse_call": [{"lead": "Stool type and frequency", "text": "Ask about the stool type (Bristol Stool Chart) and frequency — types 5 to 7 count as diarrhoea, and the stool chart should be completed after every bowel movement"}, {"lead": "Isolate and send sample", "text": "Ask the nurse to isolate the patient in a side room (en-suite or dedicated commode), use gloves and aprons, and send a sample of the next loose stool (one that takes the shape of the pot) now — don't wait for the doctor to arrive"}, {"lead": "Soap and water", "text": "Remind everyone to wash hands with soap and water — alcohol hand rub is less effective at removing C. difficile spores and must not replace soap and water"}, {"lead": "Antibiotics and PPIs", "text": "Ask about current or recent antibiotics and proton pump inhibitors — both are risk factors for C. difficile"}, {"lead": "Other symptoms", "text": "Ask about fever, abdominal pain or distension, and whether the patient is drinking"}], "first_five_minutes": [{"lead": "Assess and grade severity", "text": "Do an ABCDE assessment with full observations and NEWS2 (use it to grade sepsis risk under NICE NG253). Check FBC and creatinine against baseline, and examine the abdomen — severe disease can cause ileus with little or no diarrhoea. Severe infection: WCC above 15 x 10⁹/L, creatinine more than 50% above baseline, temperature above 38.5°C, or signs of severe colitis. Life-threatening: hypotension, partial or complete ileus, toxic megacolon, or CT evidence of severe disease"}, {"lead": "Look for other causes", "text": "Also look for another cause: laxatives or other drugs, inflammatory bowel disease, or norovirus if others on the ward are affected"}, {"lead": "Isolate and test (SIGHT)", "text": "Suspect, Isolate, Gloves and aprons, Hand washing with soap and water, Test — isolate before the result is back, send the stool sample immediately for two-stage testing, and tell the infection prevention and control team"}, {"lead": "Treat suspected CDI", "text": "Do not wait for confirmation. For a first episode (mild, moderate or severe), start oral vancomycin 125 mg four times a day for 10 days (NICE NG199) — check BNF/local protocol. If tests do not confirm C. difficile, consider stopping"}, {"lead": "Review antibiotics and PPIs", "text": "Review the causative antibiotic with your senior: stop it unless it is essential — if it is, consider switching to one with a lower C. difficile risk. Review PPIs, laxatives, and drugs that are risky when dehydrated (NSAIDs, ACE inhibitors, ARBs, diuretics)"}, {"lead": "Fluids, no antimotility drugs", "text": "Manage fluid losses as for gastroenteritis: oral fluids, and IV fluids per local protocol if dehydrated. Do not give antimotility drugs such as loperamide"}, {"lead": "Escalate if life-threatening", "text": "Life-threatening infection needs urgent specialist advice (microbiology, gastroenterology and surgery)"}], "can_i_do_alone": {"alone": "Isolating the patient, sending the stool sample, assessing severity with bloods and examination, starting oral vancomycin for suspected C. difficile per your local antimicrobial policy, stopping PPIs, laxatives and nephrotoxic drugs that are not needed, and starting fluids per local protocol", "senior_opinion": "Whether the original antibiotic is still essential and what to switch to, severe infection (for example WCC above 15), a further episode, or a patient who cannot take oral medicines — involve microbiology", "senior_in_person": "Life-threatening features (hypotension, ileus, toxic megacolon, peritonism), NEWS2 of 5 or more, or a single parameter scoring 3 — this needs a senior at the bedside; life-threatening infection also needs urgent microbiology, gastroenterology and surgical input"}, "escalate_now_if": ["There is hypotension, partial or complete ileus, toxic megacolon, or CT evidence of severe disease — this is life-threatening", "There is severe infection: WCC above 15 x 10⁹/L, creatinine more than 50% above baseline, temperature above 38.5°C, or signs of severe colitis", "NEWS2 is 5 or more, or any single parameter scores 3", "Symptoms worsen rapidly at any point, or are not improving by day 7 of treatment", "This is a further episode — a relapse is within 12 weeks of symptoms resolving", "The patient has severe abdominal pain, distension, or systemic upset"], "document": "Record the stool type and frequency, the observations and NEWS2, the time the sample was sent, isolation and infection control measures, the severity assessment (WCC, creatinine against baseline, temperature, abdominal findings), the antibiotic started and the time, antibiotics, PPIs and other drugs reviewed or stopped, and the plan agreed with the senior and microbiology. Make sure the C. difficile diagnosis is recorded so it is seen before future antibiotics are prescribed.", "fail": "An unsafe response gives loperamide, fails to isolate the patient or send a stool sample promptly, or waits for a positive result before treating a patient with suspected C. difficile.", "pass": "A safe response isolates, sends a stool sample immediately, assesses severity, starts oral vancomycin for suspected C. difficile, reviews the antibiotics, PPIs and other drugs, and escalates severe or life-threatening disease.", "high_performance": "An excellent response also explains hand hygiene (soap and water, not alcohol gel) to the patient and visitors, involves microbiology early in severe disease, plans daily review, and records the diagnosis clearly for future prescribers.", "one_thing": "If you only remember one thing: isolate, send the sample and treat suspected C. difficile now with oral vancomycin — don't wait for the result, never give loperamide, and use soap and water, not gel.", "img_note": "In UK hospitals, C. difficile is a mandatory reportable infection, and each trust's infection prevention and control team (IPCT) tracks cases and may visit the ward. The SIGHT mnemonic (Suspect, Isolate, Gloves and aprons, Hand washing, Test) is used nationally — the nurse can isolate and send the sample before you arrive.", "source": "NICE, Clostridioides difficile infection: antimicrobial prescribing (NG199), Jul 2021, last reviewed Jul 2024 with an update planned (gives no fluid regimen, so fluids are per local protocol); UKHSA, Clostridioides difficile infection: how to deal with the problem (interim update), last updated Jun 2026, new guidance due 2027; UK SMI B 10, C. difficile testing (issue 2, Mar 2025); NICE NG253 (updated Sep 2026) and RCP NEWS2 (2017); BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 7 calling about Mrs Shaw — she has new diarrhoea, four type 7 stools today, after a week of co-amoxiclav, and I'm treating her as suspected C. difficile.", "B": "She's 78 and has been in hospital for two weeks with a chest infection.", "A": "Temp 38.2, pulse 96, BP 124/70, resps 18, sats 96% on air, alert, so NEWS2 is 2. WCC 16 and creatinine at baseline, so this would be severe; her abdomen is soft and not distended. She's isolated, the stool sample is sent, I've started oral vancomycin 125 mg four times a day, stopped her omeprazole and flagged the co-amoxiclav for your review.", "R": "Could you advise whether she still needs antibiotics for the chest and what to use if so — and should we involve microbiology today given the WCC?"}, "checked": "4 Oct 2026"}, {"id": "BLEEP-37", "title": "New jaundice", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mrs Ali's looked a bit yellow today, the nurses on the previous shift said she looked fine yesterday.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score — fever, hypotension or new confusion with jaundice means you need to attend now"}, {"lead": "Symptoms", "text": "Ask about abdominal pain, fever or rigors, nausea, vomiting, and any change in urine or stool colour (dark urine, pale stools)"}, {"lead": "Recent medications and procedures", "text": "Ask about recent medications, including over-the-counter and herbal (and antibiotics such as co-amoxiclav and other hepatotoxic drugs), blood transfusions, and any recent procedures"}, {"lead": "Alcohol and liver history", "text": "Ask about alcohol intake, known liver disease, and gallstones"}, {"lead": "Cannula and bloods", "text": "If the patient has a fever or rigors or is unwell, ask for a cannula and blood cultures before you arrive"}], "first_five_minutes": [{"lead": "ABCDE and sepsis screen", "text": "Assess airway, breathing, circulation, disability and exposure. Fever or rigors (or a raised white cell count or CRP) with jaundice suggests acute cholangitis, especially with right upper quadrant pain or known gallstones — use NEWS2 to grade sepsis risk under NICE NG253"}, {"lead": "High-risk sepsis: act now", "text": "If high risk (NEWS2 7 or more, or 5–6 with a 3-point parameter from the infection or other cause for concern, or medium risk with lactate over 2 mmol/L or AKI): take blood cultures and a venous gas with lactate, give IV antibiotics per your trust's biliary sepsis guideline within 1 hour, and give a 250 ml crystalloid bolus over 10–15 minutes unless contraindicated (NG253)"}, {"lead": "Bloods and urine", "text": "Send FBC, U&E, LFTs (to see the pattern: obstructive or hepatitic), CRP, amylase or lipase, clotting, glucose and a group and save, with blood cultures before any antibiotic if she has a fever or rigors — and check urine for bilirubin"}, {"lead": "Request urgent ultrasound", "text": "Request an urgent abdominal ultrasound — the first-line test for biliary obstruction and dilated ducts."}, {"lead": "Confirm jaundice, look for liver failure", "text": "Examine for jaundice and signs of chronic liver disease, and look for encephalopathy (confusion, asterixis) and a raised INR — these suggest acute liver failure. A raised INR can also be vitamin K deficiency from cholestasis: discuss it, don't correct it yourself"}, {"lead": "Consider the cause", "text": "Work through the causes: obstruction (gallstones, malignancy), drug-induced liver injury, viral or alcoholic hepatitis, haemolysis, sepsis itself, or decompensated cirrhosis — add a haemolysis screen if she is anaemic, and a liver screen (hepatitis serology, autoimmune) if no obvious cause"}, {"lead": "Escalate", "text": "Inform the registrar now for high-risk sepsis or suspected cholangitis — the registrar should review urgently and arrange gastroenterology or surgical input about drainage. If NEWS2 is 7 or more, also call your critical care outreach team. Do not delay antibiotics while waiting"}], "can_i_do_alone": {"alone": ["Examining for jaundice, liver disease and sepsis", "Taking blood cultures and a venous gas, and sending bloods including LFTs and clotting", "Giving IV antibiotics within 1 hour and a fluid bolus for a high-risk septic patient per NG253 and the trust sepsis guideline", "Requesting an urgent ultrasound if your trust lets F1s request it — while an FY2-or-above/registrar review is arranged urgently"], "senior_opinion": "Any patient where the cause is unclear, a hepatitic picture or a possible drug-induced liver injury (which drug to stop), or a mildly raised INR", "senior_in_person": "Any patient with suspected cholangitis or high-risk sepsis, NEWS2 of 5 or more or a single parameter scoring 3, encephalopathy, an INR above 1.5 or other signs of liver failure, or haemodynamic instability — these need the registrar at the bedside and gastroenterology or surgical input about biliary drainage"}, "escalate_now_if": ["There is fever or rigors with jaundice — this may be cholangitis, which needs prompt antibiotics (within 1 hour if high risk) and may need urgent biliary drainage", "There is confusion or reduced consciousness suggesting sepsis or hepatic encephalopathy", "The INR is above 1.5 not explained by anticoagulation, or platelets are below 100 and this is new (not the patient's known baseline)", "There is hypotension, low urine output or a lactate over 2 mmol/L, or NEWS2 is 5 or more or a single parameter scores 3 (7 or more is an emergency response)", "The ultrasound shows dilated bile ducts in an unwell patient"], "document": "Record the time jaundice was noted, the observations and NEWS2 score, the sepsis risk category, examination findings, blood cultures and the time IV antibiotics and fluids were given, investigations ordered (including the time the ultrasound was requested), and the plan agreed with the senior including any gastroenterology or surgical referral.", "fail": "An unsafe response dismisses new jaundice as harmless, waits for imaging or a senior before giving antibiotics to a febrile, hypotensive, confused patient, or fails to request an urgent ultrasound when obstruction is possible.", "pass": "A safe response grades sepsis risk with NEWS2, takes cultures and gives IV antibiotics within 1 hour when high risk, sends bloods including LFTs and clotting, requests an urgent ultrasound, and escalates for drainage.", "high_performance": "An excellent response also reviews the drug chart for hepatotoxic drugs, recognises the LFT pattern, and makes sure the right team is involved (gastroenterology or surgery for obstruction, hepatology for liver failure).", "one_thing": "If you only remember one thing: jaundice with fever or rigors means suspected cholangitis — cultures, IV antibiotics within the hour if high risk, urgent ultrasound, and the registrar told now, because the patient may need biliary drainage.", "img_note": "In UK hospitals, urgent inpatient imaging is requested electronically and often needs a phone call to the duty radiologist to agree priority — say clearly why it is urgent ('suspected cholangitis, febrile and hypotensive'). Most trusts have a sepsis screening tool built into the electronic observations system, triggered by NEWS2.", "source": "NICE, Suspected sepsis in people aged 16 or over (NG253), last updated 23 Sep 2026: 1.6.2, 1.8.1–1.8.7, 1.8.18–1.8.20, 1.11.4; RCP NEWS2 (2017); Tokyo Guidelines 2018 (international) (cholangitis criteria; severe-grade organ dysfunction incl. PT-INR above 1.5 and platelets below 100 x 10⁹/L, Table 3); NICE CG188 Gallstone disease (2014) 1.1.1; NICE NG85 Pancreatic cancer 1.1.1; BSG abnormal liver blood tests guideline (2018); co-amoxiclav SmPC. Liver-failure signs are standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 6 calling about Mrs Ali — she's newly jaundiced, febrile and confused, and I'm treating her as high-risk sepsis, probably cholangitis.", "B": "She's been in hospital for a week with a urinary tract infection and has been on antibiotics.", "A": "Temperature 38.5, BP 95 over 60, heart rate 115, respiratory rate 22, saturations 97% on air, new confusion — NEWS2 is 10. Her LFTs are cholestatic. I've taken blood cultures and a venous gas, given IV antibiotics per our biliary sepsis guideline and a 250 ml fluid bolus, and requested an urgent ultrasound.", "R": "Please come and review her now — I've also called critical care outreach as her NEWS2 is 10 — and can we involve gastroenterology or surgery today about biliary drainage?"}, "checked": "Oct 2026"}, {"id": "BLEEP-38", "title": "Ascites in cirrhosis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Green's abdomen has become much more distended over the last few days, he says he feels breathless and uncomfortable.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations including respiratory rate, saturations, temperature, and the NEWS2 score — if it is 5 or more, ask for observations at least hourly and say you are coming now"}, {"lead": "Breathlessness", "text": "Ask whether the patient is breathless at rest — this may be diaphragmatic splinting from tense ascites or a pleural effusion (hepatic hydrothorax)"}, {"lead": "Weight and fluid balance", "text": "Ask for the recent weights, fluid balance and urine output — rapid weight gain suggests fluid accumulation"}, {"lead": "Liver history and medications", "text": "Ask about known liver disease, alcohol intake, and current medications including diuretics and their recent doses"}, {"lead": "Confusion, fever, bleeding", "text": "Ask whether the patient has been confused or drowsy, has a fever or abdominal pain, or any GI bleeding — each is a reason for a diagnostic tap to look for spontaneous bacterial peritonitis (SBP)"}], "first_five_minutes": [{"lead": "ABCDE and oxygen", "text": "Assess ABCDE and examine the chest — consider pneumonia or heart failure, not just the ascites. Sit him up and give oxygen by nasal cannulae to 94–98% (if at risk of hypercapnia, 24% Venturi at 2–3 L/min or cannulae at 1–2 L/min to 88–92%, pending a blood gas)"}, {"lead": "Recalculate NEWS2 on oxygen", "text": "Oxygen adds 2: 7 or more means continuous monitoring and an emergency response (registrar or above). Needing a reservoir mask means urgent senior assessment"}, {"lead": "Examine the abdomen", "text": "Examine for ascites (shifting dullness, tense abdomen), tenderness, and signs of chronic liver disease and hepatic encephalopathy (confusion, asterixis) — check a capillary glucose if confused or drowsy"}, {"lead": "Diagnostic tap without delay", "text": "Every patient with cirrhosis and ascites admitted to hospital, or who deteriorates (fever, abdominal pain, encephalopathy, GI bleed, shock, worsening renal or liver function), needs a diagnostic ascitic tap without delay — routine clotting and platelet checks and blood products are not needed beforehand"}, {"lead": "Send the right samples", "text": "Send ascitic fluid for neutrophil count (a dipstick is no substitute), total protein, albumin (for the SAAG) and culture, inoculating blood culture bottles at the bedside. Send FBC, U&E, LFTs, CRP and clotting"}, {"lead": "Think sepsis", "text": "If you suspect infection, take blood cultures and a venous lactate before antibiotics. NG253: NEWS2 7 or more is high risk (IV antibiotics within 1 hour). 5–6 is medium risk (FY2 or above to review within 1 hour), but treat as high risk if lactate is over 2 mmol/L or there is an AKI, or if a single parameter scores 3 and the likely cause is the infection"}, {"lead": "Treat SBP immediately", "text": "An ascitic neutrophil count above 250/mm³ is SBP — start empirical IV antibiotics immediately, per your trust's protocol, and tell the registrar. If creatinine is raised or rising, tell your senior — they will decide on IV albumin. Localised signs, a very high count or several organisms suggest secondary peritonitis: CT and early surgical opinion"}, {"lead": "Review diuretics and kidneys", "text": "Check U&E and sodium; don't increase diuretics on call. Hold or reduce them for AKI or significant hyponatraemia (most hepatologists stop them below 125 mmol/L), and discuss changes with a senior"}, {"lead": "Paracentesis plan", "text": "Tense ascites causing breathlessness or discomfort needs large-volume paracentesis. If more than 5 L is drained, albumin is needed (8 g per litre removed) — confirm with your senior"}], "can_i_do_alone": {"alone": "Assessing the patient, giving oxygen to target, examining for ascites and encephalopathy, sending bloods and blood cultures, and doing a diagnostic ascitic tap only if you are signed off as competent — then starting IV antibiotics per trust protocol if the neutrophil count is above 250/mm³", "senior_opinion": "If stable (NEWS2 below 5, no single 3, no sign of infection): diuretic changes, a diagnostic tap if you are not yet signed off (do it under supervision), and the plan and timing for large-volume paracentesis", "senior_in_person": "NEWS2 5 or more or a single 3 (registrar for 7 or more), respiratory compromise, suspected SBP, sepsis or secondary peritonitis, encephalopathy, AKI, GI bleeding or shock — these need a senior now, with hepatology involved"}, "escalate_now_if": ["NEWS2 7 or more (emergency response, at least registrar), or 5–6 or a single parameter of 3 (urgent assessment)", "Respiratory compromise from tense ascites (may need urgent drainage), or saturations can't be kept in range without a reservoir mask", "The ascitic neutrophil count is above 250/mm³, you suspect sepsis, or there is fever, abdominal pain or worsening encephalopathy", "Localised tenderness or guarding suggesting secondary peritonitis", "There is a rapid deterioration in renal function or a significant fall in sodium", "The patient has hepatic encephalopathy (confusion, drowsiness, asterixis), a GI bleed, or low blood pressure or other signs of shock"], "document": "Record when the distension was noted, observations and NEWS2 before and after oxygen, oxygen device and target, abdominal and chest findings, the diuretic regimen and recent changes, the ascitic tap (consent, who did it, volume, samples sent, neutrophil count when available), antibiotics given and the time, the paracentesis plan including albumin, and the plan agreed with the senior.", "fail": "An unsafe response blames the breathlessness on the ascites without examining the chest, skips the diagnostic tap, sees an ascitic neutrophil count above 250/mm³ without starting antibiotics, keeps escalating diuretics without checking renal function and sodium, or does a procedure they are not signed off for without supervision.", "pass": "A safe response gives oxygen to target and recalculates NEWS2, examines for ascites and encephalopathy, arranges a diagnostic tap without delay, treats SBP immediately when the neutrophil count is above 250/mm³, reviews diuretics against U&E, and escalates respiratory compromise and a rising NEWS2 at the right level.", "high_performance": "An excellent response also inoculates culture bottles at the bedside, involves hepatology early for refractory ascites, and considers whether the patient is on a transplant pathway.", "one_thing": "If you only remember one thing: every patient with cirrhotic ascites who is admitted or deteriorates needs a diagnostic tap — and a neutrophil count above 250/mm³ means SBP, so start antibiotics straight away.", "img_note": "In UK hospitals, ascitic taps and paracentesis need supervised sign-off (often by DOPS) before you do them alone, and many trusts run nurse- or physician-led day-case paracentesis units. Written or verbal consent is needed and should be recorded.", "source": "BSG and BASL, Guidelines on the management of ascites in cirrhosis, Gut 2021 (reviewed December 2024, still valid, next review 2027); NICE, Cirrhosis in over 16s: assessment and management (NG50), last updated Sep 2023; NICE, Suspected sepsis in people aged 16 or over (NG253), last updated 23 Sep 2026; RCP, NEWS2, 2017; BTS, Guideline for oxygen use in adults in healthcare and emergency settings, 2017. Examining the chest, the blood panel and capillary glucose are standard clinical practice. BNF (accessed Oct 2026).", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 10 calling about Mr Green — his ascites is now tense and he's breathless. On air his NEWS2 was 6: resps 24, sats 92%, BP 108/70, pulse 98, alert, temp 37.4. On 2 litres by nasal cannulae his sats are 95%, so his NEWS2 is now 7.", "B": "He has alcohol-related cirrhosis and has been on spironolactone and furosemide as an inpatient.", "A": "Abdomen tense but not tender, no confusion; reduced air entry at the right base could be a hydrothorax or a chest infection. I've sat him up, sent U&E, LFTs, clotting and blood cultures, and as I'm signed off I've done a diagnostic tap — the sample has gone for cell count, protein, albumin and culture, with culture bottles inoculated.", "R": "With a NEWS2 of 7, please come and see him now. If we think this is infection he's high risk on NG253, so I'll give IV antibiotics within the hour without waiting for the ascitic neutrophil count. Please also advise on large-volume paracentesis and whether to hold his diuretics. I'll chase the neutrophil count; over 250 confirms SBP."}, "checked": "Oct 2026"}, {"id": "BLEEP-39", "title": "Fluid overload and pulmonary oedema", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Quality improvement"], "scenario": "Nurse bleeps: \"Mr Coleman's become really breathless over the last hour, he's got crackles up to his mid-zones and his saturations are 88 on air. He's had IV fluids running all day for dehydration.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations including respiratory rate, saturations, heart rate, BP, temperature, conscious level, and the NEWS2 score"}, {"lead": "Sit up + oxygen", "text": "Ask the nurse to sit the patient upright and start oxygen to a target of 94–98% — or 88–92% (24% Venturi mask at 2–3 L/min or nasal cannulae at 1–2 L/min) if at risk of hypercapnic respiratory failure, such as COPD, pending a blood gas"}, {"lead": "Stop IV fluids", "text": "Ask the nurse to stop any IV fluids that are running, but not IV drugs such as antibiotics"}, {"lead": "Fluid balance and weight", "text": "Ask for the recent fluid balance and whether the patient's weight has changed — rapid weight gain suggests fluid accumulation"}, {"lead": "IV fluids given so far", "text": "Ask for all IV fluids and boluses given in the last 24 hours, and whether the patient takes a regular diuretic"}, {"lead": "Baseline cardiac and renal history", "text": "Ask about the patient's cardiac and renal history — this determines how cautiously any diuretic is given"}], "first_five_minutes": [{"lead": "ABCDE with attention to breathing", "text": "Assess airway, breathing, circulation, disability and exposure — look for the signs of fluid overload: bibasal crackles, raised JVP, peripheral oedema, and a third heart sound"}, {"lead": "Stop IV fluids and reassess", "text": "Stop all IV fluids and reassess after each intervention. Add up all intake, including boluses, oral fluids and IV drugs (NICE CG174); no more fluids or boluses until a senior has reviewed the fluid plan"}, {"lead": "Arterial blood gas", "text": "Take an arterial blood gas — hypoxaemia, hypercapnia and acidaemia guide the oxygen target and whether non-invasive ventilation needs to be considered"}, {"lead": "ECG, troponin and chest X-ray", "text": "Request an ECG and troponin to look for an ischaemic trigger or arrhythmia, and a portable chest X-ray to confirm pulmonary oedema and exclude pneumonia or pneumothorax"}, {"lead": "Bloods including renal function", "text": "Send U&E, FBC, and natriuretic peptide (BNP or NT-proBNP) if new heart failure is suspected — renal function guides the diuretic decision"}, {"lead": "Diuretic decision with senior input", "text": "If this is cardiogenic pulmonary oedema, NICE CG187 says to offer an IV diuretic; agree the drug and dose with a senior rather than giving one from memory. NICE advises against routinely giving opiates or nitrates in acute heart failure"}, {"lead": "Monitor closely", "text": "After the diuretic, monitor urine output, weight, renal function and BP — watch for over-diuresis and for an inadequate response that needs escalation"}], "can_i_do_alone": {"alone": "Sitting the patient upright, starting oxygen to the correct target, stopping IV fluids, taking an ABG, requesting an ECG, troponin and chest X-ray, sending bloods, and recording accurate fluid balance and weight", "senior_opinion": "The IV diuretic dose, any uncertainty about whether the picture is fluid overload or something else (such as pneumonia, PE or an acute coronary syndrome), and before any IV fluids are restarted", "senior_in_person": "Anything on the escalate-now list, including this patient's NEWS2 of 8 — a senior needs to be at the bedside now, and he may need non-invasive ventilation or critical care"}, "escalate_now_if": ["He needs a reservoir mask at 15 L/min to stay in the target range (BTS: urgent senior assessment), or the blood gas shows acidaemia or a rising CO2", "His systolic BP is 90 or below, or he has other signs of cardiogenic shock", "There is new chest pain, ischaemic ECG changes, a raised troponin, or a new tachyarrhythmia other than sinus tachycardia (life-threatening if it causes pulmonary oedema)", "The NEWS2 is 5–6 or a single parameter scores 3 (urgent response), or 7 or more (emergency response) — or you are clinically concerned at any score", "The patient is exhausted, cannot complete sentences, or has a falling consciousness level", "He is not improving with treatment, especially with worsening kidney function or potassium — he may need renal replacement therapy"], "document": "Record the time the breathlessness was noted, the observations and NEWS2 score at review, examination findings including JVP, crackles and oedema, oxygen given and the target range, the ABG result, IV fluids given in the last 24 hours and when stopped, investigations ordered, fluid balance and weight, the diuretic decision and who agreed it, and the plan agreed with the senior including the time they were contacted; if the pulmonary oedema developed during IV fluids or within 6 hours of stopping them and no other obvious cause (e.g. pneumonia, PE, asthma) is found, complete an incident report.", "fail": "An unsafe response continues IV fluids in a patient who is clearly overloaded, gives oxygen to the wrong target in someone at risk of hypercapnia, gives a diuretic dose from memory without checking the patient's baseline, anchors on fluid overload without considering pneumonia, PE or a cardiac event, or sits on a high NEWS2 without escalating.", "pass": "A safe response stops IV fluids, does a structured assessment, gives oxygen to the correct target, takes an ABG, requests an ECG, troponin and chest X-ray, and escalates promptly when the NEWS2 or blood gas triggers it.", "high_performance": "An excellent response also anticipates the need for non-invasive ventilation in cardiogenic pulmonary oedema with severe breathlessness and acidaemia, pre-empts what the senior will ask about diuretic dosing, and makes sure the fluid event is reviewed and learned from.", "one_thing": "If you only remember one thing: stop the IV fluids, sit the patient up, give oxygen to the right target and get a blood gas — pulmonary oedema during or within 6 hours of IV fluids is a recognised harm of fluid prescribing.", "img_note": "In UK practice, NICE CG174 asks prescribers to use the 5 Rs (Resuscitation, Routine maintenance, Replacement, Redistribution, Reassessment) and to state the fluid type, rate and volume, and pulmonary oedema during or within 6 hours of IV fluids, with no other obvious cause, should be reported as a patient safety incident (on Datix or your trust's equivalent).", "source": "NICE, Intravenous fluid therapy in adults in hospital (CG174), last updated May 2017; NICE, Acute heart failure (CG187), last updated Nov 2021; NICE, Acute kidney injury (NG148), last updated Oct 2024; BTS, Guideline for oxygen use in adults in healthcare and emergency settings, 2017 (update due 2026); RCP, NEWS2, 2017; RCUK adult tachyarrhythmia algorithm, V3 March 2026. Stopping the infusion and troponin are standard practice; diuretic dose per local protocol.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 12 calling about Mr Coleman — he's acutely breathless with saturations of 88% on air and a NEWS2 of 8, and I think this is pulmonary oedema from IV fluids.", "B": "He's 78, with no known heart failure or lung disease, admitted with dehydration; he's had about 4 litres of IV fluid in 24 hours, including two boluses for low urine output.", "A": "On air: respiratory rate 28, saturations 88%, heart rate 115, BP 150/90, alert, temperature 37.0; crackles to the mid-zones, raised JVP. I've stopped the IV fluids, sat him up, and started oxygen to 94–98%; his ABG shows type 1 respiratory failure with no acidosis. ECG shows sinus tachycardia with no acute changes; troponin, U&E and chest X-ray are requested. I haven't yet excluded pneumonia, PE or a cardiac event.", "R": "Please come and review him now, agree the IV furosemide dose so I can give it straight away, and set a plan for his fluids from here."}, "checked": "Oct 2026"}, {"id": "BLEEP-40", "title": "Blocked or dislodged urinary catheter", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mrs Baker's catheter hasn't drained anything for four hours and she's complaining of lower abdominal pain, it might be blocked.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score — fever, rigors or a raised NEWS2 mean you need to assess for sepsis and its source"}, {"lead": "Is the catheter still in?", "text": "Ask the nurse to check whether the catheter is still in place — a dislodged catheter must never be pushed back in, and a fallen-out suprapubic catheter is urgent because the tract can close"}, {"lead": "Kinks and bag position", "text": "Ask the nurse to check for kinked tubing, a closed valve or an overfull bag, and that the bag is below the level of the bladder"}, {"lead": "Bladder scan", "text": "Ask for a bladder scan — a large residual suggests the catheter is not draining; a small residual means the problem may be low urine output (oliguria or AKI)"}, {"lead": "Blood or clots in the urine", "text": "Ask whether the urine has been bloody or contained clots — clot retention needs a different approach"}, {"lead": "Output, fluids and catheter type", "text": "Ask about fluid intake, the recent urine output trend, whether the catheter is urethral or suprapubic, and any recent urological surgery"}], "first_five_minutes": [{"lead": "Assess the patient first", "text": "Assess airway, breathing, circulation, disability and exposure and check the NEWS2 — if the patient is unwell, consider sepsis and look for its source rather than assuming it is the catheter (a catheter is a sepsis risk factor)"}, {"lead": "Examine the abdomen", "text": "Examine for a palpable, tender bladder — together with a large residual on bladder scan this points to retention"}, {"lead": "Check the catheter", "text": "Check that the catheter is still in place, the tubing is not kinked, and the bag is draining freely — fix the simple causes before anything else"}, {"lead": "Change a blocked catheter", "text": "A catheter that is not draining usually needs changing using aseptic technique. Use a flush or catheter maintenance solution only if your trust's catheter policy allows it — they are not a routine way to unblock a catheter, break the closed system, and need a recorded reason"}, {"lead": "Haematuria with clots", "text": "If clots are blocking the catheter, this is clot retention — involve the urology team now"}, {"lead": "Bladder empty: think AKI", "text": "If the bladder is empty and the catheter drains, treat this as low urine output: assess fluid status, send U&E against the baseline creatinine, start a fluid balance chart, and don't routinely give a loop diuretic"}, {"lead": "Infection? Not by dipstick", "text": "Don't dipstick to diagnose infection with a catheter in place. If infection is suspected, send a catheter specimen from the sampling port, aseptically — from the new catheter if changed"}, {"lead": "Consider the cause", "text": "Consider encrustation, debris or clots, infection, constipation and dehydration — recurrent blockage in a long-term catheter needs a care plan and may need urology review"}, {"lead": "Escalate if you cannot catheterise", "text": "Stop and escalate if you cannot pass a catheter, there is resistance or bleeding, or with a known stricture or difficult catheterisation, recent urological surgery, a three-way irrigation catheter, or a suprapubic catheter you aren't trained to change — do not force it"}], "can_i_do_alone": {"alone": "Assessing the patient, checking the catheter and tubing, arranging a bladder scan, sending U&E, and changing a blocked or dislodged urethral catheter if you are trained and competent, unless there was recent urological surgery or a known difficult catheterisation", "senior_opinion": "Recurrent blockage needing a long-term plan, uncertainty about whether this is retention or low urine output, AKI on bloods without complications, or suspected urinary infection without systemic upset", "senior_in_person": "A painful, distended bladder that you cannot catheterise, suspected urethral trauma, clot retention, a suprapubic catheter that has fallen out, no urine with an empty bladder, a blocked three-way or post-urological-surgery catheter, or a NEWS2 trigger or signs of sepsis — these need urgent senior or urology input"}, "escalate_now_if": ["You cannot re-catheterise and the patient has a painful, distended bladder", "There is suspected urethral trauma or bleeding after an attempt", "There is haematuria with clots causing the blockage (clot retention)", "NEWS2 of 5 or more, 3 in any single parameter, or signs of sepsis", "A suprapubic catheter has fallen out", "The bladder is empty on scan but there is still no urine output", "AKI with hyperkalaemia, acidosis, fluid overload, pulmonary oedema or uraemic symptoms", "There is a known urethral stricture, recent urological surgery, or a blocked three-way irrigation catheter"], "document": "Record the time the blockage was noted, the observations and NEWS2 score, the abdominal examination, the bladder scan result, whether the catheter was in place, the catheter changed (type, size, balloon volume, batch number, expiry date, residual drained), the reason for any flush, any difficulty, U&E if sent, and the plan agreed with the senior or urology team.", "fail": "An unsafe response pushes a dislodged catheter back in, forces a catheter against resistance, misses clot retention, uses a urine dipstick to diagnose infection, misses an empty bladder with no urine output, or fails to escalate when re-catheterisation has failed.", "pass": "A safe response assesses the patient, checks the catheter and tubing, arranges a bladder scan, changes a blocked catheter if competent, looks for AKI if the bladder is empty, recognises clot retention, and escalates if catheterisation fails or the patient is unwell.", "high_performance": "An excellent response also looks at why the catheter blocked (encrustation, infection, dehydration, constipation), makes sure the long-term catheter care plan and change interval are reviewed and blockages documented, and asks whether the catheter is still needed.", "one_thing": "If you only remember one thing: check the patient and the tubing first, change a catheter that isn't draining rather than forcing fluid through it, and never force a catheter — clots or failed catheterisation need urology.", "img_note": "In UK hospitals, female catheterisation is a core nursing skill and many ward nurses are more experienced at catheter care than new doctors — ask for help. Catheter details (size, type, balloon volume, batch number) are recorded in a catheter passport or care bundle, which follows the patient into the community.", "source": "epic3 national HCAI guidelines (urinary catheters), 2014: closed system, sampling port, bag position (epic4 due from autumn 2026, recheck before publishing); NICE CG139, last updated Feb 2017: long-term catheter blockage 1.2.5.10–1.2.5.12; RCN Catheter Care (010 988, Dec 2025): drainage checks, maintenance solutions only after other options, no dipstick; NICE NG148 Acute kidney injury (updated Oct 2024) 1.5.3; NICE NG113 (2018) 1.1.4; RCP NEWS2 (2017); NICE NG253 (updated Sep 2026) 1.2.1. Not pushing a dislodged catheter back in, the clot-retention pathway and urgent review for no urine with an empty bladder are standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 5 calling about Mrs Baker — her long-term catheter blocked today, and this is the third time this month.", "B": "She has a long-term catheter for urinary retention.", "A": "She had a tender, palpable bladder with 600 ml on the bladder scan; there were no kinks and no clots. Her obs are RR 16, sats 97% on air, BP 128/76, pulse 82, alert, temperature 36.8, so NEWS2 is 0. I changed the catheter and it drained 600 ml; her pain has settled. There was heavy encrustation on the old catheter.", "R": "She's safe for now — could the team review her catheter care plan and change interval tomorrow and consider a urology referral for recurrent blockage? I'll ask the nurses to call me if she becomes unwell or it stops draining."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-41", "title": "Suspected line/CVC-related sepsis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Quality improvement"], "scenario": "Nurse bleeps: \"Mr Hughes has spiked a temperature of 38.8 and his central line site looks red and tender, he's on TPN.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score — under NICE NG253 this grades the sepsis risk and sets the clock for antibiotics"}, {"lead": "Line site check", "text": "Ask the nurse to check the central line exit site and tunnel for redness, discharge, pain or swelling"}, {"lead": "Cultures and cannula", "text": "Ask for a peripheral cannula, blood culture bottles and a venous gas with lactate, and who is trained to sample from the line — but antibiotics must not wait for you to arrive if the patient is high risk"}, {"lead": "Other sources", "text": "Ask whether there are any other obvious sources of infection — chest, urine, wound, or abdominal"}, {"lead": "Line type and TPN", "text": "Ask what type of line it is, how long it has been in, and what is running through it (including TPN)"}, {"lead": "Chemo or immunosuppressants?", "text": "Ask whether he has had systemic anticancer treatment, such as chemotherapy, in the last 30 days or takes immunosuppressants; if so, suspect neutropenic sepsis (NICE CG151)"}], "first_five_minutes": [{"lead": "ABCDE and grade risk", "text": "Assess airway, breathing, circulation, disability and exposure (oxygen only to a target of 94–98%, or 88–92% if at risk of hypercapnic failure), and grade risk with NEWS2 (NG253): 7 or more is high risk; 5–6 is medium risk, but becomes high risk if a 3-point parameter is due to the infection or there is hypoperfusion (lactate over 2 mmol/L or AKI). If high risk, ask now for an urgent FY2-or-above review and recalculate NEWS2 every 30 minutes"}, {"lead": "Peripheral cultures first", "text": "Take blood cultures before antibiotics if this doesn't significantly delay them: a peripheral set first, then a line set if one is taken, labelled by site, plus FBC, CRP, U&E, LFTs, clotting and a venous gas with lactate and glucose"}, {"lead": "Antibiotics within 1 hour", "text": "If high risk, give broad-spectrum IV antibiotics within 1 hour of the NEWS2 score, using your trust's guideline for suspected line infection (which should cover staphylococci) — check BNF/local protocol and allergies. Do not wait for the registrar to arrive. At medium risk, get an FY2-or-above review within 1 hour; they decide whether antibiotics can wait, but not beyond 3 hours"}, {"lead": "Fluid bolus if high risk", "text": "Unless contraindicated, give a 250 ml isotonic crystalloid bolus over 10–15 minutes within 1 hour, reassess after each bolus, and get senior advice if not improving after 1,000 ml in total"}, {"lead": "Examine line and other sources", "text": "Examine the exit site and tunnel for redness, pus, tenderness or fluctuance, swab any exudate, and examine thoroughly for other sources, including a surgical wound or collection; consider a urine test and chest X-ray"}, {"lead": "Don't use the line yet", "text": "Avoid running anything else through the suspect line, including TPN, until the senior and nutrition team agree a plan — if TPN is paused, check capillary glucose and tell the nutrition team the same day"}, {"lead": "Escalate and review line", "text": "Tell the registrar now: line removal is a senior decision that depends on the line type and alternative access. If there is no response within 1 hour of any intervention, the senior must attend, critical care should be involved and the responsible consultant informed"}], "can_i_do_alone": {"alone": "Grading sepsis risk with NEWS2, taking peripheral cultures (and a line set if trained), sending bloods and lactate, giving IV antibiotics within 1 hour and a 250 ml fluid bolus for a high-risk patient per NG253 and trust guideline, examining the line site and other sources, and pausing TPN through the suspect line, then checking capillary glucose and telling the nutrition team the same day, while the registrar (FY2 or above) assesses urgently", "senior_opinion": "Whether antibiotics can be deferred at medium or low risk (an FY2-or-above decision), whether the line should be removed or salvaged, the antibiotic choice in a penicillin allergy or known resistant organism, and plans for TPN and alternative access — involve microbiology", "senior_in_person": "Any patient who is high risk and not responding within 1 hour, hypotensive despite fluids, with a rising lactate or reduced GCS — the senior must attend, critical care should be involved, and the responsible consultant must be informed"}, "escalate_now_if": ["The NEWS2 is 7 or more, or 5–6 with a lactate over 2 mmol/L, an AKI, or a 3-point parameter from the infection (high risk)", "A single NEWS2 parameter scores 3, such as a systolic BP of 90 or below (high-priority FY2-or-above review)", "He is mottled, ashen or cyanosed or has a non-blanching rash — consider him higher risk than his score suggests", "There is a reduced GCS or new confusion", "He has had systemic anticancer treatment in the last 30 days or takes immunosuppressants — suspect neutropenic sepsis and give empiric IV antibiotics immediately, whatever the NEWS2, using your trust's neutropenic sepsis protocol (see BLEEP-42)", "There is no improvement within 1 hour of antibiotics and fluids, or after 1,000 ml of fluid", "The line site shows spreading erythema, pus, or fluctuance suggesting a tunnel infection or abscess"], "document": "Record the time of the temperature spike, the observations and NEWS2 score, the sepsis risk category, the line site findings and other sources examined, the sites blood cultures were taken from and in what order, the time antibiotics and fluids were given, the lactate and response to treatment, what was done with the TPN, the line plan, and the time and name of the senior contacted.", "fail": "An unsafe response takes cultures but waits for the senior before giving antibiotics to a high-risk patient, assumes the line is the source without looking for others, takes cultures only from the line, or keeps running TPN through a suspected infected line without a plan.", "pass": "A safe response grades risk with NEWS2 and lactate, takes peripheral cultures first (and a labelled line set if taken), gives IV antibiotics and a fluid bolus within 1 hour when high risk, examines the line and other sources, recalculates NEWS2 every 30 minutes while high risk, and escalates promptly.", "high_performance": "An excellent response also plans alternative access and nutrition with the senior and nutrition team, involves microbiology about likely organisms, and reviews whether the line was still needed and whether line care bundles were followed.", "one_thing": "If you only remember one thing: a lactate over 2 with NEWS2 5–6 makes this high-risk sepsis — peripheral cultures first, then IV antibiotics within the hour; the line decision can follow, the antibiotics can't wait.", "img_note": "In UK hospitals, central lines and PICCs are managed with a care bundle — daily checks of the site and of whether the line is still needed — and line-related bloodstream infections are reviewed by the infection prevention and control team. TPN is usually overseen by a nutrition support team, who should be involved in any decision to stop TPN for longer or remove the line.", "source": "NICE, Suspected sepsis in people aged 16 or over (NG253), last updated Sep 2026; UKHSA UK SMI S 12, Sepsis and systemic or disseminated infections, issue 1.1, Apr 2025 (peripheral culture first when a line set is taken); UK SMI B 20, Investigation of intravascular cannulae, issue 6.2, Oct 2025 (exit-site swab; staphylococci are the commonest line organisms); NICE CG151, Neutropenic sepsis, 2012; epic3 (central venous catheters), 2014. Line removal as a senior decision and pausing TPN are standard practice, not guideline rules.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 9 calling about Mr Hughes — he has high-risk sepsis, likely from his tunnelled central line.", "B": "He has the line for TPN and has been in hospital for three weeks. He hasn't had chemotherapy or immunosuppressants.", "A": "Temperature 38.8, BP 105 over 65, heart rate 110, respiratory rate 22, saturations 95% on air, alert, NEWS2 6, lactate 2.4, and the line site is red and tender, with no other obvious source on examination. I've taken blood cultures peripherally and from the line, given IV antibiotics per our line-infection guideline within the hour, started a 250 ml fluid bolus, and paused the TPN.", "R": "Please come and review him, and can we decide together whether the line needs to come out and how we feed him in the meantime?"}, "checked": "Oct 2026"}, {"id": "BLEEP-42", "title": "Neutropenic sepsis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mrs Patel's temperature is 38.2 and she had chemotherapy ten days ago, her oncologist said to call if she spiked.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score"}, {"lead": "Anticancer treatment", "text": "Ask what anticancer treatment the patient has had and when — anyone unwell within 30 days of systemic anticancer treatment should be suspected of neutropenic sepsis"}, {"lead": "IV access, allergy, antibiotics", "text": "Ask the nurse to get IV access, take blood cultures, check for a penicillin allergy and get piperacillin with tazobactam ready — antibiotics are given immediately, before the neutrophil count is back"}, {"lead": "Neutrophil count", "text": "Ask for the most recent neutrophil count and send an urgent FBC — but never wait for it before treating"}, {"lead": "Symptom source", "text": "Ask whether there are any localising symptoms — mouth ulcers, sore throat, cough, urinary symptoms, perianal pain, or line site concerns"}], "first_five_minutes": [{"lead": "ABCDE, NEWS2, oxygen", "text": "Assess airway, breathing, circulation, disability and exposure — and use NEWS2 to guide urgency and fluids (NICE NG253). If critically ill or shocked, start oxygen by reservoir mask at 15 L/min; otherwise give oxygen if needed to a target of 94 to 98% (88 to 92% if at risk of hypercapnic respiratory failure)"}, {"lead": "Treat as an emergency", "text": "Suspected neutropenic sepsis is an acute medical emergency: offer empiric IV antibiotics immediately (NICE CG151), whatever the NEWS2 score — the general sepsis option to defer antibiotics at low or medium risk does not apply. Do not wait for the neutrophil count or other results"}, {"lead": "Piperacillin with tazobactam", "text": "Give piperacillin with tazobactam on its own — dose and penicillin-allergy alternative per BNF/local protocol. No aminoglycoside (alone or dual) and no empiric glycopeptide for a central line unless specifically indicated"}, {"lead": "Cultures and bloods", "text": "Take blood cultures (peripheral and from any central line) before the first dose, but never delay the antibiotics to do so. Send FBC, U&E, LFTs including albumin, CRP and lactate"}, {"lead": "Fluids if high risk", "text": "If NEWS2 is 7 or more, or 5 to 6 with a lactate over 2 mmol/litre or an AKI, give 250 ml isotonic crystalloid boluses within 1 hour, reassessing after each, up to 1,000 ml; get senior advice if not improving"}, {"lead": "Look for a source", "text": "Examine specifically for a source: mouth, throat, chest, abdomen, perianal area (no rectal examination), line sites, and skin breaks"}, {"lead": "Know the definition", "text": "Neutropenic sepsis is confirmed when the neutrophil count is 0.5 × 10⁹/L or lower with a temperature above 38°C or other signs of clinically significant sepsis — but treatment starts on suspicion, and people having cancer treatment may not develop a fever"}, {"lead": "Inform oncology", "text": "Tell the acute oncology or haematology team, follow your trust's protocol on isolation, and escalate urgently if there is hypotension, a rising lactate, or no response"}], "can_i_do_alone": {"alone": "Taking blood cultures and bloods, prescribing and giving piperacillin with tazobactam immediately per CG151 and the trust neutropenic sepsis protocol, examining for a source, giving 250 ml crystalloid boluses if she is high risk or shocked, reassessing after each, and informing the acute oncology team — you do not need senior approval to give the first dose", "senior_opinion": "In a penicillin allergy or known resistant organism, give the trust's neutropenic sepsis alternative immediately and then discuss with a senior or microbiology. Also ask a senior if you are unsure whether this is neutropenic sepsis rather than another cause of fever. Patients on immunosuppressant treatment for reasons other than cancer who become unwell: suspect neutropenic sepsis and treat it the same way without delay; then discuss with a senior whether any past treatment is still likely to cause neutropenia.", "senior_in_person": "Any patient with hypotension, a lactate over 2 mmol/litre, a reduced GCS, or a high-risk NEWS2 — this needs senior and possibly critical care support now, as neutropenic sepsis can progress to septic shock rapidly"}, "escalate_now_if": ["The patient is hypotensive or the lactate is over 2 mmol/litre — signs of hypoperfusion or septic shock", "There is a reduced GCS or new confusion", "The NEWS2 is 5 or more, or any single parameter scores 3", "The patient is mottled or ashen, cyanosed or has a non-blanching rash — consider higher risk than NEWS2 suggests", "The patient is not responding to initial antibiotics and fluids", "There is a source that needs urgent control (such as an abscess or line infection)"], "document": "Record the time of the temperature spike, the date and type of the last anticancer treatment, the most recent neutrophil count, allergy status, the observations and NEWS2 score, the cultures taken, the time of recognition and the time the first antibiotic dose was given, and the name of the senior and oncology team member contacted.", "fail": "An unsafe response waits for the neutrophil count or a senior before starting antibiotics, uses an aminoglycoside as initial therapy without a specific reason, or is falsely reassured by a NEWS2 of 4.", "pass": "A safe response recognises the risk from the anticancer treatment history, gives piperacillin with tazobactam immediately, takes cultures and bloods alongside, looks for a source, and informs the oncology team and senior.", "high_performance": "An excellent response also checks for fluoroquinolone prophylaxis, considers the line as a source without removing it as part of initial management, and makes sure oncology reviews the chemotherapy plan.", "one_thing": "If you only remember one thing: unwell within 30 days of systemic anticancer treatment means suspected neutropenic sepsis, fever or not — give piperacillin with tazobactam immediately, before the neutrophil count is back.", "img_note": "In UK practice, patients on chemotherapy are given a 24-hour acute oncology advice number, and most trusts have an acute oncology service you can contact. Many trusts audit 'door-to-needle' time, so record when you recognised it and when the first dose went in.", "source": "NICE, Neutropenic sepsis: prevention and management in people with cancer (CG151), published Sep 2012, minor updates Jan 2020 and Sep 2024, last reviewed Jan 2020; NICE, Suspected sepsis in people aged 16 or over (NG253), last updated Sep 2026; BTS guideline for oxygen use in adults (2017); RCP NEWS2 (2017). No rectal examination and isolation are standard practice, not NICE recommendations.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 7 calling about Mrs Patel — I'm treating her as suspected neutropenic sepsis: temperature 38.2, ten days after chemotherapy.", "B": "She has breast cancer on adjuvant chemotherapy; her neutrophil count was 1.2 five days ago.", "A": "NEWS2 is 4: respiratory rate 18, saturations 95% on air, BP 110 over 70, heart rate 95, temperature 38.2, and she's alert. She has mouth ulcers. No known drug allergies. I've taken blood cultures and bloods including FBC and lactate, and she had her first dose of piperacillin with tazobactam within 20 minutes of my review. I've informed the acute oncology team.", "R": "Could you review her as soon as you can? Please let me know if you want anything different once the neutrophil count and cultures are back. I'll call you straight away if her NEWS2 rises or her BP drops."}, "checked": "Oct 2026"}, {"id": "BLEEP-43", "title": "Needlestick / sharps injury", "fpc_tags": ["Clinical assessment", "Quality improvement", "Upholding values"], "scenario": "Nurse bleeps: \"I've just had a needlestick injury while taking blood from a patient, what should I do?\"", "nurse_call": [{"lead": "First aid now", "text": "Tell them to let the wound bleed gently under running water, wash it with plenty of soap and water, dry it and cover it with a waterproof plaster — and not to squeeze, scrub or suck it"}, {"lead": "Get advice now", "text": "Tell them to seek urgent advice now — occupational health in hours, the emergency department out of hours — because HIV and hepatitis B prophylaxis are time-critical"}, {"lead": "Source patient status", "text": "Ask who the source patient is and whether their HIV, hepatitis B and hepatitis C status is known, including any HIV viral load"}, {"lead": "Their own hepatitis B status", "text": "Ask whether they have had the hepatitis B vaccine course and whether they are a known responder or non-responder"}, {"lead": "Report the injury", "text": "Tell them to report the injury to their manager and complete an incident report — this is required and is how occupational health follow-up is triggered"}], "first_five_minutes": [{"lead": "Confirm first aid done", "text": "Confirm the first aid has been done correctly — allowed to bleed gently under running water without squeezing, washed with soap and water, covered with a waterproof dressing"}, {"lead": "Assess the risk", "text": "Assess the risk: percutaneous injury with a hollow-bore needle, a deep injury, or visible blood on the device are higher risk; exposure to blood is higher risk than other body fluids"}, {"lead": "Source patient testing", "text": "If the source's status is unknown, the source patient should be asked for consent to testing by a clinician other than the injured person, following your trust's sharps injury protocol. Don't hold up PEP for the results. If the source lacks capacity and isn't likely to regain it soon, testing needs a best-interests decision by their treating team"}, {"lead": "HIV PEP", "text": "If HIV PEP is indicated it should start as soon as possible, preferably within 24 hours and not beyond 72 hours. Occupational health or the ED decide whether it is needed"}, {"lead": "Hepatitis B prophylaxis", "text": "Depends on the injured person's vaccine status and the source — occupational health or the ED decide what is needed. HBIG is given ideally within 24 hours and not after 7 days. Don't delay the vaccine while awaiting test results"}, {"lead": "Hepatitis C", "text": "UK guidance offers no prophylaxis for hepatitis C. Occupational health arranges baseline and follow-up testing, with early referral for treatment if infected"}, {"lead": "Occupational health follow-up", "text": "Make sure occupational health is contacted urgently and will follow up (testing and counselling), and that the incident report is completed"}], "can_i_do_alone": {"alone": "Confirming first aid, assessing the risk, directing the person to occupational health or the emergency department out of hours, asking the source patient's team to seek consent for testing, and making sure the incident is reported", "senior_opinion": "Any uncertainty about whether HIV PEP or HBIG is needed, any difficulty getting occupational health or ED advice out of hours, or a source patient who lacks capacity to consent to testing — escalate to the on-call senior or site manager", "senior_in_person": "This is not usually a bedside emergency, but if the source is known HIV positive and not suppressed, get the injured person seen in the ED immediately rather than waiting for occupational health the next day"}, "escalate_now_if": ["The source is known to be HIV positive and hasn't been on treatment for at least 6 months with an undetectable viral load in the last 6 months, or the viral load or adherence is uncertain — PEP should start as soon as possible", "The source is HBsAg positive and the injured person is unvaccinated or a known non-responder, or the source is untested and the injured person is a known non-responder — HBIG is needed, ideally within 24 hours", "The source is untested but from a higher-risk group (for example, someone who injects drugs) and the injury was deep, from a needle in a vein or with visible blood on the device — this can change the PEP decision", "Occupational health is closed — send the person to the emergency department now rather than waiting", "There is a system failure (such as an overfilled sharps bin or a needle left in a bed) that puts others at risk"], "document": "Record (in the incident report and as your trust requires) the time and nature of the injury, the device, whether there was visible blood, the source patient's known status, the first aid done, and the time occupational health or the ED was contacted. Clinical details of the injured person belong in their own occupational health record, not the source patient's notes.", "fail": "An unsafe response delays seeking advice until the next working day when the source is high risk, holds up PEP for the source's results, fails to report the injury, or gets the first aid wrong (squeezing, scrubbing or sucking the wound).", "pass": "A safe response confirms the correct first aid, assesses the risk, gets the person to occupational health or ED promptly so HIV PEP and hepatitis B prophylaxis can be decided in time, and makes sure the incident is reported.", "high_performance": "An excellent response also arranges source testing correctly, looks for the system failure behind the injury and, because the source is known to have a blood-borne virus, makes sure the employer considers a RIDDOR report, and makes sure the colleague is supported — a sharps injury is frightening even when the risk is low.", "one_thing": "If you only remember one thing: let it bleed under running water without squeezing, wash it, cover it — then get advice the same day (ED out of hours), because HIV PEP should start as soon as possible, preferably within 24 hours, and not after 72.", "img_note": "In Great Britain, sharps injuries are covered by the Health and Safety (Sharp Instruments in Healthcare) Regulations 2013; employers must investigate and record them. Out of hours, the emergency department usually provides the first assessment and starter PEP packs, and occupational health follows up.", "source": "HSE, Needlestick or sharps injuries in health and social care: overview, updated 8 Sep 2026; UKHSA, Immunisation against infectious disease (Green Book), chapter 18: hepatitis B, last updated Feb 2026; BHIVA/BASHH, UK guideline for the use of HIV post-exposure prophylaxis, 2021 (2023 amendment); PHLS guidance on occupational exposure to hepatitis C (CDPH 1999); Sharp Instruments in Healthcare Regulations 2013", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm the F1 on ward 3 — a staff nurse has just had a needlestick injury from a hollow-bore needle with visible blood while taking blood, and I'm calling for urgent occupational health advice.", "B": "The source patient is known to be hepatitis C positive; their HIV and hepatitis B status are unknown. The nurse has completed the hepatitis B vaccine course and was a documented responder.", "A": "First aid has been done correctly. I've asked the patient's team to approach the patient for consent for HIV and hepatitis B testing, and the incident report is being completed.", "R": "Can you see her today to decide on PEP and arrange hepatitis C follow-up testing — or, if you can't, should I send her to the emergency department now?"}, "checked": "4 Oct 2026"}, {"id": "BLEEP-44", "title": "Infection after joint replacement", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Reid had his knee replaced two weeks ago. His leg has gone red and swollen around the wound, it's spreading and it feels hot.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score — systemic upset turns a wound review into possible sepsis"}, {"lead": "Draw around the edge", "text": "Ask the nurse to consider drawing around the extent of the redness with a skin marker to monitor progress — but be aware that redness may be less visible on darker skin tones"}, {"lead": "Wound and joint", "text": "Ask whether the wound is intact, oozing, discharging or gaping, and whether the knee itself is more painful, swollen or stiff — think about infection of the new joint, not just the skin"}, {"lead": "Pain out of proportion?", "text": "Ask about pain — pain out of proportion to the visible redness is a red flag for necrotising fasciitis"}, {"lead": "Calf and whole leg", "text": "Ask whether the calf or whole leg is swollen and whether he is on VTE prophylaxis — a red, swollen leg two weeks after a knee replacement may be a DVT"}], "first_five_minutes": [{"lead": "ABCDE and NEWS2", "text": "Assess airway, breathing, circulation, disability and exposure. If he has suspected infection with NEWS2 7 or more, or NEWS2 5–6 with a single parameter scoring 3 caused by the infection (or NEWS2 5–6 with lactate over 2 mmol/L or AKI), treat as high-risk sepsis: blood cultures, then IV antibiotics within 1 hour per your trust guideline after checking allergies, and a 250 ml crystalloid bolus unless contraindicated, repeated if needed up to 1,000 ml and reassessing after each — do not wait for orthopaedic sampling"}, {"lead": "Examine wound, joint and skin", "text": "Take the dressing down aseptically and look at the wound (dehiscence, discharge, fluctuance), the knee (effusion, warmth, pain on movement) and the surrounding skin (spreading erythema, dusky skin, blistering, crepitus), and check for other sources of infection"}, {"lead": "Think surgical site infection", "text": "Spreading redness around a recent joint replacement may be a surgical site infection or a prosthetic joint infection — do not treat it as simple cellulitis"}, {"lead": "Consider DVT", "text": "Examine the calf and calculate a two-level DVT Wells score. If DVT is likely, request a proximal leg vein ultrasound, ideally with the result within 4 hours; if that is not possible, discuss interim anticoagulation with a senior because of the recent surgery, and request the scan with the result within 24 hours"}, {"lead": "Inform orthopaedics now", "text": "Tell the on-call orthopaedic team this shift. If he is at low risk (NEWS2 below 5 with no other concern), do not start antibiotics yourself. Orthopaedics take the deep samples (joint aspiration or samples in theatre) before antibiotics — do not aspirate the joint yourself; a swab of wound discharge is not a deep sample. If NEWS2 is 5–6, get an FY2-or-above review within 1 hour and agree the antibiotic plan with orthopaedics — antibiotics can be deferred for at most 3 hours from the first NEWS2, so if deep samples cannot be taken by then, escalate to your registrar"}, {"lead": "Bloods and swab", "text": "Send FBC, CRP and U&E and swab any discharge; if NEWS2 is 5 or more, also send blood cultures, a venous gas with glucose and lactate, LFTs and a clotting screen. Ask the orthopaedic team about a plain X-ray — normal inflammatory markers do not exclude joint infection"}, {"lead": "Escalate if severe", "text": "Escalate urgently for systemic upset, rising NEWS2, pain out of proportion, crepitus, blistering or rapid spread — necrotising fasciitis and an infected joint replacement can both need emergency surgery"}], "can_i_do_alone": {"alone": "Assessing him, marking the redness, examining the wound, knee and calf, sending FBC, CRP, U&E and a swab of any discharge, calculating a DVT Wells score and requesting an ultrasound, informing orthopaedics — and, if he meets high-risk sepsis criteria, taking blood cultures, giving IV antibiotics within 1 hour and starting a fluid bolus", "senior_opinion": "Whether to start antibiotics in a patient who is not septic (the orthopaedic team decides, usually after deep samples), interim anticoagulation for a suspected DVT so soon after surgery, and any uncertainty about whether this is a deeper infection", "senior_in_person": "Any patient with sepsis, systemic upset, severe pain out of proportion, crepitus, blistering or rapid progression — this needs urgent senior and orthopaedic review, as necrotising fasciitis or an infected joint replacement may need emergency surgery"}, "escalate_now_if": ["NEWS2 is 5–6 or any single parameter scores 3 (urgent response), or NEWS2 is 7 or more (emergency response)", "He looks mottled or ashen, is cyanosed, has a non-blanching rash or is deteriorating — consider him higher risk than his NEWS2 suggests", "There is severe pain out of proportion to the visible redness", "There is crepitus, dusky skin or blistering suggesting necrotising fasciitis", "Redness or swelling spreads beyond the marked line (allowing for some initial spread), or symptoms worsen rapidly or significantly", "There is pus, wound breakdown, or a hot, swollen, painful knee suggesting infection of the joint replacement", "The calf is swollen and tender, or he becomes breathless or hypoxic (possible DVT or PE)"], "document": "Record the time the redness was noted, the observations and NEWS2 score, the extent of the erythema (with the marked line), wound, knee and calf findings, the Wells score, bloods and swabs sent, whether antibiotics were given or deliberately held and why, the date of the operation and any wound problems since, and the time the orthopaedic team was informed and their plan.", "fail": "An unsafe response treats redness around a recent joint replacement as simple cellulitis and starts antibiotics without involving orthopaedics, misses a DVT, misses necrotising fasciitis in a patient with severe pain, or delays IV antibiotics in a patient who meets high-risk sepsis criteria.", "pass": "A safe response assesses him with NEWS2, marks and examines the wound, knee and calf, sends bloods, informs the orthopaedic team the same shift, holds antibiotics in a well patient until orthopaedics have decided on sampling, and gives IV antibiotics within 1 hour if he is septic.", "high_performance": "An excellent response also formally considers DVT with a Wells score, checks his diabetes control and VTE prophylaxis, records the timing of surgery and any wound problems since, and explains to the patient why antibiotics are being held while the joint is assessed.", "one_thing": "If you only remember one thing: redness around a new joint replacement is a surgical problem — tell orthopaedics, don't start antibiotics in a well patient before deep samples, but never delay antibiotics if he is septic.", "img_note": "In UK hospitals the operating team keeps responsibility for post-operative complications, even when the patient is under your care overnight — so a problem with a joint replacement wound goes to the on-call orthopaedic registrar, not just the medical team. The British Orthopaedic Association publishes national standards (BOASTs) that set out what the orthopaedic team should do next.", "source": "BOA, BOASt: Acute management of peri-prosthetic joint infection, last updated Apr 2024; NICE, Surgical site infections (NG125), last updated Aug 2020; NICE, Cellulitis (NG141), Sep 2019; NICE, VTE diseases (NG158), last updated Aug 2023; NICE, Suspected sepsis (NG253), last updated Sep 2026; RCP, NEWS2, 2017", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Reid on ward 4, two weeks after a knee replacement — the skin around his wound is red, hot and spreading.", "B": "He has type 2 diabetes and venous insufficiency and is on VTE prophylaxis.", "A": "Resps 16, sats 95% on air, BP 132/78, pulse 102, alert, temperature 37.8 — NEWS2 2, so he's low risk on the NICE sepsis criteria. The redness extends 5 centimetres beyond the wound edge and I've marked it; the wound is intact with no discharge, the knee isn't more swollen, the pain is in proportion and his calf is soft and non-tender. I've sent FBC, CRP and U&E and I haven't started antibiotics.", "R": "Could you review him in the next few hours, well within 6 hours of this first NEWS2, and decide whether he needs aspiration or other samples before antibiotics? I've asked for 4-hourly obs and I'll call you straight back if the redness spreads past the line or his NEWS2 rises."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-45", "title": "Catheter-associated UTI", "fpc_tags": ["Clinical assessment", "Clinical prioritisation"], "scenario": "Nurse bleeps: \"Mrs Foster has a long-term catheter and she's become confused and feverish, her urine looks cloudy.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for a full set of observations and the NEWS2 score now — new confusion scores 3 on its own, so with a fever this may already be high-risk sepsis"}, {"lead": "Sepsis kit to bedside", "text": "Ask the nurse to get blood culture bottles, a blood gas syringe and IV access equipment ready for when you arrive"}, {"lead": "Is the catheter draining?", "text": "Ask whether the catheter is draining — a blocked catheter needs changing, but it does not explain away a fever and new confusion"}, {"lead": "Catheter age", "text": "Ask when this catheter was inserted or last changed — if it has been in for more than 7 days, consider removing it or, if that cannot be done, changing it as soon as possible, without delaying antibiotics"}, {"lead": "Previous cultures", "text": "Ask whether there have been previous urine cultures and what organisms were grown — this guides antibiotic choice"}], "first_five_minutes": [{"lead": "ABCDE and NEWS2", "text": "Assess airway, breathing, circulation, disability and exposure, and check her usual mental state with staff or family. Temperature 38.4 and pulse 98 score 1 each and new confusion 3: NEWS2 5 with a single parameter of 3. If the confusion is caused by the infection, NICE says manage as high risk; if something else, as medium risk"}, {"lead": "Sepsis bundle within 1 hour", "text": "Before antibiotics, take blood cultures, a catheter urine sample, a venous blood gas with lactate and glucose, FBC, U&E, creatinine, CRP, LFTs and clotting. Then give IV antibiotics per your trust's empirical guideline within 1 hour, and an IV fluid bolus within 1 hour unless contraindicated (250 mL crystalloid over 10–15 minutes, reassess and repeat as needed up to 1 litre in total)"}, {"lead": "Remove or change, don't delay", "text": "If the catheter has been in for more than 7 days, consider removing it or, if that cannot be done, changing it as soon as possible — but do not let this delay antibiotics. Sample the new catheter's sampling port with aseptic technique, or send a midstream sample if it is removed. If it cannot be changed before the antibiotic is due, sample the existing catheter's port first, then change it. Note the antibiotic time on the request"}, {"lead": "Culture, not dipstick", "text": "Send urine for culture and susceptibility, noting the catheter and any antibiotic given. Do not dipstick catheter urine — bacteria are almost always present, so it does not diagnose infection"}, {"lead": "Look for other sources", "text": "Examine the chest, skin, wounds and lines, and check previous cultures for resistant organisms — fever and confusion in a catheterised patient are not automatically a urinary source"}, {"lead": "Senior review now", "text": "NICE asks for a clinician at FY2 level or above to assess high-risk patients urgently, and referral to a senior clinical decision maker (ST3 or above) as soon as possible — call your registrar while you start treatment, not instead of starting it"}, {"lead": "Reassess within 1 hour", "text": "Recalculate NEWS2 after each intervention and at least every 30 minutes while she is high risk. If she has not responded within 1 hour of any intervention, the senior clinical decision maker must attend in person, critical care should be involved and the consultant informed"}], "can_i_do_alone": {"alone": "Assessing her, recognising high-risk sepsis, taking blood cultures, bloods and a catheter urine sample before antibiotics, giving IV antibiotics per the trust guideline and an IV fluid bolus within 1 hour, and, if you are trained and competent (per local policy), changing a catheter that has been in for more than 7 days", "senior_opinion": "Antibiotic choice if she has previous resistant organisms or allergies, uncertainty about the source, and whether the catheter can be removed altogether", "senior_in_person": "Every high-risk patient needs urgent review by a clinician at FY2 level or above, and the senior clinical decision maker (ST3 or above) in person if she has not responded within 1 hour, or has hypotension, a raised lactate or a falling GCS — critical care may be needed"}, "escalate_now_if": ["NEWS2 is 5–6 or any single parameter scores 3 (urgent response), or NEWS2 is 7 or more (emergency response)", "There is hypotension, a lactate over 2 mmol/L, or acute kidney injury", "Her consciousness level is falling", "Mottled or ashen skin, cyanosis or a non-blanching rash (consider her risk higher than NEWS2 suggests)", "She has not responded within 1 hour of any intervention", "The catheter cannot be changed or a new one cannot be passed"], "document": "Record the time the fever and confusion were noted, her usual mental state, the observations and NEWS2 score, the sepsis risk level, the time of blood cultures, antibiotics and fluids, the catheter's age and whether it was changed, the urine sample source and time, other sources examined, and the time the senior was contacted and their plan.", "fail": "An unsafe response treats fever with new confusion as 'just cloudy urine', delays IV antibiotics beyond 1 hour in a high-risk patient, samples urine after antibiotics, waits for a catheter change before giving antibiotics, or relies on a urine dipstick.", "pass": "A safe response recognises high-risk sepsis, samples blood and catheter urine before antibiotics, gives the sepsis bundle within 1 hour, considers removing or changing a catheter in for more than 7 days, looks for other sources, and gets an urgent FY2-or-above review.", "high_performance": "An excellent response also reviews whether the catheter is still needed, chooses antibiotics using previous culture results, and reviews the antibiotic when sensitivities return. Cloudy urine without systemic signs is not, on its own, a reason for antibiotics in a long-term catheter.", "one_thing": "If you only remember one thing: fever plus new confusion in a catheterised patient is possible sepsis, not just a UTI — look for every source, sample before antibiotics, give antibiotics within 1 hour if she is high risk, and never let a catheter change delay them.", "img_note": "UK hospitals use a sepsis screening tool built around NEWS2, often in the electronic observations system, and an empirical antibiotic guideline (often on a trust app) that F1s are expected to prescribe from without waiting for microbiology. NICE's quality standard says not to use urine dipsticks to diagnose UTI in adults with catheters, so many wards no longer dipstick catheter urine.", "source": "NICE, Suspected sepsis in people aged 16 or over (NG253), last updated 23 Sep 2026 (1.4.6, 1.6.2, 1.6.3, 1.6.5, 1.8.1–1.8.9, 1.8.15, 1.8.17, 1.8.18, 1.8.20); NICE, Urinary tract infection (catheter-associated): antimicrobial prescribing (NG113), Nov 2018, last reviewed Apr 2019 (1.1.1, 1.1.3–1.1.5); NICE, Urinary tract infections in adults (QS90), last updated Feb 2023 (statement 2); RCP, NEWS2 (2017). Escalating a catheter that cannot be changed, and senior attendance for hypotension or a falling GCS, are standard practice rather than guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Foster on ward 6, who has a long-term catheter and a fever with new confusion — I'm treating her as high-risk sepsis.", "B": "This catheter has been in for two weeks; she has no other source I can find on examination.", "A": "Temperature 38.4, pulse 98, BP 128/76, resps 18, sats 96% on air, NEWS2 5 with 3 points for new confusion, and the catheter is draining cloudy urine. In the last hour I've taken blood cultures, bloods including lactate and a urine sample, given IV antibiotics per our guideline and started a fluid bolus, and changed the catheter.", "R": "I need you to review her within the hour, look at the lactate with me, and help decide on escalation if she isn't responding."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-46", "title": "Acute agitation and behavioural disturbance", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Ethics and law"], "scenario": "Nurse bleeps: \"Mr Dawson's become really agitated and is shouting at staff, he's pulled his cannula out and he's trying to get out of bed.\"", "nurse_call": [{"lead": "Is anyone at risk?", "text": "Ask whether the patient is at immediate risk of harming himself or others, and ask the nurse to keep the area safe, calling for help under trust policy if needed"}, {"lead": "Physical cause?", "text": "Ask for a full set of observations with a NEWS2 score and a bedside glucose — agitation is often the first sign of hypoxia, hypoglycaemia, sepsis, or another physical cause"}, {"lead": "Baseline and change", "text": "Ask what his baseline cognitive state is and when the change started; if no one knows, treat it as new"}, {"lead": "Triggers and pain", "text": "Ask about obvious triggers: pain, urinary retention, constipation, a new medication, or alcohol withdrawal"}, {"lead": "De-escalation first", "text": "Ask the nurse to try calm verbal de-escalation and to avoid physical restraint unless there is an immediate safety risk"}], "first_five_minutes": [{"lead": "Look for a physical cause", "text": "Check glucose, saturations and a full set of observations now — agitation in a medical inpatient is often delirium from a physical cause rather than a primary psychiatric disorder"}, {"lead": "New agitation scores 3", "text": "New confusion, disorientation or agitation scores 3 on NEWS2 by itself: a single red score needing urgent review and at least hourly observations. With his infection, request a high-priority review by an FY2 or above now to decide his sepsis risk, and do not wait for it: with a NEWS2 of 5 or more he is at least medium risk, so take bloods now, including blood cultures and a venous gas with lactate. If the new confusion is likely to be from the infection, he is managed as high risk — follow the high-risk sepsis steps (see BLEEP-03); as he is already on IV antibiotics, the reviewer must decide within 1 hour whether they need changing"}, {"lead": "Assess for pain and retention", "text": "Examine for pain, urinary retention (bladder scan), constipation, and any other source of distress driving the behaviour"}, {"lead": "Review the drug chart", "text": "Review the drug chart for new or recently changed medications that could cause agitation, such as opioids, steroids or anticholinergics"}, {"lead": "Use non-drug measures first", "text": "Try verbal de-escalation, reorientation, a calm environment, reducing stimulation, and involving family or carers — these come before any medication"}, {"lead": "Consider the cause", "text": "Work through the likely causes: infection or metabolic disturbance, pain, urinary retention, alcohol or drug withdrawal, a reaction to medication, or a primary psychiatric disorder. Screen for delirium with the 4AT if competent to do so"}, {"lead": "Medication only if needed", "text": "If de-escalation has failed and there is genuine distress or risk, discuss medication with a senior. Your senior decides whether haloperidol is appropriate. It is contraindicated in Parkinson's disease, dementia with Lewy bodies or known QTc prolongation, and with other QTc-prolonging drugs; a baseline ECG is recommended first. Other antipsychotics can cause severe sensitivity reactions in Lewy body or Parkinson's disease dementia"}, {"lead": "Restraint must be proportionate", "text": "Assume capacity unless assessed otherwise: if he has capacity for the decision, he cannot be held under the Mental Capacity Act to make him accept care, even if the decision seems unwise; if he is an immediate risk to others, follow trust policy and get senior and security help. If he lacks capacity, the Mental Capacity Act allows holding or restricting him only when necessary to prevent harm to him and proportionate to its likelihood and seriousness — use the least restrictive option and record your reasoning"}, {"lead": "Document and debrief", "text": "Document the incident clearly, and arrange a post-incident debrief for the staff involved after any restrictive intervention"}], "can_i_do_alone": {"alone": "Checking glucose and observations with NEWS2, examining for a physical cause, reviewing the drug chart, assessing capacity for the specific decision, and attempting non-drug de-escalation measures", "senior_opinion": "Any patient requiring consideration of medication for agitation, any uncertainty about whether this is delirium or a primary psychiatric cause, or any patient where the cause remains unclear", "senior_in_person": "New agitation with infection (a single NEWS2 score of 3) needs a high-priority FY2-or-above review now; a senior also needs to come if the patient remains a danger to himself or others despite de-escalation, needs more than brief restraint, or is physiologically unstable"}, "escalate_now_if": ["The patient is a genuine danger to himself or others despite de-escalation", "New confusion or agitation with a suspected or known infection (a single NEWS2 score of 3), or a NEWS2 total of 5 or more", "Signs of serious underlying illness, such as hypoxia, hypoglycaemia or sepsis", "A new focal neurological deficit or falling consciousness", "Medication or physical restraint is being considered", "The agitation is preventing essential care or monitoring in a physically unwell patient"], "document": "Record the time the agitation was noted, observations with NEWS2, glucose, examination findings, medications reviewed, de-escalation tried and its effect, your capacity assessment, any restriction and why it was necessary and proportionate, any medication with the time and baseline ECG, the outcome, and the plan agreed with the senior, including any liaison psychiatry referral.", "fail": "An unsafe response sedates before excluding a reversible physical cause, gives haloperidol without checking for Parkinson's disease or Lewy body dementia, or restrains a patient who has capacity to make him accept care, or without trying de-escalation first.", "pass": "A safe response scores the new agitation on NEWS2, excludes dangerous reversible causes first, uses non-drug measures first, assesses capacity for the specific decision, and escalates when safety or diagnostic uncertainty requires senior input.", "high_performance": "An excellent response also involves family or carers to help reorient the patient, documents a clear capacity assessment and the justification for any restriction, arranges a post-incident debrief for staff, and addresses the underlying cause rather than just managing the behaviour.", "one_thing": "If you only remember one thing: new agitation in a medical inpatient counts as new confusion and scores 3 on NEWS2 — check the glucose, the observations and the drug chart, and look for a physical cause, before reaching for sedation.", "img_note": "In England and Wales, holding or restraining a confused patient who lacks capacity is lawful under section 6 of the Mental Capacity Act only if you reasonably believe it is necessary to prevent harm to him and it is proportionate. The Mental Health Act is for treating mental disorder; it is not the route for treating a physical illness causing delirium. Prolonged or repeated restriction may need a Deprivation of Liberty Safeguards authorisation — ask your senior or the trust safeguarding team.", "source": "NICE CG103 Delirium, last updated Jan 2023 (1.6.1 4AT; 1.7.3 de-escalate first; 1.7.4 consider short-term haloperidol); MHRA Drug Safety Update, Dec 2021 (haloperidol contraindications, baseline ECG); NICE NG97 Dementia, 2018, 1.7.4; NICE NG10 Violence and aggression, May 2015 (de-escalation, debrief; being updated, expected Jan 2027); RCP NEWS2, 2017 (new confusion scores 3); NICE NG253 Sepsis, updated Sep 2026, 1.6.2; Mental Capacity Act 2005, sections 1 and 6, Schedule A1. Glucose, bladder scan, focal signs and liaison psychiatry are standard practice. Doses per local protocol.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Dawson on ward 11, he's become acutely agitated and is shouting at staff and trying to get out of bed.", "B": "he was admitted with a chest infection and has been on intravenous antibiotics, he has no known psychiatric history.", "A": "his observations are temperature 37.6, pulse 92, respiratory rate 18, saturations 94% on air, BP 148/86 and new confusion, so his NEWS2 is 5 with a single score of 3; his glucose is 6.2. He's pulling at his cannula and trying to climb out of bed, and I've tried calm reorientation and reducing stimulation without success.", "R": "Please come and review him now — with his chest infection he needs an FY2-or-above decision on his sepsis risk, I think this is delirium from the infection, and I need your advice on whether any medication is appropriate."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-47", "title": "Alcohol withdrawal and delirium tremens", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Collins is shaky and sweaty, he says he usually drinks a lot and he's not had anything since he came in yesterday.\"", "nurse_call": [{"lead": "Full obs + NEWS2", "text": "Ask for the full set of observations and the NEWS2 score — autonomic instability is a key feature of severe withdrawal"}, {"lead": "Withdrawal score", "text": "Ask whether a withdrawal score (such as CIWA-Ar) has been done, and if not, request one — it supports clinical judgement"}, {"lead": "Drinking history", "text": "Ask how much the patient usually drinks, when they last drank, and whether they have had previous withdrawal seizures or delirium tremens"}, {"lead": "Thiamine", "text": "Ask whether thiamine has been given or prescribed"}, {"lead": "Seizures and confusion", "text": "Ask about any seizure activity or confusion — red flags for severe withdrawal or delirium tremens"}], "first_five_minutes": [{"lead": "Assess severity", "text": "Assess the severity of withdrawal using the trust's withdrawal score (such as CIWA-Ar) and clinical judgement — previous withdrawal seizures or delirium tremens put him at high risk"}, {"lead": "Check observations and glucose", "text": "Check observations, glucose, and electrolytes including magnesium and potassium — low potassium and low magnesium are risk factors for delirium tremens"}, {"lead": "Give thiamine", "text": "Give thiamine now, parenterally if he is malnourished or at risk of malnourishment, has decompensated liver disease or has any sign of Wernicke's encephalopathy (confusion, ataxia, eye signs); suspected Wernicke's: IV Pabrinex 2–3 pairs three times a day, each infused over 30 minutes with anaphylaxis treatment to hand; high risk without signs: prophylactic thiamine per local protocol — don't use 5% glucose as a rehydration fluid, but never delay treating hypoglycaemia"}, {"lead": "Start the trust regimen", "text": "Start benzodiazepine treatment straight away using your trust's alcohol withdrawal protocol (usually chlordiazepoxide or diazepam) — do not wait for a senior to choose the dose if he fits the protocol"}, {"lead": "Monitor frequently", "text": "Repeat the withdrawal score and observations, including respiratory rate and oxygen saturations, as often as the protocol says, watching for seizures, worsening confusion, autonomic instability and oversedation"}, {"lead": "Delirium tremens is an emergency", "text": "If delirium tremens develops (confusion, hallucinations, marked autonomic instability), it is a medical emergency: call a senior now, review his withdrawal regimen, and look for other causes such as head injury, sepsis, hypoxia or hepatic encephalopathy"}, {"lead": "Benzodiazepines first in delirium tremens", "text": "Oral lorazepam is first-line; your senior decides what to give if symptoms persist or oral medication is refused. On the ward give parenteral benzodiazepines IM, not IV. Haloperidol is a senior decision, only as an adjunct to adequate benzodiazepines; not in Parkinson's disease or dementia with Lewy bodies, and get a baseline ECG"}, {"lead": "Withdrawal seizure", "text": "For a withdrawal seizure, consider a quick-acting benzodiazepine such as lorazepam to reduce the chance of further seizures, and if a seizure lasts 5 minutes or more, get senior help now and follow the status epilepticus pathway — IV lorazepam if IV access and resuscitation facilities are immediately available (the one exception to IM-only on the ward); any further drug is a senior decision, and do not use phenytoin for alcohol withdrawal seizures, and look for another cause such as head injury or hypoglycaemia"}], "can_i_do_alone": {"alone": "Assessing him, checking observations, glucose and electrolytes, giving thiamine, starting benzodiazepine treatment as set out in the trust protocol, and monitoring the withdrawal score — do not delay treatment while waiting for a senior", "senior_opinion": "Doses outside the protocol or a patient not settling on it, decompensated liver disease, respiratory disease or frailty affecting benzodiazepine choice, and whether he needs a higher level of monitoring", "senior_in_person": "Any patient with delirium tremens (confusion, hallucinations, marked autonomic instability), a withdrawal seizure, suspected Wernicke's encephalopathy, oversedation after benzodiazepines, any decision to use haloperidol, or significant physiological instability — these need senior review now and may need critical care support"}, "escalate_now_if": ["There is a seizure", "There is confusion, hallucinations, or agitation suggesting delirium tremens", "There is marked autonomic instability (rising heart rate, very high or low blood pressure, fever), NEWS2 is 5 or more, or a single parameter scores 3", "He becomes hard to rouse, or his respiratory rate or oxygen saturations fall after benzodiazepines", "He is not settling despite treatment given as per the protocol", "There is suspected Wernicke's encephalopathy (confusion, ataxia, ophthalmoplegia)"], "document": "Record the time withdrawal was noted, the CIWA-Ar score and observations, the drinking history and last drink, thiamine given, the benzodiazepine regimen and dose, the response, and the plan agreed with the senior, including any escalation to higher-level care.", "fail": "An unsafe response fails to give thiamine, delays benzodiazepine treatment while waiting for a senior, treats a withdrawal seizure with phenytoin, gives haloperidol alone or IV benzodiazepines on a general ward other than for status epilepticus, or fails to recognise delirium tremens as a medical emergency.", "pass": "A safe response assesses severity, gives thiamine, starts benzodiazepine treatment promptly using the trust protocol, monitors frequently, and escalates if delirium tremens, a seizure or Wernicke's develops.", "high_performance": "An excellent response also considers higher-level care early, corrects electrolyte abnormalities, and refers him to alcohol services for longer-term support before discharge.", "one_thing": "If you only remember one thing: give thiamine and start the trust withdrawal regimen without delay — and treat delirium tremens and withdrawal seizures as emergencies needing lorazepam and a senior.", "img_note": "Many UK hospitals have an alcohol care team or alcohol liaison nurse who will see the patient, advise on the withdrawal regimen and arrange community follow-up — refer during the admission. Parenteral thiamine may be Pabrinex, a generic vitamin B and C injection, or thiamine alone (IM Pabrinex is discontinued); check your trust protocol for product and dose.", "source": "NICE CG100, Alcohol-use disorders: physical complications (last updated Apr 2017; an update of the withdrawal and thiamine sections was agreed in 2019 and has not been published). DHSC UK clinical guidelines for alcohol treatment (Nov 2025, updated Apr 2026), chapters 10 and 16: delirium tremens risk factors and other causes, haloperidol only as an adjunct, no IV benzodiazepines outside ED resus or high dependency, no 5% glucose for rehydration, alcohol care teams. NHS SPS thiamine guidance (Sep 2025). BNF, Vitamin B substances with ascorbic acid (Pabrinex) (accessed Oct 2026). Haldol SmPC (2023). RCP NEWS2 (2017). NICE NG217 (status epilepticus). Checking glucose is standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Collins on ward 6, he's shaky and sweaty and hasn't had alcohol since admission yesterday.", "B": "he usually drinks heavily and has had a previous withdrawal seizure, his CIWA-Ar score is 18.", "A": "his heart rate is 110, BP is 150 over 90, he's tremulous and anxious but not confused, I've given thiamine and started the symptom-triggered chlordiazepoxide regimen as per our protocol.", "R": "I'd like you to review him — I'm concerned about the severity of his withdrawal and I want your advice on whether he needs higher-level monitoring."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-48", "title": "Opioid toxicity / overdose", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Ellis is barely rousable, his respiratory rate is 8 and his pupils are pinpoint, I think he's had too much of his morphine.\"", "nurse_call": [{"lead": "Airway and breathing", "text": "Ask the nurse to check the airway and breathing now, give oxygen aiming for saturations of 88–92%, and support ventilation with a bag-mask and oxygen if he is not breathing adequately"}, {"lead": "Unresponsive, not breathing normally: 2222", "text": "If he becomes unresponsive and is not breathing normally, or has no signs of life, tell the nurse to call 2222 and start CPR"}, {"lead": "Recent opioids", "text": "Ask what opioid he has had, when and by what route, and whether he is opioid dependent"}, {"lead": "Stop the opioid source", "text": "Ask the nurse to stop any PCA, opioid infusion or syringe driver, remove any fentanyl or buprenorphine patch, and bring naloxone to the bedside"}, {"lead": "Other causes, glucose", "text": "Ask whether there are any other possible causes of reduced consciousness — head injury, stroke, hypoglycaemia, or other sedative medication — and for a capillary blood glucose"}], "first_five_minutes": [{"lead": "ABCDE, support ventilation", "text": "Assess ABCDE. If he is unresponsive and not breathing normally, call 2222 and start CPR, unless you are trained and sure he has a pulse: then it is a respiratory arrest, so bag-mask ventilate with high-concentration oxygen and give naloxone. If breathing is inadequate, open the airway and bag-mask ventilate"}, {"lead": "Controlled oxygen, then a gas", "text": "While he breathes for himself, aim for 88–92% (for example a 24% Venturi mask at 2–3 L/min) and take a blood gas for CO2. Oxygen does not treat slow breathing, so watch the respiratory rate, not just the saturations"}, {"lead": "Remove the source", "text": "Stop any PCA, infusion or syringe driver and remove any opioid patch — otherwise the opioid keeps going in after the naloxone"}, {"lead": "Give small naloxone doses", "text": "Respiratory rate 8 or less with him barely rousable is respiratory depression; drowsiness with adequate breathing alone is not an indication. Use the low-dose IV regimen: naloxone 100–200 micrograms IV, then 100 micrograms for up to 2 doses at 1-minute intervals if there is no response to the previous dose, continuing to titrate to breathing up to a maximum of 2 mg (BNF; check local protocol). On regular morphine, a large bolus risks severe pain, acute withdrawal and cardiac complications. IM only if there is no IV access (dose per BNF/trust protocol). In respiratory or cardiac arrest, give it as soon as possible per local protocol, regular opioids or not"}, {"lead": "Titrate to breathing", "text": "The target is a respiratory rate over 10 and protective airway reflexes, not full consciousness"}, {"lead": "Expect it to wear off", "text": "Naloxone can wear off before the opioid, so respiratory depression can return — especially with modified-release opioids, patches or poor renal function. Buprenorphine may be only partly reversed, so support ventilation and get senior help early"}, {"lead": "Repeat doses or infusion", "text": "If repeated boluses are needed to keep him breathing, get a senior to review him now for a naloxone infusion"}, {"lead": "Review the drug chart", "text": "Review the chart for the opioid, dose and timing, renal function and other sedatives, and complete an incident report if prescribing or administration contributed"}], "can_i_do_alone": {"alone": "Calling 2222 and starting CPR if he arrests, supporting the airway and ventilation, controlled oxygen and a blood gas, stopping or removing the opioid source, giving titrated IV naloxone, and monitoring closely", "senior_opinion": "A patient who has responded to naloxone and is breathing adequately — to agree whether he needs an infusion, the monitoring plan, any uncertainty about the cause, and how to restart pain relief safely", "senior_in_person": "Any patient who is not breathing adequately despite naloxone, whose respiratory depression recurs after reversal, or who is peri-arrest — this needs immediate senior and critical care support"}, "escalate_now_if": ["He is unresponsive and not breathing normally, or has no signs of life: call 2222", "He is not breathing adequately despite naloxone", "The blood gas shows a raised CO2 with respiratory acidosis", "There is a suspected mixed overdose (opioid plus benzodiazepine, gabapentinoid, alcohol, or another sedative)", "He does not respond to naloxone — consider another cause of reduced consciousness", "Respiratory depression recurs after initial reversal", "He develops severe pain, agitation, withdrawal, an arrhythmia or pulmonary oedema after naloxone"], "document": "Record the time he was found, the respiratory rate, saturations and oxygen given, GCS and pupils, the glucose and blood gas, the opioid involved and when, the source stopped or removed, each naloxone dose with time, route and response, the time of any 2222 call, and the monitoring plan. If prescribing or administration contributed, complete an incident report.", "fail": "An unsafe response delays naloxone in opioid-induced respiratory depression, starts CPR on a responsive patient, gives a large bolus that precipitates withdrawal and severe pain in a patient on regular opioids, is reassured by saturations on oxygen while the breathing stays slow, leaves the PCA, driver or patch running, or stops monitoring before the naloxone has worn off.", "pass": "A safe response supports the airway, stops the opioid source, gives small titrated IV doses of naloxone to restore breathing, monitors for recurrence for at least 4 hours after the last dose (longer with modified-release opioids, patches or poor renal function), and escalates if he does not respond.", "high_performance": "An excellent response also considers a mixed overdose and renal impairment, plans safe pain relief afterwards, and reviews the prescribing and administration process to identify any system failure.", "one_thing": "If you only remember one thing: in a patient on regular opioids, give naloxone in small titrated IV doses to restore breathing, not consciousness — and keep watching, because it may wear off before the opioid.", "img_note": "NHS England issued a national Patient Safety Alert in 2014 after deaths from inappropriate naloxone doses in patients on long-term opioids, which is why many UK trusts have a ward naloxone protocol with small titrated doses. Check the naloxone product and strength before you draw it up. Opioid overdoses caused by prescribing or administration errors are reported through the trust incident system (for example Datix).", "source": "NHS England, Patient Safety Alert NHS/PSA/W/2014/016 (naloxone), 2014, and supporting information, Feb 2015; NHS Specialist Pharmacy Service, Reversing an adult opioid overdose with naloxone, updated 13 Mar 2026 (to be revised after the 2026 naloxone consultation); Naloxone 400 microgram/ml solution for injection or infusion (AOP Orphan, PL 30414/0004) SmPC, emc 8967, text revised Apr 2019; BTS oxygen guideline, 2017, section 8.13.4; Resuscitation Council UK, ABCDE approach (Jul 2024), Adult basic life support and Special circumstances guidelines, 2025; RCEM and NPIS, Acute opioid toxicity in adults in the ED, Apr 2024; BNF (accessed Oct 2026; the naloxone repeat interval follows the BNF low-dose regimen — the SmPC and SPS give 2–3 minutes)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Ellis on ward 8, he's barely rousable with a respiratory rate of 8 and pinpoint pupils — I think this is opioid toxicity.", "B": "He's on regular morphine for pain and had an extra dose an hour ago.", "A": "I've opened his airway, he's on oxygen aiming for 88–92% with bag-mask support available, I've stopped his morphine and given naloxone 200 micrograms IV in titrated doses — his respiratory rate is now 12 and he's maintaining his airway. His blood gas is pending.", "R": "Please review him — I need help deciding whether he needs a naloxone infusion and how to manage his pain safely. I'll keep him on close monitoring for at least 4 hours after the last dose, and longer if his renal function is poor."}, "checked": "Oct 2026"}, {"id": "BLEEP-49", "title": "Disclosure of suicidal ideation or self-harm", "fpc_tags": ["Communication and care", "Ethics and law", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Fraser has told me he's been having thoughts of ending his life, he says he doesn't want to go on.\"", "nurse_call": [{"lead": "Is he safe now?", "text": "Ask whether he is safe now and whether he has already harmed himself or taken anything — if so, start ABCDE, tell you now so you can come straight away, and put out an emergency call if he is seriously unwell"}, {"lead": "Ask directly about plans", "text": "Ask the nurse whether the patient has expressed any specific plans or intent, or whether he has access to means — asking directly about suicide does not increase risk and is recommended"}, {"lead": "Stay with the patient", "text": "Ask for a trained member of the nursing team to stay with him and not leave him alone until you arrive — not security or untrained staff"}, {"lead": "Background", "text": "Ask whether there is any relevant background: a history of self-harm or mental illness, recent adverse life events, or current alcohol or drug use"}, {"lead": "Liaison psychiatry", "text": "Ask whether liaison psychiatry has been involved and whether there is a current care plan"}], "first_five_minutes": [{"lead": "See the patient promptly", "text": "See the patient as soon as possible — do not delegate this to someone not trained or experienced enough to assess and manage it"}, {"lead": "Ask directly and compassionately", "text": "Ask directly and compassionately about suicidal thoughts, plans, and intent, and whether he has already harmed himself or taken anything — asking someone about suicidal thoughts does not increase their risk (NICE NG105)"}, {"lead": "Assess immediate safety", "text": "Assess immediate safety: does the patient have a specific plan, intent or preparations, and access to means? Consider removing items he could use to harm himself, involving him in the decision and using the least restrictive measures. Check the drug chart for medicines toxic in overdose, such as opioid painkillers or tricyclic antidepressants"}, {"lead": "Do not rely on risk tools", "text": "Do not use risk assessment tools or low, medium or high risk stratification to predict suicide or to decide treatment or discharge — NICE recommends against this"}, {"lead": "Consider capacity and safeguarding", "text": "Presume capacity; if in doubt, assess it for the specific decision, such as staying on the ward, and consider safeguarding. Look for treatable contributors such as delirium, pain, or alcohol or drug withdrawal — seek specialist advice from liaison psychiatry if needed"}, {"lead": "Agree interim safety steps", "text": "Agree with him what he will do and who he will tell if the thoughts get worse before liaison psychiatry see him — a full safety plan is developed with him as part of their assessment"}, {"lead": "Refer to liaison psychiatry", "text": "Refer urgently to liaison psychiatry for assessment and follow-up. Tell your registrar and the nurse in charge, and agree an interim observation level (1:1 if he is at immediate risk) until liaison psychiatry and the ward team decide it jointly; consider whether a Mental Health Act assessment is needed"}, {"lead": "If he tries to leave", "text": "If he tries to leave before assessment, keep him safe and escalate now. If he lacks capacity, the Mental Capacity Act may allow proportionate steps to keep him on the ward; if a mental disorder puts him at risk and he needs a Mental Health Act assessment, the doctor or approved clinician in charge of his treatment (or their nominated deputy) can consider a section 5(2) holding power, whether or not he has capacity. Call them now; you can use it yourself only if you are the nominated deputy"}], "can_i_do_alone": {"alone": "Seeing the patient promptly, asking directly about suicidal thoughts and plans, assessing immediate safety, reducing access to means with his involvement, asking for him not to be left alone, and referring to liaison psychiatry", "senior_opinion": "Any uncertainty about the level of risk, any difficulty arranging liaison psychiatry input, or any doubt about whether the ward environment is safe", "senior_in_person": ["Any patient at immediate risk of acting on suicidal thoughts", "Any patient trying to leave who may need to be kept on the ward under the Mental Capacity Act or a section 5(2) holding power", "Any patient who has self-harmed needing medical treatment", "Any patient whose mental state is deteriorating"]}, "escalate_now_if": ["He has a specific plan, intent or preparations, or access to means", "He has already taken steps towards self-harm or suicide", "He is trying to leave the ward before a mental health assessment", "His mental state is deteriorating or he is becoming more distressed", "You are unable to arrange liaison psychiatry input in a timely way", "A safeguarding concern, such as abuse, exploitation, or children or other dependants at risk"], "document": "Record the time of disclosure, the patient's exact words as far as possible, the direct questions asked and the responses, the immediate safety assessment (plans, intent, means), anything removed and the drug-chart check, any capacity assessment and the decision it covered, the interim observation level and who agreed it, the time liaison psychiatry was contacted, and the plan for follow-up.", "fail": "An unsafe response fails to ask directly about suicide for fear of making things worse, relies on a risk assessment tool to determine risk, or fails to arrange specialist mental health input in a timely way", "pass": "A safe response sees the patient promptly, asks directly about suicidal thoughts and plans, assesses immediate safety, stays with the patient, and refers urgently to liaison psychiatry", "high_performance": "An excellent response also agrees interim safety steps with the patient, considers the ward environment and whether any means, including medicines toxic in overdose, need to be removed, involves the patient's support network where consent allows, and ensures prompt follow-up is arranged", "one_thing": "If you only remember one thing: ask directly about suicide — it does not increase risk, and NICE recommends against using risk tools to predict it. See the patient yourself and refer to liaison psychiatry.", "img_note": "Section 5(2) of the Mental Health Act 1983 (England and Wales) lets the doctor in charge of an informal inpatient's treatment (or their nominated deputy) hold them for up to 72 hours while a Mental Health Act assessment is arranged — in a general hospital this is usually the consultant or a senior doctor they have nominated, so check your trust's list before you need it. Most UK acute hospitals have a liaison psychiatry team who can be contacted at any time.", "source": "NICE, Self-harm: assessment, management and preventing recurrence (NG225), Sep 2022 (scope is people who have self-harmed, applied here by extension); NICE, Preventing suicide in community and custodial settings (NG105), Sep 2018; Mental Health Act 1983, section 5(2)–(3), and Code of Practice (England) 2015, ch 18; Mental Capacity Act 2005. Screening for delirium, pain or withdrawal is standard practice, not guideline", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Fraser on ward 7, he's disclosed thoughts of ending his life to the nursing staff.", "B": "He has a history of depression but no previous self-harm; he was admitted with a chest infection and has been struggling with his mood.", "A": "I've seen him: he has thoughts but no specific plan, no access to means on the ward, and he's willing to talk and to stay. I've asked for him not to be left alone and I've referred him to liaison psychiatry.", "R": "I'd like you to review him and agree the level of observation until liaison psychiatry see him — and I'll call you immediately if he tries to leave."}, "checked": "Oct 2026"}, {"id": "BLEEP-50", "title": "Capacity assessment and treatment refusal", "fpc_tags": ["Ethics and law", "Communication and care", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Green is refusing his antibiotics, he says he doesn't want any more treatment, but he seems confused to me.\"", "nurse_call": [{"lead": "What is he refusing?", "text": "Ask exactly what the patient is refusing and whether this is a change from his usual position"}, {"lead": "Baseline and change", "text": "Ask whether this is new behaviour and what his baseline cognitive state is — a change may suggest delirium or another acute cause"}, {"lead": "Communication needs", "text": "Ask whether there are any communication difficulties, and whether an interpreter, advocate, or family member could help"}, {"lead": "Advance decisions", "text": "Ask whether there is any advance decision to refuse treatment, or a lasting power of attorney for health and welfare, documented in the notes"}, {"lead": "Physical cause", "text": "Ask for a full set of observations, including NEWS2, and a glucose — confusion may be the first sign of a physical deterioration"}], "first_five_minutes": [{"lead": "See the patient yourself", "text": "See the patient yourself and talk to him about his decision — capacity is decision-specific and time-specific, so assess it for this decision: refusing antibiotics"}, {"lead": "Check for deterioration first", "text": "Do a quick ABCDE review and check his observations. If the confusion is new, look for a physical cause (infection, hypoxia, hypoglycaemia, a new medication, pain) — delirium is common and may be reversible. A deteriorating patient needs escalating regardless of the refusal"}, {"lead": "Presume capacity", "text": "Start from the presumption that he has capacity — the burden is on you to show that he lacks it, not on him to prove that he has it"}, {"lead": "Support decision-making", "text": "Take all practicable steps to help him decide — explain what the antibiotics are for and what is likely to happen if he refuses them, use simple language, give him time, involve someone he trusts, and choose a better time or place if needed"}, {"lead": "Apply the capacity test", "text": "First ask the functional question: can he understand, retain, use or weigh the information, and communicate a decision about the antibiotics? Only if he cannot, ask whether that inability is because of an impairment or disturbance of mind or brain (temporary, such as delirium, or permanent)"}, {"lead": "Do not equate unwise with incapable", "text": "A capacitous adult may make a decision others regard as unwise — refusing antibiotics is not automatically evidence of incapacity. If he has capacity, his refusal stands even if it may cause him serious harm: explore his reasons, make sure he knows he can change his mind, and tell your senior"}, {"lead": "If he lacks capacity", "text": "Check for a registered health and welfare LPA (the attorney decides, and can refuse life-sustaining treatment only if the LPA expressly says so) or a valid, applicable advance decision; otherwise the treating team, led by your senior, decides in his best interests, choosing the least restrictive option and taking into account his wishes, values and beliefs and the views of those close to him. In an emergency, if his wishes can't be found out, you can give treatment that is immediately necessary to save his life or prevent a serious deterioration; tell your senior at once"}], "can_i_do_alone": {"alone": "Seeing the patient, supporting decision-making, performing a capacity assessment for the specific decision, and looking for a reversible physical cause of confusion", "senior_opinion": "Any uncertainty about the capacity assessment, or any patient with capacity who is refusing treatment he needs", "senior_in_person": "Any high-stakes, contested decision, any patient requiring restraint (which must be necessary to prevent harm and proportionate) or deprivation of liberty to provide treatment, or any patient where you are unsure whether a best interests decision can be made safely — these need a senior now, who may seek legal advice"}, "escalate_now_if": ["The patient lacks capacity to refuse the treatment and the treatment is necessary to prevent serious harm", "There is disagreement between the clinical team and the family about what is in the patient's best interests", "You are considering providing treatment against the patient's expressed wishes", "There is an advance decision to refuse treatment that conflicts with the proposed treatment", "The patient is at risk of serious harm from the refusal", "His observations are getting worse or he becomes newly drowsy"], "document": "Record the specific decision being assessed, what you told him about the consequences of refusing, how you supported him, his answers on understanding, retaining, weighing and communicating, whether any inability was caused by an impairment of mind or brain and your reasoning, his wishes and values, any LPA or advance decision checked, the best interests decision if he lacks capacity, and who was involved.", "fail": "An unsafe response assumes a patient lacks capacity because he is making a decision others disagree with, fails to take steps to support decision-making, or makes a best interests decision without properly considering the patient's wishes and values", "pass": "A safe response checks for deterioration, presumes capacity, takes steps to support decision-making, applies the functional test then the causative link, looks for a reversible cause, respects a capacitous refusal, checks for an LPA or advance decision, and involves senior input if the decision is complex or contested", "high_performance": "An excellent response also involves his family or carers where appropriate, considers whether an independent mental capacity advocate (IMCA) is needed, and documents the decision and reasoning clearly, including his own perspective", "one_thing": "If you only remember one thing: presume capacity, support decision-making, and remember that refusing treatment is not automatically evidence of incapacity — but look for a reversible physical cause if the confusion is new.", "img_note": "The Mental Capacity Act 2005 applies in England and Wales to people aged 16 and over (Scotland and Northern Ireland have their own laws). The Mental Health Act cannot be used to treat a physical illness such as a chest infection. A health and welfare Lasting Power of Attorney can only be used once it is registered with the Office of the Public Guardian, and an advance decision refusing life-sustaining treatment must be in writing, signed, witnessed and state that it applies even if life is at risk. Only adults aged 18 or over can make an LPA or an advance decision. If a patient who lacks capacity has no family or friends to consult about serious medical treatment, the NHS body must instruct an Independent Mental Capacity Advocate (IMCA) unless the treatment is urgent.", "source": "Mental Capacity Act 2005, sections 1–6, 9–11, 24–26 and 37; Supreme Court, A Local Authority v JB [2021] UKSC 52; NICE, Decision-making and mental capacity (NG108), Oct 2018; Mental Capacity Act Code of Practice, 2007; GMC, Decision making and consent (2020, updated 3 Aug 2026), paras 63 and 81–82 (emergency treatment when a patient lacks capacity; assessing capacity is a core clinical skill)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Green on ward 9, he's refusing his antibiotics and the nursing staff think he seems confused.", "B": "He was admitted with a chest infection and has been on intravenous antibiotics, he has no previous history of cognitive impairment.", "A": "His observations are unchanged from this morning and his glucose is 6.5, he's orientated to place and time but is not retaining information about why he needs the antibiotics, I've tried explaining the decision in simple terms and giving him time.", "R": "Could you come and review him as soon as you can — I'm concerned that his confusion may be delirium from his infection and I need your help deciding whether he has capacity to refuse this treatment and, if not, what is in his best interests."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-51", "title": "Anaphylaxis", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"Mr Nash has come out in a rash and his lips are swelling, he's struggling to breathe after his IV antibiotics.\"", "nurse_call": [{"lead": "Stop the trigger", "text": "Ask the nurse to stop the infusion immediately and disconnect it, keeping the cannula"}, {"lead": "Call 2222", "text": "Ask the nurse to call 2222 (or your resuscitation team) now — anaphylaxis is a medical emergency"}, {"lead": "IM adrenaline now", "text": "Ask the nurse to give IM adrenaline 1 mg/mL (1:1000) from the anaphylaxis kit immediately, into the anterolateral thigh — this is first-line treatment and must not wait for you"}, {"lead": "Position", "text": "Ask the nurse to lie him flat, with or without legs raised, if he is faint or hypotensive; he may sit up only if breathing is the problem and his blood pressure is normal. He must not stand or walk"}, {"lead": "Oxygen and monitoring", "text": "Ask the nurse to give oxygen 15 L/min via a reservoir mask and attach pulse oximetry, ECG and blood pressure monitoring"}, {"lead": "Note the time", "text": "Ask the nurse to note the time symptoms started — you will need it for adrenaline repeats and tryptase samples"}], "first_five_minutes": [{"lead": "ABCDE and call for help", "text": "Assess airway, breathing, circulation, disability and exposure — make sure 2222 has been called. Treat the greatest threat to life first"}, {"lead": "Give IM adrenaline without delay", "text": "Give IM adrenaline 500 micrograms (0.5 mL of 1 mg/mL) into the anterolateral thigh for adults and children over 12 (check BNF/local protocol) — repeat after 5 minutes if there is no improvement"}, {"lead": "Remove the trigger", "text": "Stop the infusion if this can be done without delaying adrenaline"}, {"lead": "Position and oxygen", "text": "Lie him flat (with or without legs raised) if hypotensive; sit him up only if breathing is the main problem and BP is normal. Give oxygen 15 L/min via a reservoir mask, aiming for SpO2 94–98% (even if at risk of hypercapnia, until a blood gas guides you), and attach monitoring — no sudden changes in posture"}, {"lead": "IV fluid if shocked", "text": "If he is hypotensive or responds poorly to the first adrenaline, secure IV access and give a rapid crystalloid bolus of 500–1000 mL, then reassess"}, {"lead": "Refractory or cardiac arrest", "text": "If breathing or circulation problems persist despite two IM doses, follow the refractory anaphylaxis algorithm, keep giving IM adrenaline every 5 minutes until an adrenaline infusion is running, and get critical care help. If he becomes unresponsive with absent or abnormal breathing, this is cardiac arrest: start CPR and follow ALS, with adrenaline IV or IO, not IM"}, {"lead": "Tryptase without delaying treatment", "text": "Once treatment is under way, take mast cell tryptase as soon as feasible and again 1–2 hours (no later than 4 hours) after onset, recording the exact times"}], "can_i_do_alone": {"alone": "Calling 2222, giving IM adrenaline and repeating it after 5 minutes, continuing IM adrenaline every 5 minutes until an infusion is started, stopping the trigger, positioning, oxygen, an IV fluid bolus if shocked, taking timed tryptase samples, and recording the drug allergy", "senior_opinion": "Any uncertainty about the diagnosis, how long to observe him after resolution, and alternative antibiotics for his infection", "senior_in_person": "Any patient with refractory anaphylaxis (breathing or circulation problems persisting despite two doses of IM adrenaline) or cardiac arrest — this needs senior and critical care support now, and an adrenaline infusion must only be given by those experienced in its use with cardiac monitoring"}, "escalate_now_if": ["There is airway swelling, stridor, or hoarseness", "There is increased work of breathing, wheeze, tiring, cyanosis, or SpO2 below 94%", "There is hypotension, confusion, or reduced consciousness", "There is no improvement after two doses of IM adrenaline — this is refractory anaphylaxis", "Symptoms return after initial improvement (a biphasic reaction)", "He becomes unresponsive with absent or abnormal breathing (cardiac arrest) — start CPR and make a 2222 arrest call"], "document": "Record the time the reaction started, the suspected trigger, each adrenaline dose with time and route, the response, fluids, oxygen, the time 2222 was called, tryptase sample times, and the plan agreed with the senior. Record the drug allergy on the drug chart and in the notes (drug, reaction, date), tell the patient, and make sure the GP is informed and a referral to an allergy service is made.", "fail": "An unsafe response delays IM adrenaline while waiting for a senior or for tests, gives IV adrenaline boluses outside a cardiac arrest without specialist experience, sits a hypotensive patient up, fails to repeat adrenaline after 5 minutes when there is no improvement, or fails to record the drug allergy so the drug is given again.", "pass": "A safe response recognises anaphylaxis, gives IM adrenaline immediately, repeats it after 5 minutes if needed, positions the patient correctly, gives oxygen and fluids if shocked, calls for help early, and records the allergy.", "high_performance": "An excellent response also recognises refractory anaphylaxis early, takes timed tryptase samples, plans a risk-stratified observation period for a biphasic reaction, and refers the patient to a specialist drug allergy service.", "one_thing": "If you only remember one thing: give IM adrenaline immediately and repeat after 5 minutes if there is no improvement — antihistamines and steroids are not the emergency treatment.", "img_note": "UK law (Human Medicines Regulations 2012, Schedule 19) allows anyone to give IM adrenaline 1 mg/mL for anaphylaxis to save a life, so the nurse should not wait for you or a prescription. Suspected drug reactions should also be reported to the MHRA through the Yellow Card scheme. Your senior decides how long to observe him for a biphasic reaction.", "source": "Resuscitation Council UK, Emergency treatment of anaphylaxis: guidelines for healthcare providers, May 2021, and 2021 algorithms (still current in Oct 2026 and referenced by RCUK 2025 Special circumstances; review date May 2026 passed); BTS emergency oxygen guideline 2017 (rec E2); NICE, Anaphylaxis: assessment and referral after emergency treatment (NG258), May 2026; NICE, Drug allergy (CG183), Sep 2014; Human Medicines Regulations 2012, Schedule 19; BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Nash on ward 8 — he has anaphylaxis after IV co-amoxiclav; 2222 has been called.", "B": "He had no known allergies and the co-amoxiclav was started an hour ago for a chest infection.", "A": "He had lip swelling, wheeze and saturations of 90% on air. The infusion is stopped, he's lying flat on 15 L/min oxygen via a reservoir mask, and he's had IM adrenaline 500 micrograms twice, five minutes apart. His wheeze is still present and his BP is 85 systolic, so I've started a 500 mL crystalloid bolus. First tryptase is sent.", "R": "This is refractory anaphylaxis — I'm giving a third IM dose now and will repeat every 5 minutes; I need you and critical care here now for an adrenaline infusion."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-52", "title": "Suspected drug error", "fpc_tags": ["Clinical assessment", "Quality improvement", "Upholding values"], "scenario": "Nurse bleeps: \"I think I've given Mr Price the wrong medication, I meant to give him his regular metformin but I've given him someone else's gliclazide.\"", "nurse_call": [{"lead": "What was given?", "text": "Ask exactly what drug was given, what dose, by what route, and at what time"}, {"lead": "What was intended?", "text": "Ask what drug was intended and what the patient's regular medication is"}, {"lead": "Patient status and glucose", "text": "Ask for the current observations and a capillary blood glucose now, and whether he has any symptoms; if glucose is below 4.0 mmol/L, ask the nurse to treat it straight away using the ward hypoglycaemia protocol without waiting for you"}, {"lead": "Allergies", "text": "Ask whether the patient has any allergies or known reactions to the drug that was given"}, {"lead": "Preserve evidence", "text": "Ask the nurse to keep the medication packaging, the prescription chart, and any remaining medication — do not discard anything"}, {"lead": "The other patient", "text": "Ask who the gliclazide was prescribed for, whether that patient has had his own medicines, and ask for his team to be told"}], "first_five_minutes": [{"lead": "Assess the patient", "text": "Assess airway, breathing, circulation, disability and exposure — and check observations and glucose, particularly if the drug given could cause hypoglycaemia"}, {"lead": "Treat any hypo now", "text": "If glucose is below 4.0 mmol/L, treat it straight away (BLEEP-06): oral fast-acting carbohydrate if he can swallow, IV glucose if he cannot, and IM glucagon only if there is no IV access (it may be less effective after a sulfonylurea)"}, {"lead": "Identify the drug and dose", "text": "Establish exactly what was given, the dose, route and time — this determines the potential harm and the monitoring needed"}, {"lead": "Consider the potential harm", "text": "Consider what the drug could do — for example, gliclazide can cause hypoglycaemia, opioids respiratory depression, and anticoagulants bleeding"}, {"lead": "Monitor and treat", "text": "Monitor for the expected effects of the drug and treat any harm. After a sulfonylurea such as gliclazide, JBDS warns hypoglycaemia risk may persist for up to 24–36 hours after the dose, especially with renal impairment, so check recent U&Es and arrange regular capillary glucose checks for that period (at least 24–48 hours if he has a hypo); keep him eating regular carbohydrate, not nil by mouth, and ask TOXBASE or the on-call pharmacist how often to test"}, {"lead": "Seek senior advice", "text": "Discuss with a senior or the on-call pharmacist — they can advise on likely effects, monitoring, and whether any antidote or further treatment is needed"}, {"lead": "Report it, covering both patients", "text": "Check the other patient too: his gliclazide dose may have been missed, and he may have been given Mr Price's medicines — tell his team. Report it on your trust's incident system (for example Datix) whether or not harm occurred"}, {"lead": "Be open with the patient", "text": "Make sure the patient is told promptly and honestly what has happened, with an apology — this is part of every professional's duty of candour"}], "can_i_do_alone": {"alone": "Assessing the patient, checking observations and glucose, identifying the drug and dose, starting the monitoring plan, treating hypoglycaemia using the protocol, reporting the incident, and making sure the patient is told", "senior_opinion": "Any uncertainty about the potential effects of the drug given or how long to monitor, any patient who develops symptoms, and advice from the on-call pharmacist on toxicity", "senior_in_person": "Any patient who develops significant adverse effects (such as recurrent or severe hypoglycaemia, respiratory depression, or anaphylaxis) — these need senior review and may need critical care support"}, "escalate_now_if": ["The patient develops any adverse effects from the drug given", "The drug given has a narrow therapeutic index or high potential for harm (such as insulin, opioids, anticoagulants or sulfonylureas)", "Glucose stays below 4.0 mmol/L after 3 treatments or 30–45 minutes, or hypoglycaemia recurs", "Glucose is falling within, or repeatedly in, the 4.0–6.0 mmol/L JBDS alert range after the wrong sulfonylurea dose (a single 4.0–6.0 reading: give carbohydrate and increase checks per TOXBASE/local protocol)", "He is not eating, is vomiting, or has to be nil by mouth", "You are unsure about the potential effects of the drug given", "The incident may be a Never Event (for example mis-selection of a strong potassium solution, IV chemotherapy given intrathecally, oral or enteral medicine given by a parenteral route, or an insulin overdose due to abbreviations or the wrong device)"], "document": "Record the time of the error, what was given and what was intended, the dose and route, the patient's observations and any symptoms, the monitoring and treatment given, the time senior advice was sought, the other patient involved and the action taken for him, and the incident report reference. Complete a clear factual record without blame.", "fail": "An unsafe response fails to assess the patient for adverse effects, stops checking glucose after one normal reading, discards the medication packaging or prescription chart, or fails to report the incident.", "pass": "A safe response assesses the patient, identifies the drug and dose, monitors for expected effects, seeks senior advice, reports the incident, and is open with the patient", "high_performance": "An excellent response also reviews the prescribing and administration process to identify how the error occurred (look-alike packaging, interrupted administration, unclear prescription), and ensures the learning is shared with the wider team to prevent recurrence.", "one_thing": "If you only remember one thing: assess the patient first, identify exactly what was given, and report the incident — the purpose is learning and prevention, not blame", "img_note": "In England, incidents are recorded on the trust's local system (often Datix), which feeds the national Learn from Patient Safety Events service, and the trust decides how to respond under the Patient Safety Incident Response Framework (PSIRF) rather than the old 'serious incident' process. Never Events are a short national list of wholly preventable incidents. You have a professional duty of candour to tell the patient; the trust also has a separate statutory duty of candour (in England) when an incident has caused, or could cause, moderate or severe harm, death or prolonged psychological harm.", "source": "NHS England, Never Events list 2018, updated Feb 2021; NHS England, Patient Safety Incident Response Framework, 2022; JBDS-IP, Hospital management of hypoglycaemia in adults with diabetes (JBDS 01), Jan 2023; GMC and NMC, Openness and honesty when things go wrong: the professional duty of candour, 2015, last updated Dec 2024; Health and Social Care Act 2008 (Regulated Activities) Regulations 2014, reg. 20 (duty of candour); NPIS: TOXBASE is the first port of call. No national guideline sets a glucose-testing schedule after a wrong sulfonylurea dose: follow TOXBASE and local protocol", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about a medication error on ward 4 — Mr Price was given gliclazide 80 mg, prescribed for another patient, instead of his metformin.", "B": "He has type 2 diabetes managed with metformin alone; the gliclazide was given an hour ago.", "A": "He is asymptomatic, observations are normal (NEWS2 0) and his glucose is 5.2, in the JBDS 4.0–6.0 alert range. I've set up regular capillary glucose checks for the next 24–36 hours with the hypoglycaemia protocol available, told the other patient's team that his gliclazide may have been missed, completed an incident report covering both patients and explained what happened to him.", "R": "I'd like your advice on whether he needs anything beyond glucose monitoring — for example an infusion if he becomes hypoglycaemic — and I'll call you if his glucose keeps falling or drops below 4.0."}, "checked": "Oct 2026"}, {"id": "BLEEP-53", "title": "Pain poorly controlled", "fpc_tags": ["Clinical assessment", "Holistic planning", "Communication and care"], "scenario": "Nurse bleeps: \"Mrs Bennett is three days after her hip replacement and still in a lot of pain despite regular paracetamol and codeine, she's saying it's worse than ever.\"", "nurse_call": [{"lead": "Pain score and site", "text": "Ask for the pain score, the site, and the character of the pain — and whether it is new or a worsening of the usual pain"}, {"lead": "What has been given?", "text": "Ask what analgesia has been given, at what time, and by what route"}, {"lead": "Leg and new symptoms", "text": "Ask whether the operated leg looks shortened or rotated, whether she can feel and move her foot, and about any new swelling, fever or calf pain — these suggest a complication, not just undertreated pain"}, {"lead": "Renal and hepatic function", "text": "Ask whether there are any recent blood results — renal and hepatic function affect the choice and dose of analgesia"}, {"lead": "Current medications", "text": "Ask about regular medications, allergies, contraindications to common analgesics, and other sedating drugs such as gabapentin, pregabalin or a benzodiazepine"}, {"lead": "Observations and drowsiness", "text": "Ask for a full set of observations and whether she is drowsy or confused"}], "first_five_minutes": [{"lead": "Assess the pain properly", "text": "Assess the pain: site, radiation, character, severity at rest and on movement, and what she can't do because of it — don't judge analgesia on a pain score alone"}, {"lead": "Look for a complication", "text": "Three days after a hip replacement, examine for dislocation (sudden pain, shortened and rotated leg), periprosthetic fracture, neurovascular compromise of the foot, compartment syndrome (pain out of proportion, or on passive movement of the muscles: release any circumferential dressing), DVT, wound haematoma or infection, and a full bladder — a new cause must be excluded before escalating analgesia, and the orthopaedic team told if you find one"}, {"lead": "Review the drug chart", "text": "Check what has actually been given and when, and that regular and PRN doses are being offered at the right intervals"}, {"lead": "Build a multimodal plan", "text": "Make sure regular paracetamol is prescribed, add an NSAID such as ibuprofen if renal function, bleeding risk and the surgical team allow (not after hip fracture surgery), and for moderate to severe pain, once you have examined for a surgical complication, prescribe an oral immediate-release opioid per local protocol rather than relying on codeine alone — involve the acute pain team if standard doses are not working. Never use a prolonged-release opioid or a patch for post-operative pain"}, {"lead": "No routine gabapentinoids", "text": "Don't start gabapentin or pregabalin yourself — both add sedation and respiratory depression risk with opioids"}, {"lead": "Plan for opioid side effects", "text": "With any opioid, prescribe an antiemetic and a laxative, check naloxone is prescribed per local protocol, and ask the nurses to monitor sedation, which predicts opioid-induced breathing problems better than respiratory rate. Reassess after each dose"}, {"lead": "Consider non-drug measures", "text": "Consider non-drug measures: positioning, heat or cold, distraction, and reassurance"}, {"lead": "Escalate severe or new pain", "text": "Escalate if it is a new pain, if severe pain is not settling after an immediate-release opioid, or if you are unsure whether there is an underlying cause that needs urgent treatment"}], "can_i_do_alone": {"alone": "Assessing the pain and examining for a complication, reviewing the drug chart, making sure regular paracetamol (and an NSAID if appropriate) is prescribed, prescribing an oral immediate-release opioid per local protocol after examining for a surgical complication (acute pain team if standard doses are not working), using non-drug measures, and requesting an urgent hip X-ray if you suspect dislocation or fracture, while escalating", "senior_opinion": "Any uncertainty about the cause of the pain, renal impairment, opioid tolerance or other sedating drugs affecting the choice, and pain still severe after a stronger opioid", "senior_in_person": "Any patient with suspected dislocation, periprosthetic fracture, neurovascular compromise, compartment syndrome or another new serious cause — this needs urgent senior and orthopaedic review. Signs of opioid toxicity also need a senior at the bedside: stop the opioid and give naloxone per local protocol while help comes"}, "escalate_now_if": ["The pain is new and severe, suggesting a new serious cause", "The leg is shortened or rotated, or there is sudden pain with loss of movement (possible dislocation or fracture)", "The foot is cold, pale, numb or weak", "Pain is out of proportion, or there is pain on passive movement of the muscles (possible compartment syndrome)", "The calf is swollen and tender, or she becomes breathless (possible DVT or PE)", "NEWS2 is 5 or more, or any single parameter scores 3", "She becomes increasingly drowsy or hard to rouse, or her breathing becomes slow or shallow"], "document": "Record the pain score at rest and on movement and its character, what analgesia had already been given, examination findings, any new cause identified, what you prescribed (drug, dose, route, interval and 24-hour maximum) and the time, the sedation monitoring plan, the response, and the plan agreed with the senior if escalation was needed.", "fail": "An unsafe response escalates analgesia without examining the operated leg, misses a dislocation, fracture, compartment syndrome or neurovascular problem, uses a prolonged-release opioid or patch, or adds strong opioids or gabapentinoids without considering renal function, other sedatives and sedation monitoring.", "pass": "A safe response assesses the pain properly, examines for a complication of the hip replacement, makes sure regular multimodal analgesia is prescribed, steps up to an immediate-release opioid per local protocol, with acute pain team input if standard doses are not working, and covers nausea, constipation and sedation monitoring.", "high_performance": "An excellent response also considers the patient's individual needs (including renal function and previous opioid use), involves the acute pain team if the pain is complex or poorly controlled, and communicates clearly with the patient about the plan.", "one_thing": "If you only remember one thing: a new or worsening pain is a diagnostic clue, not just a prescribing problem — examine the patient before reaching for stronger analgesia.", "img_note": "Most UK hospitals have an acute pain team (often nurse-led, linked to anaesthetics) who advise on difficult postoperative pain and PCAs, and the orthopaedic team remains responsible for a post-operative complication even if a medical or orthogeriatric team is co-managing the patient. Always check renal function before prescribing NSAIDs or morphine, as both can cause harm in renal impairment.", "source": "NICE, Perioperative care in adults (NG180), Aug 2020 (1.6.10 amended Jul 2025), recs 1.6.2–1.6.13; NICE, Hip fracture (CG124), updated Jan 2023, rec 1.3.9 (no NSAIDs); MHRA Drug Safety Update, Mar 2025 (no prolonged-release opioids or patches after surgery); Faculty of Pain Medicine, Opioids Aware, acute pain (sedation, function, pain team); BOAST Compartment syndrome, Jul 2025; NICE NG46 Controlled drugs (2016); RCP NEWS2 (2017); NICE, Venous thromboembolic diseases (NG158), last updated Aug 2023. Antiemetic, laxative, naloxone and checking for retention are standard practice, not guideline.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Bennett on ward 6, three days after an elective hip replacement, with severe pain despite regular paracetamol and codeine.", "B": "She has no allergies, normal renal function on yesterday's bloods, and has had all her regular doses. She's on enoxaparin prophylaxis and has no history of GI bleeding.", "A": "Her pain score is 8 out of 10. The leg isn't shortened or rotated, the foot is warm with normal sensation and movement, the calf is soft, the wound looks clean and her bladder isn't full. Heart rate 88, BP 132/78, resps 16, sats 97% on air, temp 36.9, alert: NEWS2 0.", "R": "I'd like to add ibuprofen if you're happy given her enoxaparin, and your advice on oral immediate-release morphine with an antiemetic, laxative and sedation monitoring, and whether she needs an X-ray or the acute pain team — I want to be sure we're not missing a complication."}, "checked": "Oct 2026"}, {"id": "BLEEP-54", "title": "Blood transfusion reaction", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Quality improvement"], "scenario": "Nurse bleeps: \"Mrs Taylor has developed a temperature and a rash during her blood transfusion, she says she feels shivery and unwell.\"", "nurse_call": [{"lead": "Stop the transfusion", "text": "Ask the nurse to stop the transfusion now — do not flush the blood left in the line into the patient"}, {"lead": "Keep the cannula", "text": "Ask the nurse to keep the cannula and run 0.9% saline through a new giving set so you have IV access for treatment"}, {"lead": "Full obs against baseline", "text": "Ask for a full set of observations, including temperature, respiratory rate, saturations and blood pressure, compared with the pre-transfusion baseline"}, {"lead": "Check identity, look at the pack", "text": "Ask the nurse to check the patient's identity band against the compatibility label on the blood pack, and to look at the pack for clumps or discolouration — a wrong-blood transfusion must be excluded straight away"}, {"lead": "Keep the blood pack", "text": "Ask the nurse to keep the blood pack and giving set sealed — the transfusion laboratory will need them"}, {"lead": "Deteriorating? Don't wait", "text": "If she is struggling to breathe or her blood pressure is falling, ask the nurse to call the resuscitation or critical care outreach team per local policy rather than wait for you"}], "first_five_minutes": [{"lead": "ABCDE and assess severity", "text": "Assess airway, breathing, circulation, disability and exposure — anaphylaxis, haemolysis, bacterial contamination, TRALI and circulatory overload (TACO) are emergencies"}, {"lead": "Stopped, saline, cannula kept", "text": "Confirm the transfusion is stopped and saline is running through a new giving set; for anything more than a mild reaction keep the unit and giving set disconnected and do not discard them — the lab will want them back"}, {"lead": "Check identity and the pack", "text": "Check the patient's identity against the pack and compatibility label and look at the unit for clumps or discolouration — an ABO-incompatible transfusion is a Never Event; if the unit was meant for another patient, phone the transfusion lab immediately"}, {"lead": "Grade the reaction", "text": "Mild means a temperature of 38°C or more but under 39°C with a rise of 1–2°C and nothing else, or a rash or itch alone. A rise of 2°C or more, a temperature of 39°C or more, rigors, chills or other systemic symptoms make it at least moderate — do not restart it without senior advice"}, {"lead": "Send the investigations", "text": "For a moderate or severe reaction send FBC, U&E and LFTs, and a chest X-ray if breathless without allergic features. If the febrile reaction is sustained, also send a repeat group and compatibility sample, DAT, LDH, haptoglobin, coagulation screen, blood cultures and urine for haemoglobin, and return the unit. Consider tryptase in severe allergy"}, {"lead": "Severe: treat now", "text": "Don't wait for results: Suspected anaphylaxis (life-threatening airway, breathing or circulation problems, e.g. stridor, hoarse voice, wheeze, hypotension, usually with skin or mucosal changes, which can be absent): IM adrenaline first, per the RCUK anaphylaxis algorithm (500 micrograms IM, 0.5 mL of 1 mg/mL [1:1000], into the anterolateral thigh, repeated after 5 minutes if there is no improvement; check BNF/local protocol), without waiting for shock, and even if platelets are low or clotting is deranged — if in doubt, give it — with oxygen, positioning and IV fluids alongside. Oxygen to BTS targets (reservoir mask at 15 L/min if critically ill or shocked); lie her flat with legs raised if hypotensive; IV fluids per local protocol if shocked without fluid overload. Suspected contamination: blood cultures, then broad-spectrum IV antibiotics per local protocol. If she is being transfused for bleeding, hypotension may be haemorrhage and continuing may be life-saving — get senior advice at once"}, {"lead": "Other reactions", "text": "Breathlessness with raised BP, crackles or a positive fluid balance suggests TACO: sit up, oxygen, and discuss a diuretic with a senior, as diuretics can harm in TRALI. Paracetamol for fever; antihistamines only for allergic features, never for fever alone, and no steroids"}, {"lead": "Call the transfusion lab", "text": "Phone the transfusion laboratory now and report it on the trust incident system"}], "can_i_do_alone": {"alone": "Stopping the transfusion, keeping IV access with saline through a new giving set, checking identity and inspecting the unit, grading the reaction, sending the investigations, calling the transfusion laboratory, giving IM adrenaline for anaphylaxis, and treating a mild isolated fever or rash", "senior_opinion": "Any moderate reaction, whether the unit is restarted or further transfusion is needed and which product, suspected TACO and diuretic treatment, and any uncertainty about the type of reaction", "senior_in_person": "Any patient with a severe reaction (anaphylaxis, suspected haemolysis or wrong blood, suspected bacterial contamination, hypotension, or respiratory compromise) — this needs immediate senior review, the on-call haematologist informed, and may need critical care support"}, "escalate_now_if": ["Suspected anaphylaxis — a life-threatening airway, breathing or circulation problem (stridor or hoarse voice, wheeze or increased work of breathing, hypotension or signs of shock), usually with skin or mucosal changes (urticaria, flushing, angioedema), which can be absent: give IM adrenaline now (500 micrograms IM, 0.5 mL of 1 mg/mL, repeated after 5 minutes if there is no improvement; check BNF/local protocol), do not wait for shock — if in doubt, give it. Breathlessness or hypoxia with raised BP, crackles or a positive fluid balance suggests TACO; also think of TRALI or TAD — stop the transfusion and treat as below.", "There is a suspected haemolytic reaction (loin or back pain, dark or red urine, new bleeding or oozing, or hypotension with fever)", "There is any suspicion that the wrong blood was transfused", "There is new breathlessness or hypoxia during or within 24 hours of the transfusion (TACO, TRALI or TAD)", "There is high fever, rigors and shock, or the unit looks abnormal, suggesting bacterial contamination"], "document": "Record the time the reaction started, the observations against the pre-transfusion baseline, the component and unit number, the time the transfusion started and stopped, the volume transfused, the identity check and appearance of the unit, the severity grade, treatment given, investigations sent, and the time the transfusion laboratory was contacted. Complete an incident report so the transfusion team can report to SHOT and SABRE.", "fail": "An unsafe response restarts a transfusion after fever with rigors, flushes the blood in the line into the patient, fails to check identity, misses TACO, or fails to send the investigations and inform the transfusion laboratory.", "pass": "A safe response stops the transfusion, keeps IV access with a new giving set, checks identity, grades the reaction correctly, sends the BSH investigations, treats according to severity, and contacts the transfusion laboratory.", "high_performance": "An excellent response also reviews whether the transfusion was indicated, considers TACO risk (age, heart failure, renal impairment, positive fluid balance) before any further transfusion, and plans future transfusions with the transfusion team.", "one_thing": "If you only remember one thing: stop the transfusion, check identity against the pack, and if it is anything more than a mild fever or a rash alone — rigors, a rise of 2°C or more, 39°C or more, or any breathing or BP change — do not restart it on your own decision — investigate and call the transfusion lab.", "img_note": "Every UK hospital has a transfusion laboratory and a hospital transfusion team. As the doctor on the ward you report the reaction locally; for moderate and severe reactions the transfusion team reports to the MHRA through SABRE (a legal requirement) and to SHOT, the UK haemovigilance scheme.", "source": "BSH, Guideline on the investigation and management of acute transfusion reactions (Soutar et al., Br J Haematol 2023;201:832–844; replaces BCSH 2012); SHOT, Definitions of current SHOT reporting categories, Jan 2026 (review due Nov 2026); MHRA, Blood authorisations and safety reporting (SABRE), updated Feb 2026; NHS England, Never Events list 2018, updated Feb 2021 (framework under review); BTS, Guideline for oxygen use in healthcare and emergency settings, 2017; Resuscitation Council UK, Emergency treatment of anaphylaxis: guidelines for healthcare providers, May 2021, and anaphylaxis algorithm 2021 (IM adrenaline dose); BNF, Adrenaline (emergency treatment of acute anaphylaxis, IM; accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Taylor on ward 7, who has had a moderate reaction to a red cell transfusion — the transfusion is stopped.", "B": "She's having red cells for post-operative anaemia; it started 30 minutes ago.", "A": "Her temperature is 38.2 from a baseline of 36.6, she has rigors and a widespread urticarial rash, BP is 110 over 70 with no wheeze or breathlessness. Her identity matches the pack and the unit looks normal. I've kept the cannula with saline through a new giving set, sent FBC, U&E and LFTs, and with the rigors ongoing, blood cultures and a repeat group sample, and phoned the transfusion lab, who want the unit back.", "R": "I'd like your advice, because with rigors this is at least a moderate reaction and I won't restart it on my own — and on whether she still needs red cells and which unit."}, "checked": "Oct 2026"}, {"id": "BLEEP-55", "title": "Warfarin/DOAC reversal query", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Understanding medicine"], "scenario": "Nurse bleeps: \"Mr Clarke is on warfarin and he's just had a fall and hit his head, his INR was 4.2 yesterday, should we reverse it?\"", "nurse_call": [{"lead": "What happened?", "text": "Ask exactly what happened — the mechanism of injury, whether there was a head strike, any loss of consciousness or memory loss, and whether there is any bleeding"}, {"lead": "Full obs + GCS", "text": "Ask for the full set of observations, GCS and pupils — a head injury in a patient on any anticoagulant is high risk — and to start neurological observations now"}, {"lead": "Which anticoagulant, last dose?", "text": "Ask exactly which drug (warfarin, or a DOAC: apixaban, rivaroxaban, edoxaban or dabigatran), the dose and when it was last taken, and whether they also take an antiplatelet. WARFARIN: ask for the latest INR and when it was taken. DOAC: the INR does not measure its effect, so ask for the timing of the last dose and the latest renal function instead"}, {"lead": "Any bleeding?", "text": "Ask about any active bleeding — from the wound, nose, gums, or any other site"}, {"lead": "Why anticoagulated?", "text": "Ask why the patient is anticoagulated (for example AF, a metallic heart valve or a recent clot) — this informs the balance of bleeding versus thrombosis risk"}], "first_five_minutes": [{"lead": "ABCDE, bleeding and neck", "text": "Assess airway, breathing, circulation, disability and exposure — look for external bleeding and signs of internal bleeding (tachycardia, hypotension, abdominal tenderness). If there is neck pain or tenderness, tell your senior: at 65 or over, a suspected cervical spine injury needs CT within 1 hour"}, {"lead": "Apply the NG232 CT criteria", "text": "CT head within 1 hour for GCS 12 or less, GCS below 15 at 2 hours after the injury, suspected skull fracture, post-traumatic seizure, focal neurological deficit or more than 1 vomit. Loss of consciousness or amnesia plus age 65 or over, a bleeding or clotting disorder, a dangerous mechanism or more than 30 minutes' retrograde amnesia needs CT within 8 hours of the injury (within 1 hour if more than 8 hours have passed). Otherwise, on warfarin or a DOAC, NICE NG232 says consider CT within 8 hours, or within 1 hour if more than 8 hours have passed. On warfarin, keep a lower threshold for CT: scalp or facial bruising or laceration, or persistent headache, warrants an urgent CT; follow local protocol (see BLEEP-07)"}, {"lead": "Neuro obs frequency", "text": "With a GCS of 15: half-hourly for 2 hours, then hourly for 4 hours, then 2-hourly. Keep them half-hourly while the GCS is below 15, and go back to half-hourly if he deteriorates"}, {"lead": "WARFARIN: withhold and repeat INR", "text": "Withhold tonight's warfarin and repeat the INR now, because the 4.2 is from yesterday. A raised INR with no bleeding is managed by withholding doses, not by PCC. Delayed bleeding can follow a normal CT; if the INR is above range, ask your senior about oral vitamin K to bring it back into range (not full reversal), per local protocol"}, {"lead": "WARFARIN: when to reverse", "text": "Give prothrombin complex concentrate (PCC) immediately only for severe bleeding or a head injury with suspected intracranial haemorrhage (NICE NG24) — for example a bleed on CT, or a falling GCS or new focal signs. It is given with IV vitamin K. Do not wait for the INR in major bleeding, or for the CT when intracranial bleeding is strongly suspected (BSH). PCC is dosed by weight per the local protocol"}, {"lead": "DOAC: INR is not a guide", "text": "For apixaban, rivaroxaban, edoxaban or dabigatran, the INR does not measure the anticoagulant effect — a normal INR does not mean the drug has worn off. Withhold the next dose, note when the last dose was taken, check renal function, and ask haematology about drug-specific levels if they would change management"}, {"lead": "DOAC: reversal is specialist", "text": "For life-threatening bleeding on a DOAC, call your senior and haematology now: the reversal agent depends on the drug, it is a senior and haematology decision, and not every trust stocks every agent"}, {"lead": "Escalate and weigh thrombosis risk", "text": "Tell your senior and get haematology advice for any reversal decision. Reversing or omitting anticoagulation carries a thrombosis risk, which is highest with a metallic valve or a recent clot, so the plan must include when to restart"}], "can_i_do_alone": {"alone": "Assessing the patient, starting neurological observations, applying the NG232 CT criteria and requesting the scan, withholding the next dose of warfarin or DOAC (and telling your senior), repeating the INR for warfarin or sending clotting and renal function for a DOAC, and contacting haematology for advice", "senior_opinion": "Any decision to give vitamin K (oral or IV), PCC, idarucizumab or andexanet alfa, any doubt about the balance of bleeding versus thrombosis risk, and the plan for restarting anticoagulation", "senior_in_person": "Major bleeding, haemodynamic instability, a GCS below 15, new focal neurology, or a CT showing intracranial haemorrhage — these need a senior at the bedside now, and warfarin reversal with PCC plus IV vitamin K should not wait for the INR"}, "escalate_now_if": ["There is major bleeding or haemodynamic instability", "After the head injury the GCS falls, or there is new focal neurology (such as unequal pupils), a seizure, more than 1 vomit, a severe or increasing headache, or new agitation or abnormal behaviour", "The CT shows intracranial haemorrhage — WARFARIN: reverse now with PCC plus IV vitamin K; DOAC: urgent haematology advice on the reversal agent", "The patient is on a DOAC and bleeding significantly — the INR will not show the anticoagulant effect, and the agent may not be stocked at your trust", "The repeat INR is rising"], "document": "Record the time and mechanism of the fall, the observations, GCS and pupils, the neuro obs frequency, the CT criteria you applied and when the scan was requested, the anticoagulant and the time of its last dose, the INR and when it was taken (warfarin) or the renal function (DOAC), the dose you withheld, any reversal decision with who made it, any agent given, and the plan agreed with your senior and haematology, including when to restart.", "fail": "An unsafe response gives PCC for a raised INR when there is no severe bleeding or suspected intracranial haemorrhage (unless needed for emergency surgery), delays PCC for strongly suspected intracranial bleeding to wait for the CT or INR, uses the INR to judge a DOAC's effect, misses the CT criteria or neuro obs in an anticoagulated head injury, or lets tonight's warfarin be given.", "pass": "A safe response assesses the patient, applies the NG232 CT criteria, starts neurological observations at the NICE frequency, withholds the next dose, repeats the INR for warfarin, and keeps reversal for severe bleeding or suspected intracranial haemorrhage after senior and haematology discussion.", "high_performance": "An excellent response also separates the warfarin and DOAC pathways clearly, considers the indication for anticoagulation and the thrombosis risk, and makes sure there is a documented plan for restarting anticoagulation.", "one_thing": "If you only remember one thing: in an anticoagulated head injury, apply the NG232 CT criteria and withhold the next dose — PCC is for severe bleeding or suspected intracranial haemorrhage, and the INR tells you nothing about a DOAC.", "img_note": "In UK hospitals, PCC (such as Beriplex) is a plasma-derived blood product, usually issued by the blood transfusion laboratory, and specific DOAC reversal agents are often kept in a central emergency drug store. The on-call haematology registrar is reached through switchboard. Patients on warfarin often carry a yellow anticoagulant record book with their recent INRs and target range, so ask to see it.", "source": "NICE, Blood transfusion (NG24), last updated Feb 2026; NICE, Head injury (NG232), May 2023 (1.5.8 to 1.5.13, 1.6.2, 1.9.11 to 1.9.13); NICE, Andexanet alfa (TA697), last updated Jan 2025; BSH, Oral anticoagulation with warfarin, 4th edn, 2011 (reviewed 2016); BSH, Measurement of heparin, direct oral anticoagulants and other non-coumarin anticoagulants and their effects on haemostasis assays, 2024; MHRA, DOAC reversal agents, Jun 2020; BSH, Use of andexanet alfa: position statement, Apr 2026; NICE TA1029 (terminated appraisal); BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Clarke on ward 9. He's had a fall and hit his head, and he's on warfarin with an INR of 4.2 yesterday.", "B": "He's 78, has atrial fibrillation and has been on warfarin for two years, and he doesn't recall the fall clearly.", "A": "His GCS is 15 with equal reactive pupils, his observations are stable, and there's no external bleeding, focal neurology or vomiting. Because he's 78, can't recall the fall and is on warfarin, I've requested an urgent CT head, to be done as soon as possible and no later than 8 hours after the injury. I've started half-hourly neuro obs, withheld tonight's warfarin and sent a repeat INR.", "R": "Please confirm the plan: no reversal unless the CT shows a bleed or he deteriorates, in which case he needs PCC and IV vitamin K straight away. Can you review him if anything changes?"}, "checked": "Oct 2026"}, {"id": "BLEEP-56", "title": "Verification and certification of death", "fpc_tags": ["Communication and care", "Ethics and law", "Holistic planning"], "scenario": "Nurse bleeps: \"I'm sorry to have to tell you, Mr Campbell has just died. Could you come and verify the death?\"", "nurse_call": [{"lead": "When did it happen?", "text": "Ask what time the patient died, whether the death was expected, and whether there is a documented DNACPR decision or ReSPECT plan; without one, this may be a cardiac arrest call"}, {"lead": "Was anyone with them?", "text": "Ask whether family were present and whether they have been informed"}, {"lead": "Any implants or devices?", "text": "Ask whether the patient had a pacemaker, implantable defibrillator, other battery-powered implant or radioactive treatment — the MCCD asks whether a hazardous implant is present and whether it has been removed"}, {"lead": "Infection status", "text": "Ask whether there is any known infection risk — this informs the precautions needed when handling the body"}, {"lead": "Notes available?", "text": "Ask for the patient's notes and drug chart to be available so you can review the history before verifying"}], "first_five_minutes": [{"lead": "Review the notes first", "text": "Review the medical history, recent entries and drug chart before examining — this helps you judge the likely cause of death and spot anything the coroner needs to know"}, {"lead": "Confirm identity", "text": "Confirm the patient's identity using their wristband or another reliable means, and check the documented resuscitation decision yourself, before verifying"}, {"lead": "Observe for 5 minutes", "text": "Stay with the patient and observe for at least 5 minutes, confirming continuous absence of breathing and circulation: no chest movement, no breath sounds, no central pulse and no heart sounds on auscultation"}, {"lead": "Then confirm neurological signs", "text": "After the 5 minutes, confirm the pupils do not react to light and there is no motor response to supraorbital pressure (add corneal reflexes if death follows soon after an arrest). Any return of function means a further 5 minutes of observation"}, {"lead": "Document the verification", "text": "Record the date and time death was confirmed (this is the time of death, not the time breathing was last seen), your findings, your name (printed and signed), GMC number and bleep in the notes"}, {"lead": "Check the coroner triggers", "text": "The death must be notified to the coroner if it may be due to poisoning, a toxic substance, a medicine or drug, violence, trauma or injury (including a fall), self-harm, neglect, a medical treatment or procedure, or work-related disease; if it may be unnatural or the cause is unknown; if the patient was in custody or state detention (including detention under the Mental Health Act); or if no doctor who attended the patient in life is available, or if the person's identity is unknown. If the death may be referred to the coroner, ask the nurses to leave all lines, tubes, drains and catheters in place; if the circumstances are suspicious, keep contact with the body to a minimum, do not let it be washed, and tell your senior now so the police can be informed"}, {"lead": "Who completes the MCCD?", "text": "Any doctor who attended the patient during their lifetime can complete the MCCD, if they can state the cause to the best of their knowledge and belief and the death does not need to be notified to the coroner; the consultant in charge agrees who certifies. If you never cared for the patient, hand over to their team. Write the cause in full with no abbreviations, record any hazardous implant, and talk to the medical examiner office early, especially if you are unsure about the coroner"}, {"lead": "Inform the family", "text": "Make sure the family has been told and offered support — sensitively and, where possible, by someone who knew the patient"}], "can_i_do_alone": {"alone": "Verifying death if you are trained (including the 5-minute observation) when a decision not to resuscitate is documented (or there are signs unequivocally associated with death, such as rigor mortis), documenting it, and — if you attended the patient in life, know the cause, no coroner trigger applies and the consultant agrees — completing the MCCD for medical examiner scrutiny", "senior_opinion": "Any uncertainty about the cause of death or about whether the death must be notified to the coroner — discuss this with your senior and the medical examiner before anyone completes the MCCD", "senior_in_person": "A senior is not usually needed at the bedside, but involve one in person if the death was unexpected, the circumstances are unclear or suspicious, or there are concerns about the care given"}, "escalate_now_if": ["There is no documented decision not to resuscitate and no resuscitation attempt that has stopped, even if the death was expected: call 2222 and consider CPR, unless there are signs unequivocally associated with death such as rigor mortis", "The death was unexpected or the circumstances are unclear; if suspicious, tell your senior now, as the police should be informed immediately", "Any coroner trigger applies (for example a fall or injury, a procedure, a medicine, self-harm, neglect, or detention under the Mental Health Act)", "No doctor who attended the patient in life is available within a reasonable time — the death must then be notified to the coroner", "There are any concerns about the care the patient received", "The family are distressed or raise concerns"], "document": "Record the time breathing was last seen, the time of death (the time you confirmed it), the 5-minute observation and your examination findings, and your name, GMC number and contact details. Put your primary medical qualifications on the MCCD. Record the proposed cause of death, any hazardous implant and whether it was removed, and any discussion with the medical examiner or coroner. If the death involved a notifiable disease, notify the health protection team unless already done. The MCCD is a statutory document and must be completed accurately and honestly.", "fail": "An unsafe response confirms death with neither a documented decision not to resuscitate nor a resuscitation attempt that has stopped (unless there are signs unequivocally associated with death, such as rigor mortis), confirms it without at least 5 minutes of observation, completes an MCCD without having attended the patient in life, or for a death that should have been notified to the coroner but was not, or leaves out a hazardous implant.", "pass": "A safe response reviews the notes, observes for at least 5 minutes and confirms the neurological signs, documents clearly, checks the coroner triggers, and makes sure an eligible doctor completes the MCCD for the medical examiner.", "high_performance": "An excellent response also involves the medical examiner office early, writes a clear and specific cause of death with no abbreviations, makes sure the family is supported and knows the medical examiner's office will contact them, and recognises when a death needs coroner notification.", "one_thing": "If you only remember one thing: observe for at least 5 minutes before confirming death, and check the coroner triggers before anyone writes the MCCD — any doctor who attended the patient in life can now complete it.", "img_note": "Since 9 September 2024, every death in England and Wales that the coroner does not investigate is independently scrutinised by a medical examiner, whose office also speaks to the bereaved family. Deaths must be registered within 5 days of the registrar receiving the MCCD, so do not leave it for days. Scotland and Northern Ireland have different systems. Find out where your medical examiner office is in your first week.", "source": "AoMRC, A Code of Practice for the diagnosis and confirmation of death, Jan 2025; DHSC, Guidance for medical practitioners completing MCCDs in England and Wales, last updated Apr 2025; MoJ, Guidance for registered medical practitioners on the Notification of Deaths Regulations, Sep 2024", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling to let you know Mr Campbell on ward 12 has died. I've confirmed the death.", "B": "He was admitted with pneumonia and had been deteriorating over the last 48 hours, he had a DNACPR in place, and the death was expected.", "A": "I observed him for 5 minutes, confirmed death and documented my findings. None of the coroner triggers apply, and he had no pacemaker or other implant. I've been looking after him this admission, so I can complete the MCCD.", "R": "Could you confirm you agree with my proposed cause of death, 1a community-acquired pneumonia, with any contributing conditions in part 2, before I send the MCCD to the medical examiner office?"}, "checked": "Oct 2026"}, {"id": "BLEEP-57", "title": "DNACPR / resuscitation status query", "fpc_tags": ["Ethics and law", "Communication and care", "Holistic planning"], "scenario": "Nurse bleeps: \"Mrs Hughes' family are asking about resuscitation status, they want to know if she's for CPR, and there's nothing documented in her notes.\"", "nurse_call": [{"lead": "Is she deteriorating?", "text": "Ask for her observations and NEWS2 trend — this sets how urgently a CPR decision is needed"}, {"lead": "Does she have capacity?", "text": "Ask whether the patient has capacity to take part in a discussion about resuscitation and treatment escalation"}, {"lead": "Any ReSPECT, ADRT or LPA?", "text": "Ask whether there is an existing ReSPECT plan, an advance decision to refuse treatment (ADRT), or a health and welfare lasting power of attorney (LPA)"}, {"lead": "Family concerns", "text": "Ask what specifically the family are worried about — this helps you address their concerns directly"}, {"lead": "Senior involvement", "text": "Ask whether a senior has already discussed this with the patient or family — if not, you may need to escalate"}, {"lead": "No verbal \"not for resus\"", "text": "With no recorded decision she is for CPR. Don't give a \"not for resus\" by phone: a senior decides, and it must be recorded"}], "first_five_minutes": [{"lead": "Review the notes and plans", "text": "Look for a ReSPECT form or DNACPR decision, an ADRT refusing CPR, or a registered health and welfare LPA. An ADRT refusing CPR must be written, signed, witnessed, say it applies even if life is at risk, and apply to this situation"}, {"lead": "Assess condition and prognosis", "text": "Assess the patient's condition, her prognosis and whether she may be approaching the end of life — this decides whether CPR could work and whether it would be of benefit. If arrest is foreseeable, decide early, not in a crisis"}, {"lead": "Assess capacity", "text": "Assume capacity, then assess it for this decision: a stroke alone doesn't establish incapacity. If she has capacity, involve her. She can refuse CPR, and that must be respected. No one can demand CPR that would not work, but she must still be told of a DNACPR decision unless that would cause her physical or psychological harm"}, {"lead": "Senior-led conversation", "text": "Conversations about CPR should be led by someone with the training and competence to do so — usually a senior. Your job is to prepare: know the history, the prognosis and any existing plans. DNACPR covers only CPR; all other care continues"}, {"lead": "If she lacks capacity", "text": "Decide in her best interests (Mental Capacity Act). Consult those close to her about her wishes, values and what she would regard as an acceptable outcome, and record their views"}, {"lead": "Relatives do not decide", "text": "Family views inform the decision but do not make it, and relatives are not asked to sign the form. The exception is a health and welfare attorney whose LPA covers life-sustaining treatment. If she lacks capacity and the family or attorney dispute the decision, your senior seeks legal advice"}, {"lead": "A senior takes responsibility", "text": "Overall responsibility for a CPR decision rests with the most senior clinician responsible for her care, as defined by your trust's policy — usually the consultant"}, {"lead": "Document clearly", "text": "Record the decision and reasoning on the ReSPECT form (or your trust's DNACPR form) per trust policy on who may complete it — a senior endorses it at the earliest opportunity — and record in the notes who was involved and what was said. Until then, make sure the nurse in charge knows she is for CPR"}], "can_i_do_alone": {"alone": "Reviewing existing documentation, assessing capacity, explaining to the family how decisions about CPR are made, and recording their views — but you should not make a DNACPR decision alone", "senior_opinion": "Any DNACPR decision, or any doubt about an ADRT or LPA", "senior_in_person": "Any conflict between the family (or an attorney) and the clinical team, or any patient where you are unsure whether CPR would be appropriate — a senior with the right training should lead the discussion"}, "escalate_now_if": ["There is disagreement between the family (or an attorney) and the clinical team about resuscitation status — if she lacks capacity, this needs legal advice", "The patient has capacity and disagrees with the clinical recommendation", "You are unsure whether CPR would work or be of benefit", "There is no existing plan and the patient is deteriorating — without a recorded decision, the initial presumption is to attempt CPR", "The family are distressed and need senior support"], "document": "Record the conversation, who was present, the patient's own views (if she has capacity), any ADRT or LPA and whether it applies, the family's views, the clinical reasoning, the decision made, and the senior clinician responsible for it.", "fail": "An unsafe response makes a DNACPR decision alone or gives an unrecorded \"not for resus\", does not involve the patient (or, if she lacks capacity, those close to her), tells the family the decision is theirs or asks them to sign, or treats age or disability alone as the reason not to attempt CPR.", "pass": "A safe response reviews existing plans, assesses capacity, involves the patient or those close to her appropriately, and makes sure the decision is made and owned by the senior responsible clinician.", "high_performance": "An excellent response also explores the patient's values and what outcomes matter to her, uses ReSPECT to cover wider treatment escalation and not just CPR, checks any LPA or ADRT carefully, and documents so the whole team can act on the plan.", "one_thing": "If you only remember one thing: with no recorded decision, the initial presumption is to attempt CPR — a DNACPR decision belongs to the senior responsible clinician, who involves the patient or those close to her, and relatives do not decide.", "img_note": "ReSPECT (Recommended Summary Plan for Emergency Care and Treatment) is a non-legally binding plan used by most providers in England and many in Scotland; Wales has an All Wales DNACPR policy. In England and Wales, relatives cannot consent or refuse on behalf of an adult unless they hold a relevant LPA.", "source": "BMA, RCUK and RCN, Decisions relating to cardiopulmonary resuscitation, 3rd edn (1st revision) 2016 – Update June 2026 (ss8, 14, 15, 15.2; June 2026 notice on disputes for adults lacking capacity); GMC, Treatment and care towards the end of life, 2010 (updated Dec 2024), paras 131, 139, 143; R (Tracey) v Cambridge University Hospitals NHS FT [2014] EWCA Civ 822; Winspear v City Hospitals Sunderland NHS FT [2015] EWHC 3250 (QB); Mental Capacity Act 2005; RCUK ReSPECT policy briefing, Feb 2026. No verbal \"not for resus\" is standard practice, not guideline text.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Hughes on ward 6. Her family are asking about her resuscitation status, and there's nothing documented.", "B": "She was admitted with a stroke, has been deteriorating, and lacks capacity for this discussion. I've checked and there's no ReSPECT form, ADRT or LPA.", "A": "Her prognosis is poor and I don't think CPR would be of benefit, but this is a senior decision. Until one is recorded she is for CPR, and the nurse in charge knows. I've explained to the family that we will listen to what they know of her wishes, but the decision is a clinical one and not theirs to carry.", "R": "Could you come and lead the discussion with the family and make the CPR decision? I'll document it and complete the ReSPECT form with you."}, "checked": "Oct 2026"}, {"id": "BLEEP-58", "title": "End-of-life symptom control", "fpc_tags": ["Clinical assessment", "Holistic planning", "Communication and care"], "scenario": "Nurse bleeps: \"Mrs Price is dying and she's very agitated and uncomfortable, she's been prescribed anticipatory medicines but they don't seem to be working.\"", "nurse_call": [{"lead": "What symptoms?", "text": "Ask what symptoms she is experiencing — agitation, pain, breathlessness, nausea, or noisy respiratory secretions"}, {"lead": "What has been given?", "text": "Ask what anticipatory medicines have been given, at what dose and time, and whether they have helped"}, {"lead": "Is she on the care plan?", "text": "Ask whether she is on an individualised care plan for the last days of life"}, {"lead": "Family present?", "text": "Ask whether the family are present and whether they have any concerns"}, {"lead": "Any distressing symptoms not covered?", "text": "Ask about any symptoms that are not covered by the current anticipatory prescriptions"}], "first_five_minutes": [{"lead": "Review the patient and care plan", "text": "Review her individual symptoms and the care plan before giving more anticipatory medicine, and adjust the plan and prescriptions as needed"}, {"lead": "Look for reversible causes", "text": "Agitation is sometimes caused by unrelieved pain or a full bladder or rectum. Examine for urinary retention and a loaded rectum and treat them, and check for uncontrolled pain (use a validated behavioural pain tool if she can't tell you). Think of reversible metabolic causes (for example renal failure or hyponatraemia) if appropriate to her care plan — but do not delay symptom control if she is distressed"}, {"lead": "Two doses failed? Reassess", "text": "If two doses haven't settled her, reassess at the bedside straight away and call your senior — don't leave her distressed while you wait. Is this delirium rather than anxiety? Could a drug be contributing — for example hyoscine hydrobromide can cause delirium and urinary retention? If more than 2 or 3 as-required doses are needed in 24 hours, consider a syringe pump"}, {"lead": "Match the drug to the problem", "text": "Benzodiazepine for anxiety or agitation; antipsychotic for delirium. Before any antipsychotic, check for Parkinson's disease or Lewy body dementia: haloperidol is contraindicated in both, and other antipsychotics can cause severe sensitivity reactions. Adjusting the prescription is a senior decision — escalate promptly rather than repeating an ineffective dose"}, {"lead": "Consider the route", "text": "If she cannot swallow, make sure medicines are prescribed by a route she can use: subcutaneous or intravenous, not intramuscular"}, {"lead": "Seek specialist palliative advice", "text": "Seek specialist palliative care advice if her symptoms do not improve promptly, if the diagnosis of agitation or delirium is uncertain, or if treatment causes unwanted sedation"}, {"lead": "Monitor benefit and side effects", "text": "Monitor for benefits and side effects at least daily and give feedback to the lead healthcare professional"}, {"lead": "Support the family", "text": "Support the family and explain what is happening — this is part of holistic end-of-life care"}], "can_i_do_alone": {"alone": "Reviewing the patient and the care plan, assessing what is driving the symptoms, monitoring for benefit and side effects, and supporting the family", "senior_opinion": "Any adjustment to the anticipatory medicines (including an antipsychotic or a syringe pump), as-required doses needed more than 2 or 3 times in 24 hours, uncertainty about the cause of the agitation, symptoms not improving promptly, or a serious disagreement with her family about her care", "senior_in_person": "Any patient whose symptoms remain uncontrolled despite treatment, any patient with undesirable side effects such as unwanted sedation, or real uncertainty about whether she is entering the last days of life"}, "escalate_now_if": ["The patient's symptoms do not improve promptly with treatment, or as-required doses are needed more than 2 or 3 times in 24 hours", "There are undesirable side effects such as unwanted sedation", "The diagnosis of agitation or delirium is uncertain", "There is a serious disagreement with her family about her care", "You are uncertain whether she is entering the last days of life, or she may be stabilising or recovering"], "document": "Record the symptoms, what anticipatory medicines were given and the response, any adjustments to the prescription, the time specialist palliative care advice was sought if applicable, and the plan agreed with the senior.", "fail": "An unsafe response repeats ineffective anticipatory medicines without reviewing the prescription, gives an antipsychotic without checking for Parkinson's disease or Lewy body dementia, or fails to seek specialist palliative care advice when symptoms do not improve promptly.", "pass": "A safe response reviews the symptoms and the care plan, adjusts the prescription if needed with senior input, monitors for benefit and side effects, and seeks specialist advice if symptoms do not improve.", "high_performance": "An excellent response also supports the family throughout, individualises the care plan to her symptoms, and seeks specialist palliative care advice early rather than waiting for symptoms to become uncontrolled.", "one_thing": "If you only remember one thing: if symptoms do not improve promptly with treatment, seek specialist palliative care advice — do not just repeat the same medicine.", "img_note": "In UK practice, care of dying adults follows NICE NG31: an individualised care plan and anticipatory 'just in case' medicines prescribed in advance, usually given subcutaneously, sometimes by syringe driver. Hospital specialist palliative care teams advise in hours, and many areas also run out-of-hours specialist palliative care telephone advice — find your local number on your first shift.", "source": "NICE, Care of dying adults in the last days of life (NG31), Dec 2015 (Oct 2021 change not to these recommendations). NICE NG97 (2018) and haloperidol injection SmPC (Apr 2024) on antipsychotics in Parkinson's disease and Lewy body dementia. GMC, Treatment and care towards the end of life (2010, updated 2024), on seeking advice in a serious disagreement with family. Doses per local protocol. Calling your senior after two ineffective doses is standard practice, not guideline wording.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Price on ward 8. She's dying and is very agitated and uncomfortable despite her anticipatory medicines.", "B": "She has metastatic cancer and is on the individualised care plan for the last days of life. She's had two doses of midazolam without effect.", "A": "I've examined her: she isn't in retention, her rectum isn't loaded and her pain seems controlled. She's restless and seems confused, so I think this may be terminal delirium rather than anxiety. She hasn't had hyoscine hydrobromide and has no Parkinson's or Lewy body dementia.", "R": "I'd like your advice on adjusting her medicines — possibly an antipsychotic — and on whether we should get specialist palliative care advice now. Can you review her?"}, "checked": "Oct 2026"}, {"id": "BLEEP-59", "title": "Angry or distressed relative wanting to speak to a doctor", "fpc_tags": ["Communication and care", "Upholding values", "Ethics and law"], "scenario": "Nurse bleeps: \"Mr Taylor's daughter is here and she's very angry, she wants to speak to a doctor now about why he's not getting better.\"", "nurse_call": [{"lead": "What is she angry about?", "text": "Ask what specifically she is upset about — this helps you prepare for the conversation and address the concern directly"}, {"lead": "What has she been told?", "text": "Ask what information has already been given to her and by whom"}, {"lead": "Consent to share?", "text": "Ask whether Mr Taylor has capacity and has agreed to information being shared with his daughter — check the notes, or ask him first"}, {"lead": "Is she being aggressive?", "text": "Ask whether there is any aggression or threat to safety. If so, the nurse should step away and call security under the trust's policy, and you don't go in alone"}, {"lead": "Is he clinically OK?", "text": "Ask for his latest observations, NEWS2 and any new change. A worried relative is sometimes the first to notice deterioration"}], "first_five_minutes": [{"lead": "See him first if there's concern", "text": "If the nurse has any clinical worry, review Mr Taylor before the conversation. A deteriorating patient comes first"}, {"lead": "Prepare yourself", "text": "Read the notes: the plan, any ceiling of care or resuscitation decision, and what the family has been told. Take a moment to regulate your own emotions"}, {"lead": "Check consent before sharing", "text": "If Mr Taylor has capacity, share only with his agreement. If he refuses, respect that (rare public-interest exceptions are a senior decision), but you can still listen to her, which is not a breach of confidentiality. If he lacks capacity, it is reasonable to keep her informed of his general condition and prognosis unless he has indicated otherwise, and you must share relevant information if she holds a health and welfare lasting power of attorney or is a court-appointed deputy"}, {"lead": "Find a quiet space", "text": "Find a quiet, private space, with the nurse if possible. A corridor or waiting room is not appropriate"}, {"lead": "Listen, then summarise", "text": "Let her speak without interruption. Acknowledge her emotions ('I can see that you're very worried'), then summarise: 'What I hear is that you're worried your dad isn't improving.' This lets her correct you and shows she has been heard"}, {"lead": "Give clear, honest information", "text": "Explain the plan in plain language. Acknowledge uncertainty rather than giving false reassurance, don't guess at prognosis or criticise colleagues, and say what will happen next and when"}, {"lead": "If something went wrong, say sorry", "text": "If something went wrong in his care, apologise, explain what you know, tell a senior and report it under the trust's incident policy. An apology is not, of itself, an admission of legal liability"}, {"lead": "Set boundaries if needed", "text": "If her behaviour becomes abusive, calmly state what is acceptable: 'I want to help you, but I cannot do so while being shouted at'"}, {"lead": "Involve a senior if necessary", "text": "If the situation is not resolving, or you feel unsafe, involve a senior colleague or security. Asking for help is good judgement, not failure"}], "can_i_do_alone": {"alone": "Listening to her concerns, apologising for her experience, giving an accurate update that Mr Taylor has agreed to (or that is allowed if he lacks capacity), and giving PALS details", "senior_opinion": "Any new or detailed conversation about prognosis beyond what is documented in the plan, a formal complaint, or any conversation that is not resolving", "senior_in_person": "Any threat to safety, Mr Taylor deteriorating, any conversation about end-of-life decisions, or any situation where you feel out of your depth"}, "escalate_now_if": ["There is any aggression or threat to safety: involve security", "Mr Taylor has deteriorated (a rising NEWS2 or a new change in his condition)", "Something may have gone wrong and harmed him (a fall, a missed or wrong medicine, a delay)", "She raises a concern about abuse or neglect: follow the trust's safeguarding policy", "She wants information that Mr Taylor has not agreed to share, and you are unsure what to do", "The conversation involves complex clinical information that you are not confident to give", "You feel unsafe or out of your depth"], "document": "Record the time, who was present, the patient's consent to sharing (or the basis if he lacks capacity, including any attorney or deputy), her concerns, what you told her, any apology and incident report, PALS details given, and agreed follow-up. If a senior was involved, record their name and advice.", "fail": "An unsafe response becomes defensive or dismissive, raises their voice, refuses to listen 'because of confidentiality', shares confidential information without the patient's agreement or another lawful basis, misses that he has deteriorated, or fails to involve a senior when the situation is escalating.", "pass": "A safe response checks the patient is clinically stable, checks consent to share, listens without interruption, validates the relative's emotions, gives clear and honest information, and involves a senior if the situation is not resolving.", "high_performance": "An excellent response also summarises what the relative has said to confirm understanding, sets boundaries calmly if needed, offers a follow-up conversation with the consultant, and tells her how to raise a concern formally, and that doing so won't affect his care.", "one_thing": "If you only remember one thing: check the patient is happy for you to share, then listen first and validate the emotion — people escalate when they feel unheard.", "img_note": "In UK hospitals, adult relatives, including next of kin, have no automatic right to information about a patient with capacity: the patient decides. In England, most NHS trusts have a Patient Advice and Liaison Service (PALS) for concerns, separate from the formal complaints process. Pointing a family to PALS is not a brush-off. If you feel unsafe, you may end the conversation and call security.", "source": "GMC, Good medical practice (2024): paras 23, 37, 45 (apologise; not of itself an admission of liability), 46 (a complaint must not affect care). GMC, Confidentiality: good practice in handling patient information (2017): paras 36-40 (patient's wishes; abide by a refusal; lacks capacity: general condition and prognosis; don't refuse to listen) and 47 (share with an attorney or deputy). De-escalation, security and PALS are standard practice and trust policy.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Taylor's daughter on ward 6. She's very angry and wants to speak to a doctor about why he's not getting better.", "B": "She's had some information from the nursing staff but feels no doctor has explained things clearly. Mr Taylor has capacity and is happy for me to update her.", "A": "I've checked on him and he's clinically stable. She's distressed and demanding answers but not aggressive. I think she needs a clear, honest explanation and to feel heard.", "R": "I'm going to speak with her now in a quiet room. Could you be available if the conversation needs senior input, and could the consultant meet her tomorrow?"}, "checked": "Oct 2026"}, {"id": "BLEEP-60", "title": "Safeguarding concern raised by nursing staff", "fpc_tags": ["Ethics and law", "Upholding values", "Communication and care"], "scenario": "Nurse bleeps: \"I'm worried about Mrs Green, she's got bruises in different stages of healing and her husband won't leave the room when we try to talk to her.\"", "nurse_call": [{"lead": "What are you worried about?", "text": "Ask the nurse to describe exactly what she has observed and why she is concerned"}, {"lead": "Any injuries?", "text": "Ask about the nature, site and pattern of any injuries — bruises in different stages of healing are a red flag — and whether she is on an anticoagulant or has had falls"}, {"lead": "Who is present? Any danger now?", "text": "Ask who is with her and whether anyone is stopping her speaking freely. If anyone is in immediate danger, the nurse should call security and the police without waiting for you. Ask staff not to challenge her husband"}, {"lead": "Any children at home?", "text": "Ask whether there are children or other dependants in the household — they may also be at risk"}, {"lead": "Previous concerns?", "text": "Ask whether there have been any previous safeguarding concerns or referrals"}], "first_five_minutes": [{"lead": "See the patient alone", "text": "Find a way to see her on her own, in private — for example while her partner is asked to step out for a test. If someone is preventing this, that is itself a safeguarding concern"}, {"lead": "Ask sensitively", "text": "Ask about the injuries kindly and without leading questions: 'I've noticed some bruising — can you tell me how that happened?' Ask directly but gently whether anyone at home is hurting or frightening her. Don't promise to keep what she tells you secret. If she needs an interpreter, use a professional one — never her partner or a family member."}, {"lead": "Examine and document", "text": "With her consent and a chaperone, document the injuries (site, size, colour and pattern) and record what she says in her own words. Consider falls, anticoagulants or a clotting problem — they would not explain her husband's behaviour"}, {"lead": "Capacity: wishes count, limits exist", "text": "Assume she has capacity unless there is reason to doubt it; if in doubt, assess it for this specific decision. If she has capacity, her wishes carry great weight and may limit what can be done for her — so focus on reducing harm. But her wishes do not override action if she may be under duress or coercion, if others (including children) are at risk, or if a serious crime is suspected"}, {"lead": "Domestic abuse pathway", "text": "The safeguarding team will lead a domestic abuse risk assessment (such as the DASH checklist) in private and decide on any MARAC referral or independent domestic violence adviser (IDVA) support"}, {"lead": "Make a referral if indicated", "text": "Contact the trust safeguarding adults team (or your trust's out-of-hours route) and make a local authority safeguarding referral if indicated — with her consent where possible, or without it if she lacks capacity and it is in her best interests, or if there is duress, risk to others or a serious crime. If there are children in the home, refer to children's social care; her consent is not needed where a child may be at risk"}, {"lead": "Do not confront him", "text": "Do not confront the person you are concerned about — this could put her at greater risk. If she is in immediate danger, call security and the police"}, {"lead": "Escalate to a senior", "text": "Tell your senior and the safeguarding lead — safeguarding decisions are complex and you should not carry them alone"}], "can_i_do_alone": {"alone": "Seeing the patient alone, asking sensitively, documenting factually, informing the trust safeguarding team, and making a referral where the trust policy allows", "senior_opinion": "Any decision to refer without her consent, any patient who lacks capacity, and any complex safeguarding situation", "senior_in_person": "A senior is not usually needed at the bedside, but escalate urgently if she is at immediate risk of harm, the partner becomes threatening, or she has an injury needing urgent assessment — involve the safeguarding lead, security and, if needed, the police"}, "escalate_now_if": ["She is at immediate risk of harm, or the partner becomes threatening", "She has an injury that needs urgent assessment, such as a possible fracture or head injury", "She lacks capacity and you are concerned about her safety", "There are signs of duress or coercion, she says she is too frightened to go home, or you suspect a serious crime", "There are children or other adults at risk in the household", "You are unsure how to proceed — ask a senior or the safeguarding lead"], "document": "Record exactly what you observed, what the patient said in her own words, who was present, the date and time, her capacity and wishes, whether she agreed to information being shared (or your reasons for sharing without consent), and the action you took. Record facts objectively and separate them from opinion. Document any risk assessment, referral and the outcome. Do not record safety plans where the partner may read them.", "fail": "An unsafe response dismisses the concern, confronts the partner, promises to keep what she says secret, accepts 'she has capacity, so nothing can be done' without considering duress or risk to others, or fails to involve the safeguarding team.", "pass": "A safe response sees the patient alone, documents factually, assesses capacity and risk, and follows the trust safeguarding policy, including the domestic abuse pathway.", "high_performance": "An excellent response also asks about children and other people at risk, offers the IDVA and safety information discreetly, plans with the safeguarding team so she is not discharged into danger, and follows the referral through.", "one_thing": "If you only remember one thing: see her alone, document facts in her own words, and involve the safeguarding team — her capacity matters, but it does not end your duty when there is duress or risk to others.", "img_note": "In England, adult safeguarding enquiries are led by the local authority under section 42 of the Care Act 2014, but every NHS trust has its own safeguarding adults team — your first call in hours. Domestic abuse cases at high risk are discussed at a MARAC (Multi-Agency Risk Assessment Conference) with police, health and specialist services, and an IDVA supports the victim. In an emergency, call 999.", "source": "DHSC, Care and support statutory guidance (Care Act 2014), chapter 14, last updated Jul 2025 (14.92, 14.95, 14.108 capacity and refusal; 14.187 no promise of secrecy); NICE, Domestic violence and abuse: multi-agency working (PH50), Feb 2014, update planned (recs 6–9: see her alone, consider MARAC or IDVA if high risk, professional interpreters); Mental Capacity Act 2005. DASH, the medical check of bruising and recording practice are standard practice, not national guidance", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about a safeguarding concern for Mrs Green on ward 4.", "B": "The nurses noticed bruises in different stages of healing, and her husband won't leave the room when they try to speak with her.", "A": "I saw her alone briefly. She was frightened and reluctant to talk. I've assessed that she has capacity to make this decision, and she doesn't want it taken further at this point. There are no children at home. I've documented everything and informed the safeguarding team.", "R": "I'd like your help to decide whether we refer without her consent. The safeguarding team will do a DASH risk assessment with her, and we should agree a plan so she isn't discharged before it's done."}, "checked": "Oct 2026"}, {"id": "BLEEP-61", "title": "Blocked, dislodged or misplaced NG tube", "fpc_tags": ["Clinical assessment", "Quality improvement", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Ward's NG tube has come out and he needs it re-siting, he's due his feed and medications.\"", "nurse_call": [{"lead": "Blocked or dislodged?", "text": "Ask whether the tube has come out, has moved (has the external length at the nose changed? An unchanged length doesn't exclude movement) or is blocked — the management differs"}, {"lead": "Fully or partly out?", "text": "If it is partly out, has moved or is coiled at the back of the mouth, stop any feed and do not use it. A displaced tube is not simply pushed back and used"}, {"lead": "Any coughing or breathlessness?", "text": "Ask whether any feed or medicine has gone through it since it moved, and whether he has coughed, vomited, become breathless or dropped his saturations — think aspiration"}, {"lead": "Why does he need it?", "text": "Ask why he needs the tube (feeding, medicines or both) and whether he has a safe swallow"}, {"lead": "What is due?", "text": "Ask what feed and medicines are due, especially time-critical medicines such as those for Parkinson's disease, so alternatives can be arranged, and whether he has insulin with his feed"}], "first_five_minutes": [{"lead": "Check for aspiration first", "text": "If the tube moved during feeding, or he is coughing, breathless or desaturating, stop the feed, sit him up and assess him for aspiration before doing anything else. If saturation is low, give oxygen to a target of 94 to 98% (88 to 92% if at risk of hypercapnic respiratory failure)"}, {"lead": "Plan medicines, feed and glucose", "text": "Check whether he can safely swallow (follow any SALT advice), and ask pharmacy about other routes so time-critical medicines are not missed. If he has insulin with his feed, stopping the feed risks hypoglycaemia: check capillary glucose hourly, consider IV glucose, don't give a feed-related insulin dose that falls due (never omit basal insulin in type 1 diabetes), and get the insulin plan reviewed"}, {"lead": "Blocked: replacement is safest", "text": "The safest way to deal with a blocked NG tube is to remove it and insert a new one. Trying to aspirate and gently massaging the external tube is reasonable first, but never insert a guidewire to clear a blockage, and never flush with fizzy drinks. If anyone wants to keep a blocked tube because it is hard to replace, follow local policy — its position cannot be re-confirmed by pH."}, {"lead": "Re-site only if competent", "text": "Insert a new tube only if you are trained and signed off as competent under your trust policy, or are supervised by someone who is. Never re-insert a guidewire into a tube that is already in the patient"}, {"lead": "Confirm with pH strips", "text": "Aspirate and test with CE-marked pH strips designed for gastric aspirate. A pH of 5.5 or below means it is safe to use; if the pH is 5 to 5.5, a second competent person should check the reading. Never use the 'whoosh' test, litmus paper, the look of the aspirate or his lack of symptoms"}, {"lead": "pH above 5.5: do not use", "text": "Do not give anything through the tube. Follow your trust policy to retry — for example repositioning him on his left side and re-aspirating once the feed has been off for at least an hour. If you still cannot get a pH of 5.5 or below, a chest X-ray is the second-line test"}, {"lead": "X-ray read by competent staff", "text": "State on the request that it is to check NG position for feeding. The chest X-ray must be read by someone trained and competent to confirm NG position — misreading X-rays is the commonest cause of NG tube incidents"}, {"lead": "Document", "text": "Record the reason for re-siting, tube type and size, external length, each pH reading (or no aspirate) and second checker, any X-ray and who read it, and who did the procedure"}], "can_i_do_alone": {"alone": "Assessing for aspiration, re-siting a dislodged or blocked tube if you are trained and competent, confirming position with pH testing (with a second competent check for pH 5 to 5.5), and arranging alternative routes for medicines with pharmacy", "senior_opinion": "Repeated failed insertion, a pH persistently above 5.5 so an X-ray is needed, a tube that is difficult to replace and that someone wants to keep rather than replace, or an NG X-ray you are not assessed as competent to read", "senior_in_person": "Suspected aspiration of feed or medicine, respiratory deterioration, or any suspicion that the tube is in the airway. If feed has gone through a tube in the airway, a senior decides whether to remove it, as it may be needed to suction the feed out"}, "escalate_now_if": ["Feed or medicine may have been given through a displaced or misplaced tube", "He is coughing, breathless or desaturating during or after insertion or feeding — stop, withdraw the tube during insertion or stop the feed, and get help", "There is any suspicion that the tube has entered the respiratory tract", "Repeated attempts at insertion fail", "Position cannot be confirmed by pH and you are not assessed as competent to read an NG X-ray"], "document": "Record the date and time, why the tube was replaced, the type and size of tube, the external length, the pH results and any second checker, any X-ray with who interpreted it, who performed the procedure, any capillary glucose results, and the plan for medicines, feed and insulin.", "fail": "An unsafe response uses the whoosh test or litmus paper, feeds when the pH is above 5.5, uses a guidewire to unblock a tube, or pushes a displaced tube back and uses it without re-confirming position.", "pass": "A safe response checks for aspiration, replaces a blocked or displaced tube if competent, confirms position with pH strips before use, and uses an X-ray read by a competent person when pH fails.", "high_performance": "An excellent response also protects time-critical medicines while the tube is out, involves the dietitian and SALT, and looks for why the tube came out or blocked (for example agitation, or crushed tablets given through it) to prevent it happening again.", "one_thing": "If you only remember one thing: nothing goes down an NG tube until a pH of 5.5 or below — or a competently read X-ray — confirms it is in the stomach; replace a blocked tube rather than forcing it.", "img_note": "In the UK, starting a feed, flush or medicine through an NG tube misplaced in the lungs or pleura that was not detected is a Never Event, and misplacement remains a recurring theme in national patient safety alerts. Most trusts require you to complete an NG competency before inserting tubes or checking their position, and any misplacement must be reported on the incident system (for example Datix) for review under PSIRF. Find out where the pH strips are kept on your ward.", "source": "NNNG (BAPEN), Safe insertion and ongoing care of NG feeding tubes in adults, 3rd edn, Apr 2023 (review date Apr 2025 passed); HSIB, Placement of nasogastric tubes (I2019/006), Dec 2020; NHS Improvement, Nasogastric tube misplacement: continuing risk of death and severe harm (NHS/PSA/RE/2016/006) and resource set, Jul 2016; NHS England Never Events list 2018 (updated Feb 2021); JBDS-IP 05, Glycaemic management during enteral feeding, Apr 2024, s10; BTS oxygen guideline 2017, A2–A3. Sitting him up is standard practice.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Ward on ward 5. His NG tube has come out and needs re-siting before his feed and medicines are due.", "B": "He's had a stroke with an unsafe swallow, and he needs the tube for feeding and medicines.", "A": "The tube is fully out and nothing has been given through it since it moved. He's not coughing or breathless, and his saturations are normal. I'm trained to insert NG tubes. I'll confirm position with pH strips and get a second check if the pH is between 5 and 5.5.", "R": "I'm going to re-site it now. I'll call you if I can't get a pH of 5.5 or below and he needs an X-ray. Pharmacy are advising on his time-critical medicines in the meantime."}, "checked": "Oct 2026"}, {"id": "BLEEP-62", "title": "Wound dehiscence", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Holistic planning"], "scenario": "Nurse bleeps: \"Mr Hughes' surgical wound has opened up, there's a gap in the middle and I can see some tissue underneath.\"", "nurse_call": [{"lead": "How big is the gap?", "text": "Ask how much of the wound has opened and whether there is any tissue protruding — if there is bowel or omentum visible, this is an emergency"}, {"lead": "Any discharge?", "text": "Ask whether there is any discharge and what it looks like. A sudden gush of pink, serosanguineous fluid may come before the deep layer (fascia) gives way; pus or bowel contents suggest infection or a leak"}, {"lead": "Obs, NEWS2 and pain", "text": "Ask for the observations and NEWS2, and about pain and fever. Ask to be called back at once if the NEWS2 reaches 5 or more or a single parameter scores 3"}, {"lead": "Cover the wound", "text": "If tissue is exposed, ask the nurse to lay him flat and cover it with sterile gauze soaked in sterile saline, changed hourly so it stays moist — not to push anything back in"}, {"lead": "When was the surgery?", "text": "Ask what operation the patient had and when — this informs the likely cause and the urgency — and when his last anticoagulant dose was given"}], "first_five_minutes": [{"lead": "ABCDE and assess severity", "text": "Assess airway, breathing, circulation, disability and exposure, and calculate the NEWS2 — if he is systemically unwell, think sepsis or an intra-abdominal complication. A NEWS2 of 7 or more needs your trust's emergency response"}, {"lead": "Assess the wound — don't probe", "text": "Look at how much has opened, whether you can see the base, what tissue is visible, and the discharge. Do not probe the wound to test the depth — a short gap can extend deeply, and that assessment is for the surgical team"}, {"lead": "Cover, never reduce", "text": "Cover exposed tissue with saline-soaked gauze and change it hourly so viable tissue does not dry out. Never try to push bowel or omentum back into the abdomen"}, {"lead": "Evisceration is an emergency", "text": "If bowel or omentum is protruding (burst abdomen), inform the surgical team immediately, lie him flat, keep him nil by mouth, gain IV access, send bloods including group and save, give analgesia, and prepare for theatre"}, {"lead": "Call the surgical team", "text": "Call the surgical team now for any dehiscence after laparotomy or other abdominal surgery — don't wait for results, and say if you suspect a deep or fascial dehiscence. Superficial separation may be managed with dressings; deeper or fascial dehiscence may need theatre, so site a cannula and send bloods including clotting and a group and save"}, {"lead": "Think infection and leak", "text": "Look for spreading erythema, pus or systemic upset — dehiscence and surgical site infection often go together. Examine the abdomen: after bowel surgery, distension, peritonism, sepsis or enteric discharge may mean an anastomotic leak or a deep collection"}, {"lead": "Suspected sepsis? Grade the risk", "text": "Use NICE NG253: NEWS2 7 or more is high risk, 5–6 medium, 1–4 low; consider higher if mottled, ashen, cyanosed or a non-blanching rash. Take blood cultures before antibiotics. High risk: urgent FY2-or-above review and IV antibiotics within 1 hour. Medium or low risk: an FY2-or-above clinician decides on antibiotics, and at medium risk a lactate over 2 mmol/L or an AKI means treat as high risk"}, {"lead": "Analgesia and the cause", "text": "Give analgesia, and an antiemetic if he is vomiting. Consider the cause — infection, poor healing (malnutrition, steroids, diabetes), raised abdominal pressure (coughing, vomiting, distension) or technical factors. If he has diabetes or takes steroids, ask the surgical team to plan these while he is nil by mouth, per local protocol"}], "can_i_do_alone": {"alone": "Assessing the wound without probing, NEWS2, covering exposed tissue with saline-soaked gauze, analgesia, nil by mouth pending review, bloods including a group and save, and calling the surgical team", "senior_opinion": "A small skin-only gap with a visible base, nothing exposed, no serosanguineous gush and a well patient, or infection confined to the wound: phone the surgical team now for a plan, including whether antibiotics are needed", "senior_in_person": "Anything on the escalate list — evisceration, suspected deep or fascial dehiscence, a possible leak, or a systemically unwell patient — needs urgent surgical review at the bedside and possibly theatre"}, "escalate_now_if": ["There is evisceration (bowel or omentum protruding) — this is a surgical emergency", "There has been a sudden gush of serosanguineous fluid, the fascia appears to be open, or you can't see the base of the gap", "NEWS2 of 5 or more or any single parameter scoring 3, or he is systemically unwell with suspected sepsis or a possible anastomotic leak (new abdominal pain, distension or peritonism)", "There is spreading infection or enteric (bowel) content in the wound", "The wound is bleeding — apply direct pressure, lay him flat and call for help", "The patient is in severe pain"], "document": "Record the time the dehiscence was noted, the NEWS2, the size of the opening, whether the base was visible and the tissue seen (without probing), the discharge, abdominal findings, the dressing applied, nil by mouth status, bloods sent, the last anticoagulant dose, who in the surgical team you called and when, and the plan agreed.", "fail": "An unsafe response leaves exposed tissue uncovered or drying out, tries to push bowel back in or probes the wound, or fails to call the surgical team urgently for a deep dehiscence or evisceration.", "pass": "A safe response checks the NEWS2, assesses the wound without probing, covers exposed tissue with moist saline gauze, assesses for infection and leak, and calls the surgical team.", "high_performance": "An excellent response also recognises a serosanguineous gush as a warning sign, considers the underlying cause, involves the tissue viability nurse for ongoing wound care, and supports the patient with analgesia and explanation.", "one_thing": "If you only remember one thing: cover exposed tissue with moist saline gauze, never push it back or probe, and call the surgical team now.", "img_note": "In UK hospitals, superficial surgical wound problems are often managed with the tissue viability nurse (TVN) once the surgical team has assessed the wound. The decision about closure or theatre always rests with the operating surgical team, so call them, not just the on-call medical team.", "source": "National Wound Care Strategy Programme, Recommendations for Preventing and Managing Surgical Wound Complications (reviewed May 2024): burst abdomen (inform the surgical team immediately, lay flat, saline-soaked gauze changed hourly, p. 11) and wound haemorrhage as emergencies. NICE NG253 Suspected sepsis (2025, updated 23 Sep 2026): risk bands (1.6.2, 1.6.3), samples first (1.8.1), antibiotic decisions by risk (1.8.2, 1.8.3, 1.8.17, 1.8.20, 1.8.23). RCP NEWS2 (2017). Consensus, not guideline: WUWHS Surgical wound dehiscence (2018) for the serosanguineous warning sign and not probing. Standard surgical practice: not reducing contents, nil by mouth, group and save, and urgent bedside review for suspected fascial dehiscence.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mr Hughes on ward 7. His laparotomy wound has opened in the middle with tissue visible underneath.", "B": "He had a laparotomy five days ago and had been recovering well; his last anticoagulant dose was last night. The nurse noticed a gush of pink fluid from the wound this morning.", "A": "The wound is open about 3 cm in the middle and I can't see the base. There's no bowel or omentum protruding and no pus, and his abdomen is soft and not distended. Resps 16, sats 97% on air, BP 128/76, pulse 84, alert, temp 36.9: NEWS2 0. I haven't probed it, but after a serosanguineous gush I'm worried the fascia may have opened.", "R": "I've covered it with saline-soaked gauze, given analgesia, kept him nil by mouth and sent bloods including a group and save. I'd like the surgical team to review him now to decide whether he needs closure in theatre. I'll call back at once if anything becomes visible in the wound or his NEWS2 reaches 5."}, "checked": "Oct 2026"}, {"id": "BLEEP-63", "title": "Postpartum haemorrhage", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Midwife bleeps: \"Mrs Campbell is bleeding heavily after delivery, she's losing a lot of blood and her BP is dropping, can you come now?\"", "nurse_call": [{"lead": "Call for help", "text": "Ask the midwife to pull the emergency bell or put out the obstetric emergency call now, before you arrive — major PPH is time-critical"}, {"lead": "How much blood?", "text": "Ask for the blood loss, measured or weighed if possible, as visual estimates often underestimate it — primary PPH is minor (500–1000 mL) or major (more than 1000 mL)"}, {"lead": "Full obs + MEWS", "text": "Ask for BP, heart rate, respiratory rate, saturations, temperature and consciousness, and the maternity early warning score"}, {"lead": "Uterine tone", "text": "Ask whether the uterus feels well contracted or soft and boggy — uterine atony is the commonest cause of primary PPH — and, if soft, to rub up the fundus now"}, {"lead": "IV access and bloods", "text": "Ask for two large-bore IV cannulas, IV fluids, and bloods: FBC, clotting including fibrinogen, U&Es, LFTs and crossmatch (at least 4 units)"}, {"lead": "Which uterotonic already given?", "text": "Ask what was given for the third stage and what has been given since — this decides the next uterotonic"}], "first_five_minutes": [{"lead": "ABCDE and resuscitate", "text": "Resuscitate first: high-concentration oxygen (10–15 L/min via a facemask, regardless of her saturations), two large-bore cannulas, warmed IV fluids (no more than 3.5 L of clear fluids while waiting for blood), lie her flat and keep her warm"}, {"lead": "Call for senior help", "text": "Get the obstetric registrar, obstetric anaesthetist and coordinating midwife now, and alert the consultant obstetrician and anaesthetist, haematology and the transfusion lab — major PPH needs them simultaneously"}, {"lead": "Massage, uterotonic, empty bladder", "text": "Rub up the uterus, give the first-line uterotonic from your trust's PPH protocol (the choice depends on what was given in the third stage; check contraindications, such as ergometrine in hypertension or pre-eclampsia, and caution with carboprost in asthma), and insert a urinary catheter, because a full bladder stops the uterus contracting"}, {"lead": "Tranexamic acid 1 g IV", "text": "Give tranexamic acid 1 g IV over 10 minutes alongside the uterotonics, and repeat if bleeding continues after at least 30 minutes (NICE NG235). Check BNF/local protocol"}, {"lead": "Assess the cause: 4 Ts", "text": "Tone (atony — commonest), Trauma (perineal, vaginal or cervical tears, uterine rupture), Tissue (retained placenta or membranes), Thrombin (coagulopathy)"}, {"lead": "Monitor and record", "text": "Continuous pulse, BP, respiratory rate and saturations, and temperature every 15 minutes, on the maternity early warning chart; one person records times, drugs, fluids and blood; someone stays with her and her partner"}, {"lead": "Activate major haemorrhage protocol", "text": "If blood loss is over 1000 mL and continuing, or she shows signs of shock, activate the major obstetric haemorrhage protocol; give blood as soon as it is clinically needed (O RhD-negative, K-negative until group-specific is available) without waiting for lab results"}, {"lead": "Prepare for theatre", "text": "If bleeding continues, prepare for theatre — the obstetric team will decide on the procedure"}], "can_i_do_alone": {"alone": "Calling for help, giving oxygen, gaining IV access and sending bloods, starting fluids, emptying the bladder with a catheter, uterine massage, and giving the first-line uterotonic and tranexamic acid as set out in the trust PPH protocol", "senior_opinion": "A minor PPH (500–1000 mL) without shock (make sure the midwife in charge and first-line obstetric and anaesthetic doctors know), any uterotonic beyond the protocol's first-line drug (for example repeat carboprost or misoprostol), blood product decisions, or uncertainty about the cause", "senior_in_person": "Any major PPH (over 1000 mL), haemodynamic instability, or ongoing bleeding despite first-line measures — this needs the obstetric registrar and anaesthetist at the bedside now, and the consultant obstetrician in person if loss passes 1500 mL and is continuing"}, "escalate_now_if": ["Blood loss exceeds 1000 mL, or bleeding continues despite first-line measures; if it passes 1500 mL and is continuing, the consultant obstetrician should attend in person", "The patient is haemodynamically unstable (tachycardia, hypotension, reduced consciousness) or her airway is at risk", "The uterus remains atonic despite uterotonics and massage", "There is suspected uterine rupture or inversion, retained placenta or membranes, a bleeding genital tract tear, or coagulopathy", "The patient is not responding to initial resuscitation; if she collapses, put out a 2222 crash call"], "document": "Record the time bleeding was noted, the estimated (ideally measured) blood loss, the observations and early warning score, the uterine tone, the likely cause (Tone, Trauma, Tissue, Thrombin), every uterotonic and tranexamic acid dose with its time, catheterisation, fluids and blood products, the time senior help was called and arrived, and the plan, including any decision about theatre. A loss over 1500 mL should have a formal clinical incident review, so complete an incident report per local policy.", "fail": "An unsafe response fails to call for help early, is reassured by normal-looking observations, fails to assess uterine tone or empty the bladder, delays uterotonics and tranexamic acid, or fails to activate the major haemorrhage protocol when indicated.", "pass": "A safe response calls for help early, resuscitates, gives a uterotonic and tranexamic acid, empties the bladder and massages the uterus, works through the 4 Ts, and activates the major haemorrhage protocol if indicated.", "high_performance": "An excellent response also anticipates theatre and interventional radiology early, keeps the woman and her partner informed, and supports clear leadership across obstetrics, anaesthetics, haematology and midwifery.", "one_thing": "If you only remember one thing: major PPH is time-critical — call for help, rub up the uterus, give a uterotonic and tranexamic acid 1 g IV, empty the bladder, and activate the major haemorrhage protocol.", "img_note": "In UK maternity units, observations in pregnancy and after birth are scored on a maternity early warning chart (MEWS or MEOWS), not NEWS2. Obstetric emergencies are usually called by the emergency bell or a 2222 obstetric emergency call; the call name and team are set locally. Find your unit's PPH box or trolley and major obstetric haemorrhage protocol on your first shift.", "source": "NICE, Intrapartum care (NG235), last updated 9 Jun 2026 (1.10.33–1.10.36, table 12); RCOG, Prevention and management of postpartum haemorrhage (Green-top Guideline No. 52), Dec 2016, still current (third edition in development); NPSA 2004 for 2222; BNF (accessed Oct 2026)", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Campbell in delivery room 3. She's bleeding heavily after delivery and her BP is dropping.", "B": "She had a prolonged labour and a forceps delivery, with no known bleeding disorder.", "A": "Her BP is 85/50 and her heart rate is 130. The uterus is soft and boggy; the measured loss is over 1000 mL and she's still bleeding. I've given the first-line uterotonic from our PPH protocol and tranexamic acid 1 g IV, catheterised her, started fluids and oxygen, and I'm massaging the uterus.", "R": "I need the obstetric registrar and anaesthetist here now for second-line uterotonics and to control the bleeding. I'm activating the major haemorrhage protocol."}, "checked": "4 Oct 2026"}, {"id": "BLEEP-64", "title": "Pre-eclampsia / eclampsia", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Midwife bleeps: \"Mrs Taylor is 34 weeks pregnant and her BP is 165 over 110, she's got a severe headache and her vision is blurry, I'm worried about pre-eclampsia.\"", "nurse_call": [{"lead": "Full obs + BP", "text": "Ask for the full set of observations, including BP, on the maternity early warning chart (not NEWS2), and whether the BP has been repeated and confirmed"}, {"lead": "Urine protein", "text": "Ask whether proteinuria has been checked — dipstick positive (1+ or more) requires quantification by protein:creatinine ratio or albumin:creatinine ratio"}, {"lead": "Symptoms", "text": "Ask specifically about severe headache, visual disturbance, epigastric or right upper quadrant pain, and nausea or vomiting"}, {"lead": "Fetal wellbeing", "text": "Ask whether fetal movements are normal and whether the midwife has checked the fetal heart rate"}, {"lead": "Call obstetric team", "text": "Ask the midwife to call the obstetric registrar — severe pre-eclampsia needs urgent senior review"}, {"lead": "IV access and bloods", "text": "Ask for IV access, and for bloods including FBC, U&E, LFTs, clotting, and a group and save"}], "first_five_minutes": [{"lead": "ABCDE and assess severity", "text": "Assess airway, breathing, circulation, disability and exposure — look for signs of severe pre-eclampsia or impending eclampsia (severe headache, visual disturbance, clonus, epigastric pain)"}, {"lead": "Confirm the diagnosis", "text": "Pre-eclampsia is new hypertension (140 mmHg systolic or higher, or 90 mmHg diastolic or higher) after 20 weeks of pregnancy, with proteinuria or other maternal organ dysfunction, or uteroplacental dysfunction"}, {"lead": "Severe hypertension = treat now", "text": "A systolic BP of 160 or more, or a diastolic of 110 or more, is severe hypertension. It needs admission and antihypertensive treatment now, whether or not she has symptoms. Agree the drug with the obstetric registrar immediately, per the trust protocol. Aim for 135/85 or less, checking BP every 15–30 minutes until below 160/110"}, {"lead": "Look for severe features", "text": "Severe headache, visual scotomata, nausea or vomiting, epigastric pain, oliguria, rising creatinine or transaminases, falling platelets, or fetal compromise"}, {"lead": "Magnesium sulfate", "text": "Give IV magnesium sulfate after an eclamptic fit, and consider it in severe pre-eclampsia with features like hers (headache, visual symptoms, epigastric pain). The regimen is a registrar decision, per BNF/local protocol; once it is running, monitor reflexes, respiratory rate and urine output. Know where calcium gluconate is (the antidote for magnesium toxicity). Don't use diazepam or phenytoin instead of magnesium in eclampsia."}, {"lead": "Restrict fluids", "text": "Limit maintenance fluids to 80 mL/hour unless there are ongoing losses such as haemorrhage — fluid overload causes pulmonary oedema in pre-eclampsia. No fluid boluses, except up to 500 mL crystalloid if the registrar chooses IV hydralazine"}, {"lead": "Bloods, urine and CTG", "text": "Send FBC, U&E, LFTs and clotting, quantify proteinuria (protein:creatinine ratio, 30 mg/mmol or more is significant), and arrange a CTG"}, {"lead": "Plan with the registrar", "text": "Severe pre-eclampsia is managed on the labour ward under the obstetric team, and timing of birth and antenatal corticosteroids are senior decisions — escalate immediately if features are severe or there is fetal compromise"}], "can_i_do_alone": {"alone": "Assessing the patient, repeating the BP, sending bloods and urine, gaining IV access, arranging fetal monitoring, and calling the obstetric registrar immediately", "senior_opinion": "The choice of antihypertensive, magnesium sulfate and timing of birth — agree these with the obstetric registrar; a phone discussion is enough only if the BP is below 160/110 with no severe features, and 160/110 or higher needs the registrar at the bedside now", "senior_in_person": "Any systolic BP of 160 or more, or a diastolic of 110 or more (with or without symptoms), any severe feature, any seizure, or fetal compromise — this needs the obstetric registrar at the bedside now, with the obstetric anaesthetist informed. A seizure is a 2222 obstetric emergency"}, "escalate_now_if": ["A systolic BP of 160 or more, or a diastolic of 110 or more — with or without symptoms", "There is severe headache, visual disturbance or epigastric pain", "There is any seizure — treat as eclampsia and call 2222 (obstetric emergency); while help comes, protect her from injury, maintain her airway, give high-flow oxygen and place her in the left lateral position", "There are signs of fetal compromise", "She becomes breathless or her oxygen saturations fall — possible pulmonary oedema", "Blood results suggest HELLP syndrome or other organ dysfunction"], "document": "Record the time pre-eclampsia was suspected, the BP readings, urine protein results, symptoms, blood results, fetal monitoring findings, antihypertensive given and the time, magnesium sulfate if given, and the plan agreed with the obstetric team including any decision about delivery.", "fail": "An unsafe response treats 160/110 as needing action only if she has symptoms, delays antihypertensive treatment or the call to the registrar, gives unrestricted IV fluids, or fails to consider magnesium sulfate when severe features are present.", "pass": "A safe response recognises severe hypertension and severe features, calls the obstetric registrar immediately, starts antihypertensive treatment per protocol, anticipates magnesium sulfate, restricts fluids, and sends the right bloods and urine tests.", "high_performance": "An excellent response also considers the risk of eclampsia and ensures magnesium sulfate is available, arranges appropriate fetal monitoring, and communicates clearly with the patient about what is happening and why delivery may be needed.", "one_thing": "If you only remember one thing: a systolic BP of 160 or more, or a diastolic of 110 or more, in pregnancy is severe hypertension that needs treatment now, with or without symptoms — call the obstetric registrar, and with severe features anticipate magnesium sulfate.", "img_note": "In UK units, severe pre-eclampsia is managed on the labour ward (delivery suite) under the obstetric consultant, often in an obstetric high-dependency area with early input from the obstetric anaesthetist. Many units keep a pre-eclampsia or eclampsia box with magnesium sulfate prepared to the trust protocol — find it on your first shift. Pregnant women are scored on a maternity early warning chart (MEWS), not NEWS2. Obstetric emergencies are called through 2222.", "source": "NICE, Hypertension in pregnancy: diagnosis and management (NG133), last updated Apr 2023 (RCOG Green-top 10A is archived in its favour). Magnesium toxicity monitoring is standard practice: check the BNF and local protocol.", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about Mrs Taylor at 34 weeks. Her BP is 165/110 and she has a severe headache and blurred vision.", "B": "She has no previous history of hypertension, and this is her first pregnancy.", "A": "Her BP is confirmed at 165/110. Urine dipstick shows 3+ protein, and she has visual disturbance and epigastric pain. I've sent FBC, U&E, LFTs, clotting and a urine PCR, and started CTG and a fluid chart.", "R": "This is severe pre-eclampsia. I need you here now to start antihypertensive treatment and decide on magnesium sulfate. Shall I get the protocol drugs ready?"}, "checked": "Oct 2026"}, {"id": "BLEEP-65", "title": "Feverish child", "fpc_tags": ["Clinical assessment", "Clinical prioritisation", "Communication and care"], "scenario": "Nurse bleeps: \"There's a 3-year-old in the paediatric assessment unit with a temperature of 39.2, he's miserable and his mum says he's not himself.\"", "nurse_call": [{"lead": "Full obs, PEWS + age", "text": "Ask for the full set of observations including temperature, heart rate, respiratory rate, oxygen saturation, capillary refill, the PEWS score and the child's age. A baby under 3 months with a temperature of 38°C or more is high risk and needs urgent senior review on a separate pathway with its own investigations — this card does not apply. Temperature isn't part of the PEWS score, so a low PEWS doesn't exclude sepsis"}, {"lead": "Alertness and colour", "text": "Ask whether the child is alert and responding normally, and whether there is any change in colour (pale, mottled, ashen or blue)"}, {"lead": "Feeding, urine and hydration", "text": "Ask about feeding, wet nappies or urine output, and signs of dehydration (dry mucous membranes, reduced skin turgor)"}, {"lead": "Rash", "text": "Ask whether there is any rash — and specifically whether it is non-blanching"}, {"lead": "Parental concern", "text": "Ask what the parent is most worried about. Parent concern that the child is behaving differently from usual is a moderate-to-high risk sepsis criterion"}], "first_five_minutes": [{"lead": "ABCDE with attention to appearance", "text": "Assess airway, breathing, circulation, disability and exposure — in children, appearance, work of breathing and circulation to the skin are key"}, {"lead": "Traffic light: red features", "text": "Use the NICE traffic light table. Red (high risk): pale, mottled, ashen or blue skin; no response to social cues; does not wake or stay awake; weak, high-pitched or continuous cry; grunting; respiratory rate over 60; moderate or severe chest indrawing; reduced skin turgor; non-blanching rash; appears ill to a healthcare professional; neck stiffness; focal neurological signs, focal seizures or status epilepticus"}, {"lead": "Traffic light: amber features", "text": "Amber (intermediate risk) features include, over 12 months: respiratory rate over 40, saturations 95% or less in air, heart rate over 140 (age 2–5), capillary refill 3 seconds or more, reduced urine output, not responding normally to social cues, rigors, fever for 5 days or more, nasal flaring, crackles, dry mucous membranes, swelling of a limb or joint, or non-weight bearing"}, {"lead": "Ask 'could this be sepsis?'", "text": "Grade sepsis risk with NICE NG254 table 1 for his age. At 3 to 4 years, RR 40+ or HR 140+ is high risk; RR 35–39 or HR 130–139 is moderate to high. At any age, SpO2 below 90% in air or HR below 60 is high risk; so are a non-blanching petechial or purpuric rash, a mottled or ashen appearance, cyanosis of the skin, lips or tongue, grunting or apnoea. SpO2 below 92%, capillary refill 3 seconds or more, reduced urine output, abnormal response to social cues, decreased activity, pallor, nasal flaring, leg pain, cold hands or feet, or parent concern is moderate to high"}, {"lead": "Escalate if high risk", "text": "Any red feature or NG254 high-risk criterion: senior (ST4+) urgently; venous gas with lactate and glucose, cultures, FBC, CRP, U&E, creatinine, LFTs and clotting; antibiotics within 1 hour (per local protocol). Oxygen if shocked or SpO2 below 92% in air. Lactate over 2 or shock: the senior directs a 10 ml/kg glucose-free crystalloid bolus (maximum 250 ml); lactate over 4 also needs critical care referral. Suspected meningococcal disease: parenteral antibiotics at the earliest opportunity"}, {"lead": "2+ moderate-to-high: bloods and lactate", "text": "With 2 or more moderate-to-high criteria, send the same bloods; review him and the lactate within 1 hour. Lactate over 2: treat as high risk. Lactate 2 or below with no definite diagnosis: reassess at least hourly, and a senior reviews the need for antibiotics within 3 hours"}, {"lead": "Test the urine", "text": "Test the urine for UTI in a child with fever and no obvious source. With amber features and no source, also send FBC, CRP and blood cultures. Check a capillary glucose if the child is unwell or drowsy"}, {"lead": "Look for a source", "text": "Examine the ears, throat, chest, abdomen, joints and skin — look all over for a rash, including the conjunctivae, because rashes are harder to see on brown or black skin"}, {"lead": "Treat distress, not the number", "text": "Consider paracetamol or ibuprofen if the child is distressed, but not just to lower the temperature, and don't give both together. Don't use the response to antipyretics to judge severity, and reassess amber or red children after 1–2 hours"}], "can_i_do_alone": {"alone": "Assessing the child with the traffic light and NG254 tables, checking observations, testing the urine, sending bloods and lactate, and giving antipyretics if the child is distressed", "senior_opinion": "Any child with amber features or an NG254 moderate-to-high criterion, any uncertainty about the source of infection, or any decision about admission or discharge. PEWS 5 to 8, or a new suspicion of sepsis recorded on the PEWS chart, needs medical review by ST3+ or equivalent within 30 minutes", "senior_in_person": "Any red feature, NG254 high-risk criterion, or lactate over 2 with 2 or more moderate-to-high criteria: urgent senior (ST4+) assessment, antibiotics within 1 hour and consultant discussion. PEWS 9 to 12, AVPU V or a new suspicion of septic shock is a rapid review (ST3+ within 15 minutes); PEWS 13+, AVPU P or U, abnormal pupils or a life-threatening situation is a 2222 \"paediatric medical emergency\""}, "escalate_now_if": ["There is a non-blanching rash — this may be meningococcal disease", "The child is pale, mottled, ashen or blue", "There is no response to social cues, or the child will not wake or stay awake", "The respiratory rate is over 60 (40 or more at 3 to 4 years), or there is grunting or moderate to severe chest indrawing, or SpO2 is below 90% in air", "The heart rate is 140 or more at 3 to 4 years, or below 60, or there are signs of shock (for example prolonged capillary refill with cool peripheries and tachycardia, mottled skin or altered consciousness)", "He has 2 or more moderate-to-high risk criteria and a lactate over 2 mmol/L", "PEWS is 9 or more, AVPU falls to V or below, or the nurse or a parent is worried he is deteriorating, whatever the score"], "document": "Record the child's age, temperature, full observations and PEWS, the traffic light classification and NG254 risk level with the features behind them, the source of infection if identified, urine and blood tests sent including lactate, antipyretics given, the reassessment, and the plan agreed with the senior, including any decision about admission or discharge with safety-net advice.", "fail": "An unsafe response dismisses a feverish child without applying the traffic light and NG254 tables, trusts a low PEWS, misses a non-blanching rash, fails to test the urine when there is no clear source, or fails to recognise signs of shock or serious illness.", "pass": "A safe response applies the traffic light and NG254 tables, tests the urine, sends bloods with a lactate for 2 or more moderate-to-high criteria, and escalates urgently for any red feature or high-risk criterion.", "high_performance": "An excellent response also gives safety-net advice if the child goes home — verbal and written, covering what to look out for (a fit, a non-blanching rash, the child becoming less well) and how to get help — and considers the family's communication needs.", "one_thing": "If you only remember one thing: in a feverish child, grade the child with the traffic light and the NICE sepsis table for his age, not the temperature or a low PEWS; test the urine if there's no source; and treat fever with a non-blanching rash as high risk.", "img_note": "In the UK, febrile children under 5 are assessed with the NICE traffic light system, often in a paediatric assessment unit (PAU) for short-stay observation rather than admission. If a child goes home, safety-net advice should be verbal and written, and should include how to get help again — for example returning directly to the PAU or calling NHS 111 out of hours. Children in England are scored on the national PEWS chart, not NEWS2; paediatric sepsis follows NICE NG254, not NG253.", "source": "NICE, Fever in under 5s: assessment and initial management (NG143), last updated Nov 2021; NICE, Suspected sepsis in under 16s (NG254), Nov 2025 (PEWS-alignment update expected Mar 2027); NHS England national PEWS chart, 1 to 4 years, Nov 2023; NICE, Meningitis (bacterial) and meningococcal disease (NG240), Mar 2024", "trust_protocol_line": "Follow your own trust's protocol and escalation policy where it differs from this.", "sbar": {"S": "I'm calling about a 3-year-old boy in the paediatric assessment unit with a temperature of 39.2°C. His mother says he's not himself.", "B": "He was born at term with no significant medical history, and his immunisations are up to date.", "A": "He's alert but miserable and not responding normally to social cues, which is an amber feature. His heart rate is 125, respiratory rate 35, SpO2 97% in air, capillary refill 2 seconds, no rash anywhere, and his chest is clear. On the NICE sepsis table for his age he meets 3 moderate-to-high criteria: the social cues, a respiratory rate of 35 and his mother's concern. There's no obvious source, so I've sent a urine sample and the sepsis bloods, including a venous gas with lactate.", "R": "I'll review him and the lactate within the hour and ring you. If it's over 2 he's high risk and I'll need you now; otherwise could you see him within 3 hours about antibiotics and admission? I'll reassess him at least hourly."}, "checked": "4 Oct 2026"}];
window.BLEEP_GLOSSARY = {"ABG": "arterial blood gas", "VBG": "venous blood gas", "ECG": "electrocardiogram", "CTPA": "CT pulmonary angiogram", "CT": "computed tomography", "CXR": "chest X-ray", "NEWS2": "National Early Warning Score 2", "SBAR": "Situation, Background, Assessment, Recommendation", "AKI": "acute kidney injury", "CKD": "chronic kidney disease", "ACS": "acute coronary syndrome", "MI": "myocardial infarction", "PE": "pulmonary embolism", "DVT": "deep vein thrombosis", "VTE": "venous thromboembolism", "AF": "atrial fibrillation", "NSAID": "non-steroidal anti-inflammatory drug", "NSAIDs": "non-steroidal anti-inflammatory drugs", "IV": "intravenous", "IM": "intramuscular", "FBC": "full blood count", "CRP": "C-reactive protein", "GCS": "Glasgow Coma Scale", "BP": "blood pressure", "ARBs": "angiotensin receptor blockers", "ACE": "angiotensin-converting enzyme", "DKA": "diabetic ketoacidosis", "4AT": "rapid delirium assessment tool recommended by NICE", "CAM-ICU": "Confusion Assessment Method for the ICU", "ICDSC": "Intensive Care Delirium Screening Checklist", "ORBIT": "bleeding-risk score used in AF", "PGD": "patient group direction", "ABCDE": "Airway, Breathing, Circulation, Disability, Exposure", "NICE": "National Institute for Health and Care Excellence"};
